export const dnlSentences: Sentence[] = [
  {"id":"s_work_dnl_1_1","chapterId":"ch_work_dnl_1","text":"●卷一·德行","sortOrder":1},
  {"id":"s_work_dnl_1_2","chapterId":"ch_work_dnl_1","text":"文中子，隋末隱於白牛，著《王氏六經》。北面受學者皆時伟人，國初多居佐命之列。自貞觀後，三百年問號稱至治，而《王氏六經》卒不傳。至元和初，劉禹錫撰《宣州觀察使王偳碑》，盛稱文中子能昭明王道，以大中立言，遊其門者皆天下俊杰；自餘士大夫擬議及史册，未有言文中子者。","sortOrder":2},
  {"id":"s_work_dnl_1_3","chapterId":"ch_work_dnl_1","text":"姚崇每與兒孫會集，曰：\"外甥自非疏，但別姓耳。\"遣與兒侄連名。","sortOrder":3},
  {"id":"s_work_dnl_1_4","chapterId":"ch_work_dnl_1","text":"玄宗重午日，賜丞相鐘乳。宋命子弟將此付医人合煉，對曰：\"上之所賜，必當珍異，付其家，必遭竊換。\"曰：\"持誠示信，尚懼見猜，以猜示人，其可得乎？爾勿以此待人。\"","sortOrder":4},
  {"id":"s_work_dnl_1_5","chapterId":"ch_work_dnl_1","text":"开元、天寶之間，傳家法者：崔沔之家學，崔均之家法。","sortOrder":5},
  {"id":"s_work_dnl_1_6","chapterId":"ch_work_dnl_1","text":"玄宗諸王友愛特甚，常思作長枕大被，與同起臥。諸王或有疾，上輾轉終日不能食。左右开喻進膳，上曰：\"弟兄，吾之手足，手足不理，吾身废矣，何暇更思寢食？\"上於東都起五王宅，又於上都創花萼樓，益與諸王會聚。或講經義，賦詩飲酒，歡笑戲謔，未嘗猜忌。","sortOrder":6},
  {"id":"s_work_dnl_1_7","chapterId":"ch_work_dnl_1","text":"肅宗在東宮，為林甫所篝，势幾危者數矣。鬢發班白。入朝，上見之侧然，曰：\"汝歸院，吾當幸。\"及上到宮中，庭宇不洒扫，而樂器屏弃，尘埃積其上。左右使令亦無妓女。上為之動色，顧謂力士曰：\"太子居處如此，將軍盍使我知乎？\"（原註：上在禁中不呼力士名，呼為將軍）力士奏曰：\"臣嘗欲言，太子不許，雲'無勤上念'。\"乃詔力士，令京兆尹亟選人間女子頎長絜白五人，將以賜太子。力士趨出庭下，复奏曰：\"臣宣旨京兆尹閱女子，人間嚣然，而朝廷好言事者得以為口實。臣伏見掖庭中，故衣冠以事没入其家者，宜可備選。\"上大悅，使力士詔掖庭令，按籍閱视，得五人，以賜太子。而章敬吳皇後在選中，後生代宗皇帝。","sortOrder":7},
  {"id":"s_work_dnl_1_8","chapterId":"ch_work_dnl_1","text":"肅宗為太子，嘗侍膳。尚食置熟俎，有羊臂需。上顧太子，使太子割。肅宗既割，餘污漫刃，以餅絜之，上熟视，不怿；肅宗徐舉餅啖之，上大悅，謂太子曰：\"福當如是愛惜。\"","sortOrder":8},
  {"id":"s_work_dnl_1_9","chapterId":"ch_work_dnl_1","text":"玄宗西幸，車駕將自延秋門出，楊國忠請由左藏库西，上從之。望見千餘人持火以俟駕。上駐跸曰：\"何用此？\"國忠對曰：\"請焚库積，無為盜守。\"上斂容曰：\"盜至，若不得此，必厚斂於人。不如與之，無重困吾民也。\"命彻火炬而後行。聞者皆感激流涕，迭相語曰：\"吾君愛人如是，福未艾也。雖太王去豳，何以過於此也。\"","sortOrder":9},
  {"id":"s_work_dnl_1_10","chapterId":"ch_work_dnl_1","text":"玄宗西幸，始入斜穀。天尚早，煙霧甚晦。知頓使、給事中韦倜於野中得新熟酒一壶，跪獻於馬首數四，上不為之舉。倜懼，乃註以他器，自引一，滿於上前。上曰：\"卿以我為疑耶？始吾即位之初，嘗飲大醉，損一人，吾悼之，因以為戒。迨今四十餘年，未嘗甘酒味。\"指力土及近侍者曰：\"此皆知之，非绐卿也！\"","sortOrder":10},
  {"id":"s_work_dnl_1_11","chapterId":"ch_work_dnl_1","text":"天寶中，有一書生旅次宋州。時李公勉年少貧苦，與此書生同店。而不旬日，書生疾作，遂至不救。臨絕，語公曰：\"某家住洪州，將於北都求官，於此得疾且死，其命也。\"因出囊金百兩遺公，曰：\"某之仆使無知有此，足下為我畢死事，餘金奉之。\"李公許為辦事。及禮畢，置金於墓中，而同葬焉。後數年，公尉开封。書生兄弟赍洪州牒來，累路尋生行止。至宋州，知李為主丧事。专詣开封，請金之所在。公請假至墓所，出金以付焉。","sortOrder":11},
  {"id":"s_work_dnl_1_12","chapterId":"ch_work_dnl_1","text":"德宗初即位，深尚禮法。谅暗中，召諸王食馬齒羹，不設鹽酪。皇姨有寡居者，時節入宮，妆飾稍過，上見之極不悅。異日如禮，乃加敬焉。","sortOrder":12},
  {"id":"s_work_dnl_1_13","chapterId":"ch_work_dnl_1","text":"崔吏部枢夫人，太尉西平王晟之女也。晟生日，中堂大宴。方食，有小婢附崔氏婦耳語久之，崔氏婦頷之而去。有頃复來。晟曰：\"何事？\"女對曰：\"大家昨夜小不安適，使人往候。\"晟怒曰：\"我不幸有此女。大奇事！汝為人婦，豈有阿家病，不檢校湯藥，而與父作生日？\"遽遣走簷子歸，身亦續至崔氏家問疾，且拜請教訓子不至。晟治家整肅，貴賤皆不許時世妆梳。勋臣之家，稱\"西平禮法。\"","sortOrder":13},
  {"id":"s_work_dnl_1_14","chapterId":"ch_work_dnl_1","text":"李師古跋扈，憚杜黃裳為相，未敢失禮，乃寄錢物百萬，併氈車一乘。使者未敢進，乃於宅門伺候。有肩舆自宅出，從婢二人，青衣褴褛。問：\"何人？\"曰：\"相公夫人。\"使者遽歸以告，師古乃止。","sortOrder":14},
  {"id":"s_work_dnl_1_15","chapterId":"ch_work_dnl_1","text":"杜太保宣簡公，大歷中，有故人遺黃金百兩；後三年為淮南節度使，其子來投，公取其黃金還之，緘封如故。","sortOrder":15},
  {"id":"s_work_dnl_1_16","chapterId":"ch_work_dnl_1","text":"檢校刑部郎中程皓，性周慎，不談人短。每於儕類中見人有所訾，未曾應對，候其言畢，徐為辯曰：\"此皆眾人妄傳，其實不爾。\"更說其人美事。曾於廣坐被人酗骂，席上愕然，皓徐起避之，曰：\"彼人醉耳，何可與言。\"","sortOrder":16},
  {"id":"s_work_dnl_1_17","chapterId":"ch_work_dnl_1","text":"高利自濠州改楚州。時江淮米貴，職田每年得粳米直數千貫。准例替人五月五日以前到者，得職田。利欲以讓前人，發州，所在故為淹泊，過限數日然後到州，士子稱焉。","sortOrder":17},
  {"id":"s_work_dnl_1_18","chapterId":"ch_work_dnl_1","text":"兵部李約員外嘗江行，與一商胡舟楫相次。商胡病，因邀相見，以二女托之，皆絕色也。又與一珠，約悉唯唯。及商胡死，财寶鉅萬，約悉籍其數送官，而以二女求配。始殓商胡，約自以夜光之，人莫知也。後死商胡有親屬來理資财，約請官可發掘檢之，夜光果在。其密行皆此類也。","sortOrder":18},
  {"id":"s_work_dnl_1_19","chapterId":"ch_work_dnl_1","text":"仆射柳元公家行為士大夫儀表。居大官，奉繼親薛夫人之孝，凡事不異布衣時。薛夫人左右仆使至有以小字呼公者。性嚴重，居外下輦，常惕懼。在薛夫人之侧，未嘗以嚴顏色待家人，恂恂如小子弟。敦睦內外，當世無比。宗族窮苦無告，因公而存立者甚眾。在方镇，子弟有事他適，所經境內，人不知之。族子應規，為水部員外郎，求公為市宅，公不與。潛語所親曰：\"柳應規以儒素進身，始入省，便造新宅，殊不若且稅居之為善也。\"及水部没，公撫视孤幼，恩意加厚，特為置居處，諸子皆與身名。族孫立疾病，以兒女托；公廉察鄂州，嫁其孤女，雖箱箧刀尺微物，悉手自閱视以付之。公出自清河崔氏，繼外族薛氏。前後與舅能、從同時領方镇，居省闼；又與薛氏舅苹同時為觀察使，妻父韓仆射同時居大僚：未嘗敢以爵位自高，减卑下之敬，其行己如此。","sortOrder":19},
  {"id":"s_work_dnl_1_20","chapterId":"ch_work_dnl_1","text":"元和已後，大僚睦親舊者，前辈有司徒鄭公，中間有楊詹事凭、柳元公，其後李相國武都公宗闵。","sortOrder":20},
  {"id":"s_work_dnl_1_21","chapterId":"ch_work_dnl_1","text":"裴尚書武，奉寡嫂，撫甥侄，為中表所稱。尚書卒後，工部夫人崔氏話其仁，辄流涕。工部名佶，有清德，武之長兄也。兄弟皆為八座，自丞相耀卿至工部子泰章，四世入南北省。群從居顯列者，不可勝書。泰章後亦為尚書。","sortOrder":21},
  {"id":"s_work_dnl_1_22","chapterId":"ch_work_dnl_1","text":"沈吏部傳師，性和易，不從流俗，不矯亢。觀察三郡，去镇無餘蓄。京城居處隘陋，不加一椽。所辟賓僚，無非名士。身没之後，家至貧苦。二子繼業，併致時名，又以報施不妄。其父禮部員外郎既濟，撰《建中實錄》，見稱於時。公亦為史官，及出領湖南、江西，奉詔在镇修《憲宗實錄》，當時榮之。","sortOrder":22},
  {"id":"s_work_dnl_1_23","chapterId":"ch_work_dnl_1","text":"劉敦儒事親以孝聞。親心緒不理，每鞭之見血，則一日悅畅。敦儒常斂衣受杖，曾不变容。憲宗朝旌表門闾。又趙郡李公道枢先夫人盧氏性嚴，事亦類此。道枢名聲已聞，又在班列，賓至門，往往值其受杖。","sortOrder":23},
  {"id":"s_work_dnl_1_24","chapterId":"ch_work_dnl_1","text":"滎陽鄭還古，俊才嗜學，性孝友。初家青、齊間，值李師道叛命，扶老親歸洛，與其弟自舁肩舆。晨暮奔追，兩肩皆瘡。妻柳氏，仆射元公之女，有婦道。弟齊古，好博戲赌錢。還古帑中恣其所用，齊古得之辄盡。還古每出行，必封管付家人，曰：\"留待二十九郎，傥博，勿使別取债息，為惡人所陷也。\"弟感其言，為之稍節。有堂弟善栗，投許昌軍為健兒。還古使使召之，自與洗沐，同榻而寢，因致書方镇，求補他職。竟以刚躁喜持論，不容於時。","sortOrder":24},
  {"id":"s_work_dnl_1_25","chapterId":"ch_work_dnl_1","text":"路相隨幼孤。其母問：\"汝識汝父否？\"曰：\"不識。\"曰：\"正如汝面。\"隨號絕久之，終身不照鏡。李衛公慕其淳素篤行，結為親家，以女適路氏。","sortOrder":25},
  {"id":"s_work_dnl_1_26","chapterId":"ch_work_dnl_1","text":"孫侍郎在翰林，父為太子詹事，分司東都。因春時遊宴歡，忽念溫清，進状乞省觀。其詞曰：\"'陟彼岵兮'，孰不瞻父？'方寸亂矣'，何以事君？\"自內廷径出。時皆稱之。至華陰，拜河南尹。","sortOrder":26},
  {"id":"s_work_dnl_1_27","chapterId":"ch_work_dnl_1","text":"宣宗天資友愛，敦睦兄弟。大中元年，作雍和殿於十六宅，數臨幸，諸王無少長，悉預坐。樂陳百戲，抵暮而罢。諸王或有疾，斥去戲樂，即其臥內，躬自撫之，忧形於色。","sortOrder":27},
  {"id":"s_work_dnl_1_28","chapterId":"ch_work_dnl_1","text":"宣宗郊天前一日，謁太廟。至憲宗室，捧而入，涕泗交下。左右觀者莫能仰视。","sortOrder":28},
  {"id":"s_work_dnl_1_29","chapterId":"ch_work_dnl_1","text":"宣宗嘗出內府錢帛，建報聖寺。大為堂殿，金碧圬墁之麗，近所未有。堂曰介福之堂，憲宗御像在焉。堂之北曰虔思殿，上休憩所也。每由复道至寺。凡進荐於介福者，雖甚微細，必手自題緘。","sortOrder":29},
  {"id":"s_work_dnl_1_30","chapterId":"ch_work_dnl_1","text":"萬寿公主，宣宗之女。上在藩時，主尤鐘愛。及下嫁，武德禁中舊儀，車舆有白金為飾者，及呈進，上曰：\"我方以俭化天下，宜從近戚始。\"乃命以銅製。主既行，每進見，上常誨曰：\"無輕待夫，無幹預時事。\"又降御勖励，其末曰：\"苟违吾戒，當有太平、安樂之禍。汝其勉之！\"故十五年間，戚屬縮然，如山東衣冠之法。","sortOrder":30},
  {"id":"s_work_dnl_1_31","chapterId":"ch_work_dnl_1","text":"宣宗時，前進士於琮選尚永福公主，連拜秘書，擢校書郎、右拾遺，賜緋；左補闕、賜紫。事忽中止。丞相上審聖旨，上曰：\"此女子，朕近與會食，對朕辄折匕箸。性情如此，恐不可為士大夫妻。\"尋改琮尚廣德公主，亦上次女也。","sortOrder":31},
  {"id":"s_work_dnl_1_32","chapterId":"ch_work_dnl_1","text":"博陵崔倕，缌麻親三世同爨。貞元已來，言家法者，以倕為首。倕生六子，一為宰相，五為要官。太常卿，太原尹酆，外壶尚書郎郾，廷尉郇，執金吾鄯，左仆射平章事鄲（原註：郾及鄆，五知貢舉，得士百四十八人）。兄弟亦同居光德里一宅。宣宗嘗叹曰：\"崔鄲家門孝友，可為士族之法矣。\"鄲嘗篝小斋於別寢，御書賜額曰：德星堂。","sortOrder":32},
  {"id":"s_work_dnl_1_33","chapterId":"ch_work_dnl_1","text":"大中年，丞郎宴席。蒋公伸在座，忽酌一杯，言曰：\"座上有孝於家，忠於國，名重於時者，飲此爵。\"眾無敢舉。李孝公景讓起引飲之，蒋以為然。","sortOrder":33},
  {"id":"s_work_dnl_1_34","chapterId":"ch_work_dnl_1","text":"李尚書性仁愛，厚於中外親戚，時推為首。嘗為一簿，遍記內外宗族姓名，及其所居郡縣，置於左右。歷官南曹。牧守及選人相知者赴所任，常閱籍以嘱之。","sortOrder":34},
  {"id":"s_work_dnl_1_35","chapterId":"ch_work_dnl_1","text":"東川韦有翼尚書自判鹽鐵，镇梓潼，有重名。平生不飲酒，不務歡笑，為家讳\"平\"故也。","sortOrder":35},
  {"id":"s_work_dnl_1_36","chapterId":"ch_work_dnl_1","text":"王鹹少監，舊族之後。少入仕。遭丧，服除數年，不飲食酒肉。後因會聚，人勸勉之，鹹捧肉欲，淚下盈盤，竟不食而離席，一坐為傛怛。後有人傳於獨狐公者，慕其獨行，遂聘其女。","sortOrder":36},
  {"id":"s_work_dnl_1_37","chapterId":"ch_work_dnl_1","text":"崔枢應進士，客居汴半歲，與海贾同止。其人得疾既篤，謂崔曰：\"荷君見願，不以外夷見忽。今疾势不起。番人重土殯，脱殁，君能終始之否？\"崔許之。曰：\"某有一珠，价萬缗，得之能蹈火赴水，實至寶也。敢以奉君。\"崔受之，曰：\"吾一進士，巡州邑以自給，奈何忽蓄異寶？\"伺無人，置於柩中，瘞於阡陌。後一年，崔遊丐亳州，聞番人有自南來尋故夫，併勘珠所在，陳於公府，且言珠必崔秀才所有也。乃於亳來追捕，崔曰：\"傥窀穸不為盜所發，珠必無他。\"遂剖棺得其珠。沛帥王彦謨奇其節，欲命為幕，崔不肯。明年登第，竟主文柄，有清名。","sortOrder":37},
  {"id":"s_work_dnl_1_38","chapterId":"ch_work_dnl_1","text":"懿宗器度深厚，形貌環玮，仁孝出於天性。鄭太後崩，而蔬菜同士人之禮。公卿奉慰，無不感泣。","sortOrder":38},
  {"id":"s_work_dnl_1_39","chapterId":"ch_work_dnl_1","text":"沈顏遊鐘陵，自章江入劍池，過臨川。時天早，水將涸。阻風，泊小渚。獲败碑，字存者十七八，乃撫州刺史顏魯公之文，即臨川所沈碑也。其文多載魯公之德業。","sortOrder":39},
  {"id":"s_work_dnl_1_40","chapterId":"ch_work_dnl_1","text":"李英公為仆射，其姊病，必親為粥，火燃，辄焚及其髭。姊曰：\"仆妾甚多，何為自苦若是？\"曰：\"豈為無人耶。顧姊年與皆老，欲久為姊粥，复可得乎？\"","sortOrder":40},
  {"id":"s_work_dnl_1_41","chapterId":"ch_work_dnl_1","text":"皇甫文備，武後時酷吏。與徐大理有功論獄，誣徐党逆人，奏成其罪，武後特出之。無何，文備為人所告，有功訊之在宽。或曰：\"彼曩將陷公於死，今公反欲出之，何也？\"徐曰：\"爾所言者私怨，我所守者公法，安可以私害公也。\"","sortOrder":41},
  {"id":"s_work_dnl_1_42","chapterId":"ch_work_dnl_1","text":"朱正諫敬則，代著孝義，自宇文周至唐，併令旌表，門標六闕。","sortOrder":42},
  {"id":"s_work_dnl_1_43","chapterId":"ch_work_dnl_1","text":"元魯山自乳兄子，兩乳涯流，能食，其乳方止。","sortOrder":43},
  {"id":"s_work_dnl_1_44","chapterId":"ch_work_dnl_1","text":"長安中爭為碑志，若市贾然。大官薨，其門如市，至有喧競扌致，不由丧家者。裴均之子求銘於韦相，許缣萬匹，貫之曰：\"寧饿不苟。\"","sortOrder":44},
  {"id":"s_work_dnl_2_1","chapterId":"ch_work_dnl_2","text":"●卷一·言語","sortOrder":1},
  {"id":"s_work_dnl_2_2","chapterId":"ch_work_dnl_2","text":"杜司徒常言：\"處世無立敵。\"范仆射常言：\"丈夫中年能損嗜欲，未有不貴達者。\"","sortOrder":2},
  {"id":"s_work_dnl_2_3","chapterId":"ch_work_dnl_2","text":"陳子雲：\"代宗時，有術士曰唐若山，餌芝術，咽氣导引，寿不逾八十。郭尚父立勋業，出入將相，窮奢極侈，寿鄰九十。\"","sortOrder":3},
  {"id":"s_work_dnl_2_4","chapterId":"ch_work_dnl_2","text":"興元中，有僧曰法钦。以其道高，居径山，時人謂之径山長者。房孺复之為杭州也，方欲决重獄，因詣钦，以理求之曰：\"今有犯禁，且獄成，於至人活之與殺之孰是？\"钦曰：\"活之則慈悲，殺之則解脱。\"","sortOrder":4},
  {"id":"s_work_dnl_2_5","chapterId":"ch_work_dnl_2","text":"陳子曰：\"衛公之戰伐，無兵也。杜員外詠歌，無詩也。張長史草聖，無書也。\"","sortOrder":5},
  {"id":"s_work_dnl_2_6","chapterId":"ch_work_dnl_2","text":"太宗止一树下，頗嘉之，宇文士及從而頌美之，不容於口。帝正色曰：\"魏徵常勸我遠佞人，我不悟佞人為誰，意疑汝而未明也，今乃果然。\"士及叩頭謝曰：\"南衙群官面折廷爭，陛下常不能舉首。今臣幸在左右，若不少順從，陛下雖貴為天子，亦何聊乎？\"意复解。","sortOrder":6},
  {"id":"s_work_dnl_2_7","chapterId":"ch_work_dnl_2","text":"武衛將軍秦叔寶，晚年常多疾病。每謂人曰：\"吾少長戎馬，經百餘戰，計前後出血不啻數斛，何能無疾乎？\"","sortOrder":7},
  {"id":"s_work_dnl_2_8","chapterId":"ch_work_dnl_2","text":"太宗將致櫻桃於阝公（原註：隋後封為阝公），稱\"奉\"則似尊，言\"賜\"又似卑，及問之虞監。監曰：\"昔梁帝遺齊巴陵王，稱'餉'。\"遂從之。","sortOrder":8},
  {"id":"s_work_dnl_2_9","chapterId":"ch_work_dnl_2","text":"太宗之征遼也，作飛梯臨其城。有應募為梯首者，城中矢射如雨，竟為先登。英公指謂中書舍人許敬宗曰：\"此人豈不大健？\"敬宗曰：\"健即大健，要是未解思量。\"帝聞，特罢之。","sortOrder":9},
  {"id":"s_work_dnl_2_10","chapterId":"ch_work_dnl_2","text":"司稼卿梁孝仁，高宗時造蓬萊宮，諸庭院列树白楊。將軍契何力，鐵勒之渠率也，於宮中縱觀。孝仁指白楊曰：\"此木易長，三數年間，宮中可荫影。\"何力一無所應，但誦古人詩雲：\"白楊多悲風，萧萧愁殺人。\"意此是冢墓間木，非宮室中所宜种。孝仁遂令拔去，更种梧桐。","sortOrder":10},
  {"id":"s_work_dnl_2_11","chapterId":"ch_work_dnl_2","text":"崑明池者，漢武帝所置。蒲魚之利，京師賴之。中宗朝，安樂公主請之。帝曰：\"前代以來不以與人，此則不可。\"主不悅，因役人徒別凿，號曰定崑池。既成，中宗往觀，令公卿賦詩。李黃門日知詩曰：\"但願暫思居者逸，無使時傳作者勞。\"及睿宗即位，謂之曰：\"當時朕亦不敢言，非卿忠正，何能若是！\"尋遷侍中。","sortOrder":11},
  {"id":"s_work_dnl_2_12","chapterId":"ch_work_dnl_2","text":"魏徵陳古今理體，言太平可致。太宗納其言。封德彝難之曰：\"三代以後，人漸浇訛，故秦任法律，漢雜霸道，皆欲理而不能，豈能理而不欲？徵書生，若信其虛論，必亂國家。\"徽語之曰：\"五帝三王，不易人而理。行帝道則帝，行王道則王，在其所化而已。考之載籍，可得而知。昔黃帝雖與蚩尤戰，既勝之後，便致太平。四夷亂德，颛頊征之，既克之後，不失其理。桀為亂德，湯放之；紂無道，武王伐之，而俱致太平。若言人漸浇訛，不返朴素，至今應為鬼魅，寧可得而教化耶？\"德彝無以難之。徵薨，太宗御製碑文併御書。後為人所讒，敕令踣之。及征遼不如意，深自悔恨，乃曰：\"魏徵若在，不使我有此舉也。\"既渡，馳驿以少牢祭之，复立碑焉。","sortOrder":12},
  {"id":"s_work_dnl_2_13","chapterId":"ch_work_dnl_2","text":"太宗嘗臨軒謂侍臣曰：\"朕非不能恣情為樂，常每励心苦節，卑宮菲食者，正為蒼生爾。我為人主，兼行將相事，豈不是奪公等名？昔漢高得萧、曹、韓、彭，天下寧宴；舜、禹、殷、周得稷、契、伊、呂，四海安。此事朕併兼用之。\"給事中張行成諫曰：\"有隋失道，天下沸騰。陛下拨亂反正，拯生人於涂炭，何禹、湯所能擬？陛下聖德含光，規模宏遠，雖文、武之烈，實無以加。何用臨朝對眾，與之校量。將謂天下已定，不藉其力，复以萬乘至尊，與臣下爭功。臣備員近枢，非敢知獻替事，辄陳狂直，伏待菹醢。\"太宗深納之，俄遷侍中。","sortOrder":13},
  {"id":"s_work_dnl_2_14","chapterId":"ch_work_dnl_2","text":"高宗朝，晉州地震，雄雄有聲，經旬不止。高宗以問張行成，行成對曰：\"陛下本封於晉，今晉州地震，不有徵應，豈使然哉！夫地，陰也，宜安靜而乃屢動。自古禍生宮掖，衅起宗親者，非一朝一夕，或恐諸王公主謁見頻煩，乘間伺隙；复恐女謁用事，臣下陰謀。陛下宜深思慮，兼修德以杜未萌。\"高宗深納之。","sortOrder":14},
  {"id":"s_work_dnl_2_15","chapterId":"ch_work_dnl_2","text":"則天以武承嗣為左丞相。李昭德奏曰：\"不知陛下委承嗣重權，何也？\"則天曰：\"我子侄，委以心腹耳。\"昭德曰：\"若以姑侄之親，何如父子？何如母子？\"則天曰：\"不如也。\"昭德曰：\"父子、母子尚有逼奪，何諸姑所能容？使其有便可乘，寶位其能安乎？陛下之子，受何福慶，而委重權於侄手？事之去矣！\"則天懼曰：\"我未思也。\"即日罢承嗣政事。","sortOrder":15},
  {"id":"s_work_dnl_2_16","chapterId":"ch_work_dnl_2","text":"太宗射猛獸於苑內，有群豕突出林中，太宗引弓射之，四發，殪四豕。有一雄豕直來冲馬，吏部尚書唐俭下馬搏之。太宗拔劍斷豕，顧而笑曰：\"天策長史，不見上將击賊耶，何懼之甚？\"俭對曰：\"漢祖以馬上得之，不以馬上理之。陛下以神武定四方，豈复逞雄心於一獸？\"太宗善之，因命罢獵。","sortOrder":16},
  {"id":"s_work_dnl_2_17","chapterId":"ch_work_dnl_2","text":"太宗言尚書令史多受賂者，乃密遣左右以物遺之，司門令史果受絹一匹。太宗將殺之，裴矩諫曰：\"陛下以物试之，遽行極法，誘人陷罪，非'道德、齊禮'之義。\"乃免。","sortOrder":17},
  {"id":"s_work_dnl_2_18","chapterId":"ch_work_dnl_2","text":"張玄素，貞觀初，太宗聞其名，召見，訪以理道。玄素曰：\"臣觀自古以來，未有如隋室丧亂之甚，豈非其君自专，其法日亂？向使君虛受於上，臣弼违於下，豈至於此！且萬乘之主，欲使自专庶務，日斷十事而有五條不中者，何况萬務乎？以日繼月，以至累年，乖谬既多，不亡何待？陛下若近鑒危亡，日慎一日，尧舜之道，何以加之！\"太宗深納之。","sortOrder":18},
  {"id":"s_work_dnl_2_19","chapterId":"ch_work_dnl_2","text":"太宗幸九成宮，還京，有宮人憩川縣官舍。俄而李靖、王至，縣官移宮人於別所而舍靖、。太宗聞之，怒曰：\"威福豈由靖等？何為禮靖等而輕我宮人！\"即令按验川官屬。魏徵諫曰：\"靖等，陛下心膂大臣；宮人，皇後賤隸。論其委任，事理不同。又靖等出外，官吏訪闕廷法式朝觐，陛下問人疾苦。靖等自當與官吏相見，官吏不可不謁。至於宮人，供養之外，不合參承。若以此罪，恐不益德音，駭天下耳目。\"太宗曰：\"公言是。\"遂舍不問。","sortOrder":19},
  {"id":"s_work_dnl_2_20","chapterId":"ch_work_dnl_2","text":"穀那律，貞觀中為諫議大夫，褚遂良呼為\"九經库\"。永徽中，嘗從獵，途中遇雨，高宗問：\"油衣若為得不漏？\"對曰：\"能以瓦為之，不漏也。\"意不為畋獵。高宗深賞焉。賜帛二百匹。","sortOrder":20},
  {"id":"s_work_dnl_2_21","chapterId":"ch_work_dnl_2","text":"武德初，萬年縣法曹孫伏伽三上表，以事諫。其一曰：\"陛下貴為天子，富有天下，凡曰狩，須順四時。陛下即位之明日，有獻鷂雏者，此乃前朝之弊風，少年之事務，何意今日行之？又聞相國參軍盧牟子獻琵琶，長安縣丞張安道獻弓箭，併蒙賞赉。但普天之下，率土之濱，莫非王臣。陛下有所欲，何求不得，豈少此物乎？\"其二曰：\"百戲散樂，本非正聲，此謂淫風，不可不改。\"其三曰：\"太子諸王左右群寮，不可不擇。願陛下納選賢才，以為寮友，則克安磐石，永固維城矣。\"高祖覽之悅，賜帛百匹，遂拜為侍御史。","sortOrder":21},
  {"id":"s_work_dnl_2_22","chapterId":"ch_work_dnl_2","text":"武德四年，王世充平後，其行台仆射蘇世長以漢南歸順。高祖责其後服。世長稽首曰：\"自古帝王受命，為逐鹿之喻，一人得之，萬夫斂手。豈有獵鹿之後，忿同獵之徒，問爭肉之罪也？\"高祖與之有舊，遂笑而釋之。後從獵於高陵，是日大獲，陳禽於旌門。高祖顧謂群臣曰：\"今日畋，樂乎？\"世長對曰：\"陛下废萬幾，事畋獵，不滿十旬，未為大樂。\"高祖色变，既而笑曰：\"狂態發耶？\"對曰：\"為臣私計則狂，為陛下國計則忠矣。\"嘗侍宴披香殿，酒酣，奏曰：\"此殿隋煬帝之所作耶？何雕麗之若是也！\"高祖曰：\"卿好諫似直，其心實诈。豈不知此殿是吾所造，何須诡疑是煬帝？\"對曰：\"臣實不知。但見傾宮、鹿台，琉璃之瓦，併非帝王節用之所為也。若是陛下所造，誠非所宜。臣昔在武功，幸當陪侍。見陛下宅宇才蔽風霜，當此時亦以為足。今因隋之侈，人不堪命，數歸有道，而陛下得之，實謂懲其奢淫，不忘俭約，今於隋宮之內，又加雕飾，欲拨其亂，寧可得乎？\"高祖每優容之。前後匡諫諷刺，多所宏益。","sortOrder":22},
  {"id":"s_work_dnl_2_23","chapterId":"ch_work_dnl_2","text":"張文素為給事中。貞觀初，修洛陽宮，以備巡幸，上書極諫。太宗善之，賜彩三百匹。魏徵叹曰：\"張公論事，遂有回天之力。可謂仁人之言，其利博哉！\"","sortOrder":23},
  {"id":"s_work_dnl_2_24","chapterId":"ch_work_dnl_2","text":"太宗將幸九成宮，馬周上疏諫曰：\"伏見明敕，以二月二日幸九成宮。臣竊惟太上皇春秋已高，陛下宜朝夕侍膳，晨昏起居。今所幸宮，去京三百餘里，鑾舆動轫，俄經旬日，非可朝發暮至；脱上皇或思感，欲即見陛下者，將何逮之。且車駕今行，本意避暑；則上皇尚留熱處，而陛下自逐涼處。溫清之道，臣切不安。\"太宗稱善。","sortOrder":24},
  {"id":"s_work_dnl_2_25","chapterId":"ch_work_dnl_2","text":"房玄齡與高士廉偕行，遇少府少監窦德素。問之曰：\"北門近來有何營造？\"德素以聞。太宗謂玄齡、士廉曰：\"卿但知南衙事，我北門小小營造，何妨卿事？\"玄齡等拜謝。魏徵進曰：\"臣不解陛下责，亦不解玄齡等謝。既任大臣，即陛下股肱耳目，所營造何容不知？责其訪問官司，臣所不解。陛下所為若是，當助陛下成之；所為若非，當奏罢之：此乃事君之道。玄齡等所問無罪而陛下责之，玄齡等不識所守。臣實不喻。\"太宗深納之。","sortOrder":25},
  {"id":"s_work_dnl_2_26","chapterId":"ch_work_dnl_2","text":"總章中，高宗將幸涼州。時隴右虛耗，議者以為非便。高宗聞之，召五品以上，謂曰：\"帝王五載一巡狩，群後四朝，此蓋常禮。朕欲暫幸涼州，乃聞中外鹹謂非宜。\"宰臣以下莫有對者。詳刑大夫來公敏進曰：\"陛下巡幸涼州，宣王略，求之故實，未虛令典。但隨時度事，臣下竊有所疑。高麗雖平，餘寇尚梗；西道經略，兵猶未停。且隴右諸州，人戶少寡，供待車駕，備擬稍闕。臣聞中外實有竊議。\"高宗曰：\"既有此言，我止度隴，存問故老，狩即還。\"遂下詔停西幸，擢公敏為黃門侍郎。","sortOrder":26},
  {"id":"s_work_dnl_2_27","chapterId":"ch_work_dnl_2","text":"德宗既貶盧杞，然常思之。後欲稍遷，朝臣恐懼，皆有諫疏。上問李公曰：\"盧杞何處奸邪？\"對曰：\"陛下不知，此所以為奸邪也。\"","sortOrder":27},
  {"id":"s_work_dnl_2_28","chapterId":"ch_work_dnl_2","text":"馬司徒之孫始生，德宗名之曰\"繼祖。\"笑曰：\"此有二意，謂以索系祖也。\"","sortOrder":28},
  {"id":"s_work_dnl_2_29","chapterId":"ch_work_dnl_2","text":"陆長源以舊德為宣武行軍司馬，韓愈為巡官。或譏年辈相懸。周願曰：\"大虫老鼠，俱為十二相屬，何怪之有。\"旬日傳於長安中。","sortOrder":29},
  {"id":"s_work_dnl_2_30","chapterId":"ch_work_dnl_2","text":"高貞公郢為中書舍人九年，家無製草。或曰：\"前辈有製集，焚之何也？\"答曰：\"王言不可存於私家。\"","sortOrder":30},
  {"id":"s_work_dnl_2_31","chapterId":"ch_work_dnl_2","text":"高貞公致仕，製雲：\"以年致政，抑有前聞；近代寡廉，罕由斯道。\"是時杜司徒年過七十，無意請老。裴晉公為舍人，以此譏之。","sortOrder":31},
  {"id":"s_work_dnl_2_32","chapterId":"ch_work_dnl_2","text":"憲宗忽問：\"京兆尹幾員？\"李相吉甫對曰：\"京兆三員：一員大尹，二員少尹。\"人以為善對。","sortOrder":32},
  {"id":"s_work_dnl_2_33","chapterId":"ch_work_dnl_2","text":"衢州人餘長安，父叔二人為同郡方金所殺。長安八歲自誓，十七乃复仇。大理斷死。刺史元錫奏：\"餘氏一家，遇橫死者實二平人，蒙顯戮者乃一孝子。\"引《公羊傳》\"父不受誅，子得复仇\"之義。時裴為宰相，李刑部為有司，事竟不行。老儒薛伯高遺錫書：\"大司寇是俗吏，執政柄乃小生，餘氏子宜其死矣！\"","sortOrder":33},
  {"id":"s_work_dnl_2_34","chapterId":"ch_work_dnl_2","text":"憲宗問趙相宗儒曰：\"人言卿在荆門，球場草生，何也？\"對曰：\"罪誠有之。雖然，草生不妨球子。\"上為之笑。","sortOrder":34},
  {"id":"s_work_dnl_2_35","chapterId":"ch_work_dnl_2","text":"鄭陽武常言欲為《易比》，以三百八十四爻各比人事。又雲：\"仁義之有莊周，猶禪律之有維摩詰，欲圖畫之，未能也。\"","sortOrder":35},
  {"id":"s_work_dnl_2_36","chapterId":"ch_work_dnl_2","text":"王相涯註《太玄》，常取以卜，自言所中多於《易》筮。","sortOrder":36},
  {"id":"s_work_dnl_2_37","chapterId":"ch_work_dnl_2","text":"高貞公之子定，通王氏《易》。為圖，合八出，以畫八卦。上圓下方，合則為重，轉則為演。七轉為六十四卦，六甲八節備焉。著外傳二十二篇。定，小字董二，時人多以小字稱。初年七歲，讀《尚書》至《湯誓》，問父曰：\"奈何以臣伐君？\"父答曰：\"應天順人。\"又問曰：\"用命，賞於祖；不用命，戮於社，豈是順人？\"父不能答。年二十三，為京兆府參軍卒。","sortOrder":37},
  {"id":"s_work_dnl_2_38","chapterId":"ch_work_dnl_2","text":"李直方嘗第果實，若貢士者。以绿李為首，楞梨為二，櫻桃為三，柑為四。蒲桃為五。或荐荔枝，曰：\"寄舉之首。\"又問：\"栗如之何？\"曰：\"最有實事，不出八九。\"始范晔以諸香品時辈，侯味虛撰《百官本草》，皆此類也。","sortOrder":38},
  {"id":"s_work_dnl_2_39","chapterId":"ch_work_dnl_2","text":"宋濟老於詞場，舉止可笑。嘗试賦，語失官韻，乃撫膺曰：\"宋五又坦率矣！\"因此大著。後禮部上甲乙名，德宗先問：\"宋五坦率否？\"","sortOrder":39},
  {"id":"s_work_dnl_2_40","chapterId":"ch_work_dnl_2","text":"伊慎每求族望以嫁子，李長榮則求時名以嫁子，皆自署為判官。奏言：\"臣不敢學交质罔上。\"德宗從之。","sortOrder":40},
  {"id":"s_work_dnl_2_41","chapterId":"ch_work_dnl_2","text":"李德裕太尉未出學院，盛有詞藻，而不樂應舉。吉甫相，俾親表勉之。衛公曰：\"好驢馬不入行。\"由是以品子叙官也。","sortOrder":41},
  {"id":"s_work_dnl_2_42","chapterId":"ch_work_dnl_2","text":"李吉甫為相，以武相元衡同列，事多不葉。每退，公詞色不怿。掌武啟白曰：\"此出之何難！\"乃請修狄梁公廟。於是武相漸求出镇，智計已聞於早成矣。","sortOrder":42},
  {"id":"s_work_dnl_3_1","chapterId":"ch_work_dnl_3","text":"●卷一·政事上","sortOrder":1},
  {"id":"s_work_dnl_3_2","chapterId":"ch_work_dnl_3","text":"高祖時，嚴甘羅，武功人。剽劫，為吏所拘。上謂曰：\"汝何為作賊？\"對曰：\"飢寒交切，所以為盜。\"上曰：\"吾為汝君，使汝窮乏，吾之罪也。\"赦之。","sortOrder":2},
  {"id":"s_work_dnl_3_3","chapterId":"ch_work_dnl_3","text":"太宗親錄囚徒，死者二百九十人，令來年秋就刑。及期畢至，悉原之。","sortOrder":3},
  {"id":"s_work_dnl_3_4","chapterId":"ch_work_dnl_3","text":"岑文本謂人曰：\"吾見馬周論事多矣！援引事類，扬榷古今，舉要删芜，會文切理。一字不可加，亦不可减。聽之靡靡，令人忘倦。昔之蘇、張、終、贾，正應爾耳。\"（案此條宜列《言語》，原書分門未當，多有類此）","sortOrder":4},
  {"id":"s_work_dnl_3_5","chapterId":"ch_work_dnl_3","text":"姚崇引宋為御史中丞，頃之入相。宋善守法，故能持天下之政；姚善應变，故能成天下之務。二人執性不同，同歸於道；协心翼贊，以致於治。","sortOrder":5},
  {"id":"s_work_dnl_3_6","chapterId":"ch_work_dnl_3","text":"姚元之牧荆州。受代日，民吏泣擁遮不使去；馬鞭、鐙，民皆藏留之。上聞，賜詔褒之。","sortOrder":6},
  {"id":"s_work_dnl_3_7","chapterId":"ch_work_dnl_3","text":"玄宗宴蕃客。唐崇句當音聲，先述國家盛德，次序朝廷歡娱，又贊扬四方慕義，言甚明辨。上極歡。崇因長入人許小客求教坊判官，久之，未敢奏。一日，過崇曰：\"今日崖公甚蚬斗，欲為弟奏請，沈吟未敢。\"崇謂小客有所欲，乃赠絹兩束。後數日，上凭小客肩，行永巷中。小客曰：\"臣請奏事。\"上乃推去之，問曰：\"何事？\"對曰：\"臣所奏，坊中事耳。\"小客方言唐崇，上遽曰：\"欲得教坊判官也？\"小客蹈舞曰：\"真聖明，未奏即知。\"上曰：\"前宴蕃客日，崇辭氣分明，我固賞之，判官何慮不得？汝出報，令明日玄武門來。\"小客歸以語崇，崇蹈舞歡躍。上密敕北軍曰：\"唐崇來，可馳馬踐殺之。\"明日，不果殺。乃敕教坊使范安及曰：\"唐崇何等，敢幹請小客奏事？可决杖，遞出五百里外。小客更不須令來。\"散樂呼天子為\"崖公\"，以歡為\"蚬斗\"，以每日在至尊左右為\"長入。\"","sortOrder":7},
  {"id":"s_work_dnl_3_8","chapterId":"ch_work_dnl_3","text":"顏魯公真卿為監察御史，充河西隴右軍试覆屯交兵馬使。五原有冤，獄决乃雨，郡人呼\"御史雨\"。","sortOrder":8},
  {"id":"s_work_dnl_3_9","chapterId":"ch_work_dnl_3","text":"玄宗御勸政樓大，縱士庶觀看百戲，人物嗔咽，金吾衛士指遏不得。上謂力士曰：\"吾以海內丰稔，四方無事，故盛為宴樂，與萬姓同歡；不謂眾人喧鬧若此，汝有何計止之？\"力士曰：\"臣不能止也。請召嚴安之處分打場，以臣所見，必有可觀。\"上從之。安之周行廣場，以手板畫地，示眾曰：\"逾此者必死！\"是以終日宴，鹹指其畫曰：\"嚴公界境。\"無人敢犯者。","sortOrder":9},
  {"id":"s_work_dnl_3_10","chapterId":"ch_work_dnl_3","text":"玄宗所幸美人，忽中夜夢見人召去，縱酒密會，極歡盡意，醉厭而歸。覺來流汗倦怠，忽忽不樂，因言於上。上曰：\"此術人所為也。汝若复往，但隨時以物記之，必验。\"其夕熟寐，飄然又往。美人半醉，見石砚在前席，密以手文印於曲房屏風上。寤而具啟。上乃潛令人詣宮觀求之，果於東明觀中得其屏風，手文尚在，所居道流已潛遁矣。","sortOrder":10},
  {"id":"s_work_dnl_3_11","chapterId":"ch_work_dnl_3","text":"开元中，山東蝗。姚元崇奏請遣使分捕。上曰：\"蝗虫，天灾也，由朕不德而致焉。卿請捕之，無乃违天乎？\"崇曰：\"《大田》之詩'秉畀炎火'者，捕蝗之術也。古人行之於前，陛下用之於後。行之所以安農除害，國之大事也，陛下熟思之！\"上曰：\"事既古，用可救時，朕之心也。\"遂行之。是時中外鹹以為不可，上謂左右曰：\"與賢相讨論已定。捕蝗之事，敢議者死。\"自是所司結奏，捕蝗十分去四。","sortOrder":11},
  {"id":"s_work_dnl_3_12","chapterId":"ch_work_dnl_3","text":"進士王如謎擼薰約渴豕┓钚冢敫墓伲菪歡朐唬?\"臣女婿王如眉烤伲ザ骰厥冢蛞患暗凇?\"上許之，宣付禮部宜與及第。侍郎李以谘執政，右相曰：\"王如夢惱驢凹暗诜瘢?\"曰：\"與亦得。\"右相曰：\"若爾，未可與之。明經、進士，國家取材之地。若聖恩優異，差可與官。今以及第與之，將何以觀材？\"即自奏聞。居二日，如帽讎笱嗪兀燈镉拧?忽中書門下牒禮部：\"王如每梢覽际浴?\"聞之罔然自失。","sortOrder":12},
  {"id":"s_work_dnl_3_13","chapterId":"ch_work_dnl_3","text":"張九齡累歷刑獄之司，無不察。每有公事，胥吏未敢訊劾，先禀於九齡。召囚面訊曲直，口占案牍，無輕重，皆引服。","sortOrder":13},
  {"id":"s_work_dnl_3_14","chapterId":"ch_work_dnl_3","text":"張延賞為河南尹，官吏有過，未曾屈辱。所犯既頻，不可容者，但謝遣之。先自下拜，立與之辭，即令郡官祖送。由是寮屬敬憚，各修飭，河南大治。","sortOrder":14},
  {"id":"s_work_dnl_3_15","chapterId":"ch_work_dnl_3","text":"德宗時，李納陆梁，上表欲進錢五百萬。上怒謂丞相曰：\"朕豈藉進奉！\"崔文公曰：\"陛下欲知真伪不難，但詔納便以回賜三軍，即其情露矣。納若遵詔，是陛下恩給三軍；納若不從，是其树怨於軍中也。\"上曰：\"賜之何名？\"甫曰：\"兩河用軍已來，天平功居多，朝廷未及優賞。\"上以為然。詔至，納慚恚，構疾而終。","sortOrder":15},
  {"id":"s_work_dnl_3_16","chapterId":"ch_work_dnl_3","text":"廣德二年，春三月，敕工部侍郎李栖筠、京兆少尹崔沔拆公主水碾十所，通白渠支渠，溉公私田，歲收稻二百萬斛，京城賴之。常年命官皆不果敢，二人不避強御，故用之。","sortOrder":16},
  {"id":"s_work_dnl_3_17","chapterId":"ch_work_dnl_3","text":"阎伯，袁州刺史。時征役繁重，袁州特為殘破，伯专以惠化招撫，逃亡皆复。鄰境慕德，襁負而來。數年之間，漁商闐凑，州境大理。及改撫州，百姓相率而隨之，伯未行，或已有先發。伯於所在江津見航，問之。皆雲：\"從袁州來，隨使君往撫州。\"前後相繼，吏不能止，其見愛如此。到職一年，撫州复治。代宗聞之，徵拜戶部侍郎，未至，卒。","sortOrder":17},
  {"id":"s_work_dnl_3_18","chapterId":"ch_work_dnl_3","text":"李封為延陵令，吏人有罪，不加杖罰，但令裹碧頭巾以辱之。隨所犯輕重，以日數為等級，日滿乃釋。吳人著此服出入，州乡以為大恥，皆相勸励無敢犯，賦稅常先諸縣。既去官，竟不捶一人。","sortOrder":18},
  {"id":"s_work_dnl_3_19","chapterId":"ch_work_dnl_3","text":"劉晏為諸道鹽鐵轉運使，時軍旅未寧，西蕃入寇，國用空竭，始於扬州轉運船，每以十只為一綱，載江南穀麥，自淮泗入汴，抵河陰，每船載一千石。扬州遣軍將押至河陰之門，填闕一千石，轉相受給，達太仓，十運無失，即授優勞官。汴水至黃河迅急，將吏典主，數運之後，無不發白者。晏初議造船，每一船用錢百萬。或曰：\"今國用方乏，宜减其費。五十萬猶多矣。\"晏曰：\"不然。大國不可以小道理，凡所創置，須謀經久。船場既興，即其間執事者非一，當有贏餘及眾人。使私用無窘，即官物堅固，若始謀便削，安能長久？數十年後，必有以物料太丰减之者。减半，猶可也；若复减，則不能用。船場既墮，國計亦圯矣。\"乃置十場於扬子縣，专知官十人，競自營辦。後五十餘歲，果有計其餘，减五百千者，是時猶可給。至鹹通末，院官杜侍御又以一千石船，分造五百石船兩舸，用木廉薄。又執事人吳尧卿為扬子縣官，变鹽鐵之製，令商人納榷，隨所送物料，皆計折納，勘每船板、釘、灰、油、炭多少而給之。物复長。軍將十家，即時委弊。","sortOrder":19},
  {"id":"s_work_dnl_3_20","chapterId":"ch_work_dnl_3","text":"韓晉公镇浙西地，痛行捶撻，人皆股忄栗。時德宗幸梁洋，眾心遽惑。公控領十五部人不動搖，而遍懲里胥。或有詰者，雲：\"里胥聞（原註：蓋或問其故，而雲答之之語也）擒賊不獲，懼死而逃，哨聚其類，曰：'我辈進退皆死，何如死中求生乎？'乃撓村劫縣，浸蔓滋多。且里胥者，皆乡縣豪吏，族系相依。杖煞一番老而狡黠者，其後補署，悉用年少，惜身保家，不敢為惡矣。今上在外，不欲更有小寇以撓上心。\"其旨如此。其里胥不杖死者，必恐為亂，乃置浙東營吏，俾掌軍籍，衣以紫服，皆樂為之，潛除酋豪，人不覺也。又痛斷屠牛者，皆暴尸連日。謂人曰：\"草賊非屠牛酾酒，不成結構之計。深其罪，所以絕其謀耳。\"當此际，賊皆失圖。","sortOrder":20},
  {"id":"s_work_dnl_3_21","chapterId":"ch_work_dnl_3","text":"德宗躬親庶政，中外除授皆自攬。監察里行浙東觀察判官趙亻參特授高陵縣令，裴尚書武亦自坊監宰櫟陽，二人同製。後數日，因遊苑中，有執役者，上問：\"何處人？\"雲：\"是高陵百姓。\"上曰：\"汝是高陵人也，我近為汝扌柬得一好長官，知否？\"亻參，貞元六年進士及第，又製策登科。","sortOrder":21},
  {"id":"s_work_dnl_3_22","chapterId":"ch_work_dnl_3","text":"韦皋薨，行軍司馬劉辟知留後，率將士逼監軍使，請奏命辟為帥，以殉軍情。旋舉兵扼鹿頭關下蜀。蜀帥李康弃城走。上敕宰臣選將讨伐。杜黃裳曰：\"保義節度使劉僢、武成節度使高崇文，皆刚毅忠勇可用。\"上曰：\"二人誰為優？\"黃裳曰：\"劉僢自涿州拔城歸闕，扶老携幼，萬人就路，飲食舒惨，與眾共之。居不設樂，動拘法令，峻嚴整肅，人望而畏。付以专征，必著勋績。\"（原註：僢，濟之弟。濟繼怦镇幽州，僢任瀛州刺史，與濟有隙，濟欲害之。母氏潛報僢丆僢乃誓拔所部歸闕。不由驿路而行，秋毫不犯。朝廷優遇，乃割鳳翔府普润、麟遊等縣為行秦州。以普润為理所，保義為軍號。拜僢行秦州刺史，充保義軍節度使。所領將十營於此。僢镇普润七年，後镇涇原）上曰：\"卿選劉僢，甚得其人，然卿慮亦未盡。僢馭眾嚴肅，固是良將。性本倔強，與濟不葉，危急歸命，河朔氣度尚在。常聞鬱鬱扼腕，恨不得名藩，應有深意。若征伐有功，須令镇西川以為寵。况全蜀重地，數十年間，硕德名臣，方可寄任。僢生長幽燕，只知盧龍節製，不識朝廷憲章。向者幽系幕吏，杖殺縣令，皆河朔規矩，我亦為之容貸。若使镇西川，是自掇心腹疾。不如崇文，久將親軍，宽和得眾，用兵沈審。\"乃命為西川行營節度使。崇文下劍門，長子曰暉，不當矢石，特斬之以励。師次綿州，斬硗州節度使李康，疏康擅離征镇，不為拒敵。（原註：當時議者雲康任懷州刺史，收殺武陟尉，即崇文判官宋君平之父。崇文乘此事為之報）入成都日，有若閒暇，命節級將吏，凡軍府事無巨細，一取韦皋故事。一應為辟协從者，但自首併不問。韦皋參佐房式、韦乾度、獨孤密、符載、郄士美（原註：本名犯文宗廟讳），皆即論荐。馆驿巡官沈衍、段文昌，辟迫令刺按，禮同上介，亦接諸公後謁。崇文謂文昌曰：\"公必為將相，未敢奉荐。\"叱起沈衍，令枭首於驿門外。舉酒與諸公盡歡，俳優請為劉辟责買戲，崇文曰：\"僢是大臣謀反，非鼠竊狗盜。國家自有刑法，安得下人辄為戲弄？\"杖優者，皆令戍邊。（原註：房式除給事中，韦乾度除兵部郎中，獨狐密除起居郎，郄士美除太常博士，符載除秘書郎，併未到謁而命下）劉辟就擒，得侍妾二人，皆殊色。監軍使請進上。崇文曰：\"谬當重寄，初收大藩，且要境內肅清，萬姓复業，以宽聖慮。進美婦人，作狐魅天子意，崇文此生不為也。\"遽命配鳏處將校。（原註：上聞之語內臣曰：\"崇文得殊色，不進來，又不自留，是忠直也，是田舍人也。\"）三年為蜀帥，惠化大行。不事威儀，禮賢接士。身與子弟車服玩用無金玉之飾。一朝謂監軍從事曰：\"崇文，河北一健兒，偶然际會，累立戰功，國家酬奖亦極矣。西川是宰相回翔地，崇文叨居已久，豈宜自安？但得為節製邊镇，死於王事，誠願足矣。\"乃陳讓請寧，以至於卒。","sortOrder":22},
  {"id":"s_work_dnl_3_23","chapterId":"ch_work_dnl_3","text":"憲宗宽仁大度，不妄喜怒。便殿與宰臣論政事，容貌恭肅。延英入閣，未嘗不以天下忧樂為意。四方進女樂皆不納。謂左右曰：\"嫔御已多，一旬之中資費盈萬，豈可更剝膚取髓，強娱耳目！\"其俭德忧民如此。","sortOrder":23},
  {"id":"s_work_dnl_3_24","chapterId":"ch_work_dnl_3","text":"吳元濟亂淮西，以宰相裴度為元帥，召對於內殿，曰：\"蔡賊稱兵，昨晚擇帥甚難。天子用將帥，如造大船，以越沧海。其功既多，其成也大，一日萬里，無所不留。若乘一苇，而蹈洪流，即其功也寡，其覆也速。朕今托卿以摧狂寇，可謂一日萬里矣。\"度曰：\"臣雖不才，敢以死效命。\"因泣下沾衿，上亦為之動容。","sortOrder":24},
  {"id":"s_work_dnl_3_25","chapterId":"ch_work_dnl_3","text":"憲宗時，權長孺知鹽福建院。贓败，有司上其獄。崔相群救曰：\"此德舆族子。\"上曰：\"德舆不合有子弟犯贓。使德舆自犯，朕且不赦。\"後知其母老，免死，杖一百，流康州。","sortOrder":25},
  {"id":"s_work_dnl_3_26","chapterId":"ch_work_dnl_3","text":"宣平鄭相之铨衡也，選人相贺得其入铨。劉禹錫弟某為鄭铨註潮州尉，一唱，唯唯而出。鄭呼之却回。鄭曰：\"如此所试，場中無五六人；一唱便受，亦無五六人。此而不奖，何以铨衡？公要何官，去家穩便？\"曰：\"家住常州。\"乃註武進縣尉。選人翕然畏而愛之。及後作相，選官，又稱第一，宜其有後於魯也。","sortOrder":26},
  {"id":"s_work_dnl_3_27","chapterId":"ch_work_dnl_3","text":"又陳諷、張复元，各註畿縣尉。請換縣，允之。既而張却請不換，鄭榜子引張，才入門，報已定，不可改。時人服之。","sortOrder":27},
  {"id":"s_work_dnl_3_28","chapterId":"ch_work_dnl_3","text":"相國晉公裴度出镇興元，因入觐，值范陽節度使朱克融因春衣使，奏曰：\"使者傲，賜衣惡，軍士皆無衣，兼請之。又聞車駕幸東都，請以丁匠五千，先理宮寢。\"敬宗召公問，公對曰：\"克融凶者，此將滅之徵也。欲挫之，則曰：'所遣工役當令供待，速行也。'若欲缓之，則發一詔曰：'聞中官慢易，俟歸，當痛责之。春服，所司之製，我已罪之也。洛之幸，職司所供，固不煩士卒也。三軍請衣，吾無所愛，但非徵役例。'\"克融却出使，宴賂命回，乃赍瑞寶以獻。不數月，克融果死。","sortOrder":28},
  {"id":"s_work_dnl_3_29","chapterId":"ch_work_dnl_3","text":"李衛公镇浙西，甘露僧知主事者訴交代常住什物為前主僧隱没金若幹兩。引證前數年皆遞相交割傳領，文籍分明。且初上之時交領分兩既明，交割之日不見其金。引慮之际，公疑其未盡，微以意揣之。僧乃曰：\"居寺者樂於知事，前後主之者，積年以來，空交分兩文書，其實五金矣。群僧以某孤立，不雜辈流，欲由此挤之。\"因流涕言其冤状。公曰：\"此非難也。\"亻免仰之間，曰：\"吾得之矣。\"乃立召兜子數乘，命關連僧人對事。鹹遣坐簷子，下帘，指揮門下，不令相對。命取黃泥，各令模交付下次金樣，以凭證據。僧既不知形状，竟模不成。數辈等皆伏罪。","sortOrder":29},
  {"id":"s_work_dnl_3_30","chapterId":"ch_work_dnl_3","text":"寶歷中，亳州雲出聖水，服之愈宿疾，亦無一差者。自洛已來及江西數十郡，人爭施金，貸之衣服，以飲焉。獲利千萬，人轉相惑。李德裕在浙西，命於大市集人，置釜取其水，設司取猪肉五斤煮，雲：\"若聖水也，肉當如故。\"逡巡熟烂。自此人心稍定，妖者尋而败露。","sortOrder":30},
  {"id":"s_work_dnl_3_31","chapterId":"ch_work_dnl_3","text":"敬宗時，吏部郎韦僟，宰相忠貞公見素之孫，大歷中刑部員外郎袭靈昌公益之子，孝友貞重。未卯角，繼踵大衅，成長謝事，終身抱戚。及釋褐，命服裹衣不釋絹素。博覽群書，不為諷詠。嗜學強記，自筮仕至夕拜，秉筆記錄，不暫废輟。士流出身，內外扬歷，行能所立，其材何適，必廣詢搜載於別錄。武臣謀將，毅勇忠廉，可將千人，可將萬人，可攻可守，無不博記其姓名。州縣征賦重輕，物產繁闕，凋殘富庶，風俗里路，山川险易，兵甲強弱，無不備詳。山泽利害，國用經費，凡曰能吏，與之较量濟物泽人、除苛靜理之術，蔚為吏師。外國所習，邊疆控扼，曾經歷者，無不與之論。洞晓天之數術，陰陽《易》象，四方灾，朝廷休寧，無不先知。丞相裴公、韦公貫之、李公絳、崔公群、萧公，皆布衣舊，繼登台袞。每有朝廷重事，廟謀未决者，必資於韦公。及敷奏施行，鹹稱折中。或尹京推镇，衔命難理之邦，命屬未之定（案：此句疑有脱誤）其人，咨於韦。韦曰：\"某宽和通簡，某刚劲峻急，某恤物利人，某殘刻執滯，某明於辨博，某練達刑書，某可以任繁剧，某可以辑凋瘵。裨贊朝略，未嘗有私。性沈厚容納，進退情理。而士大夫親昵交友，莫能知者。五丞相敬服，以為龟鏡，相顧而叹曰：\"吾辈五人智慮，自昏及晓筹度事，不逮韦公唾之間。房、杜、姚、宋，相業著於簡書，吾恨不得親承規矩；韦公之才，但恐房、杜、姚、宋，不相遠也。\"","sortOrder":31},
  {"id":"s_work_dnl_3_32","chapterId":"ch_work_dnl_3","text":"劉桂州栖楚為京兆尹，號令嚴明，誅罰不避權势。先是京城惡少及屠沽商販多系名諸軍，幹犯府縣法令，有罪即逃入軍中，無由追捕。劉公為尹，一皆窮治。有匿軍中名目，自稱百姓者，罪之。坊市奸偷宿猾屏跡。嘗有儒生入市，市內有一軍人，乘醉誤突生驢過，旁諸少年噪曰：\"癡男子，尚敢近衣冠也！\"與屬吏言，不傷氣，未嘗叱责一官人。常謂府縣官曰：\"諸公各自了本分公事，晴天美景，恣意遊賞，勿致拘束。\"","sortOrder":32},
  {"id":"s_work_dnl_3_33","chapterId":"ch_work_dnl_3","text":"權實子范，為殿中侍御史知巡。有小吏從市求取，事發，笞十數。他日复有如此者，白於台長，杖背十五。同列疑其罪同罰異。權對曰：\"前史所取者，名屬左軍，台之威令不振久矣，百司尚有不禀奉者，况凭禁軍之势耶！彼受賄於此辈，猶是抑豪強，可以矜减。後吏則挟台之威以恐百姓，杖背猶為至輕。","sortOrder":33},
  {"id":"s_work_dnl_3_34","chapterId":"ch_work_dnl_3","text":"張杰夫前白襄州從事至京，失馬，台中三院多親友，為求馬价。同列或有，不肯署字，權獨先署，謂眾曰：\"某向不與張熟，但聞其在窮丧馬，正當求祿求知之际，不可使徒行。且一千何足為輕重？\"","sortOrder":34},
  {"id":"s_work_dnl_3_35","chapterId":"ch_work_dnl_3","text":"开成中，李石作相兼度支。一日早朝中箭，遂出镇江陵。自此詔宰相坐簷子，出入令金吾以三千人宿直。李衛公复相，判雲：\"在具瞻之地，自有國容；居無事之時，何勞武備？所送併停。\"（原註：李衛公初入相是大和七年，居李石之前，衛兵不因李事。記之者有誤）","sortOrder":35},
  {"id":"s_work_dnl_3_36","chapterId":"ch_work_dnl_3","text":"武宗將賜杜之子無逸衣，所司條列其目衫色奉進。上曰：\"不可賜白衣。又其年幼未有官，不可假以服色。但賜青衣無衫可也。\"","sortOrder":36},
  {"id":"s_work_dnl_3_37","chapterId":"ch_work_dnl_3","text":"會昌中，晉陽令狄惟謙，梁公之後，善為政。州境亢陽，涉春夏，數百里水泉耗竭。祷於晉祠者數旬，無應。有女巫郭者，攻符術厭勝之道。有監軍携至京師，因緣出入宮掖。其後歸，遂號\"天師。\"天既久不雨，境內莫知所為，皆曰：\"若得天師至晉祠，則旱不足忧矣。\"惟謙請於主帥，曰：\"灾厲流行，庶焦灼。若非天師一救，萬姓恐無聊生。\"於是主帥親自為請，巫者許之。惟謙具幡蓋，迎自私室，躬為控馬。既至祠所，盛設供帳飲饌。自旦及夕，立於庭下，如此者兩日。語惟謙曰：\"為爾飛符於上帝，請雨三日，雨當足矣。\"觀者雲集，三夕，雨不降。又曰：\"此土灾，亦由縣令無德。為爾再請，七日當有雨。\"惟謙引罪於己，奉之愈恭。及期，又無應，郭乃骤索馬入州宅。惟謙曰：\"天師已為百姓此來，更乞祈祷。\"勃然怒骂曰：\"庸琐官人，不知禮！天時未肯下雨，留我复奚為？\"惟謙謝曰：\"明日排比相送。\"遲明，郭將歸，肴醴一無所設。坐於堂上，大怒。曰：\"左道女子，妖惑日久，當須毙此，焉敢言歸？\"叱左右曳於神堂前，杖背三十，投於潭水。祠後有山極高，遂令設席焚香，端笏立於其上。阖縣駭雲：\"長官打殺天師。\"馳走者紛紜。祠上忽有雲如車蓋，覆惟謙。逡巡四合，雷震數聲，甘泽大澍數尺。於是士民自山顶擁惟謙而下。州將初责以专殺巫者，既而嘉其精誠有感，與監軍表言其事，製書褒曰：\"狄惟謙剧邑良才，忠臣華胄。睹此天厲，將殫下民，當請祷於晉祠，類投巫於鄴縣。曝山極之畏景，事等焚軀；起天际之油雲，法同剪爪。遂使旱風潛息，甘泽施流。昊天猶鑒於克誠，餘志豈忘於褒善。特頒朱绂，俾耀銅章。勿替令名，更昭殊績。\"賜章服，併錢五十萬。後歷絳、隰二州刺史，所治皆有名稱。","sortOrder":37},
  {"id":"s_work_dnl_3_38","chapterId":"ch_work_dnl_3","text":"盧元公鈞镇北都，推官李璋幕中飲酒醉，决主酒軍職衙前虞候。明日，元公出赴行香，其徒百八十人橫街見公，論無小推巡决得衙前虞候例，元公命收禁责状。至衙，命李推官所决者更决配外镇，其餘虞候各罰金，內外不测。璋惶恐，衣公服求見。公問：\"何事公服？請十郎衫麻鞋相見。\"璋欲引咎，公語皆不及。臨去，曰：\"十郎不决衙前虞候，只决所由。假使错誤，亦不可縱。况太原邊镇，無故二百虞候橫拦節度使，須當挫之。\"璋後為尚書右丞。","sortOrder":38},
  {"id":"s_work_dnl_3_39","chapterId":"ch_work_dnl_3","text":"盧公镇太原，同日補左右都押衙。其牒置案前階上，補右者先自探之，展見\"右\"字，却摺於階上，退身致詞雲：\"在軍門幾十年，前後主辦，未嘗败績。伏蒙右補，情有嫌鬱，謹未敢受。\"公曰：\"君近前。君知軍中無年勞，知有拔卒為將否？君不同蔡袭，有功朝廷，合議超寵。\"其人未遜，公复召前，併排衙大校悉前，曰：\"君快恨右補都衙軍，不見盧鈞耶？\"軍中見節使自呼姓名，皆悚然。\"盧鈞進士出身，歷中外五十年，豈不消中書一頓飯？臨年暮齒，亦是得一裹香紙，合如何？\"於是牙中感泣，領拜謝而去。蔡受左都押衙，即日表荐為上將軍，尋建幢，節镇湖南。","sortOrder":39},
  {"id":"s_work_dnl_3_40","chapterId":"ch_work_dnl_3","text":"武宗好神仙，道士趙歸真者，出入禁中，自言數百歲，上頗敬之。與道士劉元靖力排釋氏，上惑其說，遂有废寺之詔。宣宗即位，流歸真於嶺南，戮元靖於市。","sortOrder":40},
  {"id":"s_work_dnl_3_41","chapterId":"ch_work_dnl_3","text":"宣宗性至孝，奉養鄭太後於大明宮，不為別宮。舅鄭光為平盧、河中兩镇節度使。大中七年，自河中來朝。上詢其政事，光不知文字，對皆鄙俚。上命留光奉朝謁。後以光生計為忧，乃厚賜金帛，不复更委方镇。","sortOrder":41},
  {"id":"s_work_dnl_3_42","chapterId":"ch_work_dnl_3","text":"宣宗微行至德觀，有女道士盛服浓妆者，赫怒歸宮，立召左街功德使末叔康，令盡逐去，別選男子二人，住持其觀。","sortOrder":42},
  {"id":"s_work_dnl_3_43","chapterId":"ch_work_dnl_3","text":"武宗於大明筑望仙台，其势中天。宣宗即位，殺道士趙歸真，而罢望仙台院。大中八年，复命葺之。右補闕陳嘏已下面論其事，立罢之，以其院為文思院。","sortOrder":43},
  {"id":"s_work_dnl_3_44","chapterId":"ch_work_dnl_3","text":"宣宗能納諫。李遂除嶺南節度，已命中使頒旄節矣，給事中萧仿封還詔書。上正聽樂，不暇別差中使，謂伶人曰：\"汝可就李遂宅，却唤使來。\"旄節及遂門而返。劉潼自鄭州刺史除桂州觀察，右諫議大夫鄭裔綽上疏言不可。中使至鄭，賜告身已數日，亦命追還。","sortOrder":44},
  {"id":"s_work_dnl_3_45","chapterId":"ch_work_dnl_3","text":"宣宗命相，一出於己。嘗詔枢密院，兵部侍郎判度支萧鄴可同中書門下平章事，仰指揮學士院降麻處分。枢密使王歸長、馬公儒以鄴先判度支，再審聖旨，未審下落，抑或仍舊？上疑左右党萧，乃詔翰林院，戶部侍郎判戶部事崔慎由，可工部尚書平章事，落下判戶部。","sortOrder":45},
  {"id":"s_work_dnl_3_46","chapterId":"ch_work_dnl_3","text":"故事：京兆尹在私第，但奇日入府，偶日入遞院。崔郢為京兆尹，囚徒逸獄，始命造京兆尹廨宅，京兆尹不得離府。宣宗以崔罕、郢併败官，面召翰林學士韦澳授之，便令赴任。上賜度支錢二萬貫。令造府宅。澳公正方嚴，吏不敢欺。委長安縣尉李信主其事，造成廨宇，極一時壮麗，尚有羨缗却進，澳連書信兩上下考。","sortOrder":46},
  {"id":"s_work_dnl_3_47","chapterId":"ch_work_dnl_3","text":"京兆府進士、明經解送，設殊、次、平等三級，以甄行能，其後撓於權势而不行。宣宗時，韦澳為尹，榜曰：\"禮部舊格，本無等第；京府解送，不當區分。今年所送省進士、明經等，併以納策试前後為定，更不分等第之限。\"詞科本以京兆等第為梯級，建中二年，崔元翰、崔敖、崔備三人，府元、府副、第三人；於邵知貢舉，依次放及第，蓋推崇藝實不能易也。自文學道丧，朋党弊興，紛競既多，澳雖憤浇弊而革之，然人亦惜其故事之废。","sortOrder":47},
  {"id":"s_work_dnl_3_48","chapterId":"ch_work_dnl_3","text":"牛丛任拾遺、補闕五年，多論事，上密記之。後自司勋員外郎為睦州刺史，入謝，上命至軒砌，問曰：\"卿頃任諫官，頗能舉職，今忽為遠郡，得非宰臣以前事為懲否？\"丛曰：\"新製：未任刺史縣令，不得任近侍官。宰臣以是奖擢，非嫌忌也。\"上曰：\"賜紫。\"丛謝畢，前曰：\"臣所衣緋衣是刺史借服，不審陛下便賜臣紫，為复別有進止？\"上遽曰：\"且賜緋。\"上慎重名器，未嘗容易，服章之賜，一朝無濫邀者。","sortOrder":48},
  {"id":"s_work_dnl_3_49","chapterId":"ch_work_dnl_3","text":"李藩自司勋郎中，知製誥，衣绿如故。鄭裔綽自給事以論驳楊漢公忤旨，出商州刺史，始賜緋。沈自禮部侍郎為浙東觀察，方賜紫。苗恪自司勋員外郎，除洛陽縣令，藍衫赴任。裴處權自司封郎中出河南少尹，到任，本府奏荐賜緋，給事中崔罕驳還。手詔褒之，曰：\"有不當，卿能驳還，職業既修，朕何所慮？\"","sortOrder":49},
  {"id":"s_work_dnl_4_1","chapterId":"ch_work_dnl_4","text":"●卷二·政事下","sortOrder":1},
  {"id":"s_work_dnl_4_2","chapterId":"ch_work_dnl_4","text":"宣宗密召學士韦澳，屏左右，謂澳曰：\"朕每與節度、觀察、刺史語，要知所委州郡風俗物產，卿采訪撰次一書進來。\"澳即采十道四藩志，撰成，題曰《處分語》，自寫面進，雖子弟不得聞。後數日，薛弘宗除邓州刺史，澳有別業在南陽，召弘宗餞之。弘宗曰：\"昨日中謝，聖上處分當州事驚人。\"澳訪之，即《處分語》中事也。","sortOrder":2},
  {"id":"s_work_dnl_4_3","chapterId":"ch_work_dnl_4","text":"宣宗獵城西，及渭水，見父老數十人，於佛祠設斋。上問之，父老曰：\"臣醴泉縣百姓，本縣令李君有異政，考秩已滿，百姓借留，詣府乞未替，來此祈佛。\"上歸，於御大書君名。中書兩擬醴泉令，上皆抹去之。逾歲，懷州刺史闕，請用人，御筆曰：\"醴泉縣令李君可為懷州刺史。\"人莫测也。君中謝，上諭其事。","sortOrder":3},
  {"id":"s_work_dnl_4_4","chapterId":"ch_work_dnl_4","text":"宣宗厚待詞學之臣，於翰林學士恩禮特異，宴遊無所間，惟於遷轉皆守常法。皇甫自吏部員外郎召入，改司勋員外，計吏員二十五个月，轉司封郎中，知製誥。孔溫裕自禮部員外郎改司封員外，召入二十五个月，改司勋郎中，知製誥。","sortOrder":4},
  {"id":"s_work_dnl_4_5","chapterId":"ch_work_dnl_4","text":"樂工羅程者，善彈琵琶，為第一，能变易新聲。得幸於武宗，恃恩自恣。宣宗初，亦召供奉。程既審上晓音律，尤自刻苦，往往令侍嫔御歌，必為奇巧聲動上，由是得幸。程一日果以眦睚殺人，上大怒，立命斥出，付京兆。他工辈以程藝天下無双，欲以動上意。會幸苑中，樂將作，遂旁設一虛坐，置琵琶於其上。樂工等羅列上前，連拜且泣。上曰：\"汝辈何為也？\"進曰：\"羅程負陛下，萬死不赦。然臣辈惜程藝天下第一，不得永奉陛下，以是為恨。\"上曰：\"汝辈所惜羅程藝耳，我所重者高祖、太宗法也。\"卒不赦程。","sortOrder":5},
  {"id":"s_work_dnl_4_6","chapterId":"ch_work_dnl_4","text":"故事：每罢左護軍，由右出；罢右護軍，由左出；蓋防微也。宣宗既以法馭下，每罢去，辄令自本軍出，中外不能测。","sortOrder":6},
  {"id":"s_work_dnl_4_7","chapterId":"ch_work_dnl_4","text":"宣宗雖宽仁愛人，然刻於用法，嘗曰：\"犯朕法，雖我子弟亦不宥。\"內外由是畏憚。","sortOrder":7},
  {"id":"s_work_dnl_4_8","chapterId":"ch_work_dnl_4","text":"優人祝漢貞者，累朝供奉，滑稽善伺人意，出口為七字語。上有指顧，遽令摹詠，捷若夙篝，尤為帝所喜。上行幸，召漢貞前，抵掌笑談，頗言及外間事。上正色曰：\"我養汝辈供戲樂耳，敢幹預朝政耶？\"遂疏之。後其子犯贓，上命杖殺，而徙漢貞於邊。","sortOrder":8},
  {"id":"s_work_dnl_4_9","chapterId":"ch_work_dnl_4","text":"柳仆射仲郢任鹽鐵使，奉敕：医人劉集宜與一場官。集医行闾阎間，頗通中禁，遂有此命。仲郢手疏執奏曰：\"劉集之藝若精，可用為翰林医官，其次授州府医博士。委務銅鹽，恐不可责其課最。又場官賤品，非特敕所宜，臣未敢奉詔。\"宣宗御筆批：\"劉集與絹百匹，放東回。\"數日，延英對，曰：\"卿論劉集大好。\"","sortOrder":9},
  {"id":"s_work_dnl_4_10","chapterId":"ch_work_dnl_4","text":"宣宗獵苑北，見樵者數人，因留與語。言涇陽百姓，因問：\"邑宰為誰？\"曰：\"李行言。\"\"為政何如？\"曰：\"性執滯。有劫賊五六人匿軍家，取來直不肯與，盡杖殺之。\"上還宮，以書其名帖於殿柱上。後二年，行言領海州，中謝。上曰：\"曾宰涇陽否？\"對：\"在涇陽二年。\"上曰：\"賜金紫。\"再謝，上曰：\"卿知著紫來由否？\"行言奏不知。上顧左右，取殿柱帖子來宣示。","sortOrder":10},
  {"id":"s_work_dnl_4_11","chapterId":"ch_work_dnl_4","text":"宣宗微疾，召医工梁新對脈（原註：禁中以诊脈為對脈）。數日，自陳求官，不與，但每月別給錢三百缗。","sortOrder":11},
  {"id":"s_work_dnl_4_12","chapterId":"ch_work_dnl_4","text":"高尚書少逸為陝州觀察使，有中使於石硤驿怒餅餌黑，鞭驿吏見血。少逸封餅以進，中使亦自言。上怒曰：\"高少逸已奏來。深山中如此食，豈易得也？\"遂謫配恭陵，复令過陝赴洛。","sortOrder":12},
  {"id":"s_work_dnl_4_13","chapterId":"ch_work_dnl_4","text":"宣宗賜鄭光雲陽、縣田，皆令免稅。宰臣奏不可。上曰：\"朕初不思爾。卿等每為匡救，必極言毋避。親戚之間，人所難言，苟非忠愛，何以及此！\"","sortOrder":13},
  {"id":"s_work_dnl_4_14","chapterId":"ch_work_dnl_4","text":"鄭光，宣宗之舅，別墅吏頗恣橫，為里中患。積歲征租不入。戶部侍郎韦澳為京兆尹，擒而械系之。及延英對，上曰：\"卿禁鄭光莊吏，何罪？\"澳具奏之。上曰：\"卿擬如何處置？\"澳曰：\"臣欲於法。\"上曰：\"鄭光甚惜，如何？\"澳曰：\"陛下自內庭用臣為京兆，是使臣理畿甸積弊。若鄭光莊吏積年為蠹，得宽重典，則是朝廷之法獨行於貧下，臣未敢奉詔。\"上曰：\"誠如此。但鄭光再三幹朕，卿與貸法，得否？不然，重决貸死，可否？\"澳曰：\"臣不敢不奉詔，但許臣且系之，俟征積年稅物畢放出，亦可為懲戒。\"上曰：\"可也。為鄭光所稅扰乡，行法自近。\"澳自延英出，径入府杖之，征欠租數百斛，乃縱去。","sortOrder":14},
  {"id":"s_work_dnl_4_15","chapterId":"ch_work_dnl_4","text":"宣宗京兆府有厭蠱獄，作符劾者郭群，屬飛龍，三牒不可取。韦澳入奏之，上曰：\"郭群屬飛龍，不错否？\"翌日，內養押郭群付府。","sortOrder":15},
  {"id":"s_work_dnl_4_16","chapterId":"ch_work_dnl_4","text":"宣宗每行幸內库，以紫衣金魚、朱衣銀魚三二副隨駕，或半年或終年不用一副，當時以得朱、紫為榮。","sortOrder":16},
  {"id":"s_work_dnl_4_17","chapterId":"ch_work_dnl_4","text":"宣宗坐朝，次對官趨至，必待氣息平均，然後問事。令狐進李遠為杭州，上曰：\"我聞李遠詩雲，'長日惟消一局棋'，何以臨郡？\"對曰：\"詩人言，不足有實也。\"仍荐廉察可任，乃許之。","sortOrder":17},
  {"id":"s_work_dnl_4_18","chapterId":"ch_work_dnl_4","text":"宣宗视遠《郡謝上表》，左右曰：\"不足煩聖慮。\"上曰：\"遠郡更無非時章奏，只有此《謝上表》，安知其不有情恳乎？吾不敢忽。\"","sortOrder":18},
  {"id":"s_work_dnl_4_19","chapterId":"ch_work_dnl_4","text":"宣宗暇日，召翰林學士韦澳入。上曰：\"要與卿款曲。少間出外，但言論詩。\"上乃出詩一篇。有小黃門置茶床訖，亟屏之。乃問：\"朕於敕使如何？\"澳曰：\"威製前朝無比。\"上閉目搖手曰：\"總未，依前怕他。在卿如何，計將安出？\"澳既不為之備，率意對曰：\"謀之於外庭，即恐有太和事，不若就其中揀拔有才者，委以計事。\"上曰：\"此乃末策。朕行之。初擢其小者，至黃、至绿、至緋，皆感恩；若紫衣掛身，即合為一片矣。\"澳漸汗而退。","sortOrder":19},
  {"id":"s_work_dnl_4_20","chapterId":"ch_work_dnl_4","text":"大中初，雲南朝貢及西川质子人數漸多，節度使奏請厘革。有讠人錄詔報雲南，雲南詞不遜。詞雲：\"一人有慶，方當萬國而來朝；四海為家，豈計十人之有費。\"爾後納貢不時，境上骚扰。宣宗崩，命內臣告哀，行及其國。南詔王丰已死，子坦綽酋龍繼立，號曰\"驃信\"，凶很悖慢。謂：\"我國亦有丧，朝廷不賜弔問，詔書又賜故王。\"於是待使者禮薄，旋又累犯封疆，掠越。朝廷以驃信名近廟讳，复無使朝貢，不告國丧，遂絕册立弔祭使。杜再入辅，議曰：\"雲南向化七十餘年，瀘水之陰，弓弛甲解，諸蠻納職如編，撫慰懷來，不勞筹策。二十年間再領西蜀，近者費用多於往年，聚蓄不得盈實，今者雖起衅端，未深為敵，宜化以禮誼。夷狄之君，立名犯上，難為奏聞，下詔令其改更。縱未行典册，且發使弔祭，以恩信全其國禮。詔清平官已下，諭其君長，名犯廟讳，朝廷未可便行册命，驃信必遣使謝恩，易名獻貢。若不納使臣入國城，即遙陳祭禮，令使臣錄文，併赙赠帛以送驃信，具報清平官已下。\"乃命左司郎中孟穆為雲南弔祭宣撫册命使，已報破越，攻邛崍關，使臣逗留數月不發。未幾，出镇鳳翔，議多異同，复言未可發使，乃詔西川令遣使示朝旨。爾後連陷城邑，征兵讨逐，朝貢遂絕。","sortOrder":20},
  {"id":"s_work_dnl_4_21","chapterId":"ch_work_dnl_4","text":"宣宗時，党項叛扰，推其由，乃邊將貪暴，利其羊馬，多欺取之。始用右諫議大夫李福為夏州節度，刑部侍郎畢衔鼓詼龋罄砬渑崾段詼取７?日，臨軒戒敕。","sortOrder":21},
  {"id":"s_work_dnl_4_22","chapterId":"ch_work_dnl_4","text":"宣宗時，浙東觀察李讷為軍士所逐，貶朗州刺史。讷褊狷，遇軍士不以禮，遂及於難。監軍使王宗景撫循無状，杖四十，流恭陵。自此戎臣失律，監軍使皆從坐。","sortOrder":22},
  {"id":"s_work_dnl_4_23","chapterId":"ch_work_dnl_4","text":"大中十二年後，藩镇繼有叛亂，宣州都將康全泰逐觀察使鄭薰，湖南都將石再順逐觀察使韓琮，廣州都將王令寰逐節度使楊發，江西都將毛鶴逐觀察使鄭憲。宣宗命淮南節度使檢校左仆射平章事崔铉兼領宣、池、歙三州觀察使，以宋州刺史溫璋為宣州刺史，以右金吾將軍蔡袭為湖南觀察使，以涇原節度使李承勋為廣州節度使，以光祿卿韦宙為江西觀察使，以鄰道兵送赴任，諸州皆平。","sortOrder":23},
  {"id":"s_work_dnl_4_24","chapterId":"ch_work_dnl_4","text":"令狐公，文公楚之子也。自翰林入相，最承恩泽。先是宣宗詔諸州刺史，秩滿不得径赴別郡，須歸朝奏對後，許之任。以隨、房鄰地，除一故舊，径令赴州。上覽《謝上表》，因問曰：\"此人緣何得便之任？\"對曰：\"比近換守，庶幾其便於迎送。\"上曰：\"朕以比來郡守因循，故令至京師，親問其施設優劣，將行黜陟。此令已行而复变之，宰相可謂有權。\"時方寒，汗透重裘。上留意郡守，凡選尤難其人。（案：此下有脱文）","sortOrder":24},
  {"id":"s_work_dnl_4_25","chapterId":"ch_work_dnl_4","text":"宣宗在位逾一紀，忧勤無怠。天下雖小康，而間水旱。又宣、洪、潭、青、廣等數郡軍亂，蓋將帥失於統御，而不日安辑，時稱小太宗。","sortOrder":25},
  {"id":"s_work_dnl_4_26","chapterId":"ch_work_dnl_4","text":"大中已後，宰相堂判無及路巖者。杜尚書忄舀，之弟，守泗州，為庞勋所围，以孤城自全；高錫望守滁州，婴城固拒而死。巖判崔雍状雲：\"錫望守城而死，已有追崇；杜忄舀孤壘獲全，尋加異奖。\"","sortOrder":26},
  {"id":"s_work_dnl_4_27","chapterId":"ch_work_dnl_4","text":"王尚書式，仆射起之子，見重於武宗。嘗自荐於上，稱有文武才。式有武幹，善用兵。既平浙東，徐州溫璋失守。朝廷以彭門頻年逐帥，乃自河陽移式，領河陽全軍赴任。駐軍境外而缓進。徐州將士自王智興後，驕橫難製。其銀刀都父子相承，每日三百人守衛，皆露刃坐於兩廊夹幕下，稍不如意，相顧笑議於飲食間，一夫號呼，眾卒相和。節度多懦怯，聞亂則後門逃去，如是且久。聞式至境，先遣衙队三百人遠接。式衩衣坐胡床受參，乃問其悖慢之罪，命盡斬於帳前。既而後來者莫知前者已死，又斬之。數日，銀刀都數千人殆盡。徐州軍士平居自恃吞噬，及式衣袄子半臂，曳履危坐，拱手栗縮就死，無一人敢拒者。其後親戚相訝，不能自知焉。式既视事，餘党併遠配，郡中小安矣。","sortOrder":27},
  {"id":"s_work_dnl_4_28","chapterId":"ch_work_dnl_4","text":"式初為京兆少尹，多從前诃者令遠，時或避之他適，京城號為\"邓子\"。性放率，不拘小節。長安坊中有夜拦街鋪設祠樂者，遲明未已，式過之，駐馬寓目。巫者喜，奉主人杯，跪獻於馬前曰：\"主人多福！感達官來，顧酒味稍美，敢進寿觴。\"式取而飲之。行百餘步复回，曰：\"向之酒甚惡，可更一杯。\"复據鞍引滿而去，其放率如此。","sortOrder":28},
  {"id":"s_work_dnl_4_29","chapterId":"ch_work_dnl_4","text":"太宗閱医方，見明堂圖，人五臟之系，鹹附於背。乃怆然曰：\"今律杖笞背，奈何髀背分受？\"乃詔不得笞背。","sortOrder":29},
  {"id":"s_work_dnl_4_30","chapterId":"ch_work_dnl_4","text":"梁公以度支之司，天下利害，郎嘗闕，求之未得，乃自職之。","sortOrder":30},
  {"id":"s_work_dnl_4_31","chapterId":"ch_work_dnl_4","text":"高宗時，司農欲以冬藏餘菜賣之。以墨敕示仆射蘇良嗣。良嗣判曰：\"昔公儀相魯，猶拔園葵，况臨萬乘而販蔬鬻菜？\"上從之，不行。","sortOrder":31},
  {"id":"s_work_dnl_4_32","chapterId":"ch_work_dnl_4","text":"开元始年，上悉出金銀珠玉錦繡之物於朝堂，若山積，皆焚之，示不复御用。","sortOrder":32},
  {"id":"s_work_dnl_4_33","chapterId":"ch_work_dnl_4","text":"姚开府凡三為相，皆兼兵部。軍镇道里與騎卒之數，皆能暗計之。","sortOrder":33},
  {"id":"s_work_dnl_4_34","chapterId":"ch_work_dnl_4","text":"郭尚書元振，始為梓州射洪尉，征求無厭，至掠部人賣為奴婢者甚眾。武後聞之，使籍其家，唯有書數卷。後令問其資财所在，皆以濟人為對，於是奇而免之。大足年間，遷涼州都督。元振風神伟壮，善於撫御。在涼州五年，夷夏畏慕，令行禁止，牛羊被野，路不拾遺，諸蕃聞風請朝獻。唐興以來，善為涼州者，郭居其最。","sortOrder":34},
  {"id":"s_work_dnl_4_35","chapterId":"ch_work_dnl_4","text":"蘇，神龍中，給事中兼宏文馆學土，轉中書舍人。時父瑰為宰相，父子同掌枢密，時人榮之。屬機事填委，凡製誥皆出其手。中書令李峤叹曰：\"舍人思如泉涌，峤所不及。\"後為中書侍郎，與宋同知政事。刚正，多所裁斷，皆順從其美，甚悅之。嘗謂人曰：\"吾與賢父子前後皆同時為宰相。仆射長厚，誠為國器；獻可替否，罄盡臣節，過其父也。\"後罢政，拜禮部尚書而薨。及葬日，元宗遊鹹宜宮，將舉獵，聞丧出，怆然曰：\"蘇今日葬，吾寧忍娱遊乎？\"遂中路還宮。","sortOrder":35},
  {"id":"s_work_dnl_4_36","chapterId":"ch_work_dnl_4","text":"姚崇以拒太平公主，為申州刺史，玄宗深德之。太平既誅，征為同州刺史。素與張說不葉，說諷趙彦昭彈之，玄宗不納。俄校獵於渭濱，密令會於行所。玄宗謂曰：\"卿頗獵乎？\"崇對曰：\"此臣少所習也。臣年三十，居泽中，以呼鷹逐兔為樂，猶不知書。張藏謂臣曰：'君當位極人臣，無自弃也。'爾來折節讀書，以至將相。臣少為獵師，老而猶能。\"上大悅，與之偕為臂鷹，遲速在手，動必稱旨。玄宗歡甚，樂則割鮮，間則咨以政事。備陳古今理亂之本上之，可行者必委曲言之。玄宗心益开，聽之宜宜忘倦，軍國之務，鹹訪於崇。崇罢冗職，修舊章，內外有叙。又請無赦宥，無度僧，無數遷吏，無任功臣以政，玄宗悉從之，而天下大理。","sortOrder":36},
  {"id":"s_work_dnl_4_37","chapterId":"ch_work_dnl_4","text":"李當尚書镇南梁，境內有朝士莊產，子孫侨寓其間，而不肖者相效為非。前牧以其各有階緣，弗克禁止，闾巷苦之。當嚴明有斷，處分宽織篾籠，召其尤者，詰其家世譜第，在朝姻親。乃曰：\"郎君藉如是地望，作如此行止，無乃辱於存亡乎？今日所懲，賢親眷聞之，必賞老夫，勉旃。\"遽命盛以竹籠，沉於漢江。由是其儕惕息，各務戢斂焉。","sortOrder":37},
  {"id":"s_work_dnl_4_38","chapterId":"ch_work_dnl_4","text":"崔珏二子凶惡，節度使劉都尉判之曰：\"崔氏二男，荆州三害，不免行刑也。\"","sortOrder":38},
  {"id":"s_work_dnl_4_39","chapterId":"ch_work_dnl_4","text":"梨園弟子有胡雏，善吹笛，尤承恩。嘗犯洛陽令崔隱甫，已而走禁中。玄宗非時托以他事召隱甫對，胡雏在侧，指曰：\"就卿乞得此否？\"隱甫奏曰：\"陛下此言，是輕臣而重樂人也，臣請休官！\"再拜而出。玄宗遽曰：\"朕與卿戲。\"遂令曳出，才至門外，杖殺之。俄而复敕釋放，已死矣，乃賜隱甫絹百匹。","sortOrder":39},
  {"id":"s_work_dnl_4_40","chapterId":"ch_work_dnl_4","text":"劉忠州晏，通百货之利，自言如見地上錢流。每入朝乘馬，則為鞭算。嘗言居取安便，不務華屋；食取飽適，不務多品；馬取穩健，不務毛色。","sortOrder":40},
  {"id":"s_work_dnl_4_41","chapterId":"ch_work_dnl_4","text":"江淮贾人，有積米以待踴貴。畫圖為人，持米一斗，货錢一千，以懸於市。扬州留後徐粲杖殺之。","sortOrder":41},
  {"id":"s_work_dnl_4_42","chapterId":"ch_work_dnl_4","text":"李惠登自軍吏為隨州刺史，自言：\"吾二名惟識'惠'字，不識'登'字。\"為政清净無跡，不求人知，兵革之後，阖境大化。","sortOrder":42},
  {"id":"s_work_dnl_4_43","chapterId":"ch_work_dnl_4","text":"武相元衡遇害，朝臣震恐，多有上疏請不窮究。獨尚書左丞許孟容奏\"當罪京兆尹，誅金吾鋪官，大索求賊\"，行行然有前辈風采。時京兆尹裴武問吏，吏曰：\"殺人者未嘗得脱。\"數日，果擒張晏辈。","sortOrder":43},
  {"id":"s_work_dnl_4_44","chapterId":"ch_work_dnl_4","text":"王悅為镇將，清苦肅下。有軍士犯禁，杖而枷之，約曰：\"百日乃脱，未及百日而脱者死。\"又曰：\"我死則脱，爾死則脱，天子之命則脱。非此，臂可折，約不可改也。\"由是秋毫不犯。","sortOrder":44},
  {"id":"s_work_dnl_4_45","chapterId":"ch_work_dnl_4","text":"李建為吏部郎中，嘗曰：\"方今秀茂皆在進士。使吾得志，當令登第之歲，集於吏部，使尉紧縣；既罢复集，使尉望縣；既罢又集，使尉畿縣；而升於朝。大凡中人三十成名，四十乃至清列，遲速為宜。既登第，遂食祿；既食祿，必登朝，誰不欲也？無淹滯以守常限，無紛競以求再捷。下曹得其修舉，上位得其更歷。就而言之，其利甚溥。\"議者是之。","sortOrder":45},
  {"id":"s_work_dnl_5_1","chapterId":"ch_work_dnl_5","text":"●卷二·文學","sortOrder":1},
  {"id":"s_work_dnl_5_2","chapterId":"ch_work_dnl_5","text":"文中子見王勃少弄筆砚，問曰：\"爾為文乎？\"曰：\"然。\"因與題《太公遇文王贊》。曰：\"姬昌好德，呂望潛華。城闕雖近，風雲尚賒。漁舟倚石，釣浦橫沙。路幽山僻，溪深岸斜。豹韜攘惡，龍鈐辟邪。雖逢相識，猶待安車。君王握手，何期晚耶？\"","sortOrder":2},
  {"id":"s_work_dnl_5_3","chapterId":"ch_work_dnl_5","text":"杜淹，國初為掾吏，嘗業詩。文皇勘定內難，詠斗雞寄意曰：\"寒食東郊道，飛翔競出籠。花冠偏照日，芥羽正生風。顧敵知心勇，先鳴覺氣雄。長翘頻埽陣，利距屢通中。\"文皇覽之，嘉叹數四，遽擢用之。","sortOrder":3},
  {"id":"s_work_dnl_5_4","chapterId":"ch_work_dnl_5","text":"王勃凡欲作文，先令磨墨數升，飲酒數杯，以被覆面而寢。既寤，援筆而成，文不加點，時人謂為腹藁也。","sortOrder":4},
  {"id":"s_work_dnl_5_5","chapterId":"ch_work_dnl_5","text":"骆賓王年方弱冠，時徐敬業據扬州而反，賓王陷於賊庭，其時書檄皆賓王之詞也。每與朝廷文字，極數伪周，天後覽之，至\"蛾眉不肯讓人，狐媚偏能惑主\"，初微笑之。及見\"一樂廖錘桑咧擄蒼冢?\"乃不悅曰：\"宰相因何失如此之人！\"蓋有遺才之恨。","sortOrder":5},
  {"id":"s_work_dnl_5_6","chapterId":"ch_work_dnl_5","text":"徐敬業十餘歲時，射必溢鏑，走馬若飛。英公每見之曰：\"此兒相不善，將赤吾族也。\"","sortOrder":6},
  {"id":"s_work_dnl_5_7","chapterId":"ch_work_dnl_5","text":"蘇少不得父意，常與仆夫雜處，而好學不倦。每欲讀書，患無燈燭，嘗於馬廄竈中，吹火照書誦焉，其苦學如此。","sortOrder":7},
  {"id":"s_work_dnl_5_8","chapterId":"ch_work_dnl_5","text":"長安春時，盛於遊賞。蘇應製詩雲：\"飛埃結紅霧，遊蓋飄青雲。\"玄宗覽之嘉賞，遂以御花親插巾上。","sortOrder":8},
  {"id":"s_work_dnl_5_9","chapterId":"ch_work_dnl_5","text":"玄宗初即位，銳意政理，好觀書，留心起居註，選當時名儒執筆。其稱職者雖十數年不去，多則遷名曹郎兼之。自先天初至天寶十二載冬季，成七百卷，內起居註為多。","sortOrder":9},
  {"id":"s_work_dnl_5_10","chapterId":"ch_work_dnl_5","text":"开元二年春，上幸寧王第，叙家人體。樂奏前後，酒食沾赉，上不自专，皆令禀於寧王。上曰：\"大哥好作主人，阿瞞但謹為上客。\"（原註：上禁中常自稱阿瞞）明日，寧王與岐、薛同奏曰：\"臣聞起居註必記天子言動，臣恐左右史記叙其事，四季朱印聯（案：此上文有脱誤）牒送史馆，附依外史。\"上以八分為答詔，謝而許之。至天寶十二載冬季，成三百卷。率以五十幅黃麻為一軸，用雕檀軸紫龍鳳綾標。寧王每請百部納於史馆。上命宴侍臣以寵之。上寶惜此書，令別起閣貯之。及祿山陷長安，用嚴、高計（原註：祿山謀主嚴莊、高尚等），未升宮殿，先以火千炬焚是閣，故《玄宗實錄》百不叙其三四，以是人間傳記尤眾。","sortOrder":10},
  {"id":"s_work_dnl_5_11","chapterId":"ch_work_dnl_5","text":"李白名播海內，玄宗見其神氣高朗，軒然霞舉，上不覺忘萬乘之尊，與之如知友焉。嘗製《胡無人》雲：\"太白入月敵可摧。\"及祿山犯闕，時太白犯月，皆謂之不凡耳。","sortOrder":11},
  {"id":"s_work_dnl_5_12","chapterId":"ch_work_dnl_5","text":"天寶中，國學增置廣文馆，以領詞藻之士。滎陽鄭虔久被貶謫，是歲始還京師參選，除廣文馆博士。虔茫然曰：\"不知廣文曹司何在？\"執政謂曰：\"廣文馆新置，總領文詞，故以公名賢處之。且令後代稱廣文博士自鄭虔始，不亦美乎？\"遂拜職。","sortOrder":12},
  {"id":"s_work_dnl_5_13","chapterId":"ch_work_dnl_5","text":"鄭虔，天寶初协律，采集異聞，著書八十餘卷，人有竊窥其藁草，上書告虔私修國史，虔遽焚之。由是貶謫十餘年，方從調選，授廣文馆博士。虔所焚藁既無別本，後更纂錄，率多遺忘，猶成四十餘卷。書未有名。及為廣文馆博士，詢於國子司業蘇源明。源明請名為《會粹》，取《爾雅序》\"會粹舊說\"也。西河太守盧象赠虔詩雲：\"書名《會粹》才偏逸，酒號屠蘇味更醇。\"即此也。","sortOrder":13},
  {"id":"s_work_dnl_5_14","chapterId":"ch_work_dnl_5","text":"著作郎孔至撰《百家類例》，第海內族姓，以燕公張說等為近代新門，不入百家之數。駙馬張，燕公子也，觀至所撰，謂弟叔曰：\"多事漢！天下族姓何關汝事，而妄為升降？\"叔與至善，以兄言告之。時工部侍郎韦述谙練士族，至書初成，以呈韦公，以為可行也。及聞言，恐懼，將追改之。韦曰：\"文士奋筆將為千載之法，奈何以一言自動搖？有死而已，胡可改也？\"遂不改。","sortOrder":14},
  {"id":"s_work_dnl_5_15","chapterId":"ch_work_dnl_5","text":"長安菩薩寺僧宏道，天寶末，見王右丞為賊所囚於經藏院，與左丞裴迪密往還。裴說--賊會宴於太極西內，王聞之泣下，為詩二絕，書經卷麻紙之後，宏道藏之，相傳數世。其詞雲：\"萬戶傷心生野煙，百官何日更朝天？秋槐葉落空宮里，凝碧池頭奏管絃。\"又雲：\"安得舍尘網，拂衣辭世喧，然策藜杖，歸向桃花源。\"","sortOrder":15},
  {"id":"s_work_dnl_5_16","chapterId":"ch_work_dnl_5","text":"代宗獨孤妃薨，赠貞皇後。將葬，尚父汾陽王子儀在州，其子尚主，欲致祭。遍問諸吏，皆雲：\"古無人臣祭皇後之儀。\"子儀曰：\"此事須柳侍御裁之。\"時殿中侍御史柳併，字伯存，掌書記，奉使在，即急召之。既至，子儀曰：\"有切事，須藉侍御為之。\"遂說祭事。殿中初亦對如諸人，既而曰：\"禮緣人情。令公勋德，不同常人。且又為姻戚，今自令公始，亦謂得宜。\"子儀曰：\"正合某本意。\"殿中草祭文，其官衔稱駙馬都尉郭暧父具官某，其文併叙特恩許致祭之意，辭簡禮備，子儀大稱之。","sortOrder":16},
  {"id":"s_work_dnl_5_17","chapterId":"ch_work_dnl_5","text":"德宗暮秋獵於苑中。是日，天已微寒，上謂近臣曰：\"九月衣衫，二月衣袍，與時候不相稱，欲遞遷一月，何如？\"左右皆拜謝。翌日，命翰林議之，而後下詔。李趙公吉甫時為承旨，以聖人上順天時，下盡物理，表請宣示天下，編之於令。李相程初為學士，獨不署名，別状奏曰：\"臣謹按：《月令》'十月始裘'，《月令》是玄宗皇帝删定，不可改易。\"上乃止。由是與吉甫不协。","sortOrder":17},
  {"id":"s_work_dnl_5_18","chapterId":"ch_work_dnl_5","text":"韦應物詩雲：\"書後欲題三百顆，洞庭須待滿林霜。\"後人多說率爾成章，不知江左嘗有人於紙尾\"寄洞庭霜三百顆\"。","sortOrder":18},
  {"id":"s_work_dnl_5_19","chapterId":"ch_work_dnl_5","text":"韓晉公治《左氏》，為浙江東西道製節。屬淮寧叛亂，發戎遣饋，案籍骈雜，而未嘗废卷。在軍中撰《左氏通例》一卷，刻石金陵府學。","sortOrder":19},
  {"id":"s_work_dnl_5_20","chapterId":"ch_work_dnl_5","text":"憲宗問宰相曰：\"天子讀何書即好？\"權德舆對曰：\"《尚書》。哲王軌范，歷歷可見。\"上曰：\"《尚書》曾讀。\"又問鄭餘慶曰：\"《老子》、《列子》如何？\"奏曰：《老子》述無為之化，若使資聖覽，為理國之枢要，即未若《貞觀政要》。\"","sortOrder":20},
  {"id":"s_work_dnl_5_21","chapterId":"ch_work_dnl_5","text":"裴晉公平淮西後，憲宗賜玉帶。臨薨欲還進，使記室作表，皆不愜。乃令子弟執筆，口占状曰：\"內府珍藏，先朝特賜，既不敢將歸地下，又不合留向人間。謹却封進。\"聞者叹其簡切而不亂。","sortOrder":21},
  {"id":"s_work_dnl_5_22","chapterId":"ch_work_dnl_5","text":"晉公貞元中，作《鑄劍戟為農器賦》，首雲：\"皇帝之嗣位十三載，寰海既清，方隅砥平。驅域中盡歸力穡，示天下不复用兵。\"憲宗平諸镇，幾至太平，正當元和十三年。而晉公以儒生作相，竟為章武佐命。","sortOrder":22},
  {"id":"s_work_dnl_5_23","chapterId":"ch_work_dnl_5","text":"楊京兆兄弟皆能文，為學甚苦。或同賦一篇，共坐庭石，霜積襟袖，課成乃已。","sortOrder":23},
  {"id":"s_work_dnl_5_24","chapterId":"ch_work_dnl_5","text":"劉禹錫雲：（案：此下至\"芍藥和物之名也\"一條，多稱劉禹錫雲，或聯書，或另條。蓋采自韦絢《劉公嘉話》，而中多讠為脱，文義難通。今本《劉公嘉話》非完書，無可參校，姑仍其舊）與柳八、韓七詣施士吝聽《毛詩》，說\"維鹈在梁\"，梁，人取魚之梁也。言鹈自合求魚，不合於人梁上取其魚。譬之人自無善事，攘人之美者，如鹈在人之梁，毛《註》失之矣。又說\"山無草木曰岵\"，所以言：\"陟彼岵兮\"，言無可怙也。以岵之無草木，故以譬之。","sortOrder":24},
  {"id":"s_work_dnl_5_25","chapterId":"ch_work_dnl_5","text":"因言\"罘偤者，复思也。今之板障、屏牆也。天子有外屏，人臣將見，至此复思其所對易攵去就、避忌也。\"\"魏\"，大\"闕\"，樓觀也。人臣將人，至此則思其遺闕。\"桓楹\"者，即今之華表也；桓、華聲訛，因呼為桓。\"桓\"亦丸丸然柱之形状也。","sortOrder":25},
  {"id":"s_work_dnl_5_26","chapterId":"ch_work_dnl_5","text":"又說：古碑有孔。今野外見碑有孔，古者於此孔中穿棺以下於墓中耳。","sortOrder":26},
  {"id":"s_work_dnl_5_27","chapterId":"ch_work_dnl_5","text":"又說：《甘棠》之詩\"勿拜，召伯所憩\"，\"拜\"言如人身之拜，小低屈也。上言\"勿翦\"，終言\"勿拜\"，明召伯漸遠，人思不得見也。毛《註》\"拜猶伐\"，非也。又言：\"維北有斗，不可挹酒漿，\"言不得其人也。毛、鄭不註。","sortOrder":27},
  {"id":"s_work_dnl_5_28","chapterId":"ch_work_dnl_5","text":"劉禹錫曰：\"為詩用僻字，須有來處。宋考功雲：'馬上逢寒食，春來不見饧。'常疑之。因讀《毛詩》鄭《箋》說吹箫處，註雲：'即今賣饧者所吹。'六經惟此中有'饧'字。吾緣明日重陽，押一'糕'字，續尋思六經竟未見有糕字，不敢為之。嘗訝杜員外'巨顙拆老拳'無據，及覽《石勒傳》雲：'卿既遭孤老拳，孤亦飽卿毒手。'豈虛言哉！後辈業詩，即須有據，不可率爾道也。\"","sortOrder":28},
  {"id":"s_work_dnl_5_29","chapterId":"ch_work_dnl_5","text":"韦絢曰：\"司馬牆何也？\"曰：\"今唯陵寢繞垣，即呼為司馬牆。\"\"而球場是也，不呼之何也？\"劉禹錫曰：\"恐是陵寢，即呼臣下避之。\"","sortOrder":29},
  {"id":"s_work_dnl_5_30","chapterId":"ch_work_dnl_5","text":"《詩》曰\"我思肥泉\"者，源同而分之曰\"肥\"也。言我今衛女嫁於曹，如肥泉之分也。","sortOrder":30},
  {"id":"s_work_dnl_5_31","chapterId":"ch_work_dnl_5","text":"魏文帝詩雲：\"畫舸覆堤\"，即今淮浙間俞船篷子上帷幕耳。《唐書·盧藩傳》言之。（案：《唐書》無《盧藩傳》。韦絢唐人，亦無引《唐書》之理，疑有脱誤）船子著油，（案：此下原闕一字）比惑之，見魏詩方悟。","sortOrder":31},
  {"id":"s_work_dnl_5_32","chapterId":"ch_work_dnl_5","text":"又曰：\"旄邱\"者，上侧下高曰\"旄邱\"，言君臣相背也。鄭《註》雲：\"旄當為{土}\"，又言：\"{土}未詳\"，何也？","sortOrder":32},
  {"id":"s_work_dnl_5_33","chapterId":"ch_work_dnl_5","text":"郭璞《山海經序》曰：\"人不得耳聞，眼不見為無。\"（案：今本《山海經序》無此二語，據文義，亦有脱誤）非也，是自不知不見耳，夏虫疑冰之類是矣。仲尼曰：\"加我數年，五十以學《易》，可以無大過矣。\"又韦編三絕，所以明未會者多於解也。","sortOrder":33},
  {"id":"s_work_dnl_5_34","chapterId":"ch_work_dnl_5","text":"有楊何者，有禮學，以廷評來夔州，轉雲安鹽官，因過劉禹錫之與，（案：此下原闕二字）何雲：\"仲尼合葬於防。防，地名。\"非也。仲尼以开墓合葬於防；防，隧道也。且潸然流涕，是以合葬也。若謂之地名，則未开墓而已潸然，何也？","sortOrder":34},
  {"id":"s_work_dnl_5_35","chapterId":"ch_work_dnl_5","text":"絢曰：\"'五夜'者，甲、乙、丙、丁、戊，更迭之。今唯言'乙夜'或'子夜'，何也？\"未詳。","sortOrder":35},
  {"id":"s_work_dnl_5_36","chapterId":"ch_work_dnl_5","text":"劉禹錫曰：茱萸二字，經二詩人用，亦有能否。杜甫言\"醉把茱萸子細看\"，王右丞\"遍插茱萸少一人\"，最優也。劉禹錫曰：牛丞相奇章公初為詩，務奇特之語，至有\"地瘦草丛短\"之句。明年秋，卷成，呈之，乃有\"求人氣色沮，凭酒意乃伸\"，益加能矣。明年乃上第。","sortOrder":36},
  {"id":"s_work_dnl_5_37","chapterId":"ch_work_dnl_5","text":"楊茂卿雲：\"河势崑崙遠，山形菡萏秋。\"此詩題雲\"過華山下作\"，而用莲蓬之菡萏，極的當而暗靜矣。","sortOrder":37},
  {"id":"s_work_dnl_5_38","chapterId":"ch_work_dnl_5","text":"劉禹錫曰：石季龍挟彈殺人，其兄怒之，其母曰：\"健犢須走車破轅，良馬須逸鞭泛駕，然後能負重致遠。\"蓋言童稚不奇，即非異器矣。","sortOrder":38},
  {"id":"s_work_dnl_5_39","chapterId":"ch_work_dnl_5","text":"又曰：為文自斗異一對不得。予嘗為大司徒杜公之故吏，司徒冢嫡之薨於桂林也，柩過渚宮，予時在朗州，使一介具奠酹，以申門吏之禮。為一祭文雲：\"事吳之心，雖雲已矣；報智之志，豈可徒然！\"\"報智\"人或用之，\"事吳\"自思得者。","sortOrder":39},
  {"id":"s_work_dnl_5_40","chapterId":"ch_work_dnl_5","text":"柳八驳韓十八《平淮西碑》雲：\"'左飧右粥'，何如我《平淮西雅》雲'仰父俯子。'\"禹錫曰：\"美憲宗俯下之道盡矣。\"柳曰：\"韓《碑》兼有帽子，使我為之，便說用兵讨叛矣。\"","sortOrder":40},
  {"id":"s_work_dnl_5_41","chapterId":"ch_work_dnl_5","text":"劉禹錫曰：\"韓《碑》柳《雅》，予詩雲：'城中晨雞喔喔鳴，城頭鼓角聲和平，'美李尚書之入蔡城也，須臾之間，賊都不覺。又詩落句言，'始知元和十二載，四海重見升平時。'所以言十二載者，因以記淮西平之年。\"","sortOrder":41},
  {"id":"s_work_dnl_5_42","chapterId":"ch_work_dnl_5","text":"段相文昌重為《淮西碑》，碑頭便曰：\"韓宏為統，公武為將。\"用《左氏》：\"栾書將中軍，栾佐之。\"文势也甚善。亦是效班固《燕然碑》樣，別是一家之美。","sortOrder":42},
  {"id":"s_work_dnl_5_43","chapterId":"ch_work_dnl_5","text":"又曰：薛伯鼻修史，為傳：收蔡州，径入為能。禹錫曰：\"我則不然。若作史官，以得李，釋縛委心用之為能。入蔡非能，乃一夫勇耳。\"","sortOrder":43},
  {"id":"s_work_dnl_5_44","chapterId":"ch_work_dnl_5","text":"劉禹錫曰：《春秋》稱\"趙盾以八百乘\"，凡帥能曰\"以\"，由也，由趙盾也。","sortOrder":44},
  {"id":"s_work_dnl_5_45","chapterId":"ch_work_dnl_5","text":"又曰：王莽以羲和為官名，如今之司天台，本屬太史氏。故《春秋》史魚、史蘇、史，皆知陰陽術數也。","sortOrder":45},
  {"id":"s_work_dnl_5_46","chapterId":"ch_work_dnl_5","text":"《南都賦》言\"春茆夏韭\"，子卯之卯也。而公孫羅雲\"茆，鳥卵。\"非也。且皆言菜也，何\"卯\"忽無言？（案此句疑有脱誤）","sortOrder":46},
  {"id":"s_work_dnl_5_47","chapterId":"ch_work_dnl_5","text":"方書中\"勞薪\"，亦有\"勞水\"者，扬之使水力弱，亦勞也。亦用\"筆心\"，筆亦心勞，一也。與\"薪勞\"之理，皆藥家之妙用。","sortOrder":47},
  {"id":"s_work_dnl_5_48","chapterId":"ch_work_dnl_5","text":"又曰：近代有中正；中正，乡曲之表也。藻別人物，知其乡中賢愚出處。晉重之。至東晉，吏部侍郎裴楷乃請改為九品法，即今之上、中、下，分為九品官也。","sortOrder":48},
  {"id":"s_work_dnl_5_49","chapterId":"ch_work_dnl_5","text":"王武子曾在夔州之西市，俯臨江岸沙石，下看諸葛亮八陣圖，箕張翼舒，鹅形鸛势，聚石分布，宛然尚存。峡水大時，三蜀雪消之际，瀕滂氵養，大树十围，枯槎百丈，破霍巨石，隨波塞川而下。水與岸齊，雷奔山裂，聚石為堆者，斷可知也。及乎水已平，萬物皆失故態，惟陣圖小石之堆，標聚行列，依然如是者，垂六七百年間，淘洒推激，迨今不動。劉禹錫曰：\"是諸葛公誠明，一心為先主效死。况此法出《六韜》，是太公上智之材所構。自有此法，惟孔明行之，所以神明保持，一定而不可改也。\"東晉桓溫征蜀過此，曰：\"此常山蛇陣，击頭則尾應，击尾則頭應，击其中則頭尾皆應。\"常山者，地名。其蛇兩頭，出於常山，其陣適類其蛇之兩頭，故名之也。\"溫遂勒銘曰：\"望古識其真，臨源愛往跡，恐君遺事節，聊下南山石。\"","sortOrder":49},
  {"id":"s_work_dnl_5_50","chapterId":"ch_work_dnl_5","text":"陆法和嘗征蜀，及上白帝城，插標，曰：\"此下必掘得諸葛亮鏃。\"既掘之，得箭鏃一斛。或曰：\"當法和至此時，去諸葛亮猶近，應有人向說，故法和掘之耳。\"法和雖是異人，必未知諸葛亮箭鏃在此也。","sortOrder":50},
  {"id":"s_work_dnl_5_51","chapterId":"ch_work_dnl_5","text":"\"諸葛亮所止，令兵士獨种蔓菁者，何也？\"曰：\"取其甲生啖，一也；葉舒者煮食，二也；久居則隨以滋長，三也；弃去不惜，四也；回則易尋而采之，五也；冬有根可食，六也。比諸蔬屬，其利博哉！三蜀之人今呼蔓菁為'諸葛菜'，江陵亦然。\"","sortOrder":51},
  {"id":"s_work_dnl_5_52","chapterId":"ch_work_dnl_5","text":"禹錫曰：\"芍藥，和物之名也。此藥之性能調和物，或音'著略'，語讠為也。\"絢時獻賦，用此\"芍藥\"字，以\"煙兮霧兮，氣兮霭兮\"，言四物調和為雲也。公曰：\"甚善。\"因以解之。","sortOrder":52},
  {"id":"s_work_dnl_5_53","chapterId":"ch_work_dnl_5","text":"白居易，長慶二年以中書舍人為杭州刺史，替嚴員外休复。休复有時名，居易喜為之代。時吳興守錢徽、吳郡守李穰皆文學士，悉生平舊友，日以詩酒寄興。官妓高玲瓏、謝好好巧於應對，善歌舞。從元稹镇會稽，參其酬唱。每以筒竹盛詩來往。居易在杭，始筑堤捍錢塘潮，鐘聚其水，溉田千頃。复浚李泌六井，民賴其汲。在蘇作詩，有\"使君全未厭錢塘\"之句。及罢，俸錢多留守库。繼守者公用不足，則假而复填，如是五十餘年。及黃巢至郡，文籍多焚燒，其俸遂亡。","sortOrder":53},
  {"id":"s_work_dnl_5_54","chapterId":"ch_work_dnl_5","text":"張宏靖十二世掌書命，至丞相。楊巨源赠公詩雲：\"伊陟無聞祖，韦賢不到孫。\"當時稱其能與張氏說家門。巨源在元和，詩韻不為新語，體律務實，功夫頗深。自旦至暮，吟詠不輟。年老頭數搖，人言吟詩多所致。","sortOrder":54},
  {"id":"s_work_dnl_5_55","chapterId":"ch_work_dnl_5","text":"韓文公與孟東野友善。韓公文至高，孟長於五言，時號\"孟詩韓筆。\"元和中，後進師匠韓公，文體大变。又柳柳州宗元、李尚書翱、皇甫郎中、冯詹事定、祭酒楊公，李公皆以高文為諸生所宗，而韓、柳、皇甫、權公皆以引接後學為務。楊公尤深於奖善，遇得一句，終日在口，人以為癖。長慶以來，李封州甘為文至精，奖拔公心，亦類數公。甘出於李相國宗闵下，時以為得人，然終不顯。又元和以來，詞翰兼奇者，有柳柳州宗元、劉尚書禹錫及楊公。劉、楊二人，詞翰之外，別精篇什。又張司業籍善歌行，李贺能為新樂府，當時言歌篇者，宗此二人。李相國程、王仆射起、白少傅居易兄弟、張舍人仲素為場中詞賦之最，言程试者宗此五人。伯仲以史學繼業。藏書最多者，蘇少常景鳳、堂弟尚書涤，諸家無比，而皆以清望為後來所重。景鳳登第，與堂兄特併時，世以為美。","sortOrder":55},
  {"id":"s_work_dnl_5_56","chapterId":"ch_work_dnl_5","text":"呂衡州溫，祖延之、父渭，俱有盛名，至大官。家世碑志不假於人，皆子孫自撰，雲：\"欲傳慶善於後嗣，儆文學之荒墜。\"","sortOrder":56},
  {"id":"s_work_dnl_5_57","chapterId":"ch_work_dnl_5","text":"裴晉公自為志銘曰：\"裴子為子之道，備存乎家牒；為臣之道，備存乎國史。\"杜牧亦自銘曰：\"嗟爾小子，亦克厥修。\"此二銘詞簡而備。白居易亦自為銘。顏魯公在蔡州，知必禍及，自為志銘置左右。","sortOrder":57},
  {"id":"s_work_dnl_5_58","chapterId":"ch_work_dnl_5","text":"文宗皇帝曾製詩以示鄭覃，覃奏曰：\"且乞留聖慮於萬幾，天下仰望。\"文宗不悅。覃出，复示李宗闵，叹伏不已，一句一拜，受而出之。上笑謂之曰：\"勿令適來阿父子見之。\"","sortOrder":58},
  {"id":"s_work_dnl_5_59","chapterId":"ch_work_dnl_5","text":"文宗尚賢樂善罕比。每宰臣學士論政，必稱才術文學之士，故當時多以文進。上每视事後，即閱群書，至亂世之君，則必扼腕嗟叹；讀尧、舜、禹、湯事，即灌手斂衽，謂左右曰：\"若不甲夜视事，乙夜觀書，即何以為君？\"试進士，上多自出題目。及所司试，覽之終日忘倦。嘗召學士於內庭論經，较量文章，宮人已下侍茶湯飲饌。李訓講《周易》，頗葉上意。時方盛夏，遂取犀如意賜訓，上曰：\"與卿為谭柄。\"讀高郢《無聲樂賦》、白居易《求元珠賦》，謂之\"玄祖\"。水部員外郎贾嵩說雲。","sortOrder":59},
  {"id":"s_work_dnl_5_60","chapterId":"ch_work_dnl_5","text":"文宗好五言詩，品格與肅、代、憲宗同，而古調尤清峻。嘗欲置詩學士七十二員，學士中有荐人姓名者（原註：當時詩人李廓馳名，為涇原從事），宰相楊嗣复曰：\"今之能詩，無若賓客分司劉禹錫。\"上無言。李珏奏曰：\"當今起置詩學士，名稍不嘉。况詩人多窮薄之土，昧於識理。今翰林學士皆有文詞，陛下得以覽古今作者，可怡悅其間；有疑，顧問學士可也。陛下昔者命王起、許康佐為侍講，天下謂陛下好古宗儒，敦扬朴厚。臣聞憲宗為詩，格合前古。當時輕薄之徒，僛章繪句，聱牙崛奇，譏諷時事，爾後鼓扇名聲，謂之'元和體'，實非聖意好尚如此。今陛下更置詩學土，臣深慮輕薄小人，競為嘲詠之詞，屬意於雲山草木，亦不謂之'开成體'乎？玷黯皇化，實非小事。\"","sortOrder":60},
  {"id":"s_work_dnl_5_61","chapterId":"ch_work_dnl_5","text":"文宗時，工部尚書陳商立《漢文帝废丧議》。又立《左氏》學議，以\"孔子修經，褒貶善惡，類例分明，法家流也。左丘明為魯史，載述時政，懼善惡失墜，以日系月，本非扶助聖言，緣飾經旨，蓋太史氏之流也。舉之《春秋》，則明白而有實；合之《左氏》，則丛雜而無征。杜元凯曾不思孔子所以為經，當與《詩》、《書》、《周易》等列；丘明所以為史，當與司馬遷、班固等列。二義不侔，乃參而貫之，故微旨有所未盡，婉章有所未一。\"其後吳郡陆龟蒙亦引啖助、趙匡為證，正與商議同。","sortOrder":61},
  {"id":"s_work_dnl_5_62","chapterId":"ch_work_dnl_5","text":"進士李為作《淚賦》及《經》、《薄》、《暗》、《小》四賦，李贺作\"樂府\"，多屬意花草蜂蝶之間。二子竟不遠大，世言文字可以見分命之優劣。","sortOrder":62},
  {"id":"s_work_dnl_5_63","chapterId":"ch_work_dnl_5","text":"上元瓦官寺僧守亮，通《周易》，性若狂易。李衛公镇浙西，以南朝舊寺多名僧，求知《易》者，因帖下諸寺，令擇送至府。瓦官寺眾白守亮曰：\"大夫取解《易》僧，汝常時好說《易》，可往否？\"守亮請行。眾戒曰：\"大夫英俊嚴重，非造次可至，汝當慎之。\"守亮既至，衛公初見，未之敬。及與言論，分條析理，出没幽赜，公凡欲质疑，亮已演其意，公大驚，不覺前席。命於甘露寺設馆舍，自於府中設講席，命從事已下，皆橫經聽之，逾年方畢。既而請再講，講將半，亟請歸甘露。既至命浴，浴畢，整巾屦遣白公雲：\"大期今至，不及回辭。\"言訖而終。公聞驚異，明日率賓客至寺致祭。適有南海使送西國異香，公於龛前焚之，其煙如絃，穿屋而上，觀者悲敬。公自草祭文，謂舉世之官爵俸祿，皆加於亮，亮盡受之，可以無愧。","sortOrder":63},
  {"id":"s_work_dnl_5_64","chapterId":"ch_work_dnl_5","text":"李德裕镇浙西，有劉三复者，少貧苦，有才學。時中使赍詔書賜德裕，德裕謂曰：\"子為我草表，能立構否？\"三复曰：\"文貴中，不貴速得。\"德裕以為然。三复又請曰：\"中外皆傳公文，請得以文集觀之。\"德裕出數軸，三复乃體而為表，德裕尤喜之。遣詣京師，果登第。其子鄴，後為丞相，上表雪德裕冤，歸榇洛中。","sortOrder":64},
  {"id":"s_work_dnl_5_65","chapterId":"ch_work_dnl_5","text":"段郎中成式，博學文章，著書甚多。守庐陵，嘗遊山寺，讀一碑，二字不過，曰：\"此碑無用於世矣。成式讀之不過，更何用乎？\"客有以此二字遍問人，果無知者。連典江南數郡，皆有名山：九江匡庐、縉雲烂柯、庐陵麻姑。前進士許棠寄詩雲：\"十年三領郡，領郡管仙山。\"盧陵時，為人妄訴，逾年方辨，乃退居於襄陽。溫博士庭筠亦謫隨縣尉，節度使徐太師留在幕府，與成式尤相善。嘗送墨一挺與庭筠，往复致謝，搜故事者凡幾函。成式子安節，娶庭筠女。安節仕至吏部郎中、沂王傅，善音律，著《樂府新錄》傳於世。","sortOrder":65},
  {"id":"s_work_dnl_5_66","chapterId":"ch_work_dnl_5","text":"令狐自吳興除司勋郎中，入禁林。一夕寓直，中使宣召，行百步，至便殿，上遣內人秉燭候之，引於御榻前賜坐，問：\"卿從江外來，彼中庶安否？廉察郡守字人求瘼之道如何？朕常思四海之大，九州之廣，雖明君不能自理，常須賢佐，邇來朝廷皆未睹其忠荩。\"降階俯伏，曰：\"聖意如此，微臣便合得罪。\"上曰：\"卿方為翰林學士，所職者朕之誥命，向來之言，本不相及。\"以玉杯酌酒賜。有小案置御床上，有書兩卷，謂曰：\"朕聽政之暇，未嘗不觀書。此讀者，先朝所述《金鏡》，一卷則《尚書·禹謨》。\"复問曰：\"卿曾讀《金鏡》否？\"對曰：\"文皇帝所著之書，有理國理身之要，披閱誦諷，不離於口。\"上曰：\"卿试舉其要。\"跪於御前誦之，至\"亂未嘗不任不肖，治未嘗不任忠賢。任忠賢，則享天下之福；任不肖，則受天下之禍。\"上止之曰：\"朕每讀至此，未嘗不三复後已。《書》又雲：'任賢勿貳，去邪勿疑。'是則欲致升平，當用此言為首。\"奏曰：\"先臣每言《金鏡》可為萬古格言，自非聰明之姿，無以探其壶奧。\"上曰：\"曩者知卿材器，今日見卿詞學。\"顧中使曰：\"持燭送學士歸院。\"當時近臣恩泽無比，居歲餘，遂遷宰相。","sortOrder":66},
  {"id":"s_work_dnl_5_67","chapterId":"ch_work_dnl_5","text":"宣宗因重陽，便殿大合樂，錫宴群臣。有御製詩，其略曰：\"款塞旋征騎，和戎委廟賢；傾心方倚註，葉力共安邊。\"宰臣以下應製皆和。上曰：\"宰相魏暮詩最佳。\"其聯雲：\"四方無事去，宸豫杪秋來；八水寒光動，幹山霁色开。\"上嘉賞久之，魏蹈舞謝。","sortOrder":67},
  {"id":"s_work_dnl_5_68","chapterId":"ch_work_dnl_5","text":"宣宗嗜書，嘗構一殿，每退朝，必獨坐內觀書，或至夜中燭ㄠ委，禁中謂上為老儒生。","sortOrder":68},
  {"id":"s_work_dnl_5_69","chapterId":"ch_work_dnl_5","text":"大中十二年，以左諫議大夫鄭漳、兵部郎中李鄴為鄆王已下侍讀。時鄆王居十六宅，夔、昭已下五王居大明宮內院。數日，追製，改充夔王已下侍讀，五日一入乾符門講讀。懿宗即位，遂停。","sortOrder":69},
  {"id":"s_work_dnl_5_70","chapterId":"ch_work_dnl_5","text":"大中、鹹通之後，每歲试禮部者千餘人。其間有名聲，如：何植、李玫、皇甫松、李孺犀、梁望、毛潯、具麻、來鵠、贾隨，以文章稱；溫庭筠、鄭渎、何涓、周鈐、宋耘、沈駕、周系，以詞翰顯；贾島、平曾、李淘、劉得仁、喻坦之、張乔、剧燕、許琳、陳覺，以律詩傳；張維、皇甫川、郭、劉庭辉，以古風著。雖然，皆不中科。","sortOrder":70},
  {"id":"s_work_dnl_5_71","chapterId":"ch_work_dnl_5","text":"陆翱為詩有情思，其《閒居即事》雲：\"衰柳迷隋苑，衡門啼暮鴉；茅厨煙不動，書牖日空斜。悔下東山石，貧於南阮家。沈忧損神慮，萱草自开花。\"《宴趙氏北樓》雲：\"殷勤趙公子，良夜竟相留；朗月生東海，仙娥在北樓。酒阑珠露滴，歌迥石城秋；本為愁人設，愁人到晓愁。\"題鸚鵡、早鶯、柳絮、燕子，皆傳於時。登第累年，無辟召，一遊東諸侯，得錢仅百萬，而卒於江南。長子希聲，好學多才藝，勤於讀史，非寢食未嘗釋卷，中朝子弟好讀史者無及。昭宗時為相。","sortOrder":71},
  {"id":"s_work_dnl_5_72","chapterId":"ch_work_dnl_5","text":"李郢有詩名，鄭尚書顥門生也。居杭州，不務進取，終（案：此下原闕一字）下郎官。初赴舉，聞鄰女有容，求娶之。遇有爭娶者，女家無以為辭，乃曰：\"備錢百萬，先至者許之。\"兩家具錢，同日皆至。女家無以為辭，复曰：\"請各賦一詩，以為優劣。\"郢乃得之。登第回江南，駐蘇州，遇故人守湖州，邀同行。郢辭以决意春歸，為妻作生日。故人不放，與之胡琴、焦桐、方物等，令且寄歸代意。郢為《寄內詩》曰：\"謝家生日好風煙，柳暖花春二月天；金鳳對翘双翡翠，蜀琴新上七絲絃。鴛鴦交頸期千歲，琴瑟諧和願百年；應恨客程歸未得，绿窗紅淚冷涓涓。\"兄子鹹通初守杭州。郢至，宿虛白堂，雲：\"缺月斜明虛白堂，寒蛩唧唧树蒼蒼。江風彻曙不得睡，二十五聲秋點長。\"","sortOrder":72},
  {"id":"s_work_dnl_5_73","chapterId":"ch_work_dnl_5","text":"馬博士戴，大中初為太原李司空掌記，以正直被斥，貶朗州龍陽尉。戴著書，自痛不得盡忠於故府，而動天下之議。行道興詠，寄情哀楚，凡數十篇。其《方城懷古》雲：\"申胥枉向秦庭哭，靳尚終貽楚國羞。\"《新春聞赦》雲：\"道在猜讒息，仁深疾苦除。尧聰能下聽，湯網本來疏。\"","sortOrder":73},
  {"id":"s_work_dnl_5_74","chapterId":"ch_work_dnl_5","text":"李字除果名、地名、人姓之外，更無有別訓義也。《左傳》\"行李之往來\"，註：\"行李，使人也。\"遠行結束，謂之行李，而不悟是行使爾。按舊文：使字作\"卒\"，傳寫之，誤作\"李\"焉。","sortOrder":74},
  {"id":"s_work_dnl_5_75","chapterId":"ch_work_dnl_5","text":"漢四皓其一號角里，角音祿，今多以\"覺\"呼者，非也。《魏子》及孔氏《秘記》、荀氏《漢紀》，慮將來之誤，直書\"祿里\"。按《玉篇》等字書皆雲：\"東方為〈龠錄〉音，或作角；角亦音祿。\"《魏子》、《秘記》、《漢紀》不書\"〈龠錄〉\"而作\"祿\"者，以其字僻，又慮誤音故也。李匡雲：角里當東方，何者？按《陳留志》稱京師亦號為灞上儒生，灞既在京師之東，則角里為東方不疑矣。以字書言，角直宜作\"〈龠錄〉\"爾，然〈龠錄〉字亦作角，音覺者，樂聲也，或亦通用\"〈龠錄〉角\"之\"角\"字，是以今人多亂其音呼之。稍留心為學者，則妄穿凿雲：音祿之\"角\"，與音覺之\"角\"，點畫有分別。又不知角、〈龠錄〉各有二音，字體皆同，而其義有異也。又《禮記》\"君大夫{髟春}爪實於绿中\"，鄭司農《註》雲：\"绿當為角，聲之誤也。\"既雲聲誤，是鄭讀\"角中\"為\"祿中\"。\"祿\"與\"绿\"是双聲，若讀角為覺，覺是腭际聲，绿是舌頭之聲。《註》复雲：\"角中，謂棺內四隅也。\"據此則又似音祿之\"角\"與音覺之\"角\"義同。陆氏《釋文》、孔氏《疏》不能窮其聲義，亦但雲：\"绿當為'角'，漢之角里，《禮》之'绿中'，皆當作'祿'音。\"","sortOrder":75},
  {"id":"s_work_dnl_5_76","chapterId":"ch_work_dnl_5","text":"《月令》，今人依陆德明說，雲是《呂氏春秋·十二紀》之首，後人删合為之，非也。蓋出於《周書》第七卷《周月》《時訓》兩篇。蔡邕、《玉篇》雲\"周公作\"。是《呂紀》采於《周書》，非《戴禮》取於《呂紀》，明矣。","sortOrder":76},
  {"id":"s_work_dnl_5_77","chapterId":"ch_work_dnl_5","text":"《論語》：\"宰予晝寢。\"梁武帝讀為\"寢室\"之\"寢\"。晝，胡卦反，言其繪畫寢室，故夫子叹\"朽木不可雕也，粪土之牆不可朽也。\"今人皆以為韓文公所說，非也。","sortOrder":77},
  {"id":"s_work_dnl_5_78","chapterId":"ch_work_dnl_5","text":"又：\"傷人乎，不問馬。\"今亦雲韓文公讀\"不\"為\"否\"，言大德聖人，豈仁於人不仁於馬？故貴人，所以前問；賤畜，所以後問。然\"不\"字上豈更要助詞？其亦曲矣，况又未必韓公所說。按陆氏《釋文》亦雲\"一讀至'不'字句絕\"，則知其\"不\"為\"否\"，其來尚矣。誠以\"不\"為\"否\"，則宜至\"乎\"字句絕，\"不\"字自為一句。何者？夫子問\"傷人乎？\"乃對曰：\"否。\"既不傷人，然後乃問馬，其文別為一讀，豈不愈於陆雲乎？","sortOrder":78},
  {"id":"s_work_dnl_5_79","chapterId":"ch_work_dnl_5","text":"稷下有諺曰：\"學識何如觀點書。\"書之難，不唯句度義理，兼在知字之正音、借音。若某字以朱發平聲，即為某字：發上聲，变為某字；去、入又改為某字，轉平、上、去、入易耳，知合發、不發為難。不可盡條舉之，今略指一隅。至如亡字、無字、毋字，併是正\"無\"字，非借音也。今見點書每遇\"亡有\"字，必以朱發平聲，其遇\"毋\"字亦然，是不知亡字、[C032]字、毋字、母字，點畫各有區別。亡從一點一畫一（原註：觀篆文當知矣，是以無字正體作亡）'[C032]'之'[C032]'中有人。'毋有'字其畫盡通也。'父母'字中有兩點。（原註：劉伯莊《音義》雲：凡非父母之母，皆呼為無字，是也。義見字書）其\"無\"\"[C043]\"二字（原註：上無下既），今多混書，陆德明已有論矣。","sortOrder":79},
  {"id":"s_work_dnl_5_80","chapterId":"ch_work_dnl_5","text":"世人多謂李氏立意註《文選》，過為迂繁，徒自騁學，且不解文意，遂相尚習五臣者，大誤也。所廣征引，非李氏立意，蓋李氏不欲竊人之功，有舊註者，必逐每篇存之，仍題元註之人姓字；或有迂闊乖谬，猶不削去之。苟舊註未備，或興新意，必於舊註中稱\"臣善\"以分別。既存元註，例皆引據，李氏續之，雅誼殷勤也。代傳數本李氏《文選》，有初註成者，有覆註成者，有三註、四註者，當初旋被傳寫之誤。其絕筆之本，兼釋音訓義，註解甚多，匡家幸而有焉。嘗將數本併校，不惟註之贍略有異，至於科段互相不同，無似餘家之本該備也。因而比量五臣者，方悟所註直盡從李氏註中出。开元進表反非斥李氏，無乃欺心欤？且李氏未詳處，將欲下筆，宜明引凭證。細而觀之，無非率爾。今聊各舉其一端，至如《西都賦》說獵雲：\"許少施巧，秦成力折。\"李雲：\"許少、秦成未詳。\"五臣雲：\"古之捷人壮士，搏格猛獸。\"施巧、力折固是捷壮，文中自解矣，豈假更言？况不知二人所從出乎？又註\"作我上都\"雲：\"上都，西京也。\"何太淺近忽易欤？必欲加李氏所未註，何不雲\"上都者，君上所居，人所都會\"耶？况秦地厥田上上，居天下之上乎？又輕改前賢文旨，若李氏註雲\"某字或作某字\"，便隨而改之；其有李氏解而自不晓，辄复移易，今不能繁驳，亦略指其所改一字。曹植《樂府》雲：\"寒鱉炙熊蹯。\"李氏雲：今之腊肉謂之\"寒\"，蓋韓國事饌尚此法；复引《鹽鐵論》\"羊淹雞寒\"、劉熙《釋名》\"韓雞\"為證，\"寒與韓同\"。又李以上句雲\"脍鯉雋胎虾\"，因註雲：\"《詩》曰'偄鱉脍鯉'。\"五臣兼見上句有\"脍\"，遂改\"寒鱉\"為\"偄鱉\"，以就《毛詩》之句。又子建《七啟》雲：\"寒芳苓之巢龟，西海之飛鱗。\"五臣亦改\"寒\"為\"搴\"，註雲：\"搴，取也。\"何以對下句之\"\"耶？况此篇全說僝事之意，獨入此\"搴\"字，於理甚不安。上句既改\"寒\"為\"搴\"，下句亦宜改\"\"為\"取\"，縱一聯稍通，亦與諸句不相承接。以此言之，明子建故用\"寒\"字，豈可改為\"偄\"、\"搴\"耶？斯類篇篇有之，學者幸留意。仍知李氏絕筆之本，懸若日月焉。方之五臣，猶虎狗、鳳雞耳。其改字，有\"翩翻\"對\"恍惚\"，則獨改\"翩翻\"為\"翩翩\"，與下句不相收。又李氏舊本作\"泉\"及年代字，五臣貴有異同，改其字，却犯國讳，豈惟矛盾也！","sortOrder":80},
  {"id":"s_work_dnl_5_81","chapterId":"ch_work_dnl_5","text":"衡山五峰曰：紫蓋、雲密、祝融、天柱、石廪。下人多文詞，至於樵夫，往往能言詩。嘗有廣州幕府夜聞舟中吟曰：\"野鵲滩西一棹孤，月光遙接洞庭湖；堪憎迥雁峰前過，望斷家山一字無。\"問之，乃其所作也。","sortOrder":81},
  {"id":"s_work_dnl_5_82","chapterId":"ch_work_dnl_5","text":"李華，字遐叔，以文學自名，與萧穎士、贾幼兒為友。華作賦雲：\"星錘電交於萬緒，霜鋸冰解於千尋。擁梯成山，攒杵為林。\"穎士讀之，謂華曰：\"可使孟堅瓦解，平子土崩矣。\"幼幾曰：\"未若'天光流於紫庭，测景入於朱戶。騰祥靈於黯霭，映旭日之葱茏。'\"華曰：\"某所自得，惟'括萬象以為尊，特巍巍於上京。分命征般石之匠，下荆、扬之材，操斧執斤者萬人，涉碛砾而登崔嵬'，不讓《東》、《西》二《都》也。\"時人以華不可居萧、贾之間。","sortOrder":82},
  {"id":"s_work_dnl_5_83","chapterId":"ch_work_dnl_5","text":"鄭（案：此下原闕二字）雲：\"張燕公文逸而學奧；蘇許公文似古，學少簡而密。張有《河朔刺史冉府君碑》，序金城郡君雲：'華前落，藁瘞城隅。天使馬悲，啟滕公之室；人看鶴舞，閉王母之墳。'亦其比也。\"公又雲：\"張巧於才，近世罕比。《端午三殿侍宴詩》雲：'甘露垂天酒，芝盤捧御書。含丹同蜓，灰骨慕蟾蜍。'上親解紫拂帶以賜焉。\"蘇嘗夢書壁雲：\"元老見逐，讒人孔多。既誅群凶，方宣大化。\"後十三年视草禁中，拜劉幽求左仆射製，上親授其意，及進本，上自益前四句，乃夢中之詞也。又聞杜工部詩如爽鶻摩霄，駿馬絕地。其《八哀詩》，詩人比之大謝《擬魏太子鄴中八篇》。杜曰：\"公知其一，不知其二。吾詩曰：'汝陽讓帝子，眉宇真天人；虬髯似太宗，色映塞外春。'八篇中有此句不？\"或曰：\"'百川赴巨海，眾星拱北辰，'所謂世有其人。\"杜曰：\"使昭明再生，吾當出劉、曹、二謝上。\"杜善鄭廣文，嘗以《花卿》及《薑楚公畫鷹歌》示鄭。鄭曰：\"足下此詩可以療疾。\"他日鄭妻病，杜曰：\"爾但言'子章髑髏血模糊，手提掷還崔大夫。'如不瘥，即雲'觀者徒驚帖壁飛，畫師不是無心學。'未間，更有'太宗拳毛，郭家師子花'。如又不瘥，雖和扁不能為也。\"其自得如此。","sortOrder":83},
  {"id":"s_work_dnl_5_84","chapterId":"ch_work_dnl_5","text":"太宗嘗出行，有司請載副書以從。帝曰：\"不須，虞世南在，此行秘書也。\"","sortOrder":84},
  {"id":"s_work_dnl_5_85","chapterId":"ch_work_dnl_5","text":"虞公為秘監，於省後堂集群書可為文章用者，號為《北堂書鈔》。後北堂猶存，而《書鈔》盛行於世。","sortOrder":85},
  {"id":"s_work_dnl_5_86","chapterId":"ch_work_dnl_5","text":"褚遂良為太宗哀册文，自朝還，馬誤入人家而不覺。","sortOrder":86},
  {"id":"s_work_dnl_5_87","chapterId":"ch_work_dnl_5","text":"沈期以詩著名，燕公張說嘗謂人曰：\"沈三兄詩，須還他第一。\"","sortOrder":87},
  {"id":"s_work_dnl_5_88","chapterId":"ch_work_dnl_5","text":"代有《山東士大夫類例》，其非士族及假冒者，不見錄，署雲相州僧曇刚撰。後柳常侍冲亦明族姓，中宗朝為相州刺史，詢問耆舊，雲：\"自隋已來，不聞有僧名曇刚。\"蓋懼見嫉於時，隱其名氏雲。","sortOrder":88},
  {"id":"s_work_dnl_5_89","chapterId":"ch_work_dnl_5","text":"鹹通中，進士皮日休進書兩通：其一，請以《孟子》為學科。有能通其義者，其科選同明經。其二，請以韓愈配饗太學，有唐以來，一人而已，苟不得在二十一賢之數列，於典禮未為備也。日休字逸少，後字袭美，襄陽竟陵人。少隱鹿門山，號醉吟先生。榜末及第，禮部侍郎鄭愚以其貌不扬，戲之曰：\"子之才學甚富，如一日何？\"皮對曰：\"侍郎不可一日废二日。\"謂不以人废言也。官至太常博士。居蘇州，與陆龟蒙為友。著《文藪》十卷、《皮子》三卷。黃巢時遇害。其子仕錢痢?","sortOrder":89},
  {"id":"s_work_dnl_5_90","chapterId":"ch_work_dnl_5","text":"王維好佛，故字摩詰。性高致，得宋之問輞川別業，山水勝絕，清源寺是也。維有詩名，然好取人句。\"行到水窮處，坐看雲起時。\"《英華集》中詩也。\"漠漠水田飛白鷺，陰陰夏木啭黃鸝。\"李嘉詩也小","sortOrder":90},
  {"id":"s_work_dnl_5_91","chapterId":"ch_work_dnl_5","text":"柳芳與韦述友善，俱為史學。述卒後，所著書未畢者，芳續之。","sortOrder":91},
  {"id":"s_work_dnl_5_92","chapterId":"ch_work_dnl_5","text":"李華作《含元殿賦》，萧穎士見之，曰：\"《景福》之上，《靈光》之下。\"華著論言龟卜可废，可謂深識之士。後以失節賊庭，故其文殷勤於四皓、元魯山，極筆於權著作，蓋心所愧也。","sortOrder":92},
  {"id":"s_work_dnl_5_93","chapterId":"ch_work_dnl_5","text":"李翰文雖宏畅，而思甚苦涩。晚居陽翟，常從邑令皇甫曾求音樂。思涸則奏樂，神全則缀文。","sortOrder":93},
  {"id":"s_work_dnl_5_94","chapterId":"ch_work_dnl_5","text":"大歷已後，专學者，有蔡廣成《周易》，強蒙《論語》，啖助、趙匡、陆质《春秋》，施士吝《毛詩》，袁彝、仲子陵、韦彤、裴偉講《禮》，章庭、薛伯高、徐润併通經。其餘地里則贾仆射，兵賦則杜太保，故事則蘇冕、蒋，歷算則董純，天文則徐泽，氏族則林寶。","sortOrder":94},
  {"id":"s_work_dnl_5_95","chapterId":"ch_work_dnl_5","text":"楚僧靈一，律行高絜而能為詩。吳僧皎然，一名晝一，工篇什，著《詩評》三卷。及卒，德宗遣使取其遺文。中世文僧，二人首出。","sortOrder":95},
  {"id":"s_work_dnl_5_96","chapterId":"ch_work_dnl_5","text":"韦應物立性高絜，鮮食寡欲，所居焚香扫地而坐。其為詩，馳骤建安已還，各得其風韻。","sortOrder":96},
  {"id":"s_work_dnl_5_97","chapterId":"ch_work_dnl_5","text":"李益詩名早著，有《征人歌》一篇，好事者畫為圖障。又有雲：\"回樂峰前沙似雪，受降城外月如霜。不知何處吹芦管，一夜征人盡望乡。\"天下亦唱為歌曲。","sortOrder":97},
  {"id":"s_work_dnl_5_98","chapterId":"ch_work_dnl_5","text":"沈既濟撰《枕中記》，韓愈撰《毛穎傳》，不下史篇，良史才也。","sortOrder":98},
  {"id":"s_work_dnl_5_99","chapterId":"ch_work_dnl_5","text":"張登為小賦，氣宏而密，間不容發，有織成隱起結彩蹙金之状。","sortOrder":99},
  {"id":"s_work_dnl_5_100","chapterId":"ch_work_dnl_5","text":"中世有造謗辭而著者（原註：雞眼、苗登二文），有傳蚁穴而稱者（原註：李公佐《南柯太守傳》），有妓樂而工篇什者（原註：蜀妓薛涛），有家僮而善著章句者（原註：郭氏奴不記名），皆事之異也。","sortOrder":100},
  {"id":"s_work_dnl_5_101","chapterId":"ch_work_dnl_5","text":"進士為時所尚久矣，俊實在其中。由此者為聞人，爭名常切，為俗亦弊。其都會謂之\"舉場\"；通稱謂之\"秀才\"；投刺謂之\"乡貢\"；得第謂之\"前辈\"；相推敬謂之\"先辈\"；俱捷謂之\"同年\"；有司謂之\"座主\"；京兆考而升之，謂之\"等第\"；外府不试而貢，謂之\"拔解\"；各相保任，謂之\"合保\"；群居而试，謂之\"私试\"；造請\"權要\"；謂之關節；激扬聲問，謂之\"往還\"；既捷，列其姓名慈恩寺，謂之\"題名\"；會醵為樂於曲江亭，謂之\"曲江宴\"；籍而入選，謂之\"春關\"；不捷而醉飽，謂之\"打〈冒毛〉〈毛〉\"；飛書造謗，謂之\"無名子\"；退而肄習，謂之\"過夏\"；執業以出，謂之\"秋卷\"；挟藏入试，謂之\"書策\"；此其大略。其風俗系於先進，其製置存於有司。雖然，賢者得其大者，故位極人臣常十有二三，登顯列常有六七，而元魯山、張睢陽有焉，劉辟、元有焉。","sortOrder":101},
  {"id":"s_work_dnl_5_102","chapterId":"ch_work_dnl_5","text":"自开元二十四年，考功員外郎李昂為士子所訴，天子以郎署權輕，移職禮部，始置貢院。天寶則有袁成用、劉長卿分為棚頭。是時常重東府西監。貞元八年，李觀、欧陽詹以廣文登第，自後乃群奔於京兆矣。","sortOrder":102},
  {"id":"s_work_dnl_5_103","chapterId":"ch_work_dnl_5","text":"貞元十二年，駙馬王士平與義陽公主不协，蔡南史、獨孤申叔播為樂曲，號《義陽子》，有《团雪》《散雪》之歌。德宗怒，欲废進士科，後獨流南史而止。","sortOrder":103},
  {"id":"s_work_dnl_5_104","chapterId":"ch_work_dnl_5","text":"或有朝客譏宋濟曰：\"近日白袍子何太紛紛？\"濟曰：\"蓋因緋袍子、紫袍子紛紛化使然也。\"","sortOrder":104},
  {"id":"s_work_dnl_5_105","chapterId":"ch_work_dnl_5","text":"元和已後，文筆學奇於韓愈，學涩於樊宗師。歌行則學流荡於張籍，詩章則學矯激於孟郊，學淺切於白居易，學淫靡於元稹，俱名元和體。大抵天寶之風尚党，大歷之風尚浮，貞元之風尚荡，元和之風尚怪也。","sortOrder":105},
  {"id":"s_work_dnl_5_106","chapterId":"ch_work_dnl_5","text":"建中初，金吾將軍裴冀曰：\"若禮部先時頒天下曰：某年试題取某經，某年试題取某史，至期果然，亦勸學之一術也。\"","sortOrder":106},
  {"id":"s_work_dnl_5_107","chapterId":"ch_work_dnl_5","text":"熊執易通《易》。建中四年，试《易簡知险阻論》。執易端坐剖析，聲動場中，一舉而捷。","sortOrder":107},
  {"id":"s_work_dnl_6_1","chapterId":"ch_work_dnl_6","text":"●卷三·方正","sortOrder":1},
  {"id":"s_work_dnl_6_2","chapterId":"ch_work_dnl_6","text":"狄梁公仁杰為度支員外郎，車駕將幸汾陽宮，仁杰奉使修供頓。併州長史李玄冲以道出妒女祠，俗稱有盛衣服車馬過者，必致雷風，欲別开路。仁杰曰：\"天子行幸，千乘萬騎，風伯清尘，雨師洒道，何妒女敢害而欲避之？\"玄冲遂止，果無他变。上聞之，叹曰：\"可謂真丈夫也。\"後為冬官侍郎，充江南安撫使。其風俗，歲時尚淫祀，廟凡一千七百餘所，仁杰併令焚之。有項羽廟，吳人所憚。仁杰先檄書，责其丧失江東八千子弟，而妄受牲牢之荐，然後焚之。","sortOrder":2},
  {"id":"s_work_dnl_6_3","chapterId":"ch_work_dnl_6","text":"陆少保，字元方，曾於東都賣一小宅。家人將受直矣，買者求見，元方因告其人曰：\"此宅子甚好，但無出水處耳。\"買者聞之，遽辭不買。子侄以為言，元方曰：\"不爾，是欺之也。\"","sortOrder":3},
  {"id":"s_work_dnl_6_4","chapterId":"ch_work_dnl_6","text":"裴光庭累典名藩，皆有異政。玄宗謂宰相曰：\"裴光庭性惡惡，如扇驅蚊蚋焉。\"","sortOrder":4},
  {"id":"s_work_dnl_6_5","chapterId":"ch_work_dnl_6","text":"宋為廣府都督，玄宗思之，使內臣楊思勖馳驿往追。就路，竟不與思勖交一言。思勖以將軍貴幸殿中，訴於玄宗。上嗟叹良久，拜刑部尚書。","sortOrder":5},
  {"id":"s_work_dnl_6_6","chapterId":"ch_work_dnl_6","text":"代宗惑釋氏業報輕重之說，政事多托於宰相，而元載专權亂國，事以货成。及常袞為相，雖賄賂不行，而介僻自专，升降多失其人。或同列進擬稍繁，則謂之\"踏伯\"。於是京師語曰：\"常分別，元好錢。賢者愚，愚者賢。\"崔甫素公直，因於眾中言曰：\"朝廷上下相蒙，善惡同致。清曹峻府，為鼠辈養資，豈所以裨政耶！\"由是為持權者所忌。建中初，甫執政，中外大悅。","sortOrder":6},
  {"id":"s_work_dnl_6_7","chapterId":"ch_work_dnl_6","text":"郭尚父在河中，禁無故走馬，犯者死。南陽夫人乳母之子抵禁，都虞候杖殺之。諸子泣訴虞候縱橫之状，公叱而遣之。明日，對賓客叹息數四，以其事告客曰：\"不賞父之都虞候，而惜母之阿你兒，非奴才而何？\"","sortOrder":7},
  {"id":"s_work_dnl_6_8","chapterId":"ch_work_dnl_6","text":"中書侍郎張鎬，為河南節度使，镇陳留。後兼統江淮諸道，將圖進取。中官絡繹。鎬起自布衣，一二年登宰相，正身特立，不為苟媚，閹宦去來，以常禮接之。由是為閹竖所嫉，稱其無經略才，征入，改為荆府長史；未幾，又除洪府長史、江西觀察使。","sortOrder":8},
  {"id":"s_work_dnl_6_9","chapterId":"ch_work_dnl_6","text":"相里造為禮部郎中，時宦官魚朝恩用事，稱詔集百僚有所評議，凌轹在位。宰相元載以下，唯唯而已；造抗言酬對，無降屈之色，朝廷壮之。","sortOrder":9},
  {"id":"s_work_dnl_6_10","chapterId":"ch_work_dnl_6","text":"崔甫為中書舍人，時宰相常袞當國，甫每見執政問事，未曾屈。舍人岑參掌誥，屢稱疾不入宿直，人雖憚而不敢發，崔獨入見，以舍人移疾既多，有同離局。袞曰：\"此子羸病日久，諸賢豈不能容之？\"崔曰：\"相公若知岑舍人抱疾，本不當遷授。今既居此，安可以疾辭王事乎？\"袞默然無以奪也，由是心衔之。及德宗在谅暗中，袞矯製除崔為河南少尹。上覺其事，遽追還之，拜中書侍郎平章事，而袞謫於嶺外。","sortOrder":10},
  {"id":"s_work_dnl_6_11","chapterId":"ch_work_dnl_6","text":"李為淄青節度判官。其使尚衡，弟頗幹政，悖屢言之。衡曰：\"兄弟孤遺相長，不忍失意。\"悖曰：\"君既愛之，當訓以道，何使其縱恣？\"衡家又好祷，車舆出入，人吏苦之。又進諫，衡不能用。他日，衡對諸客有所問，曰：\"前後獻愚直，大夫不用，今复何問？\"衡曰：\"吾子好為詆訐。\"曰：\"忠言詆訐，久居何益？請從此辭。\"遂趨出。衡怒，不使追之。","sortOrder":11},
  {"id":"s_work_dnl_6_12","chapterId":"ch_work_dnl_6","text":"裴操者，延齡之子，應鸿辭舉，延齡於吏部候消息。時苗給事及杜黃門同時為吏部知铨，將出門，延齡接見，采侦二侍郎口氣。延齡乃念操賦頭曰：\"是冲仙人。\"黃門顧苗給事曰：\"記有此否？\"苗曰：\"恰似無。\"延齡仰頭大呼曰：\"不得，不得！\"敕下，果無名操者。劉禹錫曰：\"當延齡用事之時，不預實難也。非杜黃門誰能拒之？\"","sortOrder":12},
  {"id":"s_work_dnl_6_13","chapterId":"ch_work_dnl_6","text":"韓太保皋為御史中丞、京兆尹，常有所陳，必於紫宸殿對百寮而請，未嘗詣便殿。上謂之曰：我與卿言，於此不盡，可來延英。訪及大政，多所匡益。或謂皋曰：\"自乾元已來，群臣啟事皆詣延英得盡。公何獨於外庭對眾官以陳之？無乃失於慎密乎？\"公曰：\"御史，天下之平也。摧刚植柔，惟在於公，何故不當人知之？奈何求請便殿，避人竊語，以私國家之法？且肅宗以苗晉卿年老艱步，故設延英。後來得對者多私自希寵，幹求相位，奈何以此為望哉？\"","sortOrder":13},
  {"id":"s_work_dnl_6_14","chapterId":"ch_work_dnl_6","text":"高平徐弘毅為知彈侍御史，創置一知班官，令自宣政門檢朝官之失儀者，到台司舉而罰焉。有公卿大僚令問之曰：\"未到班行之中，何必拾人細事？\"弘毅報曰：\"為我謝公卿。所以然，不以惡其無禮於其君。\"（案：此下有缺文）","sortOrder":14},
  {"id":"s_work_dnl_6_15","chapterId":"ch_work_dnl_6","text":"代宗時久旱，京兆尹黎幹於朱雀門街造龍，召城中巫覡舞雩。幹與巫覡史起舞，觀者駭笑。經月不雨，幹又請祷於文宣王。上聞之曰：\"丘之祷久矣。\"命毀土龍，罢祈雨，减膳節用，以聽天命。及是大霈，百官入贺。","sortOrder":15},
  {"id":"s_work_dnl_6_16","chapterId":"ch_work_dnl_6","text":"李希烈跋扈蔡州。時盧杞為相，奏顏魯公往宣諭，而謂顏曰：\"十三丈此行自聖意。\"顏曰：\"公之先忠烈公面上血，是某舐之。忍以垂死之年餌虎口。\"杞聞之，踣焉。盧即是御史中丞奕之子。","sortOrder":16},
  {"id":"s_work_dnl_6_17","chapterId":"ch_work_dnl_6","text":"裴為陝府錄事參軍。李岍公勉除長史充觀察。始至官，屬吏謁訖，令別召裴錄事，與之語。公曰：\"少頃有燕，便請隨判官同赴。\"凡三召，不至。公怒，明日召，讓之曰：\"久聞公名，故超禮分相召，何忽而不至？\"曰：'必也正名'，'各司其局'，古人所守，某敢忘之？中丞自有賓僚，某走吏也，安得同宴？\"岍公曰：\"吾過矣。\"遂請入幕。之子充，太常寺太祝，年甚少，時京司書考官之清高者，例得上考。充之同辈皆上中考，充訴於卿長，曰：\"此舊例也。\"充曰：\"奉常職重地高，不同他寺。本設考課，為奖励，有勞則書，豈系於官秩？若一以官上下為優劣，則卿當上上考，少卿上中考，丞中上考，主簿中考，协律下考，某等當受杖矣。\"卿笑且慚，遂特書\"上\"。後累遷同州刺史，所在有能名。充至湖州刺史。","sortOrder":17},
  {"id":"s_work_dnl_6_18","chapterId":"ch_work_dnl_6","text":"張萬福以父祖力儒不達，因焚書，從軍遼東有功，累官至右散騎常侍致仕。萬福為人慷慨，嫉险佞，雖妻子未嘗敢辄幹。嘗径造延英門，贺諫官陽城雪陆贽冤，時人稱之。仕宦七十年，未嘗病一日。雖不識字，為九郡，皆有惠愛。","sortOrder":18},
  {"id":"s_work_dnl_6_19","chapterId":"ch_work_dnl_6","text":"順宗寢疾，韦執誼、王叔文等竊弄權柄。憲宗在東宮，執誼懼之，遂令給事中陆质侍讀，潛伺上意，因解之。及质發言，上曰：\"陛下令先生與寡人講讀，何得言他？\"惶懼而出。","sortOrder":19},
  {"id":"s_work_dnl_6_20","chapterId":"ch_work_dnl_6","text":"李相國忠公，貞元十九年為饒州刺史。先是郡城已連失四牧，故府废者七稔。公莅任後，命啟鑰而居之。郡吏以有怪堅請，公曰：\"神好正直，守直則神避；妖不勝德，失德則妖興。居之在人。\"","sortOrder":20},
  {"id":"s_work_dnl_6_21","chapterId":"ch_work_dnl_6","text":"李忠公之為相也，政事堂有會食之床。吏人相傳，移之則宰臣當罢。不遷者五十年。公曰：\"朝夕論道之所，豈可使朽蠹之物秽而不除？俗言拘忌，何足聽也！以此獲免，餘之願焉。敢彻而焚之。\"其下铲去聚壤十四畚，議者稱焉。","sortOrder":21},
  {"id":"s_work_dnl_6_22","chapterId":"ch_work_dnl_6","text":"裴先德在中書。有故人，官亦不卑，自遠而至，給恤甚厚，從容款狎。乘間求京府判司，曰：\"公誠佳士也，但此官與公不相當，不敢以故人之私，而隳朝廷綱紀。他日有瞎眼宰相怜公者，不妨却得。\"其執守如此。","sortOrder":22},
  {"id":"s_work_dnl_6_23","chapterId":"ch_work_dnl_6","text":"柳元公初拜京兆尹，將趕上，有神策軍小將乘馬不避，公於市中杖殺之。及因入對，憲宗正色詰专殺之状。公曰：\"京兆尹，天下取則之地。臣初受陛下奖擢，軍中偏裨躍馬冲過，此乃輕陛下典法，不獨试臣。臣知杖無禮之人，不知打神策軍將。\"上曰：\"卿何不奏？\"公曰：\"臣只合决，不合奏。\"曰：\"既死，合是何人奏？\"公曰：\"在街中，本街使金吾將軍奏；若在坊內，則左右巡使奏。\"上乃止。","sortOrder":23},
  {"id":"s_work_dnl_6_24","chapterId":"ch_work_dnl_6","text":"柳公綽善張正甫。柳之子仲郢嘗遇張於途，去蓋下馬而拜，張却之，不從。他日，張言於公綽曰：\"寿郎相逢，其禮太過。\"柳作色不應。久之，張去，柳謂客曰：\"張尚書與公綽往還，欲使兒子街市騎馬冲公綽耶？\"張聞，深謝之。寿郎，仲郢小字也。公綽為西川從事，嘗納一姬，同院知之，或征其出妓者。公綽曰：\"士有一妻一妾，以主中饋，備洒扫。公綽買妾，非妓也。\"","sortOrder":24},
  {"id":"s_work_dnl_6_25","chapterId":"ch_work_dnl_6","text":"張正甫為河南尹，裴中令伐淮西，置宴府西亭。裴公舉一人詞藝好解頭，張正色曰：\"相公此行何為也？何記得河南府解頭！\"中令有慚色。","sortOrder":25},
  {"id":"s_work_dnl_6_26","chapterId":"ch_work_dnl_6","text":"韓愈病將卒，召群僧曰：\"吾不藥，今將病死矣。汝詳视吾手足支體，無誑人雲'韓愈癩死'也。\"","sortOrder":26},
  {"id":"s_work_dnl_6_27","chapterId":"ch_work_dnl_6","text":"文宗時，昭義軍節度使劉從諫袭父帥潞，少年明俊，自謂河朔近無倫比。及入朝，公卿輻凑其門。廣納金帛於權幸，名譽甚著。求帶平章事，人多許之，而憚宰相李固言，欲觀其意。遇休假，謁於私第，遂言其情。固言曰：\"仆射先君以天平功書於簡册，及镇上党，近二十年，但聚斂货财，雄壮軍旅，不發一卒戍邊，未嘗修朝觐之禮。及即世後，仆射從三軍之情，擅領戎務，坐邀爵秩。朝廷以仆射先君勋績，不絕賞延，當領偏師，输忠沧景，遂不行典憲，將何以上報國恩？既不能效田承嗣、張茂昭、王承元，携家赴闕，永保祿位，則請邊陲一镇，拓境复疆，朝廷豈不以袞職命賞？區區求之，一何容易！\"從諫矍然失色，再拜趨出。從諫厚結幸臣，竟加同平章事。宰相餞於郵亭，李公曰：\"相公少年，勉報國恩，幸保家，勿殃後嗣。\"從諫以笏叩額下淚。至镇，謂將校曰：\"昨者朝觐，遍觀德望，唯李公峻直貞明，凛凛可懼，真社稷之臣也！\"","sortOrder":27},
  {"id":"s_work_dnl_6_28","chapterId":"ch_work_dnl_6","text":"唐尚書特，太和六年，尉渭南，為京兆府试進士官。杜丞相時為京兆尹，將托親知間等第（原註：時重十人內為等第），召公從容，兼命茶酒。及語舉人，則趨而下階，俯伏不對。杜公竟不敢言而止。是年上等內近三十餘人，數年內皆及第，無缺落者，前後莫比。","sortOrder":28},
  {"id":"s_work_dnl_6_29","chapterId":"ch_work_dnl_6","text":"崔慎由以元和元年登第，至开成，已入翰林。因寓直，忽中夜有內使宣召，引入數重門，至一處，堂宇華复，帘幕重蔽，見二中尉對燭而坐，謂慎由曰：\"上不豫已來已數日，兼自登極後聖政多虧，今奉太後中旨，有命學士草废立令。\"慎由大驚曰：\"某有中外親族數千口，兄弟甥侄仅三百人，一旦聞此覆族之言，實不敢承命！况聖上高明之德，覆於八荒，豈可輕議？\"二中尉默然，無以為對。良久，啟後戶，引慎由至一小殿，見文宗坐於殿上，二人趨階而數文宗過惡，上惟亻免首。又曰：\"不為此拗木枕错失，不合更在坐矣。\"仍戒慎由曰：\"事泄，即汝也。\"於是二中尉自執炬送慎由出殿門，复令中使送至院。拗木枕者，俗談強項也。慎由尋以疾出翰林，遂金其事，付其子垂休，遂切於剿絕宦官者由此。","sortOrder":29},
  {"id":"s_work_dnl_6_30","chapterId":"ch_work_dnl_6","text":"李相石在中書，京兆尹薛元賞謁石於私第。故事：百僚將至宰相宅，前驅不复呵。元賞下馬，石未之知，方在廳，若與人訴競者。元賞問焉，雲：\"軍中軍將。\"元賞排闼進，曰：\"相公，朝廷大臣，天子所委註。撫蠻夷，和陰陽，安百姓，葉眾心，無敢乖谬；升絀賢不肖，賞功罰罪，皆公之職。安有軍中一將，而敢如此哉！夫貴賤失序，綱紀之紊，常必由之。苟朝廷如此，猶望相公整頓頹坏，豈有出自相公者！\"即疾趨而去，顧左右曰：\"無禮軍將，可擒於馬下桥祗候。\"元賞比至，則袒臂跽之矣。中尉仇士良有威權，其辈已有訴之者，宦官連聲傳士良命曰：\"中尉奉屈大尹。\"元賞不答，即命杖殺之。士良大怒，元賞乃白衣請見士良，士良出曰：\"敢必杖殺軍中大將，可乎？\"元賞即具言無禮状，且曰：\"宰相，大臣也；中尉，大臣也。彼既可無禮於此，此獨不可以無禮於彼乎！國家之法，中尉所宜保守，一旦坏之可惜。某已白衫，惟中尉命。\"士良以其理直，命左右取酒飲之而罢。","sortOrder":30},
  {"id":"s_work_dnl_6_31","chapterId":"ch_work_dnl_6","text":"李石從子庾，少擢進士第，石之力也。累拜監察御史，分司東都。崔相铉镇淮南，到洛累日不拜塋，庾封其節，將奏之，時人稱焉。","sortOrder":31},
  {"id":"s_work_dnl_6_32","chapterId":"ch_work_dnl_6","text":"武宗數幸教坊作樂，優倡雜進。酒酣，作技諧謔，如民間宴席，上甚悅。諫官奏疏，乃不复出。遂召優倡入，敕內人習之。宦者請令扬州選擇妓女，詔扬州監軍取解酒令妓女十人進入。監軍得詔，詣節度使杜，請同於管內選擇。曰：\"監軍自承旨。不奉詔書，不可擅預椒房事。\"監軍怒，奏之，宦者請併下驚，上曰：\"不可。藩方取妓女入宮掖，非禹、湯所為，斯極細事，豈宜詔大臣。杜累朝舊德，深得大體，真宰相也！\"及入相，中謝，上曰：\"昨詔淮南監軍選擇酒令妓女，欲因行幸，舉酒為歡樂耳。音聲使奏，偶然下命。朕德化未被，而色荒外聞，賴卿不徇苟且；不然，天下將獻納取悅，朕何由得知？報卿忠谠，命卿作相，內懷自贺，如得魏徵。\"","sortOrder":32},
  {"id":"s_work_dnl_6_33","chapterId":"ch_work_dnl_6","text":"懿安郭太後既崩，禮院檢讨王請景陵，配饗憲宗廟，宣宗大怒。宰相白敏中召，詰其事。曰：\"郭太後是憲宗元妃，汾陽王孫，迨事順宗為婦。憲宗崩，事出暧昧，母天下五朝，不可以疑似之事，黜合配之禮。\"敏中怒甚，聲色益壮。宰相將會食，周墀立敏中廳門以候，敏中語墀：\"正為一書生惱亂，但乞先之。\"墀就敏中問其事，益不屈。墀以手加額，賞其正直。翌日，貶句容縣令，墀亦免相。大中十三年秋八月，上崩，令狐為山陵禮儀使，奏為判官。又論懿安合配享憲宗，始升焉。","sortOrder":33},
  {"id":"s_work_dnl_6_34","chapterId":"ch_work_dnl_6","text":"韦澳為京兆尹，豪右斂手。鄭光，宣宗舅，莊租不納。澳系其主者，期以五日，不足，必抵法。太後為言之。上延英問澳，曰：\"今日納租足！放否？\"澳曰：\"尚在限內，來日即不得矣！\"澳既出，上連召之，曰：\"國舅莊租今日納足，放主者否？\"噢曰：\"必放。\"上白太後曰：\"韦澳不可犯，且與送錢納却。\"頃刻而租足。（案：此事已見《政事門》，文有異同，今併存之）","sortOrder":34},
  {"id":"s_work_dnl_6_35","chapterId":"ch_work_dnl_6","text":"李景讓、夏侯孜立朝有風采。景讓為御史大夫，视事之日，以侍御史孫玉汝、監察御史盧柏王觌不稱職，請移他官。孜為右丞，以職方郎中裴誠、虞部郎中韓瞻無聲績，詼諧取容，誠改太子中允，瞻為鳳州刺史。","sortOrder":35},
  {"id":"s_work_dnl_6_36","chapterId":"ch_work_dnl_6","text":"李景讓為御史大夫，宰相宅有看街樓，皆封泥之，懼其劾奏也。然終以強毅為眾所忌。故事：除大夫百日內，他人拜相，謂之辱台。景讓未旬，蒋相伸先拜，景讓除西川節度。不逾年，致仕歸東都。","sortOrder":36},
  {"id":"s_work_dnl_6_37","chapterId":"ch_work_dnl_6","text":"崔瑤知貢舉，以貴要自恃，不畏外議。榜出，率皆權豪子弟。其弟兄見之，辄曰：\"勿觀察吾眼。\"","sortOrder":37},
  {"id":"s_work_dnl_6_38","chapterId":"ch_work_dnl_6","text":"劉允章祖伯刍，父宽夫，皆有重名。允章少孤自立，以臧否為己任。及掌貢舉，尤惡朋党。初，進士有\"十哲\"之號，皆通連中官，郭、羅虬皆其徒也。每歲，有司無不為其幹撓，根蒂牢固，堅不可破。都尉於琮，方以恩泽主鹽鐵，為極力，允章不應，竟不就试。比考帖，虬居其間，允章誦其涛，有\"帘外桃花曬熟紅\"，不知'熟紅'何用？虬已具在去留中，對曰：\"《詩》雲'關關雎鳩，在河之洲；窈窕淑女，君子好逑。'侍郎得不思之？\"頃之唱落，眾莫不失色。及出榜，惑於浮說，予奪不能塞時望。允章自鄂渚分司東都，其製，中書舍人孔晦之辭。弟纾為諫官，乃允章門生，率同年送於坡下。纾猶欲前行，允章正色曰：\"請违公不去。\"故事：門生無答拜者，允章於是答拜，同行皆愕然。","sortOrder":38},
  {"id":"s_work_dnl_6_39","chapterId":"ch_work_dnl_6","text":"懿宗迎佛骨，自鳳翔至內，禮儀盛於郊祀。中出一道，夹以連索，不得辄有犯者。車馬相接，締以組繡，緣路迎拜，數十里不絕。天子親幸安福樓，以錦彩成桥，骨至，即降樓禮訖，然後迎入禁中，置於安國寺。宰相以下，施财不可勝計。百姓競為浮圖，以至失業。明年，懿宗崩，京兆尹薛逢毀之無遺。","sortOrder":39},
  {"id":"s_work_dnl_6_40","chapterId":"ch_work_dnl_6","text":"封侍郎知舉，首訪能賦人。盧骈詣羅邵舆雲：\"主司愛賦十九官。\"羅曰：\"主司安邑住，邵舆居宣平，彼處愛賦，無由得知。\"","sortOrder":40},
  {"id":"s_work_dnl_6_41","chapterId":"ch_work_dnl_6","text":"鄭少尹師薰知舉，放榜日，畢令到宅謝恩。至萧相公知舉。放榜日，併無人及門，時論稱之。主司放榜日，於貢院見門生，惟廣南鄭尚書及楊侍郎。禮部故事：每年主司中場多作風采，鄭詹尹知舉第一，李侍郎藩知舉落人極多。唯許下杜相公帖日，每去一人，必吁嗟移時。","sortOrder":41},
  {"id":"s_work_dnl_6_42","chapterId":"ch_work_dnl_6","text":"太宗得鷂子俊異，私自臂之，望見魏公，乃藏於懷。公知之，遂前白事，因話自古帝王逸豫，微以為諷。上惜鷂子恐死，而又素嚴憚徵，欲盡其言。徵語愈久，鷂竟死懷中。","sortOrder":42},
  {"id":"s_work_dnl_6_43","chapterId":"ch_work_dnl_6","text":"貞觀中，西域獻胡僧，咒術能生死人。太宗令於飛騎中選卒之壮勇者试之，如言而死，如言而蘇。帝以告宗正卿傅奕，奕曰：\"此邪法也。臣聞邪不幹正，若使咒臣，必不能行。\"帝召僧咒奕，奕對之，初無所覺。須臾，胡僧忽然自倒，若為物所击者，更不复蘇。","sortOrder":43},
  {"id":"s_work_dnl_6_44","chapterId":"ch_work_dnl_6","text":"王義方，時人比之稷、契。鄭公每雲：\"王生太直。\"高宗朝，李義府引為御史。李以定册立武後勋，恃寵任势，王惡而彈之，坐是見貶，坎坷以至於終。","sortOrder":44},
  {"id":"s_work_dnl_6_45","chapterId":"ch_work_dnl_6","text":"徐大理有功，每見武後將殺人，必據法廷爭。嘗與武後反复，詞色愈厲，後大怒，令拽出斬之，猶回顧曰：\"身雖死，法終不可改。\"至市，臨刑得免，除為庶人。如是再三，終不挫折。朝廷倚賴，至今猶憶之。其子預選，有司皆曰：\"徐公之子，安可拘以常調乎？\"","sortOrder":45},
  {"id":"s_work_dnl_6_46","chapterId":"ch_work_dnl_6","text":"狄內史仁杰，始為江南安撫使，以周赧王、項羽、吳夫概王、春申君、趙佗、馬援、吳桓王等神廟七百餘所，有害於人，悉除之，惟夏禹、吳太伯、季札、伍子胥四廟存焉。（案：此事已見本門首條。文有詳略，今併存之）","sortOrder":46},
  {"id":"s_work_dnl_6_47","chapterId":"ch_work_dnl_6","text":"李日知為大理丞，武後方肆戮，胡元禮承旨，欲陷人死刑，令日知改斷，再三不從。元禮使人謂李曰：\"胡元禮在，此人莫觅活。\"李謂使者曰：\"日知在，此人莫觅死。\"竟免之。","sortOrder":47},
  {"id":"s_work_dnl_6_48","chapterId":"ch_work_dnl_6","text":"高祖即位，以舞胡安叱奴為散騎侍郎，禮部尚書李綱進諫曰：\"臣按周禮：均工樂胥，不參士伍，雖复才如子野，妙等師曠，皆終身繼代，不改其業。故魏武帝欲使祢衡击鼓，乃解朝衣，露體而击之，問其故，對曰：'不敢以先王法服，為伶人衣也。'雖齊高緯封曹妙達為王，安馬駒為开府，有國家者但為殷鑒。天下新定，开太平之運，起義功臣；行賞未遍；高才硕學，猶滯草萊，而先令舞胡致位五品，鳴玉曳組，趨馳廟廊，固非創業規模，貽厥子孫之道。\"高祖竟不能從。","sortOrder":48},
  {"id":"s_work_dnl_6_49","chapterId":"ch_work_dnl_6","text":"周興、來俊臣羅織衣冠，朝野懼慑。御史大夫李嗣真上疏諫曰：\"臣聞曲逆之事漢祖，謀疏楚之君臣，乃用黃金七千斤，行反間之術，項羽果疑臣下，陳平之計遂行。今告事紛紜，虛多實少，如當有凶慝，焉知不先謀疏陛下君臣，後除國家良善？臣恐為社稷之禍。伏乞陛下回思遷慮，察臣狂瞽，然後退就鼎镬，實無所恨。臣得没為忠鬼，孰與存為諂人。如羅織之徒，即是疏間之漸，陳平反間，其遠乎哉！\"遂為俊臣所構，放於嶺表。俊臣死，征還，途次桂陽而終，赠濟州刺史。中宗朝，追复本官。","sortOrder":49},
  {"id":"s_work_dnl_6_50","chapterId":"ch_work_dnl_6","text":"武三思得幸於中宮，京兆人韦月將等不堪憤激，上書告白其事。中宗惑之，命斬月將。黃門侍郎宋執奏，請按而後刑。中宗愈怒，不及整衣履，岸巾出侧門，迎謂曰：\"朕以為斬矣，何以缓之？\"命促斬。曰：\"人言中宮私於三思，陛下竟不問而斬之，臣恐有竊議。\"固請按而後刑。中宗大怒，曰：\"請先斬臣，不然終不奉詔。\"乃流月將於嶺南，尋使人殺之。","sortOrder":50},
  {"id":"s_work_dnl_6_51","chapterId":"ch_work_dnl_6","text":"睿宗朝，太平公主用事。柳浑以斜封官复舊職，上疏諫曰：\"陛下即位之初，納姚、宋之計，鹹黜斜封。今以斜封之人不忍弃，是先帝之意不可违。若斜封之人不忍弃，是韦月將、燕钦融之流不可褒赠，李多祚、鄭克之徒不可清雪。陛下何不能忍於此而忍於彼？使善惡不定，反覆相攻，致令君子之道消，小人之道長，為正者衔冤，附伪者得志，將何以止奸邪？將何以懲風俗耶？\"睿宗遂從之，因而擢浑拜監察御史。（原註：《太平御覽》曰：\"柳浑拜監察御史，台中執法之地，動限儀矩。浑性放曠，不甚檢束。察長拘謹，忿其疏縱，浑不樂，乞外任。執政惜其才，特奏為左補闕。\"）","sortOrder":51},
  {"id":"s_work_dnl_6_52","chapterId":"ch_work_dnl_6","text":"韦仁約彈右仆射褚遂良，出為同州刺史。遂良复職，黜仁約為清水令。或慰勉之，仁約對曰：\"仆狂鄙之性，假以雄權，而觸物便發。丈夫當正色之地，必明目張胆然，不能碌碌為保妻子也。\"時武候將軍田仁會與侍御史張仁不协而誣奏之。高宗臨軒問仁，仁惶懼，應對失次。仁約歷階進曰：\"臣與仁連曹，頗知事由。仁懦而不能自理。若仁會眩惑聖聽，致仁非常之罪，則臣事陛下不盡，臣之恨矣。請专對其状。\"詞辯縱橫，高宗深納之，乃釋仁。仁約在憲司，於王公卿相未嘗行拜禮，人或勸之，答曰：\"雕鹗鷹，豈眾禽之偶！奈何設拜以卑之！且耳目之官，固當獨立耳。\"後為左丞，奏曰：\"陛下為官擇人，無其人則闕。今不惜美錦，令臣製之，此陛下知臣之深矣。\"振舉綱目，朝廷肅然。","sortOrder":52},
  {"id":"s_work_dnl_6_53","chapterId":"ch_work_dnl_6","text":"李義府恃恩放縱，婦人淳於氏有容色，坐系大理，乃托大理丞畢正義曲斷出之。或有告之者，詔劉仁軌鞫之。義府懼泄，系正義於獄。侍御史王義方將彈之，告其母曰：\"奸臣當路，懷祿而曠官，不忠；老母在堂，犯難以危身，不孝。進退惶惑，不知所從。\"母曰：\"吾聞王母殺身以成子之義。汝若事君盡忠，立名千載，吾死不恨焉。\"義方乃備法冠，橫玉階彈之。先叱義府令下，三叱乃出，然後跪宣彈文雲雲。高宗以義方毀辱大臣，言辭不遜，貶葉州司戶。秩滿，於昌樂聚徒教授。母亡，遂不复仕進。總章二年卒。撰《筆海》十卷。門人何彦先、員半千製師服三年，畢丧而去。","sortOrder":53},
  {"id":"s_work_dnl_6_54","chapterId":"ch_work_dnl_6","text":"李昭德在則天朝，時諛佞者必擢用，有人於洛水中獲白石，有數點赤，詣闕請進。宰臣詰之，其人曰：\"此石赤心，所以進。\"昭德叱之曰：\"洛水石豈盡反耶？\"左右皆大笑。昭德建立東都羅城及尚書省洛水中桥，人不知役而功成就。除數凶人，獄遂罢。以持正廷諍，為皇甫文所構，（案：《唐書·李昭德傳》：昭德為邱、邓汪所構，與此異）與來俊臣同日弃市。國人歡憾相半，哀昭德而快俊臣也。","sortOrder":54},
  {"id":"s_work_dnl_6_55","chapterId":"ch_work_dnl_6","text":"魏元忠以摧辱二張，反為所構，雲結少年為耐久朋。則天大怒，下獄勘之，易之以張說為證。召大臣，令元忠與易之、說等定是非，說氣逼不應。元忠懼，謂說曰：\"張說與易之共羅織魏元忠耶？\"說叱曰：\"魏元忠為宰相，而有委巷'羅織'之言，豈大臣所謂！\"則天又令說言元忠不軌状，說曰：\"臣不聞也。\"易之遽曰：\"張說與元忠同逆。\"則天問其故，易之曰：\"說往時謂元忠居伊、周之地，臣以伊尹放太甲，周公攝成王之位，此其状也。\"說奏曰：\"易之、昌宗大無知，所言伊、周徒聞其語耳，不知伊、周之本末。元忠初加拜命，授紫綬，臣以郎官拜贺。元忠曰：'無尺寸之功，而居重任，不勝畏懼。'臣曰：'公當伊、周之任，何愧三品？'然伊、周歷代書為忠臣，陛下遣臣不學伊、周，使臣將何所學？\"說又曰：\"易之以臣宗室，故托為党。然附易之，有台辅之望；附元忠，有族滅之势。臣不敢面欺，亦懼元忠冤魂耳。\"遂焚香為誓。元忠免死，流放嶺南。","sortOrder":55},
  {"id":"s_work_dnl_6_56","chapterId":"ch_work_dnl_6","text":"張易之、昌宗貴寵用事，有潛相者言其當王，险薄者多附會之。長安中，右衛西街有榜雲：\"易之兄弟、長孫汲、裴安立等謀反。\"宋時為御史中丞，奏請窮理其状。則天曰：\"易之已有奏聞，不可加罪。\"曰：\"易之為飛書所逼，窮而自陳。且謀反大逆，法無容免。請勒就台勘當，以明國法。易之等久蒙驅使，分外承恩，臣言發禍從，即入鼎镬，然義激於心，雖死不恨。\"則天不悅。內史楊再思遽宣王命，左拾遺李邕歷階而進曰：\"宋所爭，事為國家社稷，望陛下可其所奏。\"則天意始解。乃傳命，令易之就獄推問。斯須，特敕原之，仍遣易之、昌宗就辭謝。拒而不見，令使者謂之曰：\"公事當公言之。私見即私，法無私也。\"謂左右：\"恨不先打竖子腦破，而令混亂國經，吾負此恨久矣！\"時朝列呼易之、昌宗為\"五郎\"、\"六郎\"，鄭杲曰：\"公何稱易之為卿？\"曰：\"鄭杲何庸之甚！若以官秩，正當卿號；若以親，當為'張五郎'、'六郎'矣。足下非張氏家僮，號五郎、六郎，何也？\"杲大慚而退。","sortOrder":56},
  {"id":"s_work_dnl_6_57","chapterId":"ch_work_dnl_6","text":"宋。則天朝，以頻論得失不能容，而憚其公正，乃止敕往扬州推按。奏曰：\"臣以不才，叨居憲府，按州縣乃監察御史事耳，今非意差臣，不識其所謂，請不奉製。\"無何，复令按幽州都督屈突仲翔。复奏曰：\"御史中丞，非軍國大事不當出。且仲翔所犯贓污耳，今高品有侍御史，卑品有監察御史，今敕臣，恐陛下有危臣之意，請不奉製。\"月餘，優詔令副李峤使蜀，峤喜，召曰：\"叨奉渥恩，與公同謝。\"曰：\"恩製示禮數，不以禮遣，不當行，謹不謝。\"乃上言曰：\"以臣副峤，何也？恐乖朝廷故事，請不奉製。\"易之等冀出使，當別以事誅之。既不果，伺家有婚禮，將刺殺之。有密以告者，乘車舍於他所，乃免。易之尋伏誅。","sortOrder":57},
  {"id":"s_work_dnl_6_58","chapterId":"ch_work_dnl_6","text":"宗楚客兄秦客潛勸則天革命，累遷內史，後以贓罪流於嶺南死。楚客無他材能，附會武三思，神龍中為中書舍人。時西突厥阿史那與忠節不和，安西都護郭元振奏請徙忠節於內地，楚客與弟晉卿及紀處讷等納忠節厚賂，請發兵以讨西突厥，不納元振之奏。突厥大怒，舉兵入寇，甚為邊患。監察御史崔琬劾楚客等，中宗不從，遽令與琬和解。俄而韦氏败，楚客等鹹誅。","sortOrder":58},
  {"id":"s_work_dnl_6_59","chapterId":"ch_work_dnl_6","text":"文宗謂宰臣曰：\"太宗得魏徵，采拾闕遺，弼成聖政；今我得魏暮，於疑似之間，必極匡諫，雖不敢望貞觀之政，庶幾處無過之地。\"令授暮右補闕，敕舍人善為詞。又問暮曰：\"卿家有何圖書？\"暮曰：\"家書悉無，惟有文貞公笏在。\"文宗令進來。鄭覃在侧曰：\"在人不在笏。\"文宗曰：\"卿浑未晓。但甘棠之義，非要笏也。\"","sortOrder":59},
  {"id":"s_work_dnl_6_60","chapterId":"ch_work_dnl_6","text":"崔顥有美名，李邕常欲一見。及顥至獻文，其首雲：\"十五嫁王昌。\"邕叱起曰：\"小子無禮。\"遂不接。","sortOrder":60},
  {"id":"s_work_dnl_6_61","chapterId":"ch_work_dnl_6","text":"肅宗以王至為相，尚鬼神之事，分遣女巫遍祷山川。有巫者少年盛服，乘傳而行，中使隨之，所至誅求金帛，積載於後，與惡少十數辈橫行州縣。至黃州，左震為刺史，晨至驿門，扃戶不啟。震命坏鎖而入，曳巫斬階下，惡少皆死。籍其缗鉅萬，金寶堆積，悉列上曰：\"臣已斬巫。請以所籍錢，代臣貧民输稅，其中使送上，臣請死。\"朝廷慰奖之。","sortOrder":61},
  {"id":"s_work_dnl_6_62","chapterId":"ch_work_dnl_6","text":"李公勉罢嶺南節度，至石門停舟，悉搜家人犀象投水中。","sortOrder":62},
  {"id":"s_work_dnl_6_63","chapterId":"ch_work_dnl_6","text":"德宗在東宮，雅好楊崖州字，嘗令打《李楷洛碑》，釘壁以玩。及即位，征拜。炎有崖穀，言論持正，對見必為之加敬，歲餘不倦。及後以劉晏事，上不怿，盧杞揣知上意，因傾之。","sortOrder":63},
  {"id":"s_work_dnl_6_64","chapterId":"ch_work_dnl_6","text":"許孟容為給事中，宦者有以權幸相誘者，拒絕之。雖不大拜，亦不為患。","sortOrder":64},
  {"id":"s_work_dnl_6_65","chapterId":"ch_work_dnl_6","text":"韦相貫之為右丞，僧廣宣造門曰：\"竊知閣下不久拜相。\"貫之叱曰：\"安得此言。\"命草奏，僧惶恐而出。","sortOrder":65},
  {"id":"s_work_dnl_6_66","chapterId":"ch_work_dnl_6","text":"朝廷每降使新羅，其國必以金寶厚為之赠，唯李納判官一無所受，深為同辈所嫉。","sortOrder":66},
  {"id":"s_work_dnl_7_1","chapterId":"ch_work_dnl_7","text":"●卷三·雅量","sortOrder":1},
  {"id":"s_work_dnl_7_2","chapterId":"ch_work_dnl_7","text":"狄梁公與娄師德同為相，狄公排斥師德非一日，則天問狄公曰：\"朕大用卿，卿知所自乎？\"對曰：\"臣以文章直道進身，非碌碌因人成事。\"則天久之曰：\"朕比不知卿，卿之遭遇，實師德之力。\"因命左右取筐箧，得十許通荐表，以賜梁公。梁公閱之，恐懼引咎，則天不责。出於外曰：\"吾不意為娄公所涵，而娄公未嘗有矜色。\"","sortOrder":2},
  {"id":"s_work_dnl_7_3","chapterId":"ch_work_dnl_7","text":"唐公臨性宽仁多恕，嘗欲弔丧，令家僮歸取白衫，僮仆誤持餘衣，懼未敢進。臨察之，謂曰：\"今日氣逆，不宜哀泣，向取白衫且止之。\"又令煮藥，不精，潛覺其故，又謂曰：\"今日陰晦，不宜服藥，可弃之。\"終不扬其過失。","sortOrder":3},
  {"id":"s_work_dnl_7_4","chapterId":"ch_work_dnl_7","text":"裴度在中書，印忽亡失，度命張筵，舉座不晓其故。夜半宴酣，左右曰：\"印复得。\"度不答，極歡而罢。或問其故，度曰：\"此蓋諸胥盜印書券耳。缓之則存，急之則投諸水火。\"人服其臨事不撓。","sortOrder":4},
  {"id":"s_work_dnl_7_5","chapterId":"ch_work_dnl_7","text":"陽道州城未嘗有所蓄積，雖所服用不可闕者，客稱某物可佳可愛，公辄喜授之。有陳萇者，候其始請月俸，常往稱其錢帛之美，月有獲焉。","sortOrder":5},
  {"id":"s_work_dnl_7_6","chapterId":"ch_work_dnl_7","text":"韓皋為京兆尹。時久旱祈雨，縣官讀祝文，专心記公家讳，及稱官衔畢，誤呼先相之名，皋但惨然，因命重讀，亦不加责。在夏口，嘗病小瘡，令医傅膏不濡，公問之，医雲：\"天寒膏硬。\"公笑曰：\"韓皋實是硬。\"初皋自貶所量移錢塘，與李不协。後皋在鄂州，夢萬歲樓上掛冰，因自解曰：\"冰者，寒也；樓者，高也。豈韓皋來代我乎？\"意甚惡之，果移镇浙右。","sortOrder":6},
  {"id":"s_work_dnl_7_7","chapterId":"ch_work_dnl_7","text":"文宗對翰林諸學士，因論前代文章，裴舍人素數稱陳拾遺名，柳舍人目之，裴不覺。上顧柳曰：\"陳字伯玉，近亦多以字行。\"","sortOrder":7},
  {"id":"s_work_dnl_7_8","chapterId":"ch_work_dnl_7","text":"裴晉公為門下侍郎，過吏部選人官，謂同過給事中曰：\"吾徒僥悻至多；此辈優一資半級，何足問也？\"一皆註定，未曾退量。公不信術數，不好服食，每語人曰：\"雞猪魚蒜，逢著則吃；生老病死，時至則行。\"其宏達皆此類。","sortOrder":8},
  {"id":"s_work_dnl_7_9","chapterId":"ch_work_dnl_7","text":"文宗將有事南郊，祀前，本司進相扑人。上曰：\"方清齊，豈合觀此事？\"左右曰：\"舊例也，已在外祗候。\"上曰：\"此應是要賞物，可向外相扑了。\"即與賞令去。又嘗觀斗雞，優人稱叹大好雞，上曰：\"雞好，便賜汝。\"","sortOrder":9},
  {"id":"s_work_dnl_7_10","chapterId":"ch_work_dnl_7","text":"文宗時入閣，郎官有誤窥者。上覺之，班退，語宰相曰：\"適省郎班內第某人，忽斜盼视朕，何也？\"裴度對曰：\"省郎卑微，安得如此！\"欲與打著。上曰：\"此小事，不打了。\"","sortOrder":10},
  {"id":"s_work_dnl_7_11","chapterId":"ch_work_dnl_7","text":"靖安李少師宗闵，不以威重自處，好與賓客飲宴談笑。善飲酒。暑月臨池，以荷為杯，滿酌酒，密系持近口，以筋刺之而飲，不盡再舉。既散，有人言：\"昨飲大歡也。\"李曰：\"今日言歡，明前日之不歡。自今好惡，一不得言。\"","sortOrder":11},
  {"id":"s_work_dnl_7_12","chapterId":"ch_work_dnl_7","text":"夏侯孜在舉場，有王生者，有時名，遇孜下第，偕遊京西，鳳翔節度使馆之，從事有宴召焉。酒酣，以骰子祝曰：\"二秀才明年但得第，當掷堂印。\"王生自負，怒曰：\"吾誠淺薄，與夏侯孜同年乎？\"不悅而去。孜後及第，累官至宰相，王生竟無所聞。孜在河中，王生之子不知有隙，偶獲孜與其父生平書疏數紙，持以謁孜。孜問其所欲，一以予之，因召諸從事，語其事。","sortOrder":12},
  {"id":"s_work_dnl_7_13","chapterId":"ch_work_dnl_7","text":"鄭公嘗拜扫還，白太宗：\"人言陛下欲幸山南，在外悉裝束，而竟不行，何有此消息？\"帝笑曰：\"當時有心，畏卿等嗔，遂停耳。\"","sortOrder":13},
  {"id":"s_work_dnl_7_14","chapterId":"ch_work_dnl_7","text":"盧尚書承慶，總章初考內外官。有督運，遭風失米，盧考之曰：\"監運損糧，考中下。\"其人容自若，無言而退。盧重其雅量，改註曰：\"非力所及，考中中。\"既無喜容，亦無愧詞，又改曰：\"寵辱不驚，考中上。\"","sortOrder":14},
  {"id":"s_work_dnl_7_15","chapterId":"ch_work_dnl_7","text":"李昭德為內史，娄師德為納言，相隨入朝。娄體肥行缓，李屢顧待不即至，乃發怒曰：\"叵耐殺人田舍漢！\"娄聞之，徐笑曰：\"師德不是田舍漢，更阿誰是？\"師德弟為岱州刺史，將別，謂之曰：\"吾以不才，位居宰相，汝今又拜州牧，叨據過分，人所疾也，將何以全先人發膚？\"弟長跪曰：\"自今唾某面上者，亦不敢言，但拭之而已。以此自勉，庶不為兄忧。\"師德曰：\"此適以為我忧也。夫前人唾者，發於怒也，汝今拭之，是惡前人唾而拭，是逆前人怒也。唾不拭而自乾，何若笑而受之？\"當武後時，竟保其寵祿，率是道也。","sortOrder":15},
  {"id":"s_work_dnl_7_16","chapterId":"ch_work_dnl_7","text":"皇甫德參上書，言：\"陛下修洛陽宮，是勞人也；收地租，厚斂也；俗尚高髻，是宮中所化也。\"太宗怒曰：\"此人欲使國家不收一租，不役一人，宮人無發，乃稱其意！\"魏徵進曰：\"贾誼當漢文帝之時，上書曰：'可痛哭者三，可長叹者五。'自古上書，率為激切。不激切，則不能動人主之心；激切，則似謗訕。所謂'狂夫之言，聖人擇焉'。惟在陛下裁察。今苟责之，則於後誰敢言？\"乃賜絹二十匹，命歸。","sortOrder":16},
  {"id":"s_work_dnl_7_17","chapterId":"ch_work_dnl_7","text":"陆兖公為同州刺史，有家僮不下馬；參軍责之，鞭其背見血。因謁曰：\"小吏犯公，請去。\"兖公頷之曰：\"奴見官人不下馬，打了，去也得，不去也得。\"參軍不测而退。（原註：當曰：\"不下馬，打也得，不打也得。官人打了，去也得，不去也得。\"）","sortOrder":17},
  {"id":"s_work_dnl_7_18","chapterId":"ch_work_dnl_7","text":"袁亻參之破袁晁，擒其伪公卿數十人，州縣大具梏，謂必生致闕下。亻參曰：\"此惡百姓，何足以煩人。\"乃笞之，遣去。","sortOrder":18},
  {"id":"s_work_dnl_7_19","chapterId":"ch_work_dnl_7","text":"韦丹少在洛陽，嘗至中桥，見數百人喧集水濱，乃漁者網得大黿，系之桥柱。丹不忍，問曰：\"幾錢可贖？\"曰：\"五千。\"丹曰：\"吾驢直三千，可乎？\"於是與之，放黿於水，徒步而歸。","sortOrder":19},
  {"id":"s_work_dnl_7_20","chapterId":"ch_work_dnl_7","text":"任迪簡為天德判官。軍中宴，後至當飲觥酒，吏誤以醋酌。迪簡以軍使李景略令酷，發之則死矣，乃強飲之，遂病吐血。軍中聞之皆泣下，景略為之省刑。及景略卒，軍中請以為主。自衛佐拜御史中丞，為觀軍使，終易定節度使。","sortOrder":20},
  {"id":"s_work_dnl_7_21","chapterId":"ch_work_dnl_7","text":"裴相嘗應宏詞，崔枢考之不第。及為相，擢之為禮部侍郎，笑曰：\"此報德也。\"枢惶恐欲墜階，又笑曰：\"戲言也。\"","sortOrder":21},
  {"id":"s_work_dnl_7_22","chapterId":"ch_work_dnl_7","text":"長慶初，趙相為太常卿，贊郊廟之禮。時罢相二十餘年，年七十六，眾服其健。右常侍郎孝奕笑曰：\"是仆為東府试官所送進士也。\"","sortOrder":22},
  {"id":"s_work_dnl_7_23","chapterId":"ch_work_dnl_7","text":"元載之败，其女資敬寺尼真一，納於掖庭。德宗即位，召至別殿，告其父死。真一自投於地，左右皆叱。德宗曰：\"焉有聞親之丧，责其哭踴？\"遂扶出，眾皆陨涕。","sortOrder":23},
  {"id":"s_work_dnl_8_1","chapterId":"ch_work_dnl_8","text":"●卷三·識鑒","sortOrder":1},
  {"id":"s_work_dnl_8_2","chapterId":"ch_work_dnl_8","text":"貞觀二十年，王師旦為員外郎，冀州進士張昌齡、王公瑾併有文辭，聲振京邑。師旦考其策為下等，舉朝不知所以。及奏等第，太宗怪問無昌齡等名，師旦對曰：\"此辈誠有詞華，然其體輕薄，文章浮艳，必不成令器。臣擢之，恐後生仿效，有变陛下風俗。\"上深然之。後昌齡為長安尉，坐贓解，而公瑾亦無所成。","sortOrder":2},
  {"id":"s_work_dnl_8_3","chapterId":"ch_work_dnl_8","text":"中宗嘗召宰相蘇瑰、李峤子進見。二子同年。上曰：\"爾宜記所通書言之。\"瑰子應曰：\"木從繩則正，後從諫則聖。\"峤子亡其名，亦進曰：\"朝涉之胫，剖賢人之心。\"上曰：\"蘇瑰有子，李峤無兒。\"","sortOrder":3},
  {"id":"s_work_dnl_8_4","chapterId":"ch_work_dnl_8","text":"張守，陝州平陵人也。自幽州入觐，過本縣，見令李元，申桑梓之禮。見陝尉李桎梏裴冕，冕呼：\"張公！困厄中豈能相救？\"至靈寶，便奏充判官。（案：《唐書·裴冕傳》：冕以王奏充判官，非張守，與此異）冕後至宰辅。","sortOrder":4},
  {"id":"s_work_dnl_8_5","chapterId":"ch_work_dnl_8","text":"代宗宽厚出於天性。幼時，玄宗每坐於前，熟视之，謂武惠妃曰：\"此兒有異相，亦是吾家一有福天子。\"","sortOrder":5},
  {"id":"s_work_dnl_8_6","chapterId":"ch_work_dnl_8","text":"西涼州俗好音樂，製《涼州》新曲，开元中列上獻之。上顧問寧王，王進曰：\"此曲雖佳，臣有聞焉：夫音者，始之於宮，散之於商，成之於角、征、羽，莫不根柢橐龠於宮、商也。宮雜而少商，征亂而加暴。臣聞：宮，君也；商，臣也。宮不勝則君势卑，商有餘則臣下僭。君卑則畏下，臣僭則犯上。蓋形之於音律，播之於歌詠，見之於人事。臣恐一日有播越之禍，悖亂之患，莫不由此曲也。\"上聞之，默然。及安祿山之亂，華夏鼎沸，所以知寧王知音之妙也。","sortOrder":6},
  {"id":"s_work_dnl_8_7","chapterId":"ch_work_dnl_8","text":"安祿山初為張韓公帳下走使。韓公嘗洗足，韓公足下有黑子，祿山竊窥之。韓公顧而笑曰：\"黑子是吾之貴相，汝何窥之？\"祿山曰：\"賤人不幸，兩足皆有，亦似將軍者，色黑而加大。\"公奇之，約為義兒，深加慰勉。","sortOrder":7},
  {"id":"s_work_dnl_8_8","chapterId":"ch_work_dnl_8","text":"王為太常卿。早起，聞永興里人吹笛，問：\"是太常樂人否？\"曰：\"然。\"已後因閱樂而撻之。問曰：\"何得罪？\"曰：\"臥吹笛。\"又見康崑崙彈琵琶，雲：\"琵聲多，琶聲少，亦未可彈五十四絲大絃也。\"自下而上謂之琵，自上而下謂之琶。","sortOrder":8},
  {"id":"s_work_dnl_8_9","chapterId":"ch_work_dnl_8","text":"裴宽尚書罢郡，西歸汴中，日晚維舟，見一人坐树下，衣服故敝。召與語，大奇之，謂\"君才識自當富貴，何貧也？\"舉船錢帛奴婢與之，客亦不讓。語訖上船，奴婢偃蹇者鞭扑之，裴公益以為奇，其人乃張建封也。","sortOrder":9},
  {"id":"s_work_dnl_8_10","chapterId":"ch_work_dnl_8","text":"杜丞相鸿漸，世號知人。見馬燧、李抱真、盧杞、陆贽、張宏靖、李藩，皆雲\"併為將相\"，既而盡然。又大司徒杜公見張弘靖，曰：\"必為宰相。\"貴人多知人也如此。","sortOrder":10},
  {"id":"s_work_dnl_8_11","chapterId":"ch_work_dnl_8","text":"潘炎，德宗時為翰林學士，恩渥極異。其妻劉氏，晏之女也。京尹某有故，伺候累日不得見，乃遺閽者三百缣。夫人知之，謂潘曰：\"豈有人臣，京尹願一見，遺奴三百缣帛？其危可知也！\"遽勸潘公避位。子孟陽，初為戶部侍郎，夫人忧惕曰：\"以爾人材而在丞郎之位，吾懼禍之必至也。\"戶部解諭再三，乃曰：\"试會爾同列，吾觀之。\"因遍招深熟者。客至，夫人垂帘视之。既罢會，喜曰：\"皆爾之儔也，不足忧矣。末後惨绿少年，何人也？\"答曰：\"補闕杜黃裳。\"夫人曰：\"此人自別，是有名卿相。\"","sortOrder":11},
  {"id":"s_work_dnl_8_12","chapterId":"ch_work_dnl_8","text":"韦獻公夏卿有知人之鑒，人不知也。因退朝，於街中逢再從弟執誼，從弟渠牟、丹，三人皆二十四，併為郎官。簇馬久之，獻公曰：\"今日逢三二十四郎，辄欲題目之。\"語執誼曰：\"汝必為宰相，善保其末耳。\"語渠牟曰：\"弟當別奉主上恩，而連貴公卿。\"語丹曰：\"三命中，弟最長遠，而位極旄鉞。\"由是竟如其言。","sortOrder":12},
  {"id":"s_work_dnl_8_13","chapterId":"ch_work_dnl_8","text":"韦獻公夏卿不經方镇，唯嘗於東都留守辟吏八人，而路公隨、皇甫崖州葛皆為宰相，張尚書贾、段給事平仲、衛大夫中行、李常侍翱、李諫議景俭、李湖南詞皆至顯官，亦知名矣。","sortOrder":13},
  {"id":"s_work_dnl_8_14","chapterId":"ch_work_dnl_8","text":"李相絳，先人為襄州督郵，方赴舉，求乡荐。時樊司空泽為節度使，張常侍正甫為判官，主乡荐。張公知丞相有前途，啟司空曰：\"舉人悉不如李某秀才，請只送一人，請眾人之資以奉之。\"欣然允诺。又荐丞相弟為同舍郎。不十年而李公登庸，感司空之恩，以司空之子宗易為朝官。人問宗易之文於丞相，答曰：\"蓋代。\"時人用以\"蓋代\"為口實，相見論文，必曰：\"莫是樊三蓋代否？\"後丞相之為戶部侍郎也，常侍為本司郎中，因會，把詩侍郎唱歌，李終不唱而哂之，滿席大噱。","sortOrder":14},
  {"id":"s_work_dnl_8_15","chapterId":"ch_work_dnl_8","text":"韓太保皋深晓音律，嘗觀客彈琴為《止息》，乃叹曰：\"妙哉，嵇生之音也！為是曲也，其當魏、晉之际乎？\"《止息》與《廣陵散》，同出而異名也。其音主商，商為秋聲，天將肅殺，草木搖落，其歲之晏乎？此所以知魏之季慢也。其商絃與宮同，時臣奪其君之位乎？此所以知司馬氏之將篡也。'廣陵'，維扬也；'散'者，流亡之謂也。'楊'者，武後之姓，言楊後與其父駿之傾覆晉祚者也。晉難興，終'止息'於此。其音哀憤而噍殺，操者蹙而傛痛，永嘉之亂，其應此乎？叔夜撰此，將貽後代之知音，且避晉禍，托之神鬼，史氏非知味者，安得不傳其谬欤？\"","sortOrder":15},
  {"id":"s_work_dnl_8_16","chapterId":"ch_work_dnl_8","text":"吳興僧晝一，字皎然，工律詩。嘗謁韦蘇州，恐詩體不合，乃於舟抒思，作古體十數篇為獻。韦皆不稱賞，晝一極失望；明日寫其舊製獻之，韦吟諷，大加叹賞。因語晝一雲：\"幾致失聲名。何不但以所工見投，而猥希老夫之意？人各有所得，非卒能致。\"晝一服其能鑒。","sortOrder":16},
  {"id":"s_work_dnl_8_17","chapterId":"ch_work_dnl_8","text":"骆浚者，度支司書手也。嘗健羨一雜事典，題詩一絕於柏树曰：\"幹耸一條青玉直，葉鋪千叠绿雲低；爭如燕雀偏巢此，却是鸞不得栖。\"會度支使巡諸司，見此題，問左右，雲：\"浚所為也。\"召與語，可聽。曰：\"錢粗晓，詞氣不卑，言語古壮，人品亦佳。\"翌日，以語巡官李吉甫，遂擢為度支巡官。浚請兼巡覆官。自以微賤，不敢廁士大夫之列。月餘，九門內勾出數十萬貫；數月，關右、蒲、潼、京西、京北、三辅勾四百萬，佐大門，却河陰斗門，曹、汴、宿、宋，無水潦之患。後典名郡，有令名。於春明門外筑台榭，食客皆名人。盧申州題詩雲：\"地如拳石，溪橫似葉舟。\"即骆氏池馆也。","sortOrder":17},
  {"id":"s_work_dnl_8_18","chapterId":"ch_work_dnl_8","text":"裴晉公為相，布衣交友、受恩子弟，報恩奖引不暫忘。大臣中有重德寡言者，忽曰：\"某與一二人皆受知裴公。白衣時，約他日顯達，彼此引重。某仕宦所得已多，然晉公有異於初，不以辅佐相許。\"晉公聞之，笑曰：\"實負初心。\"乃問人曰：\"曾見靈芝、珊瑚否？\"曰：\"此皆希世之寶。\"又曰：\"曾遊山水否？曰\"名山數遊，唯庐山瀑布状如天漢，天下無之。\"晉公曰：\"圖畫尚可悅目，何况親觀？然靈芝、珊瑚，為瑞為寶可矣，用於廣厦，須杞、梓、樟、楠；瀑布可以圖畫，而無濟於人，若以溉良田，激碾，其功莫若長河之水。某公德行文學、器度標准，為大臣儀表，望之可敬；然長厚有餘，心無機術。傷於畏怯，剝割多疑。前古人民质朴，征賦未分，地不過數千里，官不過一百員。內無權悻，外絕奸诈。畫地為獄，人不敢逃；以赭染衣，人不敢犯。雖已列郡建國，侯伯分理；當時國之大者，不及今之一縣，易為匡濟。今天子設官一萬八千，列郡三百五十，四十六連帥，八十萬甲兵。禮樂文物，軒裳士流，盛於前古。材非王佐，安敢許人！\"","sortOrder":18},
  {"id":"s_work_dnl_8_19","chapterId":"ch_work_dnl_8","text":"相國牛僧孺，或言仙客之後，居宛、葉之間。少孤貧，力學有志。永貞中擢進士第，與同辈過政事堂，宰相謂曰：\"扫廳奉候。\"僧孺獨出曰：\"不敢。\"眾耸異之。元和初，登製科，歷省郎至丞相。大中初卒。後白敏中入相，乃奏，謚曰\"簡\"。","sortOrder":19},
  {"id":"s_work_dnl_8_20","chapterId":"ch_work_dnl_8","text":"李珏，字待价，趙郡贊皇人。早孤，居淮南，養母以孝聞。舉明經，華州刺史李絳見而謂之曰：\"日角珠庭，非常人也，當掇進士科。明經碌碌，非子發跡之地。\"一舉不第。應進士舉，許孟容為禮部，擢上第。釋褐，署乌重胤河陽府推官，書判高等，授渭南縣尉，遷右拾遺，左遷下傢縣令。丁母忧，庐居三年，不入室。免丧，諸侯交辟，皆不就。牛僧孺在武昌，掌書記，歸御史府。韦處厚秉政，稱曰：\"清廟之器，豈击搏才乎？\"擢拜禮部員外郎，改吏部員外。李宗闵為相，擢知製誥，改司勋員外郎，库部郎中，文宗召充翰林學士。珏風格端肅，屬詞敏贍，恩傾一時。累遷戶部侍郎承旨，天子屢欲以為相。鄭註以方術為侍講學士，李訓自流人入內廷，珏未嘗私焉。訓、註交谮，貶江州刺史。訓誅，征為戶部侍郎，與楊嗣复同日拜相。上雖切於求理，終優遊不斷。同列陳夷行、鄭覃請經術孤立者進用，珏與嗣复論地胄詞彩者居先，每延英議政，多異同，卒無成效，但寄之頰舌而已。文宗將崩，以敬宗子陳王成美為托。武宗立，事由兩軍，貶昭州刺史。宣宗即位，累遷河陽三城節度，吏部尚書。崔鄲薨，又拜檢校左仆射、淮南節度使。三載，薨，謚貞穆。","sortOrder":20},
  {"id":"s_work_dnl_8_21","chapterId":"ch_work_dnl_8","text":"李廓為武寧軍節度使，不治，右補闕鄭魯上疏曰：\"臣恐新麥未登，徐師必亂。乞速命良將，救此一方。\"宣宗未之省。麥熟而徐師果亂，上感悟魯言，擢為起居舍人。","sortOrder":21},
  {"id":"s_work_dnl_8_22","chapterId":"ch_work_dnl_8","text":"懿宗晚年政出群下。路巖年少固位，一旦失势，當路皆仇隙，中外沸騰，所指未必實也。初，巖為淮南崔铉度支使，除監察，十年不出京師，致位宰相。铉謂巖必貴，嘗曰：\"路十終須與他那一官！\"自監察入翰林，铉猶在淮南，聞曰：\"路十如今便入翰林，何能至老？\"皆如言。","sortOrder":22},
  {"id":"s_work_dnl_8_23","chapterId":"ch_work_dnl_8","text":"突厥平，溫仆射彦博請遷於朔方，以實空虛之地，於是入居長安者且萬家。魏鄭公以為夷不亂華，非久常之策。爭論數年不决。至开元中，六胡反叛，其地复空。","sortOrder":23},
  {"id":"s_work_dnl_8_24","chapterId":"ch_work_dnl_8","text":"太宗令衛公教侯君集，君集言於帝曰：\"李靖將反矣！至微隱之術，辄不以示臣。\"帝以讓靖，靖曰：\"此乃君集反爾！今中夏安，臣之所教，足以製四夷矣，而求盡臣之術者，將有他心焉。\"","sortOrder":24},
  {"id":"s_work_dnl_8_25","chapterId":"ch_work_dnl_8","text":"润州得玉磬十二以獻，張率更叩其一，曰：\"是晉某歲所造也。是歲餘月，造磬者法月，數有十三，今闕其一。宜於黃鐘九尺掘之，必得焉。\"敕州求之，如言而得。","sortOrder":25},
  {"id":"s_work_dnl_8_26","chapterId":"ch_work_dnl_8","text":"鄭公見《秦王破陣樂》，則俯而不视；奏《慶善樂》，則玩而不厭。","sortOrder":26},
  {"id":"s_work_dnl_8_27","chapterId":"ch_work_dnl_8","text":"貞觀中，有婆羅門僧言\"佛齒所击，前無堅物\"，於是士女奔凑，其處如市。時傅奕方病臥，聞之，謂子曰：\"非是佛齒也。吾聞金刚石至堅，物莫能敵，唯羚羊角破之。汝但取试焉。\"胡僧監護甚嚴，固求，良久乃得見。出角叩之，應手而碎，觀者乃止。今理珠者用此角。","sortOrder":27},
  {"id":"s_work_dnl_8_28","chapterId":"ch_work_dnl_8","text":"阎立本善畫。至荆州，视張僧繇舊跡，曰：\"定虛得名耳。\"明日又往，曰：\"猶是近代佳手耳。\"明日又往，曰：\"名下無虛士。\"坐臥觀之，留宿其下，一日不能去。","sortOrder":28},
  {"id":"s_work_dnl_8_29","chapterId":"ch_work_dnl_8","text":"高宗時，群蠻聚為寇，讨之辄不利，乃除徐敬業為刺史。府發卒迎，敬業盡放令還，单騎至府。賊聞新刺史至，皆繕理以待。敬業一無所問，處他事已畢，方曰：\"賊安在？\"曰：\"在南岸。\"乃從一二佐史而往觀之，莫不駭愕。賊所持兵觇望，及見船中無人，又無兵仗，更閉營隱藏。敬業直入其營內，告雲：\"國家知汝等為貪吏所害，非有他惡。可悉歸田里，無去為賊。\"唯召其帥，责以不早降之意，各笞數十而遣之，境內肅然。其祖英公壮其胆略，曰：\"吾不辦此，然破我家者必此兒！\"英公既薨，高宗思平遼勋，令製其冢，象高麗中三山，猶霍去病之祁連山。後敬業舉兵，武後令掘平之。大霧三日不解，乃止。","sortOrder":29},
  {"id":"s_work_dnl_8_30","chapterId":"ch_work_dnl_8","text":"張沛為同州，任正名為錄事，劉幽求為朝邑尉。沛常呼二公為任大、劉大，若交友。玄宗誅韦氏，沛兄殿中監涉見誅，併合誅沛。沛將出就刑，正名時謁告在家，聞之，遽出曰：\"朝廷初有大艱，同州，京之左辅，奈何单使至，害其州將？請以死守之。\"於是勸令覆奏，送沛於獄，曰：\"正名若死，使君可忧；不然，無慮也。\"時劉幽求方立元勋，用事居中，竟脱沛於難。","sortOrder":30},
  {"id":"s_work_dnl_8_31","chapterId":"ch_work_dnl_8","text":"萧至忠自晉州之入也，大理蒋钦緒即其妹婿，送之曰：\"以足下之才，不忧不見用，無為非分妄求。\"至忠不納。蒋退而叹曰：\"九代之卿族，一舉而滅，可哀也哉！\"至忠既至，拜中書令，歲餘败。","sortOrder":31},
  {"id":"s_work_dnl_8_32","chapterId":"ch_work_dnl_8","text":"高公骈镇蜀日，因巡邊，至資中郡，舍於刺史衙。對郡山顶有开元寺，是夜黃昏，僧眾禮佛，其聲喧達。公命軍候悉擒械之，來朝笞背斥逐。召將吏而謂之曰：\"僧徒禮念，亦無罪過，但此寺十年後，當有禿丁數千為亂，以是厭之。\"其後土人皆髡執兵，號\"大髡\"、\"小髡\"，據寺為寨凌胁州將，果葉高公之言。","sortOrder":32},
  {"id":"s_work_dnl_8_33","chapterId":"ch_work_dnl_8","text":"張九齡，开元中為中書令。范陽節度使張守奏裨將安祿山頻失利，送戮於京師。九齡批曰：\"穰苴出軍，必誅莊贾；孫武行法，亦斬宮嫔。守軍令若行，祿山不宜免死。\"及到中書，張九齡與語久之，因奏戮之，以絕後患。玄宗曰：\"卿勿以王夷甫識石勒之意，殺害忠良。\"更加官爵，放歸本道。至德初，玄宗在成都，思九齡先覺，製赠司徒，遣使就韶州致祭。","sortOrder":33},
  {"id":"s_work_dnl_8_34","chapterId":"ch_work_dnl_8","text":"李相夷簡未登第時，為鄭縣丞。涇軍之亂，有使走驢東去甚急，夷簡入白刺史曰：\"京城有故，此使必非朝命，請執問。\"果朱檬固险摺?","sortOrder":34},
  {"id":"s_work_dnl_8_35","chapterId":"ch_work_dnl_8","text":"德宗自复京闕，常恐生事，方镇有兵，必姑息之。唯浑奏事，不過，辄私喜曰：\"上不疑我。\"","sortOrder":35},
  {"id":"s_work_dnl_8_36","chapterId":"ch_work_dnl_8","text":"順宗風噤不言，太子未立，牛美人有異志。上乃召學士鄭於小殿，草立太子詔。執筆不請而書\"立嫡以長\"四字，跪呈。順宗然之，乃定。","sortOrder":36},
  {"id":"s_work_dnl_9_1","chapterId":"ch_work_dnl_9","text":"●卷三·賞譽","sortOrder":1},
  {"id":"s_work_dnl_9_2","chapterId":"ch_work_dnl_9","text":"貞觀中，蜀人李義府八歲，號神童。至京師，太宗在上林苑便對，有得乌者，上賜義府。義府登時進詩曰：\"日里扬朝彩，琴中伴夜啼；上林多許树，不借一枝栖。\"上笑曰：\"朕以全树借汝。\"後相高宗。","sortOrder":2},
  {"id":"s_work_dnl_9_3","chapterId":"ch_work_dnl_9","text":"玄宗燕諸學士於便殿，顧謂李白曰：\"朕與天後任人如何？\"白曰：\"天後任人，如小兒市瓜，不擇香味，唯取其肥大者。陛下任人，如淘沙取金，剖石采玉，皆得其精粹。\"上大笑。","sortOrder":3},
  {"id":"s_work_dnl_9_4","chapterId":"ch_work_dnl_9","text":"德宗每年征四方學術直言極諫之士，至者萃於闕下，上親自考试，絕請托之路。是時文學相高，當途者鹹以推賢進善為意。上试製科於宣德殿，或下等者，即以筆抹之至尾。其稱旨者，必吟誦嗟叹；翊日，遍示宰相學士，曰：\"此皆朕之門生。\"公卿無不服上精鑒。宏詞獨孤授吏部试《放馴象賦》，上自考之，稱其句曰：\"化之式孚，則必受乎來獻；物或违性，斯用感於至仁。\"上特書第三等。先是代宗時外方進馴象三十二，上即位，悉令放荆山之南。而授獻賦不傷於顧忌，上賞其知去就。","sortOrder":4},
  {"id":"s_work_dnl_9_5","chapterId":"ch_work_dnl_9","text":"白居易應舉，初至京，以詩謁顧著作况。况睹姓名，熟视曰：\"米价方貴，居亦不易。\"及披卷，首篇曰：\"鹹陽原上草，一歲一枯榮；野火燒不盡，春風吹又生。\"乃嗟賞曰：\"道得个語，居即易也。\"因為之延譽，聲名遂振。","sortOrder":5},
  {"id":"s_work_dnl_9_6","chapterId":"ch_work_dnl_9","text":"李贺以歌詩謁韓愈，愈時為國子博士分司，送客歸，極困。門人呈卷，解帶，旋讀之。首篇《雁門太守行》雲：\"黑雲壓城城欲摧，甲光向日金鱗开。\"却缓帶，命迎之。","sortOrder":6},
  {"id":"s_work_dnl_9_7","chapterId":"ch_work_dnl_9","text":"廣平程子齊昔范，未舉進士日，著《程子中暮》，韓文公稱叹之。及赴舉，幹主司曰：\"程昔范不合在諸生之下。\"當時不第，人以為屈。庾尚書承宣知貢舉，程始登第，以试正字從事涇原軍。李逢吉在相位，見其書，特荐，拜右拾遺，竟因逢吉湮厄而没。其立身貞苦，能清談樂善，士多附之。與堂舅李信州虞相善，又交裴夷直，皆士林之望也。","sortOrder":7},
  {"id":"s_work_dnl_9_8","chapterId":"ch_work_dnl_9","text":"元稹在鄂州，周复為從事。稹嘗賦詩，命院中屬和。周簪笏見稹曰：\"某偶以大人往還高門，谬獲一第，其實詩賦皆不能。\"稹曰：\"遽以實告，賢於能詩者。\"","sortOrder":8},
  {"id":"s_work_dnl_9_9","chapterId":"ch_work_dnl_9","text":"劉侍郎三复，初為金壇尉，李衛公镇浙西，三复代草表雲：\"山名北固，長懷恋闕之心；地接東溟，却羨朝宗之路。\"衛公嘉叹，遂辟為賓佐。時杭州有萧协律悅，善畫竹，家酷貧，白居易典郡，嘗叙雲：\"悅之竹舉世無倫，頗自秘重，有終歲求其一竿一枝不得者。\"又遺之歌曰：\"餘杭邑客多羁貧，其中甚者萧與殷，天寒身上猶衣葛，日高甑中未扫尘。\"悅年老多病，有一女未適。他日，病且亟，謂其女曰：\"吾聞長史劉從事，非有通家之舊，复無舉荐之力。自（案：此下原闕一字）眾為賢侯幕府，必有足觀者。今知未婚，吾雖未識，當以書托汝。\"三复覽其書，數日未决。會夜夢有黃衣使，致藁一束於其門。翊日，言於衛公，公曰：\"藁，萧也。此固定矣。\"三复遂成婚。","sortOrder":9},
  {"id":"s_work_dnl_9_10","chapterId":"ch_work_dnl_9","text":"白敏中在郎署，未有知者，雖李衛公器之，多所延譽，然而無資用以奉僚友。衛公遺錢十萬，俾為酒肴，會省僩諸公宴。已有日。時秋霖涉旬日，贺拔員外求官未得，將欲出京，來別。與敏中同年。主閽者告以方候朝官，缪以他適對。駐車留書，叙羁遊之困。敏中得書，叹曰：\"士窮達當有時命，苟以僥悻取容，未足發吾身。豈有美饌上邀當路豪貴，而遺登第故人？\"遂令召先宴。既而朝客來，聞與宴，眾人鹹去。他日，見衛公。問來者誰，敏中具對：\"以留，負於推引。\"衛公亦稱雲：\"此事真古人所為。\"自後以評事先拜，而敏中以库部郎中入翰林為學士，未逾三年，為丞相。","sortOrder":10},
  {"id":"s_work_dnl_9_11","chapterId":"ch_work_dnl_9","text":"大中末，諫官獻疏，請賜白居易謚。上曰：\"何不讀《醉吟先生墓表》？\"卒不賜謚。弟敏中在相位，奏立神道碑，使李商隱為之。","sortOrder":11},
  {"id":"s_work_dnl_9_12","chapterId":"ch_work_dnl_9","text":"宣宗舅鄭仆射光，镇河中。封其妾為夫人，不受，表曰：\"白屋同愁，已失鳳鳴之侣；朱門自樂，難容乌合之人。\"上大喜，問左右曰：\"誰教阿舅作此好語？\"對曰：\"光多任一判官田詢者掌書記。\"上曰：\"表語尤佳，便好與翰林一官。\"論者以為不由進士，又寒士，無引援，遂止。","sortOrder":12},
  {"id":"s_work_dnl_9_13","chapterId":"ch_work_dnl_9","text":"光德劉相宗望舉進士，朔望謁鄭太師從谠。閽者呈刺，裴侍郎瓒後至，先入從容，乃召劉秀才。劉相告以主司在前，不敢升坐。隅拜於副階上，鄭公降而揖焉。鄭公佇立，目送之，久方回。乃謂瓒曰：\"大好及第舉人。\"瓒唯唯，明年為門生。","sortOrder":13},
  {"id":"s_work_dnl_9_14","chapterId":"ch_work_dnl_9","text":"令狐氵高、弟澄，皆好文。自楚及澄，三世掌誥命，有稱科場中。","sortOrder":14},
  {"id":"s_work_dnl_9_15","chapterId":"ch_work_dnl_9","text":"令狐氵高以父為丞相，未得進。氵高出訪鄭侍郎，道遇大尹，投國學避之。遇廣文生吳畦，從容久之。畦袖卷呈氵高，由是出入氵高家。氵高荐畦於鄭公，遂先氵高一年及第，後至郡守。","sortOrder":15},
  {"id":"s_work_dnl_9_16","chapterId":"ch_work_dnl_9","text":"懿宗嘗行經延資库，見廣厦錢帛山積，問左右：\"誰為库？\"侍臣對曰：\"宰相李德裕，以天下每歲度支備用之餘，盡實於此。自是以來，邊庭有急，支備無乏。\"上曰：\"今何在？\"曰：\"頃坐吳湘貶崖州。\"上曰：\"有如此功，微罪豈合誅譴！\"由是劉鄴進表雪冤，遂許加赠。","sortOrder":16},
  {"id":"s_work_dnl_9_17","chapterId":"ch_work_dnl_9","text":"劉仁表，劉允章門生。初，允章知舉，仁表與李都善，即訪之，而謂都曰：\"儀之某為朝廷委任，何以見裨，少塞责乎？\"都欲荐其所知者，允章迎謂之曰：\"謂不言牛、孔，安得歲歲須人？\"先是牛、孔數家，凭势力，每歲主司為其所製，故允章亦雲，適中都所欲言者。都曰：\"蘊中错也，願其往之。\"（案：此句文義難明，疑有脱誤）以與允章雅熟，都納焉，即孔紆也。复授允章以文一軸，發之且大半，曰：\"此可以與否？\"允章佳賞，比及卷首，乃仁表也。允章鄙其輕薄而辭之。都曰：\"公是遭罹者，奈何复聽讒言乎？\"於是皆許之。仁表後為華州趙骘幕，嘗飲酒，骘命欧陽琳作錄事，酒不中者罰之。仁表酒不能滿飲，琳罰之，仁表曰：\"鄂渚尚書解取錄事，不解放門生。\"時允章镇江夏，仁表皆自謂也。","sortOrder":17},
  {"id":"s_work_dnl_9_18","chapterId":"ch_work_dnl_9","text":"畢相霞宜丶＠钪胸┱擼兄鈐盒值苡胂熟。現晾钍獻郵槭抑校钭痈?詩，絃辔Ｇ暾呃钪粒壑钭郵旨所作，稱其美。铣跻啾苤釵?曰：\"此誰作也？\"諸子不敢隱，乃曰：\"某叔，頃來畢閒悴抛饕病?\"纖斐?見。既而李呼左右责曰：\"何令馬入池中，踐浮萍皆聚，芦荻斜倒？\"怒甚，左右莫敢對。顯唬?\"萍聚只因今日浪，荻斜都為夜來風。\"李大悅，遂留為客。","sortOrder":18},
  {"id":"s_work_dnl_9_19","chapterId":"ch_work_dnl_9","text":"劉仁軌為左仆射，戴至德為右仆射，人皆多劉而鄙戴。有老父陳牒，至德方欲下筆，老父問左右：\"此是劉仆射否？\"曰：\"是戴。\"因急就曰：\"此是不解事仆射，却將牒來。\"至德突令授之。戴在職無異跡，當朝似不能言者。及薨，高宗叹曰：\"自吾丧至德，無复聞谠言。在時，事有不是者，未嘗放過。\"因索其前後所陳章奏，閱而流涕，朝廷始重之。","sortOrder":19},
  {"id":"s_work_dnl_9_20","chapterId":"ch_work_dnl_9","text":"相國劉公贍，其先人讳景，本連州人，少為漢南鄭司徒掌箋。因題商山驿侧泉石，司徒奇之，勉以進修，俾前驿換麻衣，執贽見之禮。後解荐，擢進士第，歷台省。贍孤貧有藝，雖登科第，不預急流。任大理評事日，饣粥不給，嘗於安國寺相識僧處謁飧，留所業文數軸，置在僧幾上。致仕劉賓客遊寺，見此文卷，甚奇之，怜其貧窭，厚有濟恤。又知其連州人，朝無引援，謂僧曰：\"某雖閒废，能為此人致宰相。\"爾後授河中少尹，幕僚有貴族浮薄者蔑视之。一旦有命征人，蒲尹張筵而餞之。輕薄客呼相國為\"尹公\"曰：\"歸朝作何官職？\"相國對曰：\"得路即作宰相。\"此郎官大笑之，在席亦有異言者。自是以水部員外知製誥，相次入翰林，以至拜相。","sortOrder":20},
  {"id":"s_work_dnl_9_21","chapterId":"ch_work_dnl_9","text":"鄭愚尚書，廣州人。雄才奧學，擢進士第，扬歷清顯，聲稱僺然，而性本好華，以錦為半臂。崔魏公铉镇荆南，鄭除廣南節製經過，魏公以常禮延遇。鄭舉進士時，未嘗以文章及魏公門。此日於客次換麻衣，先贽所業。魏公覽其卷首，尋已賞叹至三四，不覺曰：\"真銷得錦半臂也。\"又以魏公故相，合具軍儀廷參，不得已而受之。魏公曰：\"文武之道，備見之矣。\"其钦服形於辭色也。或曰：\"鄭公因醉眠，左右見一白猪。\"蓋杜征南蛇吐之類。","sortOrder":21},
  {"id":"s_work_dnl_9_22","chapterId":"ch_work_dnl_9","text":"郭暧尚升平公主，盛集文士，即席賦詩，公主帷而觀之。李端中宴詩成雲：\"薰香荀令偏怜少，傅粉何郎不解愁。\"眾稱妙絕，或謂夙篝，端曰：\"願试一吟。\"錢起雲：\"請以起姓為韻。\"复雲：\"新开金埒教調馬，舊賜銅山許鑄錢。\"暧出名馬金帛為赠。是席，端為首；送王相镇幽朔，韓翌為首；送劉相巡江淮，錢起為首。","sortOrder":22},
  {"id":"s_work_dnl_9_23","chapterId":"ch_work_dnl_9","text":"獨孤鬱，權相子婿也，歷掌內外製，有美名。憲宗叹曰：\"我女婿不如德舆。\"","sortOrder":23},
  {"id":"s_work_dnl_9_24","chapterId":"ch_work_dnl_9","text":"孔葵為華州刺史，奏江淮進海味，道路扰人，併其類十數條。後上不記其名，問裴晉公，亦不能對，久之方省。乃拜葵嶺南節度，有異政。南中士人死於流竄者，子女悉為嫁娶之。","sortOrder":24},
  {"id":"s_work_dnl_9_25","chapterId":"ch_work_dnl_9","text":"呂元膺為鄂嶽都团練使，夜登城，女牆已鎖，守者曰：\"軍法：夜不可开。\"乃告言中丞自登，守者又曰：\"夜中不辨是非，雖中丞亦不可。\"元膺乃歸。明日，擢為重職。","sortOrder":25},
  {"id":"s_work_dnl_10_1","chapterId":"ch_work_dnl_10","text":"●卷三·品藻","sortOrder":1},
  {"id":"s_work_dnl_10_2","chapterId":"ch_work_dnl_10","text":"姚梁公與崔監司在中書。梁公有子丧，在假旬日，政事委積，處置皆不得。言於玄宗，玄宗曰：\"朕以天下事本付姚崇，以卿坐镇雅俗。\"及梁公出，頃刻間决遣盡畢。時齊平陽為舍人，在旁見之。梁公自以為能，頗有得色，乃問平陽曰：\"餘之為相，比何等人？\"齊未及對。梁公曰：\"何如管、晏？\"曰：\"不可比管、晏。管、晏作法，雖不及後，猶及其身。相公前入相，所立法令施未竟，悉更之，以此不及。\"梁公曰：\"然則竟如何？\"曰：\"相公可謂救時之相也。\"梁公投筆曰：\"救時之相，豈易得乎？\"時齊平陽善知今事，高仲舒善知古事。姚作相，凡质疑問難，皆此二人，因叹曰：\"欲知古事，問高仲舒；欲知今事，問齊氵，即無败政矣。\"","sortOrder":2},
  {"id":"s_work_dnl_10_3","chapterId":"ch_work_dnl_10","text":"玄宗西幸，駕及古界，靈武遞至，房新除丞相。玄宗於馬上看除目，顧左右，謂裴士淹曰：\"亦不是滅賊手。\"士淹低語曰：\"請陛下勿复言。\"上色少愧。","sortOrder":3},
  {"id":"s_work_dnl_10_4","chapterId":"ch_work_dnl_10","text":"玄宗西幸，嘗鬱鬱不悅，多與裴士淹併馬語。語及平日之事，時亦解顏。上曰：\"李林甫之材不多得。\"士淹曰：\"誠如聖旨，近實無儔。\"上曰：\"但以妒賢嫉能，以此至败。\"士淹曰：\"陛下既知，何故久任之？豈唯身败，兼亦誤國。計今日之事，林甫所啟也。\"上愀然不樂。","sortOrder":4},
  {"id":"s_work_dnl_10_5","chapterId":"ch_work_dnl_10","text":"乔彝京兆府解试，時有二试官。彝日午叩門，试官令引入，則已醺醉。视題，曰《幽蘭賦》，不肯作，曰：\"兩人相對作得此題，速改之。\"乃改為《渥洼馬賦》。奋筆斯須而就，其辭甚工。便欲首送。京兆尹曰：\"乔彝峥嵘甚，以解副荐之。\"","sortOrder":5},
  {"id":"s_work_dnl_10_6","chapterId":"ch_work_dnl_10","text":"尚書白舍人初到錢塘，令訪牡丹。獨开元寺僧惠澄近於京得此花，始栽植於庭，欄围甚密，他亦未知有也。時春景方深，惠澄設油幕覆其上。牡丹自東越分而种之也，會稽徐凝自富春來，未識白公，先題詩曰：\"此花南地知誰种，慚愧僧門用意栽；海燕解怜頻睥睨，胡蜂未識更徘徊。虛生芍藥徒勞妒，羞殺玫瑰不敢开；唯有數苞紅萼在，含芳只待舍人來。\"白尋到寺看花，乃命徐生同醉而歸。時張祜榜舟而至，甚若疏誕，然張、徐二生，未之習稔，各希首荐焉。中舍曰：\"二君論文，若廉、白之斗鼠穴，较勝負於一戰也。\"遂试《長劍倚天賦》、《餘霞散成綺》詩。既解送，以凝為先，祜其次耳。張祜詩有\"地势遙尊嶽，河流侧讓關。\"多士以陳後主\"日月光天德，山河壮帝居\"比，徒有前名矣。祜題《金山寺》詩曰：树影中流見，鐘聲兩岸聞\"，雖綦毋潛雲\"塔影掛青漢，鐘聲扣白雲\"，此二句未為佳也。祜又有《觀獵》四句及《宮詞》，白公曰：\"張三作獵詩以擬王右丞，予則未敢優劣也。\"王維詩曰：\"風劲角弓鳴，將軍獵渭城；草枯鷹眼疾，雪盡馬蹄輕。忽過新丰市，還歸細柳營。回看落雁處，千里暮雲平。\"張祜詩曰：\"晚出禁城東，分围淺草中；紅旗开向日，白馬骤臨風。背手抽金鏃，翻身控角弓，萬人齊指處，一雁落寒空。\"白公又以《宮詞》四句之中皆偶對，何足奇乎？不如徐生雲：\"今古常如白練飛，一條界破青山色。\"徐凝賦曰：\"谯周室里，定遊、夏於邱、虔；馬守帷中，分《易》、《禮》於盧、鄭。如我明公荐拔，豈惟偏党乎？\"張祜亦曰：\"《虞韶》九奏，非瑞馬之至音；荆玉三投，佇良工之必鑒。且洪鐘《韶》击，瓦缶雷鳴；榮辱扎繩，复何定分！\"祜遂行歌而邁，凝亦鼓而歸。自是二生終身偃仰，不隨乡试矣。先是李補闕林宗、杜殿中牧，與白公輦下较文，具言元白體舛雜，而為清苦者見嗤，因茲有恨也。白為河南尹，李為河陽令，道上相遇，尹乃乘馬，令則肩舆，似乖趨事之禮。嘗謂樂天為\"囁嚅公\"，聞者皆笑，樂天之名稍减。白曰：\"李直木（原註：林宗字也）吾之犭製子也，其鋒不可當。\"後杜舍人之守秋浦，與張生為詩文交，酷愛祜《宮詞》，亦知錢塘之歲，自有是非之論，懷不平之色，為詩二首以高之，曰：\"誰人得似張公子，千首詩輕萬戶侯。\"又雲：\"如何故國三千里，虛唱歌辭滿六宮。\"","sortOrder":6},
  {"id":"s_work_dnl_10_7","chapterId":"ch_work_dnl_10","text":"升平裴相兄弟三人，俱有盛名。世謂俅不如休。休好釋氏，善隸書，所在寺額多書之。","sortOrder":7},
  {"id":"s_work_dnl_10_8","chapterId":"ch_work_dnl_10","text":"隋吏部侍郎高孝基主選，見梁公房玄齡、蔡公杜如晦，愕然降階，與之抗禮。延入內廳，食甚恭，曰：\"二賢當為王霸佐命，位極人臣，然杜年寿稍减於房耳。願以子孫相托。\"貞觀初，杜薨於左仆射，房位至司徒，秉政二十餘年。","sortOrder":8},
  {"id":"s_work_dnl_10_9","chapterId":"ch_work_dnl_10","text":"太宗稱虞監：博聞、德行、書翰、詞藻、忠直，一人而已，而兼是五善。","sortOrder":9},
  {"id":"s_work_dnl_10_10","chapterId":"ch_work_dnl_10","text":"貞元中，楊氏、穆氏兄弟人物才名不相遠。或雲：\"楊氏兄弟賓客皆同；穆氏兄弟賓客皆異。\"以此為優劣。","sortOrder":10},
  {"id":"s_work_dnl_10_11","chapterId":"ch_work_dnl_10","text":"穆氏兄弟四人：贊、賞、质、員。時人謂：贊俗而有格，為\"酪\"；质美而多文為\"酥\"；員為\"醍醐\"，言粹而少用；賞為\"乳腐\"，言最為凡固也。","sortOrder":11},
  {"id":"s_work_dnl_10_12","chapterId":"ch_work_dnl_10","text":"德宗晚年絕嗜欲，尤工詩，臣下莫及。每御製奉和而退，笑曰：\"排公在。\"","sortOrder":12},
  {"id":"s_work_dnl_10_13","chapterId":"ch_work_dnl_10","text":"杜太保在淮南，進崔叔清詩百篇，上謂使者曰：\"此惡詩，焉用進？\"時人呼為\"准敕惡詩\"。","sortOrder":13},
  {"id":"s_work_dnl_10_14","chapterId":"ch_work_dnl_10","text":"盧肇、黃頗，同遊李衛公門下。王起再知貢舉，訪二人之能。或曰：\"盧有文學，黃能詩。\"起遂以盧為状頭，黃第三人。","sortOrder":14},
  {"id":"s_work_dnl_11_1","chapterId":"ch_work_dnl_11","text":"●卷三·規箴","sortOrder":1},
  {"id":"s_work_dnl_11_2","chapterId":"ch_work_dnl_11","text":"太宗常幸洛陽，頗見可欲，多治隋氏舊宮，或縱畋遊。魏徵骤諫，上忻然罢，曰：\"非公，無此語。\"","sortOrder":2},
  {"id":"s_work_dnl_11_3","chapterId":"ch_work_dnl_11","text":"肅宗五月五日抱小公主，顧山人李唐曰：\"念之，勿怪。\"唐曰：\"太上皇亦應思陛下。\"肅宗泣涕。是時張氏已用事，不由己矣。","sortOrder":3},
  {"id":"s_work_dnl_11_4","chapterId":"ch_work_dnl_11","text":"陽城為諫議大夫，德宗欲用裴延齡為相，城曰：\"白麻若出，我必裂之而死。\"德宗以為難，竟不相延齡。","sortOrder":4},
  {"id":"s_work_dnl_11_5","chapterId":"ch_work_dnl_11","text":"國子監諸生猥雜，陽城為司業，以道德訓諭，有违親三年者，勉歸觐。","sortOrder":5},
  {"id":"s_work_dnl_11_6","chapterId":"ch_work_dnl_11","text":"自天寶九年，置廣文馆，至元和中，堂宇虛構，材木堆積，主者或盜用之。","sortOrder":6},
  {"id":"s_work_dnl_11_7","chapterId":"ch_work_dnl_11","text":"憲宗固英睿。初即位，得杜公贊导；及其成功，多公力也。","sortOrder":7},
  {"id":"s_work_dnl_11_8","chapterId":"ch_work_dnl_11","text":"每大朝會，監察御史押班，不足，則使下御史因朝奏者攝之。","sortOrder":8},
  {"id":"s_work_dnl_11_9","chapterId":"ch_work_dnl_11","text":"諫院以章疏之故，忧患略同。台中則務苛禮，省中多事，旨趣不一。故言：\"遺、補相惜，御史相憎，郎官相輕。\"","sortOrder":9},
  {"id":"s_work_dnl_11_10","chapterId":"ch_work_dnl_11","text":"於司空因韦太尉《奉聖樂》，亦撰《順聖樂》以進，每宴，必使奏之。其曲將半，缀皆伏，而一人舞於中央。慕容韦缓笑曰：\"何用窮兵獨舞？\"雖笑談詼諧，亦有為也。碛至钆宋瑁趁睿潘鏤洹端呈ダ幀貳?","sortOrder":10},
  {"id":"s_work_dnl_12_1","chapterId":"ch_work_dnl_12","text":"●卷三·夙慧","sortOrder":1},
  {"id":"s_work_dnl_12_2","chapterId":"ch_work_dnl_12","text":"上官昭容者，侍郎儀之孫也。儀之得罪，婦鄭氏填宮，遺腹生昭容。其母將誕之夕，夢人與秤曰：\"持之秤量天下文士。\"鄭氏冀其男也，及生昭容，视之，雲：\"秤量天下，豈是汝耶？\"口中哑哑如應曰：\"是。\"","sortOrder":2},
  {"id":"s_work_dnl_12_3","chapterId":"ch_work_dnl_12","text":"玄宗善八分書，將命相，皆先以御札書其名於案上。會太子入侍，上以金甌覆其名以告之，曰：\"此宰相名也，汝庸知其誰？即射中，賜若卮酒。\"肅宗拜而稱曰：\"非崔琳、盧從願乎？\"上曰：\"然。\"因舉甌以示，乃賜卮酒。是時琳與從願皆有宰相望，上倚為相者數矣，竟以宗族蕃盛，附托者眾，不能用之。","sortOrder":3},
  {"id":"s_work_dnl_12_4","chapterId":"ch_work_dnl_12","text":"蘇瑰初未知，常處於馬廄中，與庸仆雜行。一日有客詣瑰，候於客次。擁庭庑間，遺落一文字，客取而视之，乃詠崑崙奴子，詩雲：\"指如十挺墨，耳似兩張匙，\"客異之。良久，瑰出，客淹留言詠，以其詩問瑰\"何人，豈非足下宗庶之孽也？\"瑰備言其事，客驚訝之，謂瑰加禮收舉，必蘇氏之令子也，瑰稍稍親之。有人獻兔，懸於廊庑之下，乃召詠之，曰：\"兔子死阑单，將來掛竹竿，试將明鏡照，無異月中看。\"瑰讀詩異之。由是學問日新，文章蓋代。及玄宗平內難，旦夕製誥絡繹，無非之所出，時稱\"小許公\"雲。","sortOrder":4},
  {"id":"s_work_dnl_12_5","chapterId":"ch_work_dnl_12","text":"开元初，上留心理道，革去弊訛。不六、七年間，天下大理，河清海晏，物殷俗阜，安西諸國悉平為郡縣。置开遠門，亘地萬餘里。入河湟之賦稅滿右藏；東納河北諸道租庸，充滿左藏。财寶山積，不可勝計。四方丰稔，百姓樂業。戶計一千餘萬，米每斗三錢。丁壮之夫，不識兵器。路不拾遺，行不赍糧。奇瑞叠委，重譯至。人物欣然，鹹思登岱告成。上猶惕厲不已，讓數四。是時彭城劉晏年八歲，獻《東封書》，上覽而奇之，命宰相出題，就中書试。張說、源乾曜鹹相感慰荐。上以晏間生秀妙，引於內殿，縱六宮觀看。楊妃坐於膝上，親為畫眉總髻，宮人投花掷果者甚多。拜為秘書正字。","sortOrder":5},
  {"id":"s_work_dnl_12_6","chapterId":"ch_work_dnl_12","text":"張說問曰：\"居官以來，正字幾何？\"晏抗顏對曰：\"他字皆正，獨'朋'字未正。\"說聞而異之。","sortOrder":6},
  {"id":"s_work_dnl_12_7","chapterId":"ch_work_dnl_12","text":"燕文正公弟某女婦盧氏，嘗為舅盧公求官，候公下朝而問焉。公不語，但指支床龟而示之。女拜而歸室，告其夫曰：\"舅得詹事矣。\"","sortOrder":7},
  {"id":"s_work_dnl_12_8","chapterId":"ch_work_dnl_12","text":"开元中有李幼奇者，以藝幹柳芳，念百韻詩。芳便暗記，題之於壁，謂幼奇曰：\"此吾之詩也。\"幼奇大驚。徐曰：\"相戲耳，此君所念詩也。\"因謂幼奇更念他新著文章，一遍皆能記。","sortOrder":8},
  {"id":"s_work_dnl_12_9","chapterId":"ch_work_dnl_12","text":"开元初，潞州常敬忠十五明經擢第，數年遍通五經，上書自舉，雲：\"一遍誦千言。\"敕赴中書考试，張燕公問曰：\"學士能一遍誦千言，十遍誦萬言乎？\"對曰：\"未曾自试。\"燕公遂出書，非人間所見也，謂之曰：\"可十遍誦之。\"敬忠危坐而讀，每遍畫地為記。讀七遍，起曰：\"此已誦得。\"燕公曰：\"可滿十遍，\"敬忠曰：\"若十遍，即是十遍誦得。今七遍已得，何要滿十遍？\"燕公執本觀覽不暇，而敬忠誦畢不差一字，見者莫不嗟叹。即日聞奏，命引對，賜彩衣一副，兼赍物。拜東宮衛佐，仍直集賢院，侍講《毛詩》，百餘日中三改，為同辈所嫉，中毒而卒。","sortOrder":9},
  {"id":"s_work_dnl_12_10","chapterId":"ch_work_dnl_12","text":"天寶中，漢州雒縣尉張陟應一藝，自舉\"日试萬言。\"須中書考试。陟令善書者二十人，各執筆操紙就席，環庭而坐，俱占題目。身自巡歷，依題口授，言訖即過，周而复始。至午後詩成七千餘字，仍請滿萬。宰相雲：\"七千可謂多矣，何必須萬？\"具以状聞，敕賜缣帛，拜太公廟丞，直廣文馆，時號張萬言。","sortOrder":10},
  {"id":"s_work_dnl_12_11","chapterId":"ch_work_dnl_12","text":"韦皋镇西川，進《奉聖樂》曲，兼樂工舞人曲譜到京。於留邸按閱，教坊人潛窥，得先進之。","sortOrder":11},
  {"id":"s_work_dnl_12_12","chapterId":"ch_work_dnl_12","text":"李衛公幼時，憲宗賞之，坐於前。吉甫每以敏捷夸於同列。武相元衡召之，謂曰：\"吾子在家，所嗜何書？\"德裕不應。翌日，元衡具告，吉甫歸以责之。德裕曰：\"武公身為宰相，不問理國調陰陽，而問所嗜書，其言不當，所以不應。\"","sortOrder":12},
  {"id":"s_work_dnl_12_13","chapterId":"ch_work_dnl_12","text":"宣宗強記默識，宮中廁役之賤及備洒扫者數十百辈，一見辄記其姓字。或將有所指念，必曰：\"召某人令措某事。\"無一差誤者，宦官宮婢以為神。簿書刑獄卒吏姓名，紛雜交至，經覽多所記憶。","sortOrder":13},
  {"id":"s_work_dnl_12_14","chapterId":"ch_work_dnl_12","text":"崔大夫涓，之子，禮部侍郎澹之兄，俊爽強記。初守杭州，视事數日，召都押衙謂曰：\"乍到郡，未能記諸走使，當直將卒凡幾人？\"對曰：\"直者三百。\"乃令紙一幅，大書其姓名貼於胸，每人閱過。自此一閱，至三考，未嘗誤唤一人者。","sortOrder":14},
  {"id":"s_work_dnl_12_15","chapterId":"ch_work_dnl_12","text":"杭州端午競渡，於錢塘弄潮。先數日，於湖濱列舟舸，結彩為亭槛，東西袤高數丈。其夕北風，飄泊南岸。涓至湖上，大將懼乏事。涓問：\"競舟凡有幾？\"令齊往南岸，每一彩舫系以三五小舟，號令齊力鼓棹而引之，倏忽皆至。","sortOrder":15},
  {"id":"s_work_dnl_12_16","chapterId":"ch_work_dnl_12","text":"崔涓守杭州，湖上飲餞，客有獻木瓜，所未嘗有也。傳以示客，有中使即袖歸，曰：\"禁中未曾有，宜進於上。\"頃之，解舟而去。郡守懼得罪，不樂，欲撤飲。官妓作酒監者立白守曰：\"請郎中盡飲，某度木瓜經宿必委中流也。\"守從之。會送中使者還雲：\"果潰烂，弃之矣。\"郡守異其言，召問之，曰：\"使者既請進，必函貯以行。初因遞觀，則以手掐之。此物芳脆易損，必不能入獻。\"守命有司加給，取香錦面赍之。","sortOrder":16},
  {"id":"s_work_dnl_12_17","chapterId":"ch_work_dnl_12","text":"華陰楊牢，幼孤，六歲時就學歸，誤入人家，乃父友也。二丈人彈棋次，見楊氏子，戲曰：\"爾能為丈人詠此局否？\"楊登時叉手詠曰：\"魁形下方天顶凸，二十四寸窗中月。\"父友驚撫其首，遺以梨栗，曰：\"爾後必有文。\"年十八，一上中進士第，有詩集六十卷。性狷急，累居幕府，主人同列多不容。同列有固護之者，與詩雲：\"虾蟆欲吃月，保護常教圓。\"又雲：\"心明外不察，月向懷中圓。\"又雲：\"羅帏苦不卷，誰道中無人。\"其辭多怨恚。其妻亦有志行。在青州幕，奉使出，得疾，不诊脈服藥而殒。","sortOrder":17},
  {"id":"s_work_dnl_12_18","chapterId":"ch_work_dnl_12","text":"太宗使宇文士及割肉，乃以餅拭手，帝屢目之。士及佯為不悟，更徐拭而後之。","sortOrder":18},
  {"id":"s_work_dnl_12_19","chapterId":"ch_work_dnl_12","text":"太宗令虞監寫《列女傳》，以裝屏風，未及閱卷，乃暗書之，一字無失。","sortOrder":19},
  {"id":"s_work_dnl_12_20","chapterId":"ch_work_dnl_12","text":"贾嘉隱年七歲，以神童召見。時長孫太尉無忌、李司空於朝堂立語。李戲之曰：\"吾所倚何树？\"嘉隱雲：\"松树。\"李曰：\"此槐也，何言松？\"嘉隱曰：\"以公配木，何得非松。\"長孫复問：\"吾所倚何树？\"曰：\"槐树。\"公曰：\"汝不复能矯對耶？\"嘉隱曰：\"何須矯對，但取其鬼木耳。\"李叹曰：\"此小兒獠面，何得如此聰明！\"嘉隱應聲曰：\"胡頭尚作宰相，獠面何废聰明。\"李状胡也。","sortOrder":20},
  {"id":"s_work_dnl_12_21","chapterId":"ch_work_dnl_12","text":"崔相慎由豪爽，廉察浙西，有瓦官寺持《法華經》僧為門徒。或有術士言：\"相國面上氣色有貴子。\"問其妊娠之所在，夫人洎媵妾間皆無所見。相國徐思之，乃召曾侍更衣官妓而示，術士曰：\"果在此也。\"及載誕日，腋下有文，相次分明，即瓦官僧名，因命小字緇郎。年七歲，尚不食肉。一日，有僧請見，乃掌其頰，謂曰：\"既愛官爵，何不食肉？\"自此方味葷血，即相國垂休也。","sortOrder":21},
  {"id":"s_work_dnl_12_22","chapterId":"ch_work_dnl_12","text":"\"小子謀餐而已，（案：此上有脱文）此人豈享富貴者乎？\"幽求聞之，拂衣而出。盧令遽下階捉幽求衣，伸謝之，幽求竟去。盧回，謂諸郎官曰：\"輕笑劉生，禍從此始。\"盧令竟為宗、紀所排，左遷金州司馬。六月，中宗晏駕。十五日酒間，裴ㄘ臥於私第，幽求忽來詣ㄘ，直入臥內，戴揖耳帽子，著白衤阑衫，底著短緋白衫，執ㄘ手曰：\"裴三！死生一决。\"言訖而去。ㄘ大驚，不测其故，謂其妻曰：\"仆竟坐與（案：此下有脱文）非笑此子，恐禍在須臾。\"明日（原註：時去清明九十九日）中宗小祥，百官率慰少帝。是日，月華門至辰巳後方开，傳聲曰：\"斬决使劉相公出。\"衣黃金甲，佩橐，統萬騎，兵士白刃耀日。自宗、紀及前時輕笑者，鹹受戮於朝。又唤兵部員外郎裴ㄘ，ㄘ股忄栗而前。幽求曰：\"相識否？\"ㄘ答曰：\"不識。\"劉曰：\"幽求與公，俱以本官一例赴中書上任。\"其夜凡製誥百餘首，皆幽求作也。自為拜相白麻雲：\"前朝邑尉劉幽求忠貞貫日，羲勇橫秋。首建雄謀，果成大業，可中書舍人，參知機務。賜甲第一區，金銀器皿十床，細婢十人，馬百匹，錦彩千段，仍給鐵券，特恕十死。\"翌日，命金州司馬盧齊卿京兆少尹知府事。載柳冲常侍所著《姓系·劉氏卷中》。","sortOrder":22},
  {"id":"s_work_dnl_13_1","chapterId":"ch_work_dnl_13","text":"●卷四·豪爽","sortOrder":1},
  {"id":"s_work_dnl_13_2","chapterId":"ch_work_dnl_13","text":"玄宗為潞州別駕，入觐京師，尤自卑損。暮春，豪家子數辈遊崑明池。方飲次，上戎服臂鷹，疾驅至前，諸人不悅。忽一少年持酒船唱曰：\"今日宜以門族官品自言。\"酒至，上大聲曰：\"曾祖天子，祖天子，父相王，臨淄王李某。\"諸少年驚走，不敢复视。上乃連飲三銀船，盡一巨餡，乘馬而去。","sortOrder":2},
  {"id":"s_work_dnl_13_3","chapterId":"ch_work_dnl_13","text":"玄宗幸太山回，車次上党，路逢父老，負擔壶漿遠迎。上親加存問，受其所獻，賜赍有差。父老舊識者，上悉賜酒，與之話舊。所過村乡，必令謁問，或有丧疾，俱令弔恤。百姓欣然，乞願駐跸。及車駕過金桥（原註：桥在潞州），御路萦轉。上見數十里旌旗嚴絜，羽衛整肅，謂左右曰：\"張說言我勒兵三十萬，旌旗千里，挟□、（案：此下原闕一字）陝右、上党，止於太原，真才子也！\"左右皆稱萬歲。遂詔吳道元、韦無忝、陳閎等，令寫《金桥圖》。其聖容及上所乘馬照夜白，陳閎主之；桥梁、山水、車舆、人物、草树、鷹鳥、器仗、帏幕，吳道玄主之；犬馬、驢騾、牛羊、骆駝、熊猿、猪雞之類，韦無忝主之。其圖謂之三絕。","sortOrder":3},
  {"id":"s_work_dnl_13_4","chapterId":"ch_work_dnl_13","text":"上為皇孫時，風神秀異，英姿雋邁，於朝堂叱武攸暨曰：\"我國家朝堂，汝安得恣蜂蠆而狼顧耶！\"則天聞之，曰：\"此兒氣概，終當是吾家太平天子。\"","sortOrder":4},
  {"id":"s_work_dnl_13_5","chapterId":"ch_work_dnl_13","text":"玄宗在藩邸時，每歲畋於城南韦杜之間。嘗因逐兔，意樂忘反，與其徒十餘人，飢倦休息於大树下。忽有一書生，殺驢拔蒜，為具甚備。上顧而奇之。及與語，磊落不凡，問姓名，王琚也。自此每遊，必過其舍。或語，多合上意，乃益親之。及韦氏专製，上忧甚，密言之。琚曰：\"亂則殺之，又何慮焉。\"上遂納其謀，平國內難，累拜琚為中書侍郎，預配享。","sortOrder":5},
  {"id":"s_work_dnl_13_6","chapterId":"ch_work_dnl_13","text":"玄宗洞晓音律，絲管皆造其妙。製作諸曲，隨意即成，如不加意。尤愛羯鼓橫笛，雲：\"八音之領袖，諸樂不可為比。\"嘗遇二月初，詰旦，巾櫛方畢，時宿雨始晴，景氣明麗，殿庭柳杏將拆。上曰：\"對此景物，豈得不為他判斷乎？\"左右相目，將令備酒。獨高力士遣取羯鼓，上臨軒縱击一曲，名《春光好》\"（原註：上自製也）。神氣自得。及顧柳杏皆已發拆，指而笑曰：\"不唤我作天公可乎？\"嫔嫱侍臣皆稱萬歲。又嘗製《秋風高》，每至秋空迥彻，纖埃不起，即奏之，必遠風徐來，庭葉墜下，其神妙如此。","sortOrder":6},
  {"id":"s_work_dnl_13_7","chapterId":"ch_work_dnl_13","text":"玄宗起涼殿，拾遺陳知節上疏極諫，上令力士召對。時暑毒方甚，上在涼殿，座後水激扇車，風獵衣襟。知節至，賜坐石榻。陰僯沈吟，仰不見日。四隅積水成帘飛洒，座內含冻。复賜冰屑麻節飲。陳體生寒忄栗，腹中雷鳴，再三請起方許，上猶试汗不已。陳才及門，遺泄狼籍，逾日复故。謂曰：\"卿論事宜審，勿以己方萬乘也。\"","sortOrder":7},
  {"id":"s_work_dnl_13_8","chapterId":"ch_work_dnl_13","text":"玄宗性俊邁，不好琴。會聽琴，正弄未畢，叱琴者曰：\"待詔出！\"謂內官曰：\"速令花奴將羯鼓來，為我解秽。\"","sortOrder":8},
  {"id":"s_work_dnl_13_9","chapterId":"ch_work_dnl_13","text":"玄宗封太山，進次滎陽旃然河，見巨黑龍，命弧矢而親射之。矢發龍滅；自是旃然伏流，於今百餘年矣。按旃然即濟水，溢而為滎，遂名旃然。《左傳》：\"楚涉潁，次於旃然。\"即其地。","sortOrder":9},
  {"id":"s_work_dnl_13_10","chapterId":"ch_work_dnl_13","text":"武後朝，嚴安之、挺之，崑弟也。安之為長安兵曹，權過京兆，至今為寮者賴安之之術焉。挺之則登歷台省，亦有時名。挺之薄妻而愛其子。嚴武年八歲，詢其母曰：\"大人常厚玄英（原註：妾也），未嘗慰省我母，何至於斯？\"母曰：\"吾與汝子母也，以汝尚幼，未知之也。汝父薄行，嫌吾寢陋，枕席數宵，遂即懷汝。自後相弃，為汝父離婦焉。\"其母凄咽，武亦憤惋。候父出，玄英方睡，武持小鐵錘击碎其首。及挺之歸，驚愕，视之，已毙矣。左右曰：\"小郎君戲運錘而致之。\"挺之呼武曰：\"汝何戲之甚？\"武曰：\"焉有大朝人士，厚其侍妾，困辱兒之母乎？故須击殺，非戲也。\"父曰：\"真嚴挺之子。\"武年二十三，為給事黃門，明年，擁旄西蜀，累於飲筵對客騁其筆札。杜甫拾遺乘醉而言曰：\"不謂嚴挺之乃有此兒也！\"武恚目久之，曰：\"杜審言孫子擬捋虎須耶？\"合坐皆笑以弥縫之。武曰：\"與公等飲饌，所以謀歡，何至幹祖考耶？\"房太尉亦微有所忤，忧怖成疾。武母恐害損賢良，遂以小舟送甫下峡，母則可謂賢也，然二公幾不免於虎口矣。李太白作《蜀道難》，乃為房、杜危之也。其略曰：\"劍閣峥嵘而崔嵬，一夫當關，萬夫莫开。所守或非人，化為狼與豺。朝避猛虎，夕避長蛇。磨牙吮血，殺人如麻。錦城雖雲樂，不如早還家。蜀道之難，難於上青天！侧身四望長咨嗟。\"杜初自作《阆中行》：\"豺狼當路，無地遊從。\"或謂章仇大夫兼琼為陳子昂拾遺雪獄，高侍御適與王江寧昌齡申冤，當時同為義士也。李翰林作此歌，朝右聞之，皆疑嚴武有劉焉之志，其屬刺史章彝因小瑕，武怒，遽命杖殺之。後為彝之外家報怨，嚴氏之後遂微焉。","sortOrder":10},
  {"id":"s_work_dnl_13_11","chapterId":"ch_work_dnl_13","text":"顏太師魯公刻姓名於石，或致之高山之上。或沉之大洲之地，而雲\"安知不有陵穀之变耶？\"","sortOrder":11},
  {"id":"s_work_dnl_13_12","chapterId":"ch_work_dnl_13","text":"劉司徒玄佐，滑州匡城人。嘗出師，經其本縣，欲申桑梓之禮於令，令辭曰\"不敢\"，玄佐叹恨久之。先是，陳金帛數匡，將遺邑僚，以其無知而止。時乡里姻舊，以地近多歸之，司徒不欲私擢居將校之列，又難置於賤卒，盡署為將判官。此職列假緋衫銀魚，外视榮之，實處在散冗。其類漸眾。久之，有獻啟訴於公者，乃署他職。","sortOrder":12},
  {"id":"s_work_dnl_13_13","chapterId":"ch_work_dnl_13","text":"憲宗七歲，德宗抱置膝上，戲曰：\"汝是何人，乃在我懷中？\"對曰：\"是第三天子。\"德宗大喜。","sortOrder":13},
  {"id":"s_work_dnl_13_14","chapterId":"ch_work_dnl_13","text":"鄭太穆郎中為金州刺史，致書於襄陽於司空恚另匀簦莆蘅ち胖瘛?書曰：\"閣下為南溟之大鵬，作中天之一柱。騫騰則日月暗，搖動則山嶽頹。真天子之爪牙，諸侯之龟鑒也。太穆幼孤，二百餘口，飢冻兩京。小郡俸薄，尚為衣食之忧，溝壑之期，斯須至矣。伏惟賢公息雷霆之威，垂特達之節，賜錢一千貫，絹一千匹，器物一千事，米一千石，奴婢各十人。\"且曰：\"分千树一葉之影，即是浓陰；减四海數滴之泉，便為膏泽。\"於公覽書，亦不嗟訝，曰：\"鄭君所須，各依來數一半。以戎旅之际，不全副其本望也。\"又有匡庐符山人，遣童子齊書，乞買山錢百萬，公遂與之，仍加紙墨衣服等。又有崔郊秀才者，寓居於漢上，蘊有文藝，而家貧。與姑婢通，其婢端麗，解音律，漢南之最也。姑貧鬻婢於連帥，愛之，以類無双（原註：無双即薛太保愛妾，至今圖畫觀之），給錢四十萬。郊思之不已，即強就府署，願一見焉。其婢因寒食節來從事家還，值郊立於柳陰。馬上連泣，誓若山河。崔生赠之以詩曰：\"公子王孫逐後尘，绿珠垂淚滴羅巾；侯門一入深如海，從此萧郎是路人。\"或有寫郊詩於公座，公睹詩，令召崔生，左右莫之测。及見郊，曰：\"'侯門一入深如海，從此萧郎是路人，'便是君製也？四百千小哉，何惜一書，不早相示！\"遂命婢同歸。至於帏幌奁匣，悉為赠飾之物。有客自零陵來，稱戎昱使君席上有善歌者，公遽命召焉。戎不敢违，逾月而至，及至，令唱歌，歌乃戎使君送妓之詩。其辭曰：\"寶钿青蛾悲翠裙，妆成掩泣欲行雲；殷勤好取襄王夢，莫向陽台夢使君。\"公曰：\"丈夫不能立功業，為異代之所稱，豈可奪人愛姬，為己之嬉娱。以此觀之，誠可竄身於無人之地。\"遂以繒帛赆行，為書謝零陵守。","sortOrder":14},
  {"id":"s_work_dnl_13_15","chapterId":"ch_work_dnl_13","text":"李尚書翱，潭州席上有舞柘枝者，顏色忧悴。殷尧藩侍御當筵而赠詩曰：\"姑蘇太守青娥女，流落長沙舞柘枝；滿坐繡衣皆不識，可怜粉脸淚双垂。\"李公詰其事，乃故姑蘇台韦中丞愛姬之女也。李公曰：\"吾與韦族，其姻舊矣。\"速命更舞衣，即延入與韓夫人（原註：吏部之侄）相見。顧其言語清楚，宛有冠蓋風儀，遂於賓榻中，選士嫁之。舒元舆侍郎聞之，赠李公詩曰：\"湘江舞罢忽成悲，便脱蠻靴出絳帷；誰是蔡邕琴酒客，魏公懷舊嫁文姬。\"李尚書初守庐江，有重系者當大辟，引慮之時，啟曰：\"昔於群小，专習一藝，願於貴人之前试之。\"乃曰：\"長嘯也。\"公命缓系而聽之，曰：\"不謂蘇門之風，出於赭衣之下。\"遂蠲其罪。後镇山南，夜聞長笛之音，而瀏亮不絕。問：\"是何人吹也？\"具雲：\"府獄重囚。\"令明日引來。官吏遞相尤怨，夜使囚徒為樂，罪累必深。及至，公曰：\"汝之吹竹已得其能。少不事農桑，可為伶人耳。\"卒歲而怜愍之，便令奔去。","sortOrder":15},
  {"id":"s_work_dnl_13_16","chapterId":"ch_work_dnl_13","text":"李相紳督大梁日，聞镇海軍進健卒四人，一曰富仓龍，二曰沈萬石，三曰冯五千，四曰錢子涛，悉能拔橛角觚之戲。翌日，於球場內犒勞，以老牛筋皮為炙，状瘤魁之脔（原註：魁，酒缸也，盛一斗二升。多以樽槐瘤為之，或銅鑄也）。坐於地茵，大半令食之。萬石等三人，视炙堅粗，莫敢就食，獨五千瞑目張口，兩手捧炙，如虎啖肉。丞相曰：\"真壮士也，可以扑殺西域健胡。\"又令试戲，仓龍等亦不利，獨五千勝之。十萬之眾，為之披靡。於是獨留五千，仓龍等退還本道。語曰：\"壮兒過大梁，如上龍門也。\"城北門常扃，鎖不开，开必有事，公命开之。騾子營骚動軍府，乃悉誅之，自此遂安也。李公既治淮南，决吳湘之獄，而持法清峻，犯之者無宥，有嚴、張之風也。狡吏奸豪，潛形匿跡。然出於獨見，寮佐莫敢諫之。李元將評事及弟仲將嘗侨寓江都，李公羁旅之年，每止於元將之馆，而叔呼之。榮達之後，元將稱弟、稱侄，皆不悅也；及為孫、子，方似相容。又有崔巡官者，居鄭圃，與丞相同年之舊，特遠來謁。才到客舍，不意家仆與市人有競。詰其所以，仆曰：\"宣州管驿崔巡官。\"下其仆與市人，皆抵極法。令捕崔至，曰：\"昔嘗識君，到此何不相見也？\"崔生叩頭謝曰：\"適憩旅舍，日已遲晚，相公尊重，非時不敢具陳卑禮。伏希哀怜，獲歸乡里。\"遂縻留服罪，笞股二十，送過秣陵。時人相謂曰：\"李公宗叔翻為孫子，故人忽作流囚。\"邑人懼禍，渡江過淮者眾。主吏啟曰：\"戶口逃亡不少。\"丞相曰：\"汝不見淘麥乎？秀者在下，糖比隨流；隨流者不必報來。\"自此一言，竟無俞境者。又有少年，势似疏簡，自雲：\"辛氏郎君，來謁丞相。\"於晤對之間，未甚周至。先是白居易寄元相詩曰：\"悶勸迂辛酒，閒吟短李詩。\"且曰：\"辛大邱度性迂嗜酒，李二十紳短而能詩。\"辛氏郎君，即邱度之子也。因謂李公曰：\"小子每憶白二十二丈詩曰：'悶勸畴昔酒，閒吟廿丈詩。'\"李曰：\"辛大有此狂兒，吾敢不存舊乎？\"凡諸宦族，快辛子之能忤，丞相之受侮。有一曹官到任，儀质頗似府公。府公見而惡之，書其状曰：\"著青把笏，也請料錢；睹此形骸，足可駭叹。\"左右皆竊笑焉。又有宿將，有過請罰，且雲：\"老兵倚恃年老，而刑不加，若在軍門，一百也决。\"竟不免其刑。凡所書判，或是卒然，故趨事者皆驚神破胆矣。初，李公赴荐，嘗以《古風》求呂光化溫，謂齊員外煦及弟恭曰：\"吾觀李二十秀才之文，斯人必為卿相。\"果如其言。詩曰：\"春种一粒粟，秋成萬顆子。四海無閒田，農夫猶饿死。鋤禾日當午，汗滴禾中土。誰知盤中餐，粒粒皆辛苦。\"先是元相廉察江東之日，修龟山寺魚池，以為放生之所，戒其僧曰：\"勸汝諸僧好自持，不須垂釣引青絲。雲山莫厭看經坐，便是浮生得道時。\"李公到镇，遊於野寺，觀元公詩，笑曰：\"僧有漁罟之事，必投於鏡湖。\"後有犯者，遂不恕。复為二絕以示之雲：\"剃發多緣是代耕，好聞人死惡人生。祗園說法無高下，爾辈何勞尚世情？\"\"汲水添池活白莲，十千鬣盡生天。凡庸不識慈悲意，自葬江魚入九泉。\"忽有老僧謁，願以因果喻之。丞相問：\"阿師從何處來？\"答曰：\"貧道從來處來。\"遂决二十，曰：\"任從去處去。\"至如浮薄賓客，莫敢候問，三教所來，俱有區別，海內服其才俊。","sortOrder":16},
  {"id":"s_work_dnl_13_17","chapterId":"ch_work_dnl_13","text":"李衛公佐武宗，平上党，破回鶻，自矜其功，於平泉莊置構思亭、伐叛亭以自旌。","sortOrder":17},
  {"id":"s_work_dnl_13_18","chapterId":"ch_work_dnl_13","text":"李丞相回，少嘗遊覃懷王氏別墅。王氏先世仕宦，子孫以力自業，待之甚厚，回深德之。及貴，王氏子齊其家牒求謁，不得通，於金吾鼓舍伺丞相出，拜於道左，久之方省，曰：\"故人也。\"遂廪饩之。逾旬，以前術衔除大理評事，取告身面授。舊製：大理寺官初上，召寺僚或在朝五品以上清資保識。王氏本耕田，宗無故舊，复邀回言之。回問：\"有状乎？\"對曰：\"無。\"又曰：\"有紙乎？\"曰：\"無。\"\"袖中何物？\"曰：\"告身。\"即取告身署曰：\"中書侍郎兼禮部尚書平章事李回識。\"仍謂諸曹長曰：\"此亦五品以上清資也。\"","sortOrder":18},
  {"id":"s_work_dnl_13_19","chapterId":"ch_work_dnl_13","text":"宣宗幸苑中，回顧仗外舍屋际，有倚竹一竿，可見者止尺餘，去御馬百步外。遂命弓橫綜，上挟矢曰：\"朕以法製威天下，而党羌窮寇，敢來幹我，連年兵不解。我今射此竹，卜其濟否。\"左右耸觀。上攘袖挽弓，一發洞其竹，分而為二，矢貫於外。左右呼萬歲，贺於馬前。未逾月，羌果滅。","sortOrder":19},
  {"id":"s_work_dnl_13_20","chapterId":"ch_work_dnl_13","text":"裴相為宣州觀察，朝謝後，閒行曲江；荷花盛發，與省僩諸公同遊。自慈恩至紫雲樓下，見五六人坐水次，裴與諸人憩於旁。中有黃衣，飲酒軒昂，笑語輕脱。裴稍不平，問曰：\"君所任何官？\"對曰：\"诺，即不敢，新授宣州廣德縣令。\"复問裴曰：\"押衙所任何職？\"曰：\"诺，即不敢，新授宣州觀察使。\"於是奔走而去，一席皆歡，聞者大笑。左右訪於吏部雲：\"有廣德縣令，已請換羅江令矣。\"宣宗在藩邸聞之，常與諸王為笑樂。及即位，裴為丞相，因書麻製回，謂左右曰：\"诺，即不敢，新授中書侍郎平章事。\"","sortOrder":20},
  {"id":"s_work_dnl_13_21","chapterId":"ch_work_dnl_13","text":"長孫趙公朝宴，酒酣樂阕，顧群公曰：\"無忌不才，幸遇休明之運。因緣寵私，致位上公，人臣之貴可謂極矣。公视無忌，何如越公？\"（原註：楊素有大功，封越公）或對曰：\"不如。\"或曰：\"過之。\"公曰：\"吾自揣誠不羨越公。越公之貴也老，而無忌之貴也少。\"","sortOrder":21},
  {"id":"s_work_dnl_13_22","chapterId":"ch_work_dnl_13","text":"李太師光顏女未聘，從事許當及幕僚因從容次，盛譽一鄭秀才詞學門閥，冀其選揀。謝曰：\"李光顏，一健兒也，遭遇多，偶立微功，豈可妄求名族？已選得一婿也，諸賢未見。\"乃召客司小將指之曰：\"此即某女之婿也。超三五階軍職，厚與金帛，足矣。\"","sortOrder":22},
  {"id":"s_work_dnl_13_23","chapterId":"ch_work_dnl_13","text":"浑太師，年十一，隨父釋之防秋。朔方節度使張齊丘戲問：\"將乳母來否？\"其年立跳功。後二年收石堡城，收龍駒島，皆有奇數。","sortOrder":23},
  {"id":"s_work_dnl_13_24","chapterId":"ch_work_dnl_13","text":"馬司徒讨李懷光，自太原引兵至寶鼎下營，問其地名，曰：\"埋懷村。\"大喜曰：\"擒賊必矣。\"","sortOrder":24},
  {"id":"s_work_dnl_14_1","chapterId":"ch_work_dnl_14","text":"●卷四·容止","sortOrder":1},
  {"id":"s_work_dnl_14_2","chapterId":"ch_work_dnl_14","text":"开元中，燕公張說當朝文伯，冠服以儒者自處。玄宗嫌其異己，賜內樣巾子，長腳羅幞頭，燕公服之入謝，玄宗大喜。","sortOrder":2},
  {"id":"s_work_dnl_14_3","chapterId":"ch_work_dnl_14","text":"玄宗早朝，百官趨班。上見張九齡風儀秀整，有異於眾，謂左右曰：\"朕每見張九齡，精神頓生。\"","sortOrder":3},
  {"id":"s_work_dnl_14_4","chapterId":"ch_work_dnl_14","text":"裴仆射遵慶二十入仕，裹折上巾子，未嘗隨俗樣。凡代之移易者五六，而公年九十時，尚幼少所裹者。今巾子有仆射樣。","sortOrder":4},
  {"id":"s_work_dnl_14_5","chapterId":"ch_work_dnl_14","text":"韓晉公久镇浙西，所取賓佐，隨其所長，無不得人。嘗有故舊子弟投之，與語，更無他能；召之燕而觀之，畢席端坐，不旁视，不與比坐交言。後數日，署以隨軍，令監库門。使人视之，每早入，惟端坐至夕。警察吏卒，無敢濫出入者。","sortOrder":5},
  {"id":"s_work_dnl_14_6","chapterId":"ch_work_dnl_14","text":"李相國程為翰林學士，以階前日影為入候。公性懶，每人必逾八砖，後號為八砖學士。","sortOrder":6},
  {"id":"s_work_dnl_14_7","chapterId":"ch_work_dnl_14","text":"鄭瑜為河南尹，送迎中使皆有常處。人吏窥之，馬足差跌不出三五步。議者以瑜為河南尹，可繼張延賞，而重厚堅正，前後莫有及。","sortOrder":7},
  {"id":"s_work_dnl_14_8","chapterId":"ch_work_dnl_14","text":"大中十一年正月一日，含元殿受朝，太子太師盧鈞年八十，自樂懸南步而及殿墀，稱贺上前，舉止中禮，士大夫叹之。十二年正月朔，含元殿受朝，太子少師柳公權，亦年八十，复為百官班首，自樂懸南步至殿下，力已委頓，及上尊號\"聖敬文思和武光孝皇帝\"，公權誤曰\"光武和孝。\"御史彈之，罰一季俸。世譏公權不能退身自止。","sortOrder":8},
  {"id":"s_work_dnl_14_9","chapterId":"ch_work_dnl_14","text":"薛調、季瓒同年進士。調美姿貌，人號為\"生菩薩\"；瓒俊爽，人號為\"劍\"。調宽恕而瓒猜忌，論者以時人所稱，协其性也。劉元章罢江夏入朝，以風標自任。一日，調謁之，倒屣出迎，愛其風韻，去而复留者數四。既去，謂左右曰：\"若不見其（案：此下有闕文）也。\"調為翰林學士。郭妃悅其貌，謂懿宗曰：\"駙馬盍若薛調乎？\"頃之暴卒，時以為中鸩。卒年四十三，常覽鏡曰：\"薛調豈止四十三乎？\"豈嘗有言其寿者耶？","sortOrder":9},
  {"id":"s_work_dnl_14_10","chapterId":"ch_work_dnl_14","text":"杜相審權镇浙西，性宽厚，左右僮仆希見其語。在翰林最久，習於慎密。在镇三歲，自初视事，坐於東廳，至其罢去，未嘗易處。雖大臣經過，亦不俞中門。视事之暇，日未夕，非有故，不還私室。端默斂犭各，常若對賓旅。夏日中欲寢息，則顧軍將令下帘。或四顧無人，即自起去帘鉤，以手捧軸，徐下帘至地，方拱退。進止雍容如畫。時杜先達，人謂之老杜相，審權為小杜相。","sortOrder":10},
  {"id":"s_work_dnl_14_11","chapterId":"ch_work_dnl_14","text":"魏仆射元忠，每立朝，必得常處，人或記之，不差尺寸。","sortOrder":11},
  {"id":"s_work_dnl_14_12","chapterId":"ch_work_dnl_14","text":"路侍中巖，風貌之美，為世所聞。镇成都日，委執政於孔目吏邊鹹，日以妓樂自隨。宴於江津，都人士女懷掷果之羨，雖衛、潘嶽不足為比。善巾裹，蜀人見必效之。後乃翦紗巾之角，以異於眾也。闾巷有ㄚ服修容者，人必譏之曰：\"爾非路侍中耶？\"比至鬻豚之肆，見儈豕者謂屠主曰：\"此豚端正，路侍中不如。\"用之比方，良可笑也。以官妓行雲等十人侍宴，移镇渚宮日，於合江亭離筵赠行雲等《感恩多》詞。有：\"離魂何處斷？煙雨江南岸。\"至今播於倡樓也。","sortOrder":12},
  {"id":"s_work_dnl_15_1","chapterId":"ch_work_dnl_15","text":"●卷四·自新","sortOrder":1},
  {"id":"s_work_dnl_15_2","chapterId":"ch_work_dnl_15","text":"江淮客劉圓，嘗謁江州刺史崔沆，稱\"前拾遺\"。沆引坐勸曰：\"諫官不可自稱，司直、評事可矣。\"須臾他客至，圓稱曰：\"大理司直劉圓。\"沆甚賞之。","sortOrder":2},
  {"id":"s_work_dnl_15_3","chapterId":"ch_work_dnl_15","text":"李，從父弟也。為宋州刺史，聞反状，恸哭，悉驅妻子奴婢，無老幼，量頭為枷，自拘於觀察使。朝廷悯之，薄貶。","sortOrder":3},
  {"id":"s_work_dnl_15_4","chapterId":"ch_work_dnl_15","text":"天寶已前，多刺客。李氵公勉為开封府，鞫囚有意氣者，鹹哀勉求生，縱而逸之。後數歲，勉罢官，客行河北。偶見故囚，迎歸，厚待之。告其妻曰：\"此活我者，何以報德？\"妻曰：\"以缣千匹，可乎？\"曰：\"未也。\"\"二千匹，可乎？\"曰：\"未也。\"妻曰：\"大恩難報，不如殺之。\"故囚心動。其僮哀勉，密告勉，被衣乘馬而遁。比夜半，百餘里至津店。津店老人曰：\"此多猛獸，何故夜行？\"勉因言其故，未畢，梁上有人瞥下曰：\"幾誤殺死長者！\"乃去。未明，携故囚夫妻二首而至示勉。","sortOrder":4},
  {"id":"s_work_dnl_15_5","chapterId":"ch_work_dnl_15","text":"田神功自平盧兵使授淄青節度，舊官皆偏裨時部曲，神功平受其拜；及此前使判官劉位已下數人併留在院，神功待之亦無降禮。後因围宋州，見李光弼與敕使打球，聞判官張亻參至，光弼答拜。神功大驚，歸幕呼劉位問之，曰：\"太尉今日見張郎中來，與之拜答，是何禮也？\"位曰：\"判官幕客，使主無受拜之禮。\"神功曰：\"公何不早說？\"遂令屈諸判官，謝之曰：\"神功武將，起自行伍，不知朝廷禮數，誤受判官等拜。判官又不言，成神功之過，今還諸公拜。\"遂一一拜之。","sortOrder":5},
  {"id":"s_work_dnl_15_6","chapterId":"ch_work_dnl_15","text":"包誼，江浙人，下第遊漢南。與劉太真相會辯難，劉辭屈，责其不敬，誼掷杯中其額。後太真為禮部侍郎，誼應舉。太真覽其文卷於包侍郎佶之家，初甚驚叹，及视其名，包誼也，遂默然。至出榜，宰相欲有去留，面問太真換一名。太真不能對；忽記誼之姓名，遽言之，遂中第。","sortOrder":6},
  {"id":"s_work_dnl_15_7","chapterId":"ch_work_dnl_15","text":"魏仆射本名真宰，武後朝被誣構下獄，有司將出之，小吏聞之以告魏，魏喜曰：\"汝名何？\"曰：\"元忠。\"遂改從元忠焉。","sortOrder":7},
  {"id":"s_work_dnl_16_1","chapterId":"ch_work_dnl_16","text":"●卷四·企羨","sortOrder":1},
  {"id":"s_work_dnl_16_2","chapterId":"ch_work_dnl_16","text":"進士張倬，濮陽王柬之曾孫也。時初落第，兩手捧《登科記》顶之，曰：\"此《千佛名經》也。\"其企羨如此。","sortOrder":2},
  {"id":"s_work_dnl_16_3","chapterId":"ch_work_dnl_16","text":"盧杞令李揆入蕃，揆對德宗曰：\"臣不憚遠使，恐死於道路，不達君命。\"上惻然，欲免之，謂杞曰：\"李揆暮老，無使。\"杞曰：\"和戎之使，且須谙練，非揆不可。且使揆去，向後差使小於揆年者，不敢辭遠使矣。\"揆既至，蕃長曰：\"聞唐家第一人李揆，公是否？\"揆曰：\"非也。他那个李揆爭肯到此？\"恐其拘留，以此謾之也。揆門第第一，文學第一，官職第一。揆致仕東都，大司徒杜公罢淮海也，入洛見之，言及\"頭頭第一\"之說。揆曰：\"若道門戶，有所自，承餘裕也；官職，遭遇爾。今形骸凋瘁，看即下世，一切為空，何第一之有？\"","sortOrder":3},
  {"id":"s_work_dnl_16_4","chapterId":"ch_work_dnl_16","text":"苗給事子缵應舉次，而給事以中風語涩，而心中至切。臨试，又疾亟。缵乃為状，請許入试否。給事猶能把筆，淡墨為書，曰：\"入！\"其父子之情切如此。其年缵及第。","sortOrder":4},
  {"id":"s_work_dnl_16_5","chapterId":"ch_work_dnl_16","text":"陆相贽受淮南尉，吏部侍郎不與；顧少連擬與江淮一尉，不伏，竟得之。顯其德而自吟曰：\"繞階流氵助，夹砌树陰陰。\"□後罢相，□□在假日，敕下不謝官，又貶為忠州司馬。大官降敕日，令朝謝。但恐私忌□亦須出入始了。","sortOrder":5},
  {"id":"s_work_dnl_16_6","chapterId":"ch_work_dnl_16","text":"开元以後，不以姓名而可稱者：燕公、許公、魯公；不以名而可稱者：宋开府、陆兖州、王右丞、房太尉、郭令公、崔太尉、楊司徒、劉忠州、楊崖州、段太尉；位卑而名著者：李北海、王江寧、李馆陶、鄭廣文、元魯山、萧功曹、獨孤常州、崔比部、張水部、梁補闕、韦蘇州；二人連呼者：岐薛、燕許（原註：大手筆）、李杜、姚宋（原註：亦曰蘇宋）、萧李（原註：文章）。元和後，不以名可稱者：李太尉、韦中令、裴晉公、白太傅、贾仆射、路侍中、杜紫微；位卑名著者：贾長江、趙渭南；二人連呼者；元白；又有羅鉗吉綱（原註：酷吏），員推韦状（原註：能吏）。又有四夔、四凶。","sortOrder":6},
  {"id":"s_work_dnl_16_7","chapterId":"ch_work_dnl_16","text":"於良史為張徐州建封從事，每自吟曰：\"出身三十年，白發衣猶碧；日暮倚朱門，從未污袍赤。\"公聞之，為奏章服焉。","sortOrder":7},
  {"id":"s_work_dnl_16_8","chapterId":"ch_work_dnl_16","text":"韓仆射皋為京兆尹，韦相貫之為畿甸尉。及貫之人為相，皋為吏部尚書。每至中書，韦常異禮，以申故吏之敬。皋家自黃門以來，三世傳執一笏。經祖父所執，未嘗輕授於仆人之手。歸則別置於臥內一榻，以示敬慎。","sortOrder":8},
  {"id":"s_work_dnl_16_9","chapterId":"ch_work_dnl_16","text":"趙昭公以舊相為吏部侍郎，考前進士杜元穎宏詞登科；及镇荆南，又奏為從事。杜公入相，昭公复掌選；至杜出镇西川，奏宋相申錫為從事。數年，杜以南蠻入寇，貶刺循州，遂卒；宋以宰相被誣，謫佐开州。後數年，昭公始卒。公凡八任铨衡，三領節镇，皆帶府號，為尚書，惟不歷工部，其兵部太常皆再任。年八十七薨，其間未嘗遇重疾。俭素（案：俭素，趙《因話錄》作\"異數\"）寿考，為朝中之首。","sortOrder":9},
  {"id":"s_work_dnl_16_10","chapterId":"ch_work_dnl_16","text":"權文公德舆，身不由科第，嘗知貢舉三年，門下所出諸生相繼為公相，號得人之盛。","sortOrder":10},
  {"id":"s_work_dnl_16_11","chapterId":"ch_work_dnl_16","text":"趙郡李氏，元和初，三祖之後，同時一人為相。藩南祖，吉甫西祖，絳東祖，而皆第三。至太和、开成間，又各一人前後在相位。德裕，吉甫之子；固言，藩再從弟：皆第九，珏亦絳之近從。","sortOrder":11},
  {"id":"s_work_dnl_16_12","chapterId":"ch_work_dnl_16","text":"李尚書益，有宗人庶子同名，俱出於姑臧公；而人謂尚書為文章李益，庶子為門戶李益。而尚書尚兼門地焉。嘗姻族間有禮會，尚書歸，笑謂家人曰：\"大堪笑！今日局席，兩个座頭總是李益。\"","sortOrder":12},
  {"id":"s_work_dnl_16_13","chapterId":"ch_work_dnl_16","text":"李太師逢吉知貢舉，榜未放而入相，禮部尚書王播代放榜。及第人就中書見座主，時謂\"好腳跡門生\"，前世未有。","sortOrder":13},
  {"id":"s_work_dnl_16_14","chapterId":"ch_work_dnl_16","text":"陽城為朝士，家苦貧，常以布衾木枕质錢數萬，人爭取之。","sortOrder":14},
  {"id":"s_work_dnl_16_15","chapterId":"ch_work_dnl_16","text":"李願司空兄弟九人，四有土地：願為夏州、徐泗、鳳翔、宣武、河中五節度，憲為江西觀察、嶺南節度，為唐邓、襄陽、徐泗、鳳翔、泽潞、魏博六節度，聽為夏州、靈武、河東、鄭滑、魏博、寧七節度。一門登壇受鉞，無比焉。","sortOrder":15},
  {"id":"s_work_dnl_16_16","chapterId":"ch_work_dnl_16","text":"胡尚書證，河中人。太傅昭公镇河中，尚書建節赴振武，備桑梓禮入謁，持刺稱百姓。獻昭公詩雲：\"詩書入京國，旌旆過乡關。\"州里榮之。進士趙橹著《乡籍》一篇，夸河東人物之盛，皆實錄也。同乡中，趙氏軒冕文儒最著，曾祖父、祖父，世掌纶誥。橹崑弟五人，進士及第，皆歷台省。盧少傅宏宣，盧尚書簡辭、宏正、簡求，皆其姑子也，時稱\"趙家出\"。外家敬氏，先世亦出自河中，人物名望皆謂至盛，橹著《乡籍》載之。","sortOrder":16},
  {"id":"s_work_dnl_16_17","chapterId":"ch_work_dnl_16","text":"楊仆射於陵在考功時，舉李師稷及第。至其子相國嗣复知舉，門生集候仆射，而李公在座。時人謂之楊家上下門生。世有姑之婿與侄之婿，謂之上下同門，蓋以此况也。","sortOrder":17},
  {"id":"s_work_dnl_16_18","chapterId":"ch_work_dnl_16","text":"李相石，庾尚書承宣門生，不數年，李佐魏博軍，因奏事特賜紫，而庾尚衣緋。人謂李侍御將紫底緋上座主。","sortOrder":18},
  {"id":"s_work_dnl_16_19","chapterId":"ch_work_dnl_16","text":"李相宗闵知貢舉，門生多清雅俊茂；唐冲、薛庠、袁都，時謂之玉筍。","sortOrder":19},
  {"id":"s_work_dnl_16_20","chapterId":"ch_work_dnl_16","text":"柳公權與族孫，开成中同在翰林，時稱大柳舍人、小柳舍人。自祖父郎中芳已來，奕世文學，居清列。久在名場淹屈，及擢第，首冠諸生，當年宏詞登高科，十餘年便掌纶誥，侍翰苑。性喜汲引，後進多出其門。以誠明待物，不妄然诺，士益附之。","sortOrder":20},
  {"id":"s_work_dnl_16_21","chapterId":"ch_work_dnl_16","text":"开成三年，書判考官刑部員外郎紇幹公，崔相群門生也。紇幹及第時，於崔相新昌宅小廳中集見座主；及為考官之前，假居崔相故第，亦於此廳見門生焉。是年科目八人，敕頭孫河南，先於雁門公為丞。紇於封雁門公。","sortOrder":21},
  {"id":"s_work_dnl_16_22","chapterId":"ch_work_dnl_16","text":"文宗自太和乙卯歲後，常戚戚不樂，事稍閒，則必有叹息之音。會幸三殿東亭，見橫廊架巨軸，上指謂畫工程修己曰：\"此《开元東封圖》也。\"命內臣懸於東庑下。上舉玉如意指張說辈叹曰：\"使吾得其中一人，則可見开元之理。\"","sortOrder":22},
  {"id":"s_work_dnl_16_23","chapterId":"ch_work_dnl_16","text":"文宗為莊恪太子選妃，朝臣家子女悉令進名，中外為之不安。上知之，謂宰臣曰：\"朕欲為太子求汝鄭間衣冠子女為新婦，扶出來田舍傄傄地，如聞朝臣皆不願與朕作親情，何也？朕是數百年衣冠，無何神尧打朕家事羅诃去。\"遂罢其選。","sortOrder":23},
  {"id":"s_work_dnl_16_24","chapterId":"ch_work_dnl_16","text":"冯河南宿之三子陶、宽、圖兄弟，連年進士及第，連年登宏詞科，一時之盛無比。太和初，冯氏進士十人，宿家兄弟叔侄亦八人焉。","sortOrder":24},
  {"id":"s_work_dnl_16_25","chapterId":"ch_work_dnl_16","text":"李右丞迥甓牛惺橛邑?","sortOrder":25},
  {"id":"s_work_dnl_16_26","chapterId":"ch_work_dnl_16","text":"宣宗好儒，多與學士小殿從容議論，殿柱自題曰：\"乡貢進士李某。\"或宰臣出镇，賦詩以赠之。凡對宰臣及上言者，必先整容貌，易衣盥手，然後召見。語及政事，即終日忘倦。","sortOrder":26},
  {"id":"s_work_dnl_16_27","chapterId":"ch_work_dnl_16","text":"宣宗愛羨進士，每對朝臣，問\"登第否\"？有以科名對者，必有喜，便問所賦詩賦題，併主司姓名。或有人物優而不中第者，必叹息久之。嘗於禁中題\"乡貢進士李道龍\"。宦官知書，自文、宣二宗始。","sortOrder":27},
  {"id":"s_work_dnl_16_28","chapterId":"ch_work_dnl_16","text":"宣宗尚文學，尤重科名。大中十年，鄭顥知舉，宣宗索《登科記》。顥表曰：\"自武德以後，便有進士諸科。所傳前代姓名，皆是私家記錄。臣尋委當行祠部員外郎趙，采訪諸科目記，撰成十三卷。自武德元年至於聖朝，敕翰林自今放榜後，仰寫及第人姓名及所试詩賦題目進入，仰所司逐年編次。\"","sortOrder":28},
  {"id":"s_work_dnl_16_29","chapterId":"ch_work_dnl_16","text":"李某為中丞，奏孔尚書溫、徐相商為監察御史。孔為中丞，李在外多年，除宗正少卿，歸而為丞郎。每燕集，時人以為盛事。","sortOrder":29},
  {"id":"s_work_dnl_16_30","chapterId":"ch_work_dnl_16","text":"大中九年，沈侍郎詢以中書舍人知舉。其門生李彬父丛為萬年令，同年有起居之會。仓部李郎中時在座，因戲諸進士曰：\"今日極盛，某與賢座主同年。\"謂郴州李侍郎也。眾皆以為異。是日數公皆詣，賓客冯尚書審，則又郴州座主楊相國之同年也，舉座異之。","sortOrder":30},
  {"id":"s_work_dnl_16_31","chapterId":"ch_work_dnl_16","text":"張不疑進士擢第，宏詞登科。當年四府交辟。江西李中丞凝、東川李相回、淮南李相紳、興元歸仆射融，皆當時盛府。不疑赴淮南命，到府未幾，以协律郎卒。不疑娶崔氏，以不协出之，後娶顏氏。","sortOrder":31},
  {"id":"s_work_dnl_16_32","chapterId":"ch_work_dnl_16","text":"東夷有識山川者，偏禮五嶽，一拜而退；惟入關望華山，自關西門步步禮拜。至山下，仰望叹詫，七日而去。謂京師衣冠文物之盛，由此而致。","sortOrder":32},
  {"id":"s_work_dnl_16_33","chapterId":"ch_work_dnl_16","text":"崔起居雍，少有令名，進士第，與鄭顥齊名。士之遊其門者多登第，時人語為崔雍、鄭顥世界。","sortOrder":33},
  {"id":"s_work_dnl_16_34","chapterId":"ch_work_dnl_16","text":"崔雍自起居郎出守和州，遇庞勋寇歷陽，雍弃城奔浙西，為路巖所構，賜死。雍兄明、序、福兄弟八人皆進士，列甲乙科。當時號為點頭崔家。","sortOrder":34},
  {"id":"s_work_dnl_16_35","chapterId":"ch_work_dnl_16","text":"崔澹容貌清瘦明白，擢第升朝，崔铉辟入幕。先是朝中以流品為朋甲，以名德清重者為首。鹹通中，李都為大龍甲頭，沙汰名士，以經緯其伍。渭，澹兄弟也；澹在品中，以涓強侵為粗，卒不取焉。渭卑屈欲見取，其党皆避之。","sortOrder":35},
  {"id":"s_work_dnl_16_36","chapterId":"ch_work_dnl_16","text":"琅邪王氏與太原皆同出於周。琅邪之族世貴，號\"饣崔頭王氏\"，太原子弟爭之，稱是己族，然實非也。太原自號\"鏤王氏\"。崔氏，博陵與清河亦上下。其望族，博陵三房。第二房雖長，今其子孫即皆拜第三房子弟為伯叔者，蓋第三房婚娶晚遲，世數因而少故也。姑臧李氏亦然，其第三房，皆受大房、第二房之禮。清河崔氏亦小房最著，崔程出清河小房也。世居楚州寶應縣，號\"八寶崔氏\"。寶應本安宜縣，崔氏夢捧八寶以獻，敕改名焉。程之姨，北門李相蔚之夫人；蔚乃姑臧小房也，判鹽鐵。程為扬州院官，舉吳尧卿。蔚以為得人，竟亂擢之任。程累郡無政績，小杜相聞程諸女有容德，致書為其子讓能娶焉。程初辭之，謂人曰：\"崔氏之門，若有一杜郎，其何堪矣。\"而杜相堅請不已，程不能免，乃於寶應諸院取一娣侄嫁之。其後讓能貴，為國夫人，而程之女不顯。","sortOrder":36},
  {"id":"s_work_dnl_16_37","chapterId":"ch_work_dnl_16","text":"進士舉人各树名甲，元和中語曰：\"欲入舉場，先問蘇、張。蘇、張猶可，三楊殺我。\"","sortOrder":37},
  {"id":"s_work_dnl_16_38","chapterId":"ch_work_dnl_16","text":"後有東西二甲，東呼西為\"茫茫队\"，言其無藝也。","sortOrder":38},
  {"id":"s_work_dnl_16_39","chapterId":"ch_work_dnl_16","text":"开成、會昌中，又曰：\"魯、紹、瑰、蒙，識即命通。\"又曰：\"鄭、楊、段、薛，炙手可熱。\"又有\"薄徒\"\"厚徒\"，多輕侮人，故裴泌侍御作《美人賦》譏之。後有瑰值、韦羅甲，又曰：\"瑰、值、都、雍，識即命通。\"又有大小二甲。又有註已甲。又有四字甲，言\"深辉軒庭\"。又四凶甲。又\"芳林十哲\"，言其與宦官交遊，若劉晔、任江洎、李巖士、蔡鋌、秦韜玉之徒。鋌與巖士各將兩軍書題，求華州解元，時謂對軍解頭。太和中，又有杜颛、窦訓、萧ㄍ，極有時稱，為後來領袖。","sortOrder":39},
  {"id":"s_work_dnl_16_40","chapterId":"ch_work_dnl_16","text":"杜自拾遺賜緋後，應舉及第，又拜拾遺，時號\"著緋進士\"。鄭延昌相公為京兆尹，兼知貢舉。","sortOrder":40},
  {"id":"s_work_dnl_16_41","chapterId":"ch_work_dnl_16","text":"白居易葬龍門山。河南尹盧貞刻《醉吟先生傳》於石，立於墓侧。相傳洛陽士人及四方遊人過矚墓者，必奠以卮酒，故冢前方丈之土常成渥。","sortOrder":41},
  {"id":"s_work_dnl_16_42","chapterId":"ch_work_dnl_16","text":"崔魏公铉與江西李侍郎骘同在李相石襄陽幕中。铉自下追入，不二年拜丞相。骘時在幕，為李相草贺書曰：\"賓筵初啟，曾陪樽俎之歡；將幕未移，已在陶鈞之下。\"（原註：杜佑佐權德舆幕，李珏佐牛僧孺幕，後與使主同為相）","sortOrder":42},
  {"id":"s_work_dnl_16_43","chapterId":"ch_work_dnl_16","text":"鄭裔綽為浙東觀察使，奏侍御史鄭公綽為副使。幕客與府主同姓聯名甚寡。","sortOrder":43},
  {"id":"s_work_dnl_16_44","chapterId":"ch_work_dnl_16","text":"鹹通末，鄭浑之為蘇州錄事，談銖為鹾院官，鐘輻為院巡，俱廣文。時湖州牧李超、趙蒙相次俱状元。二郡地土相接，時為語曰：\"湖接兩頭，蘇連三尾。\"","sortOrder":44},
  {"id":"s_work_dnl_16_45","chapterId":"ch_work_dnl_16","text":"蘇員外粹與母弟冲俱鄭都尉顥門生。後粹為東陽守，冲為信陽守，欲相見境上，本府許之。兩郡之守，携賓客同府主出省，俱自外郎，兄弟之榮少比。","sortOrder":45},
  {"id":"s_work_dnl_16_46","chapterId":"ch_work_dnl_16","text":"范陽盧，自興元元年癸亥德宗幸梁洋，二年甲子，鮑防侍郎知舉，至乾符二年乙未崔沆侍郎知舉，計九十二年，而二年停舉；九十年中，登進士者一百一十六人，諸科在外。而為字皆聯子。（案：此句疑有訛誤）所不聯者不十數人。然而世謂盧氏不出座主。自唐來，唯景雲二年考功員外郎盧逸知舉，後無繼者。韦都尉保衡常怪之。鹹通十三年，盧莊為閣長，都尉欲以知禮部，莊七月卒。盧相携在中書，以為恥。廣明元年，乃追陝州盧渥中丞入知舉；帖經後，黃巢犯闕，天子幸蜀，韦昭度侍郎於蜀代之，放十二人。","sortOrder":46},
  {"id":"s_work_dnl_16_47","chapterId":"ch_work_dnl_16","text":"閩自貞元以前，未有進士。觀察使李始建庠序，請獨孤常州及為《新學記》雲：\"缦胡之纓，化為青衿。\"林藻弟蘊與欧陽詹睹之叹息，相與結誓，繼登科第。","sortOrder":47},
  {"id":"s_work_dnl_16_48","chapterId":"ch_work_dnl_16","text":"薛元超謂所親曰：\"吾不才，富貴過人。平生有三恨：始不以進士擢第，不娶五姓女，不得修國史。\"","sortOrder":48},
  {"id":"s_work_dnl_16_49","chapterId":"ch_work_dnl_16","text":"高宗承貞觀之後，天下無事。上官侍郎儀獨持國政，嘗凌晨入朝，循洛水堤，步月徐辔，詠雲：\"脈脈廣川流，驅馬歷長洲。鵲飛山月曙，蝉噪野風秋。\"音韻清亮，群公望之，猶若神仙焉。","sortOrder":49},
  {"id":"s_work_dnl_16_50","chapterId":"ch_work_dnl_16","text":"玄宗既誅韦氏，擢用賢良，革中宗之政，依貞觀故事。有志者莫不想太平。中書令姚元崇、侍中宋、御史大夫畢構、河南尹李杰，皆一時之選，時人稱姚、宋、畢、李焉。","sortOrder":50},
  {"id":"s_work_dnl_16_51","chapterId":"ch_work_dnl_16","text":"开元二十三年，加榮王已下官，敕宰臣入集賢院，分寫告身以賜之。侍中裴耀卿因入書库觀書，既而謂人曰：\"聖上好文，書籍之盛事，自古未有。朝宰充使，學徒雲集，官家設教，盡在是矣。前漢有金馬、石渠，後漢有蘭台、東觀；宋有總章，陳有德教；周則虎門、麟趾，北齊有仁寿、文林；雖載在前書，而事皆琐細，方之今日，則豈得扶輪捧轂者哉！\"","sortOrder":51},
  {"id":"s_work_dnl_17_1","chapterId":"ch_work_dnl_17","text":"●卷四·傷逝","sortOrder":1},
  {"id":"s_work_dnl_17_2","chapterId":"ch_work_dnl_17","text":"天寶十五載正月，安祿山反，陷洛陽。王師败績，關門不守。車駕幸蜀，次馬嵬驿，六軍不發，賜貴妃死，然後駕發。行至骆穀，上登高平，馬上謂力士曰：\"吾仓皇出狩，不及辭宗廟。此山絕高，望見秦川。吾今遙辭陵廟。\"下馬東向再拜，呜咽流涕，左右皆泣。又謂力士曰：\"吾取張九齡之言，不至於此。\"乃命中使往韶州，以太牢祭之。既而取長笛吹自製曲，曲成复流涕，詔樂工錄其譜。至成都，乃進譜而請名，上已不記，顧左右曰：\"何也？\"左右以骆穀望長安索長笛吹出對之。良久，曰：\"吾省矣。吾因思九齡，可號為《謫仙怨》。\"有人自西川傳者，無由知其本末，但呼為《劍南神曲》。其音怨切動人。大歷中，江南人盛傳。隨州刺史劉長卿左遷睦州司馬，祖筵聞之，長卿隨撰其詞，意頗自得，蓋亦不知事之始。詞雲：\"晴川落日初低，惆怅孤舟解携。鳥去平芜遠近，人隨流水東西。白雲千里萬里，明月前溪後溪。獨恨長沙謫去，江潭春草萋萋。\"其後，台州刺史窦宏餘以長卿之詞雖美，而與本曲意興不同，复作詞以廣不知者，其詞曰：\"胡尘犯闕冲關，金辂提携玉顏。雲雨此時消散，君王何日歸還？傷心朝恨暮恨，回首千山萬山。獨望天邊初月，蛾眉獨自弯弯。\"","sortOrder":2},
  {"id":"s_work_dnl_17_3","chapterId":"ch_work_dnl_17","text":"德宗初登勤政樓，外無知者。望見一人，衣绿乘驢戴帽，至樓下，仰视久之，亻免而東去。上立遣宣示京尹，令以物色求之。君召萬年捕賊官李銘，使促求訪。李尉佇立思之，曰：\"得必矣。\"出召幹事所由，春明門外數里內，應有諸司舊職事伎藝人，悉搜羅之，而绿衣果在其中。詰之，對曰：\"某天寶舊樂工也。上皇當時數登此樓，每來，鴟必集樓上，號'隨駕老鴟'。某自罢居城外，更不复見。今群鴟盛集，又覺景象宛如昔時，必知天子在上，悲喜且欲泣下。\"於是敕盡收此辈，却系教坊。李尉亦為京尹所擢用，後至郡守。","sortOrder":3},
  {"id":"s_work_dnl_17_4","chapterId":"ch_work_dnl_17","text":"貞元四年，劉太真侍郎入貢院，寄前主司萧聽尚書詩曰：\"獨坐貢闈里，愁心芳草生；山公昨夜事，應見此時情。\"","sortOrder":4},
  {"id":"s_work_dnl_17_5","chapterId":"ch_work_dnl_17","text":"太和九年，仇士良誅王涯、鄭註，上或登臨遊幸，雖百戲列於前，未嘗少悅。往往瞠目獨語，左右不敢進問。題詩雲：\"輦路生春草，上林花發時。凭高何限意，無复侍臣知。\"更於殿內看牡丹，翘足凭欄，誦舒元與《牡丹賦》雲：\"俯者如愁，仰者如悅，开者如語，合者如咽。\"久之，方省元舆詞，不覺叹息泣下。時有宮人沈阿翘為上舞《河滿子》詞，聲態宛轉，錫以金臂環。乃問其從來，阿翘曰：\"妾本吳元濟女。元濟败，因入宮。\"","sortOrder":5},
  {"id":"s_work_dnl_17_6","chapterId":"ch_work_dnl_17","text":"王太尉播，少貧，居瓜洲寄食，多為人所薄。及登第，歷榮顯，掌鹽鐵三十餘年。自劉忠州之後，無如播者。後镇淮南，乃遊瓜洲故居，賦詩感舊。李衛公出在蜀關，而致和其詩以寄播。","sortOrder":6},
  {"id":"s_work_dnl_17_7","chapterId":"ch_work_dnl_17","text":"宣宗以憲宗常幸青龍寺，命复道开便門，至寺升眺，追感者久之。","sortOrder":7},
  {"id":"s_work_dnl_17_8","chapterId":"ch_work_dnl_17","text":"杜豳公丧公主，進状請落駙馬都尉，雲：\"臣每見官衔有'駙馬'字，凄感難勝。\"","sortOrder":8},
  {"id":"s_work_dnl_17_9","chapterId":"ch_work_dnl_17","text":"太宗謂梁公曰：\"以銅為鏡，可以正衣冠；以古為鏡，可以知興替；以人為鏡，可以明得失。朕嘗保三鏡，用防己過。今魏徵殂逝，一鏡亡矣。\"","sortOrder":9},
  {"id":"s_work_dnl_17_10","chapterId":"ch_work_dnl_17","text":"太宗聞虞監亡，哭之恸曰：\"石渠、東觀之中，無复人矣！\"","sortOrder":10},
  {"id":"s_work_dnl_17_11","chapterId":"ch_work_dnl_17","text":"杜羔有至性。其父為河北尉卒，母非嫡，經亂不知所之，羔常抱終身之感。會堂兄兼為潞州府判官，鞫獄於私第，有老婦辯對，見羔出入，竊謂人曰：\"此少年状類吾夫。\"詰之，乃羔母也，自此迎歸。又往求先人之墓，邑中故老已盡，不知所詢。馆於佛寺，日夜悲泣。忽视屋柱煙煤之下，見字數行，拂而视之，乃其父遺跡，言：\"我子孫若求吾墓，當於某村某家問之。\"羔號哭而往，果有老父年八十餘，指其邱垅，遂得歸葬。","sortOrder":11},
  {"id":"s_work_dnl_18_1","chapterId":"ch_work_dnl_18","text":"●卷四·栖逸","sortOrder":1},
  {"id":"s_work_dnl_18_2","chapterId":"ch_work_dnl_18","text":"宣州當涂隱居山巖，即陶貞白煉丹所也，爐跡猶在。後為佛舍。有僧名彦范，俗姓劉，雖為沙門，而通儒學，邑人呼為劉九經。顏魯公、韓晉公、劉忠州、穆監寧、獨孤常州，皆與之善。各執經受業者數十人。年八十，猶強精神，僧律不虧。唯頗嗜飲酒，亦不亂。學者有携壶至者，欣然受之。每飲三數杯，則講說方銳。所居有小圃，自植茶，為鹿所損，眾勸以短垣隔之，諸名士悉為運石共成。穆兵部贽事之最謹。嘗得美酒，密以小瓷壶置於懷中，累石之际，白師曰：\"有少好酒，和尚飲否？\"彦范笑而滿引，徐謂穆曰：\"不用般石，且來聽書。\"遂與剖析奧旨，至多不倦。人有得穆兵部遺彦范書者，其辭雲：\"某偶忝名宦，皆因善誘。自居班列，終日尘屑。却思昔歲，臨清涧，荫長松，接侍座下，獲聞微言。未知何時复遂此事？遙瞻水中月，嶺上雲，但馳攀想而已。和尚薄於滋味，深於酒德，所食仅同婴兒，所飲或如少壮。常恐尊體有所不安，中夜思之，實懷忧恋。\"其誠切如此。月日之下，稱門人姓名状和尚前。","sortOrder":2},
  {"id":"s_work_dnl_18_3","chapterId":"ch_work_dnl_18","text":"元和初，南嶽道士田良逸、蒋含宏有道業，遠近稱之，號曰\"田、蒋\"。良逸天資高峻，虛心待物，不為表飾。呂侍郎渭、楊侍郎凭觀察湖南，皆師事之。潭州旱，祈雨不應，或請邀之，楊曰：\"田先生豈為人祈雨者耶？\"不得已迎之。良逸蓬發敝衣，欣然就舆。到郡亦終無言，即日降雨。所居嶽觀，內建黃壇場已具，而天陰晦，弟子請先生祈晴，良逸亦無言，岸帻垂發而坐。左右整冠履，扶而升壇，亦遂晴霁。嘗有村老持一絹襦來施，良逸對眾便著，坐客竊笑，不以介意。楊凭嘗迎至潭州，良逸方洗足，使到，乘小舟便行，侍者以履襪追及於衡門，即於門外坐砖階著襪，若無人在旁。楊自京尹謫臨贺尉，使使候之，遺以銀器。良逸受之，便悉付門人。使還，良逸曰：\"報汝阿郎，不久即歸，勿忧也。\"未幾，楊果移杭州長史。良逸未嘗幹人，人至亦不送，不記人官位姓名，第與呂渭分最深。後呂郎中溫為衡州刺史，因祭嶽候先生，告以使君\"侍郎之子\"。及溫入，良逸下繩床，撫其背曰：\"你是呂渭兒子耶？\"溫泫然降階，先生亦不止，其真率如此。良逸母為喜王寺尼，寺中皆呼良逸為小師。良逸常日負兩束薪以奉母，或自有故不及往，即弟子代送之。或傳寺眾晨起，見一虎在田媪門外，走以告媪，媪曰：\"毋怪，應是小師使致柴耳。\"蒋君含宏有操尚，時人以為不及良逸。然二人齊名，常兄事良逸。含弘善符術，後居九真觀，曾使弟子至縣市斋物，不及期還，詰其故，雲：\"於山口遇猛虎，當道不去，以故遲滯。\"含宏曰：\"吾居此庇渠已多時，何敢如此！\"即以一符置所見處，明日虎踣符下。含弘聞之，曰：\"吾本以符却之，豈知遂死。既以害物，安用術為？\"取符焚之，後不复留意。又有欧陽平者，行業亦高，兄事含弘，而道業不及也。欧陽曾一夕夢三爐自天而下，若有召說。既寤，潛告人曰：\"二先生不久去矣，我繼之。\"俄而田良逸死，含弘次年卒。桐柏山陳寡言、徐虛符、冯雲翼三人，皆田之弟子也。衡山周混，蒋之弟子也。陳、徐在東南，品地比田、蒋，而冯在欧陽之列。周自幼入道，善科法，亦為南嶽之冠。","sortOrder":3},
  {"id":"s_work_dnl_18_4","chapterId":"ch_work_dnl_18","text":"江南多名僧，貞元、元和已來，越州有清江、清晝，婺州有乾俊、乾辅。時謂之會稽二清，東陽二乾。","sortOrder":4},
  {"id":"s_work_dnl_18_5","chapterId":"ch_work_dnl_18","text":"白居易少傅分司東都，以詩酒自娱，著《醉吟先生傳》以自叙。盧尚書簡辭有別墅，近伊水，亭榭清峻。方冬，與群從子侄同登眺嵩洛。既而霰雪微下，說镇金陵時，江南山水，每見居人以葉舟浮泛，就食菰米鱸魚，思之不忘。逡巡，忽有二人，衣蓑笠，循岸而來，牵引篷艇。船頭覆青幕，中有白衣人與衲僧偶坐；船後有小竈，安銅甑而炊，卯角仆烹魚煮茗，溯流過於槛前。聞舟中吟笑方甚。盧叹其高逸，不知何人。從而問之，乃告居易與僧佛光，自建春門往香山精舍。","sortOrder":5},
  {"id":"s_work_dnl_18_6","chapterId":"ch_work_dnl_18","text":"李瞻，漢之子，有文學，氣貌淳古。非其人，雖富貴不交也。累遷司封郎中，歸茅山，拜給事中，不就。兩京亂，竟不罹其禍。","sortOrder":6},
  {"id":"s_work_dnl_18_7","chapterId":"ch_work_dnl_18","text":"李尚書褒，晚年修道，居陽羨川石山後。長子召為吳興，次子昭為常州，當時榮之。","sortOrder":7},
  {"id":"s_work_dnl_18_8","chapterId":"ch_work_dnl_18","text":"吳郡陆龟蒙，字魯望，舊族也。其父賓虞，進士甲科，浙東從事、侍御史，家於蘇台。龟蒙幼精六籍，弱冠攻文，與顏荛、皮日休、羅隱、吳融為益友。性高絜，家貧，思養親之祿，與張搏為吳興、庐江二郡僿。著《吳興實錄》四十卷，《松陵集》十卷，《笠泽丛書》三卷。丞相李公蔚、盧公携景重之。羅給事寄陆詩雲：\"龍樓李丞相，昔歲仰高文；黃閣今無主，青山竟不焚。\"蓋嘗有征聘之意。唐末以左拾遣授之，詔下之日，疾終。光化三年，赠右補闕。吳侍郎融立傳貽史官，右補闕韦莊撰诔文，相國陆希聲撰碑文，給事中顏荛書。皮日休博士為詩友，寇死浙中。方幹詩名著於吳中，陆未許之。一旦頓作詩五十首，裝為方幹新製，時辈吟賞降仰，陆謂曰：\"此乃下官效方幹之所作也。方詩在模范中爾。\"奇意精識者亦然之。薛許州能以詩道為己任，還劉夢得詩卷，有詩雲：\"百首如一首，卷初如卷終。\"譏劉不能变態，乃陆之比也。","sortOrder":8},
  {"id":"s_work_dnl_18_9","chapterId":"ch_work_dnl_18","text":"天寶之亂，元結自汝墳率鄰里南投襄漢，保全者千餘家。乃舉兵宛葉之間，有城守寇之力。結，天寶中稱中行子。始在商餘山，自稱元子。逃難入猗幹沮，始稱猗幹子。或稱浪士。漁者呼為聱叟，酒徒呼為漫郎。","sortOrder":9},
  {"id":"s_work_dnl_18_10","chapterId":"ch_work_dnl_18","text":"崔趙公嘗問径山曰：\"弟子出家得否？\"径山曰：\"出家是大丈夫事，非將相所為也。\"","sortOrder":10},
  {"id":"s_work_dnl_18_11","chapterId":"ch_work_dnl_18","text":"大歷中，關東飢疫，人多死。滎陽人鄭損，率有力者，每乡為一大墓，以葬弃尸，謂之乡葬，翕然有仁義之聲。損，盧藏用之甥，不仕，乡里號為雲居先生。","sortOrder":11},
  {"id":"s_work_dnl_18_12","chapterId":"ch_work_dnl_18","text":"竟陵僧於水濱得婴兒者，育為弟子。稍長，自筮得《蹇》之《漸》。繇曰：\"鸿漸於陆，其羽可用為儀。\"乃姓陆氏，字鸿漸，名羽。有文學，多意思，恥一物不盡其妙。最晓茶。巩縣為瓷偶人，號\"陆鸿漸\"。買十器，得一\"鸿漸\"。市人沽茗不利，辄灌註之。羽於江湖稱竟陵子，於南越稱桑苎翁。貞元末卒。","sortOrder":12},
  {"id":"s_work_dnl_18_13","chapterId":"ch_work_dnl_18","text":"韓愈好奇，嘗與客登華山絕顶，度不可下返，發狂恸哭，為遺書。華陰令百計取之，乃下。","sortOrder":13},
  {"id":"s_work_dnl_18_14","chapterId":"ch_work_dnl_18","text":"陽城居夏縣，拜諫議大夫；鄭鋼居阌乡，拜右拾遺；李周南居曲江，拜校書郎。時人以為轉遠轉高，轉近轉卑也。","sortOrder":14},
  {"id":"s_work_dnl_19_1","chapterId":"ch_work_dnl_19","text":"●卷四·賢媛","sortOrder":1},
  {"id":"s_work_dnl_19_2","chapterId":"ch_work_dnl_19","text":"高祖乃煬帝友人，煬帝以圖讖多言姓李將王，每排斥之。而後因大會，煬帝目上，呼為阿婆面。上不怿，歸家色猶摧沮。後怪而問，久之方說：\"帝目某為阿婆面。\"後喜曰：\"此可相贺。公是袭唐公，'唐'之為言'堂'也，阿婆面是'堂主'。\"上大悅。","sortOrder":2},
  {"id":"s_work_dnl_19_3","chapterId":"ch_work_dnl_19","text":"上都崇勝寺有徐賢妃妆殿。太宗召妃，久不至，怒之。因進詩曰：\"朝來臨鏡台，妆罢且徘徊。千金始一笑，一召詎能來？\"","sortOrder":3},
  {"id":"s_work_dnl_19_4","chapterId":"ch_work_dnl_19","text":"狄仁杰為相，有盧氏堂姨，居午桥南別墅，未嘗入城。仁杰伏腊，每修禮甚謹。嘗雪後休假，候盧氏安否，適見表弟挟弧矢携雉兔來歸，羞味進於堂上。顧揖仁杰，意甚輕傲。仁杰因啟曰：\"某今為相，表弟有何欲，願悉力從其意。\"姨曰：\"吾止有一子，不欲令事女主。\"仁杰慚而去。","sortOrder":4},
  {"id":"s_work_dnl_19_5","chapterId":"ch_work_dnl_19","text":"玄宗柳婕妤有才學，上甚重之。婕妤妹適趙氏，性巧慧，因使工鏤板為雜花，象之而為夹結。因婕妤生日，獻王皇後一匹。上見而賞之，因敕宮中依樣製之。當時甚秘，後漸出，遍於天下，乃為至賤所服。","sortOrder":5},
  {"id":"s_work_dnl_19_6","chapterId":"ch_work_dnl_19","text":"柳婕妤生延王。肅宗每見王，則語左右曰：\"我與王兄弟中更相親，外家皆關中貴族。\"蓋柳氏奕葉貴盛，人物盡高，方舆公、康城公，皆《北史》有傳矣。睦州俊邁，風格特異。自隋之後，家富於财。嘗因調集至京師，有名娼曰娇陳者，姿藝俱美，為士子之所奔走。睦州一見，因求納焉。娇陳曰：\"第中設錦帳三十重，則奉事終身矣。\"本易其少年，乃戲之也。翌日，遂如言，載錦而張之以行。娇陳大驚，且賞其奇特，竟如約，入柳氏之家，執仆媵之禮，節操為中表所推。玄宗在人間，聞娇陳之名。及召入宮見上，因涕泣，稱痼疾且老，上知其不欲背柳氏，乃許其歸。因語之曰：\"我聞柳家多賢女子，可以備職者，為我求之。\"娇陳乃以睦州女弟對。乃選入充婕妤，生延王及永穆公主焉。","sortOrder":6},
  {"id":"s_work_dnl_19_7","chapterId":"ch_work_dnl_19","text":"玄宗在禁中嘗稱阿瞞，亦稱鴉。寿安公主是曹野那姬所生也，以其九月而誕，遂不出降。常令衣道衣，主香火，小字虫娘，玄宗呼為師娘。時代宗起居，上曰：\"汝在東宮，甚有令譽也。\"因指寿安曰：\"虫娘是鴉女，汝後可與一名號。\"及代宗在靈州，遂命蘇發尚之，封寿安公主也。","sortOrder":7},
  {"id":"s_work_dnl_19_8","chapterId":"ch_work_dnl_19","text":"刑部郎中元沛之妻劉氏，全白之妹，賢而有文學，著《女儀》一篇，亦曰《直訓》。劉既寡居，奉道受於吳筠先生，清苦寿考。長子固，早有名，官歷省郎、刺史、國子司業；次子察，進士及第，累佐使府，後隱居庐山。察之長子，好道不仕；次子充，進士及第，亦尚道家。","sortOrder":8},
  {"id":"s_work_dnl_19_9","chapterId":"ch_work_dnl_19","text":"和政公主，肅宗第三女也，降柳潭。肅宗宴於宮中，女優有弄假官戲，绿衣秉簡，謂之參軍椿。天寶末，番將阿布思伏法，其妻配掖庭，為善優，因使隸樂工。是日遂為參軍椿。上及侍宴者笑樂，公主獨亻免首果眉不视。上問其故，公主遂諫曰：\"禁中侍女不少，何必須得此人？使阿布思真逆人也，其妻亦同刑人，不合近至尊之座；果冤橫，又豈忍使其妻與群優雜處，為笑謔之具哉？妾雖至愚，深以為不可。\"上亦悯惻，遂罢戲，而免阿布思之妻。由是賢重。公主即柳晟母。","sortOrder":9},
  {"id":"s_work_dnl_19_10","chapterId":"ch_work_dnl_19","text":"郭子儀镇汾陽時，殿中柳併為掌書記。柳君有母，汾陽王每因大燕，嘗誡左右曰：\"柳侍御太夫人就棚，可先來告。\"及趙夫人舆至，王降階與僚屬序立候，至棚而退。嘗謂柳君曰：\"子儀幼孤，不識奉養。今日幸忝恩寵逾望。雖為貴盛，賓無侍御之榮。\"因呜咽久之。又曰：\"若太夫人許見顧子儀之家，當使南陽夫人以下執爨，子儀自捧饌。\"而趙夫人以清絜自居，終不一往。","sortOrder":10},
  {"id":"s_work_dnl_19_11","chapterId":"ch_work_dnl_19","text":"劉玄佐貴為將相，其母月織缣一匹，示不忘本。每觀玄佐视事，見縣令走階下，退必語玄佐：\"貴為將相。吾向見長官白事卑敬，不覺恐悚。思汝父為吏本縣時，常畏長官汗忄栗。今爾當廳據案待之，亦何安也？\"因喻以朝廷恩寄之重，須務捐軀，故玄佐終不失臣節。","sortOrder":11},
  {"id":"s_work_dnl_19_12","chapterId":"ch_work_dnl_19","text":"陆相贽知舉，放崔相群。群知舉，而陆氏子簡禮被黜。群妻李夫人謂群曰：\"子弟成長，盍置莊園乎？\"公曰：\"今年已置三十所矣。\"夫人曰：\"陆氏門生知禮部，陆氏子無一得事者，是陆氏一莊荒矣。\"群無以對。","sortOrder":12},
  {"id":"s_work_dnl_19_13","chapterId":"ch_work_dnl_19","text":"穆宗大漸，內臣議請郭太後臨朝。太後曰：\"向者武後妖蠹，幻惑高宗，擅親庶政；及中宗踐位，蒙掩聖德，遽行遷逮，幾於革命。賴宗社威，神器再复。每聞其說，未嘗不疾首痛心。奈何今日吾兒厭世，卿等骤興此議？我家九个與武氏同流。先祖汾陽王有社稷大勋，我外氏□門閥赫奕，我禮嫔帝室，非复嫔嫱之比，豈可污彤管繼悖逆者耶？今皇太子聰睿，卿等各宜慎擇耆舊，親侍左右，遠屏邪佞，勿令近密。宰相任重德名賢，內官勿幹時政，吾所願也。\"遂取製裂之。時太後兄钊任太常卿，聞其議，密進疏於太後曰：\"果徇此請，當率子弟納官爵，歸田園。\"太後覽疏，泣曰：\"我祖盡忠於國，餘慶鐘於我兄。\"","sortOrder":13},
  {"id":"s_work_dnl_19_14","chapterId":"ch_work_dnl_19","text":"劉異赴分寧，安平公主辭，以異侍女從。宣宗曰：\"此何人也？\"曰：\"劉郎音聲人。\"上喜安平不妒，顧左右曰：\"與作主人，不令與宮娃同處。\"","sortOrder":14},
  {"id":"s_work_dnl_19_15","chapterId":"ch_work_dnl_19","text":"太宗嘗罢朝，怒曰：\"會須殺田舍漢！\"文德皇後謂帝曰：\"誰觸忤陛下？\"帝曰：\"豈過魏徵，每廷辱我常不自得。\"後退而具朝服，立於廷。帝驚曰：\"皇後何為若是？\"後曰：\"妾聞主聖臣忠。今陛下聖明，致魏徵得直言；妾備數後官，安敢不贺？\"","sortOrder":15},
  {"id":"s_work_dnl_19_16","chapterId":"ch_work_dnl_19","text":"高宗乳母盧氏，本滑州總管杜才幹妻。以謀逆誅，故虜没入官。帝既即位，封燕國夫人，品第一。盧既藉恩寵，屢訴及杜□氏；臨亡，复請與才幹合葬，帝以獲罪先朝，亦不許之。","sortOrder":16},
  {"id":"s_work_dnl_19_17","chapterId":"ch_work_dnl_19","text":"隴西李知璋，妻滎陽鄭氏，雅不見重。知璋為江夏尉，因醉杖殺人母，其子入复仇。知璋與鄭以床拒門，仇者推窗而入，鄭急以身蔽知璋，舉手承刃，右臂既落，复伸左臂，仇复斷之，猶以身代夫死。方懷妊，仇者以刀鑠其腹，胎出於外而陨。乃害知璋，及其二子。州司以聞，坐死數十人。","sortOrder":17},
  {"id":"s_work_dnl_19_18","chapterId":"ch_work_dnl_19","text":"太宗造玉華宮於宜春縣，徐充容諫曰：\"妾聞為政之本，貴在無為；切見土木之功，不可兼遂。北闕初建，南宮翠微，曾未逾時，玉華創製。雖复因山藉水，非架筑之勞；損之又損，頗有無功之費。終以茅茨示約，猶興求石之疲。假使和顧取人，豈無煩扰之弊？是以卑宮菲食，聖主之所安；金屋瑤台，驕主之作麗。故有道之君，以逸逸人；無道之君，以樂樂身。願陛下使之以時，則力不竭；不用而息之，則人胥悅矣。\"充容名惠，孝德之女，堅之姑也。文彩綺麗，有若天生。太宗崩，哀慕而卒，時人傷異之。","sortOrder":18},
  {"id":"s_work_dnl_19_19","chapterId":"ch_work_dnl_19","text":"蜀之士子，莫不沽酒，慕相如涤器之風。陳會郎中家以當壚為業。為不扫官街，吏殴之。其母甚賢，勉以修進，不達不要歸乡，以成名為期。每歲舉糧紙筆衣服仆馬，皆自成都赍至中都助業。後業成八韻，唯《螗螂賦》大行。元和元年及第。李相固言覽報状，處分厢界收下酒旆，阖其戶。家人猶拒之。逡巡，贺登第，實聖善奖諭之力也。後為白中令婿，西川副使，連典彭、漢兩郡而終。","sortOrder":19},
  {"id":"s_work_dnl_19_20","chapterId":"ch_work_dnl_19","text":"尚書左丞相李逵星宓隆Ｆ涿茫蹶唐摶病ｊ谭奖ǎ⒃煲劍又燎奘搖?見其門帘甚弊，乃令人潛度廣狹，以鹿竹織成，加緣飾，將以赠濉Ｈ撩牛不敢發言而去。","sortOrder":20},
  {"id":"s_work_dnl_19_21","chapterId":"ch_work_dnl_19","text":"江左之亂，江陰尉邹待征妻薄氏為盜所掠，密以待征官告托於村媪，而後死之。李華為《哀節婦賦》以行於世。","sortOrder":21},
  {"id":"s_work_dnl_20_1","chapterId":"ch_work_dnl_20","text":"●卷五·補遺（起高祖至代宗）","sortOrder":1},
  {"id":"s_work_dnl_20_2","chapterId":"ch_work_dnl_20","text":"（案：以下《補遺》四卷，併采自《永樂大典》，原分門目，已不可考見，今略以時代為次，無時代者編附於後）","sortOrder":2},
  {"id":"s_work_dnl_20_3","chapterId":"ch_work_dnl_20","text":"高祖既受隋禪，坐太極前殿，會朝之次，忽報南山急，賊不测。安南大首領冯盎前奏曰：\"急击之，必退散，無能為也。\"遣百騎御之。俄頃報賊南遁，上召盎曰：\"卿安能遠料賊果败退？\"盎曰：\"奏報之時，臣望氣，雲形似树。辰在金，金能克木，击之必勝。\"上喜，面賜金帶。","sortOrder":3},
  {"id":"s_work_dnl_20_4","chapterId":"ch_work_dnl_20","text":"武德末年，突厥至渭桥，控絃四十萬。太宗初親庶政，驿召李衛公問策。時發諸州府軍未至，長安居人勝兵者不過數萬。突厥精騎騰突挑戰，日數十合。帝怒，欲击之。靖請傾府库，邀其歸路，帝從其言，突厥兵遂退。於是據险邀之，遂弃老弱而遁。獲馬數百匹，金帛一無遺焉。","sortOrder":4},
  {"id":"s_work_dnl_20_5","chapterId":"ch_work_dnl_20","text":"李密掛《漢書》牛角，行且讀。","sortOrder":5},
  {"id":"s_work_dnl_20_6","chapterId":"ch_work_dnl_20","text":"隋大業中，李衛公上書，高祖終不為人臣，請速去之。後高祖入京師，靖與滑儀、衛文升等俱見收。衛、滑既死，太宗慮囚，見靖，引與語，因請於高祖免之。始隨趙郡王孝恭南征，清巴、漢，擒萧铣，荡一扬、越，師不留行，皆靖之力也。","sortOrder":6},
  {"id":"s_work_dnl_20_7","chapterId":"ch_work_dnl_20","text":"英公始與单雄信俱仕李密，結為兄弟。密既亡，雄信降世充，來歸國。雄信壮勇過人。後與海陵王元吉围洛陽。元吉恃膂力，每行围。世充召雄信告之，酌以金碗，雄信盡飲，馳馬而出，槍不及海陵者一尺。惶遽，連呼曰：\"阿兄！此是主。\"雄信乃攬辔而止，顧笑曰：\"胡不緣爾，且竟死！\"世充既平，雄信將就戮，英公請之不得，泣而退。雄信曰：\"我固知汝不了。\"曰：\"平生誓共灰土，豈敢相忘？但將身許國，義不兩合，雖不死之，且顧兄妻子如何？\"因以刀割其股肉以授信，曰：\"示不虧前誓。\"雄信食之不疑。","sortOrder":7},
  {"id":"s_work_dnl_20_8","chapterId":"ch_work_dnl_20","text":"高宗立武後。褚河南謀於趙公無忌、英公，將以死爭。趙公請先入，褚曰：\"太尉，國之元舅，脱事不如意，使上有惡舅之名，不可。\"英公請先入，褚曰：\"司空，國之元勋，有不如意，使上有逐良臣之名，不可。遂良出自草茅，無汗馬之功，蒙先帝殊遇，以有今日。自當不讳之時，躬奉遺詔，若不效其愚衷，何以下見先帝？\"揖二公而入。帝深納其言，事遂中寢。","sortOrder":8},
  {"id":"s_work_dnl_20_9","chapterId":"ch_work_dnl_20","text":"中宗正位後，有武當縣丞寿春周憬，慷慨有節義，乃與王駙馬同皎謀誅武三思。事發，同皎見害，憬逃於比幹廟中刎死。臨死謂曰：\"比幹，紂之忠臣也；傥神道有知，明我以忠見殺。\"","sortOrder":9},
  {"id":"s_work_dnl_20_10","chapterId":"ch_work_dnl_20","text":"虬須客，姓張氏，赤發而虬須。時楊素家紅拂妓張氏奔李靖，將歸太原。行次靈桥驿，既設床，爐中煮肉，張氏以發長垂地，立梳床前，靖方刷馬，忽虬須客乘驢而來，投革囊於爐前，取枕欹臥，看張氏梳頭。靖怒，未决。張氏熟视其面，一手映身搖示靖，令勿怒。急急梳頭畢，斂衽前問其姓氏。臥客曰：\"姓張。\"張氏對曰：\"妾亦姓張，合是妹。\"遽拜之。問第幾，曰：\"第三。\"亦問第幾，曰：\"最長。\"遂喜曰：\"今日幸逢一妹。\"張氏遙呼曰：\"李郎，且來拜三兄！\"靖骤拜之，遂環坐。客曰：\"煮者何肉？\"曰：\"羊肉，計已熟矣。\"客曰：\"飢。\"靖出市胡餅，客抽腰間匕首切肉，共食之竟，以餘肉亂切飼驢。客曰：\"何之？\"曰：\"將避地太原。\"客曰：\"有酒乎？\"曰：\"主人西，則酒肆也。\"靖取酒一斗。既巡，客曰：\"吾有少下酒物，李郎能同食乎？\"靖曰：\"不敢。\"遂开革囊，取出一人頭，併心肝；却以頭貯囊中，以匕首切心肝共食之。曰：\"此天下負心者也。衔之二十年，今始獲之，吾憾釋矣！\"又曰：\"觀李郎儀形器宇，真丈夫也！亦聞太原有異人乎？\"曰：\"嘗識一人，餘謂之真人也，其餘將相而已。\"曰：\"其人何姓？\"曰：\"某之同姓。\"\"年歲？\"曰：\"仅二十。\"曰：'今何為？\"曰：\"州將之子也。\"曰：\"李郎能致吾一見乎？\"曰：\"靖之友劉文靜者與之善，因文靜見之可也。然兄欲何為？\"曰：\"望氣者雲：'太原有奇氣。'使吾訪之。李郎何日到太原？\"曰：\"靖計之，某日當達。\"曰：\"達之明日方曙，候我於汾陽桥。\"言訖，乘驢而去。其行如飛，回顧已失矣。公與張氏且驚且懼。久之，曰：\"烈士不欺人，固無畏也。\"促鞭而行。及期，入太原，候之，相見大喜。偕詣劉氏，诈謂文靜曰：\"有善相者思見郎君，請迎之。\"文靜素奇其人，方議匡辅，一旦聞客有知人者，其心可知，遽致酒延之。使回而到，不衫不履，裼裘而來，神氣扬扬，貌與常異。虬須默然，於坐末見之，心死。飲數杯而起，招靖曰：\"真天子也！吾見之，十得八九矣。然須道兄見之。李郎宜與一妹复入京。某日午時，訪我於馬行東酒樓下，有此驢及瘦騾，即我與道兄俱在其上矣。\"又別而去之。靖與張氏及期訪焉，宛見二乘，攬衣登樓，而虬須與道士方對飲。見靖驚喜，召對環飲十數巡，曰：\"樓下匮中有錢十萬，可擇一深隱處，駐一妹，某日复會我於汾陽桥下。\"靖如期至，則道士與虬須已先到矣。仍俱詣文靜。時方奕棋，揖起而話心焉。文靜飛書迎文皇，看道士對奕，虬須與靖旁立焉。俄而文皇到來，精彩驚人。揖而坐。神氣清朗，滿坐風生，顧盼伟如也。道士一見，惨然，失棋子，曰：\"此局输矣！输矣！於此失却局，奇哉！救無路矣！复奚言！\"奕罢請去。既出，謂虬須曰：\"此世界非子世界，他方圖之可矣。勉之，勿以為念。\"因共入京。虬須曰：\"計李郎之程，某日方到。到之明日，可與一妹同詣某坊小宅相訪。欲令新婦祗謁，兼議從容，無前却也。\"言畢，吁嗟而去。靖策馬而歸。遂與張氏同往。見一小板門，扣之，有應者雲：\"三郎令候李郎、一娘子久矣。\"延入重門，門愈壮麗。奴婢四十餘人，羅列庭前。奴二十人，引靖入東廳；婢二十人，引張氏入西廳。廳之陳設，頗極精異，巾箱、妆奁、冠蓋、首飾之盛，非人間之物。巾櫛既畢，又請更衣，衣甚珍奇。既畢，傳雲：\"三郎來！\"乃虬須也。紗帽裼裘，亦有龍虎之状。歡然相見，催其妻出拜，蓋真天人也。於是四人對坐，牢饌畢陳，女樂列奏。其飲食妓樂，若自天降，非人間之物。食畢行酒，而家人自堂來舁出兩床，各以錦繡帕覆之。既呈，盡去其帕，乃文簿鑰匙耳。虬須指謂曰：\"此珍寶货泉之數，吾所有悉以充赠。向者本欲於此世界求事，或當一二十年，建少功業。今既有主，住亦何為？太原李氏，真英主也。海內即當太平。李郎以奇特之才，辅清平之主，竭忠盡行，必極人臣。一妹以天人之資，蘊不世之藝，從夫之貴，榮極軒裳。非一妹不能識李郎，亦不能存李郎；非李郎不能遇一妹，亦不能榮一妹。起陆之漸，际會如斯，虎嘯風生，龍吟雲起，固當然也。將予之赠，以佐真人，贊功業也。勉之哉！此後十餘年，東南數千里外有異事，是吾得志之秋也，妹與李郎可瀝酒相贺。\"因命家仆列拜，曰：\"李郎、一妹，是汝主也。\"言畢，與其妻戎裝，從一奴，乘馬而去。數步乃不复見。靖據其宅，遂為豪家，得以助文皇締構之資，遂匡大業。貞觀十年，靖以左仆射同平章事。東南蠻奏：有海賊以千艘，帶甲者十萬人，入扶餘國，殺其主自立，國已定。靖知虬須之得志也，歸告張氏，具禮相贺，瀝酒東南祝拜之。是知真人之興，非英雄所觊，况非英雄乎？人臣之谬思亂者，乃螗臂扼轍耳。我皇家垂福萬葉，豈虛言哉！或曰：\"衛公兵法，半乃虬須所傳。\"信哉！","sortOrder":10},
  {"id":"s_work_dnl_20_11","chapterId":"ch_work_dnl_20","text":"太宗征遼，李衛公病不能從。帝使執政等召之，不果起，帝曰：\"吾知之矣。\"明日，駕臨其第，執手與別。衛公曰：\"老臣宜從，但犬馬之疾增甚。\"帝撫其背曰：\"勉之！昔司馬仲達非不老病，竟能自強，立勋魏室。\"公叩頭曰：\"老臣請舆病行。\"至相州，疾篤而不能進。上至駐跸山，高麗與合軍四十里。太宗有懼色，江夏王進曰：\"高麗傾國以拒王師，平壤之守必弱，請假臣精卒五千，覆其本根，則數十萬之眾，可不戰而降。\"帝不應。既合戰，為敵所乘，殆將不振。還謂衛公曰：\"吾以天子之眾，困於蕞爾之夷，何也？\"靖曰：\"此道宗所解。\"時江夏王在侧，帝顧之，道宗具陳前言。帝怅然曰：\"當時遽不憶也。\"","sortOrder":11},
  {"id":"s_work_dnl_20_12","chapterId":"ch_work_dnl_20","text":"太宗謂尉遲敬德曰：\"人言卿反，何故？\"對曰：\"臣反是實。臣從陛下讨逆伐叛，惟凭威靈，幸而不死，然所存，刃鋒也。今大業已定，而反疑臣。\"乃悉解衣投於地，以見所傷之處。帝對之流涕，曰：\"卿衣矣！朕以不疑卿，故以相告，何反以為恨？\"","sortOrder":12},
  {"id":"s_work_dnl_20_13","chapterId":"ch_work_dnl_20","text":"太宗謂敬德曰：\"朕將嫁女與卿，稱意否？\"敬德笑曰：\"臣雖鄙陋，亦不失為夫婦之道。臣每聞古人雲：'富不易妻，仁也。'竊慕之，願停聖恩。\"叩頭固讓，帝嘉之而止。","sortOrder":13},
  {"id":"s_work_dnl_20_14","chapterId":"ch_work_dnl_20","text":"薛萬彻尚平陽公主。人謂太宗曰：\"薛駙馬無才氣。\"因此公主羞之，不同席者數月。帝聞之，大笑，置酒召諸婿盡往，獨與薛歡語，屢稱其美。因對握槊，睹所佩刀，帝佯為不勝，解刀以佩之。酒罢，悅甚。薛未及就馬，主遽召同載而還，重之逾於舊日。","sortOrder":14},
  {"id":"s_work_dnl_20_15","chapterId":"ch_work_dnl_20","text":"中書令馬周以布衣上書，太宗覽之，未及終，命召之。乃陳世事，莫不施行。","sortOrder":15},
  {"id":"s_work_dnl_20_16","chapterId":"ch_work_dnl_20","text":"太宗嘗以飛白書賜馬周，曰：\"鳳鸞冲霄，必假羽翼；股肱之寄，要在忠力。\"又高宗嘗為飛白，賜侍臣戴至德，曰：\"泛洪源，俟舟楫\"；郝處俊，曰：\"飛九霄，假六翮\"；李敬玄，曰：\"資啟沃，罄丹誠\"；崔知悌，曰：\"罄忠節，贊皇猷\"：其詞皆有比興。","sortOrder":16},
  {"id":"s_work_dnl_20_17","chapterId":"ch_work_dnl_20","text":"率更欧陽詢，行見古碑，晉索靖所書，駐馬觀之，良久而去。數百步复還，下馬佇立，疲倦則布裘坐觀。因宿其旁，三日而去。","sortOrder":17},
  {"id":"s_work_dnl_20_18","chapterId":"ch_work_dnl_20","text":"李太史與張文收坐，忽見暴風自南而至。李曰：\"南五里當有哭者。\"張以為音樂。左右馳馬觀之，則遇送葬者，有鼓吹焉。","sortOrder":18},
  {"id":"s_work_dnl_20_19","chapterId":"ch_work_dnl_20","text":"褚遂良貴顯，其父亮尚在，乃別开門。敕嘗有所賜遂良，使者由正門而入，亮出曰：\"渠自有門。\"","sortOrder":19},
  {"id":"s_work_dnl_20_20","chapterId":"ch_work_dnl_20","text":"太宗宴近臣，戲趙公無忌，令嘲欧陽率更，曰：\"耸膊成山字，埋肩不出頭。誰教麟閣上，畫此一猕猴？\"詢應聲曰：\"索頭連背暖，完襠畏肚寒。只由心溷溷，所以面团团。\"帝斂容曰：\"欧陽詢，汝豈不畏皇後聞耶\"趙公，後之弟。","sortOrder":20},
  {"id":"s_work_dnl_20_21","chapterId":"ch_work_dnl_20","text":"侯君集為兵部尚書，以罪流嶺南。於其家得二美人，容色絕代，太宗問其状，曰：\"自小常食人乳而不飯。\"","sortOrder":21},
  {"id":"s_work_dnl_20_22","chapterId":"ch_work_dnl_20","text":"侯君集家有金簟二，甚精妙，御府所無，隱而不獻。後君集獲罪，乃於其家得之。","sortOrder":22},
  {"id":"s_work_dnl_20_23","chapterId":"ch_work_dnl_20","text":"太宗朝，泥婆羅獻娑羅树，一名\"菩提\"。葉似紅藍，實如蒺藜。","sortOrder":23},
  {"id":"s_work_dnl_20_24","chapterId":"ch_work_dnl_20","text":"太宗病，出英公為叠州都督，謂高宗曰：\"李才智有餘，屢更大任，恐其不厭服於汝，故有此授。我死後，可親任之。若遲疑顧望，便當殺之。\"奉詔，不及家而去。","sortOrder":24},
  {"id":"s_work_dnl_20_25","chapterId":"ch_work_dnl_20","text":"唐貞觀元年，長安客有買妾者。居之數年，嘗忽不知所之。一夜，提人首而告夫曰：\"我有父冤，故至此。今報矣！\"請歸，涕泣而訣。出門如風。俄頃却至，斷所生子喉而去。","sortOrder":25},
  {"id":"s_work_dnl_20_26","chapterId":"ch_work_dnl_20","text":"袁利貞為太常博士。高宗將會百官命婦於宣政殿，併設九部樂，利貞諫曰：\"臣以前殿正寢，非命婦宴會之地；象闕路寢，非倡優進御之所。請命婦會於別殿，九部樂從東西而入。散樂一色，伏望停省。若於三殿別所，可備極恩私。\"高宗即令移於麟德殿。至會日，中書侍郎薛元超謂利貞曰：\"卿門傳忠鯁，所獻直言，不加厚賜，何以奖勸？\"賜彩百匹，遷祠部員外。","sortOrder":26},
  {"id":"s_work_dnl_20_27","chapterId":"ch_work_dnl_20","text":"高宗腦痈殆甚，待詔秦鳴鶴奏曰：\"須針百會方止。\"則天大呼曰：\"天子頭上，可是出血處？\"上曰：\"朕意欲針。\"即時眼明，雲：\"諸苦悉去，殊無妨也。\"則天走於帘下，自負銀錦等賞賜，如向未嘗怒也。","sortOrder":27},
  {"id":"s_work_dnl_20_28","chapterId":"ch_work_dnl_20","text":"高宗將下詔遜位於則天，攝知國政，召宰臣議之。郝處俊對曰：\"《禮經》雲：'天子理陽道，後理陰德。'然則帝之與後，猶日之與月，陰之與陽，各有所主，不相奪也。若失其序，上則謫見於天，下則禍成於人。昔魏文帝著令，崩後尚不許皇後臨朝，奈何遂欲自禪位天後？况天下者，高祖、太宗之天下，非陛下之天下。正合謹守宗廟，傳之子孫，不可持國與人，有私於後。惟陛下審詳。\"中書侍郎李義琰進曰：\"處俊所引經典，其言至忠，惟聖慮無疑，則蒼生幸甚。\"高宗乃止。及天後受命。處俊已殁，孫象竟被族誅。始，則天以權变多智，高宗將排群議而立之；及得志，威福併作，高宗舉動必為掣肘，高宗不勝其忿。時有道士郭行真，出入宮掖，為則天行厭勝之術，內侍王伏勝奏之。高宗大怒，密詔上官儀废之。儀因奏：\"天後专恣，海內失望，請废黜以順天心。\"高宗即令儀草詔。左右馳告則天，則天遽訴。詔草猶在，高宗恐有怨懟，待之如初，且告之曰：\"此併上官儀教我。\"則天遂誅儀及伏勝等，併賜太子忠死。自此政歸武後，天子拱手而已。","sortOrder":28},
  {"id":"s_work_dnl_20_29","chapterId":"ch_work_dnl_20","text":"阎立本，總章元年，以司平大常伯拜右相。有文學，善寫真。","sortOrder":29},
  {"id":"s_work_dnl_20_30","chapterId":"ch_work_dnl_20","text":"高宗朝，太原王，范陽盧，滎陽鄭，清河、博陵崔，隴西、趙郡李等七姓，恃有族望，恥與諸姓為婚，乃禁其自婚娶。於是不敢复行婚禮，密裝飾其女以送夫家。","sortOrder":30},
  {"id":"s_work_dnl_20_31","chapterId":"ch_work_dnl_20","text":"武後時，投匦者或不陳事，而謾以嘲戲之言，乃置使閱其書奏，然後投之匦。匦之有司，自此始也。","sortOrder":31},
  {"id":"s_work_dnl_20_32","chapterId":"ch_work_dnl_20","text":"初置匦有四門，其製稍大，難於往來。後遂小其製度，同為一匦，依方色辨之。漢時趙廣漢為潁川太守，設〈缶後〉筒，言事者投書其中，匦亦〈缶後〉筒之流也。梁武帝詔於謗木、肺石函旁各置一函，橫議者投謗木函，求達者投肺石函，即今之匦也。初，則天欲通知天下之事，有魚保宗者，頗機巧，上書請置匦，以受四方之書，則天悅而從之。徐敬業於廣陵作逆，保宗曾與敬業造刀車之屬，至是為人所發，伏誅。保宗父承，自御史中丞坐貶儀州司馬。明皇以\"匦\"字聲似\"鬼\"，改\"匦使\"為\"獻納使\"。乾元初，复其舊名。","sortOrder":32},
  {"id":"s_work_dnl_20_33","chapterId":"ch_work_dnl_20","text":"洛東龍門香山寺上方，則天時名望春宮。則天御石樓坐朝，文武百執事班於水次。","sortOrder":33},
  {"id":"s_work_dnl_20_34","chapterId":"ch_work_dnl_20","text":"國有大赦，則命衛尉树金雞於闕下，武库令掌其事。金雞為首，建之於高ㄅ之上，宣赦畢，則除之。凡建金雞，則先置鼓於宮城門之左。视大理及府縣囚徒至，則挝其鼓。案：金雞，魏晉以前無聞焉。或雲始自後魏，亦雲起自呂光。《隋·百官志》雲：\"北齊，尚書省有三公曹，赦日建金雞。\"蓋自隋朝废此官而為衛尉所掌。北齊每有赦宥，則於閶阖門前树金雞柱，下取少土，雲佩之利官，數日間遂成坑，所司亦不禁約。武成帝即位，其後河間王孝琬為尚書令。先時有謠言：\"河南种穀河北生，白楊树頭金雞鳴。\"祖孝徵與和士开谮孝琬曰：\"河南、河北，河間也；金雞，言孝琬為天子，建金雞也。\"齊主信之而殺孝琬。則天封嵩嶽，大赦，改元萬歲。登封壇南有大树，树杪置金雞，因名树為\"金雞树\"。","sortOrder":34},
  {"id":"s_work_dnl_20_35","chapterId":"ch_work_dnl_20","text":"宋劾張昌宗等反状，武後不應。李邕立階下，大言曰：\"所陳社稷大事，陛下當聽。\"後色解，即可奏。邕出，或讓曰：\"子位卑，一怍旨，禍不测。\"邕曰：\"不如是，名亦不傳。\"","sortOrder":35},
  {"id":"s_work_dnl_20_36","chapterId":"ch_work_dnl_20","text":"蘇安恒博學，尤明《周禮》、《左氏》。長安二年，上疏請复子明辟，奏疏不納。魏元忠為張易之所構，安恒又申理之。易之大怒，將殺之，賴朱敬則、桓彦范等保護，獲免。後坐節悯太子事，下獄死。睿宗即位，下詔曰：\"蘇安恒文學立身，鯁直成操，往年陳疏，忠谠可嘉。屬回邪擅權，奄從非命，興言軫悼，用惻予懷。可赠諫議大夫。\"","sortOrder":36},
  {"id":"s_work_dnl_20_37","chapterId":"ch_work_dnl_20","text":"近代言樂，衛道弼為最，天下莫能以聲欺者。曹紹夔與道弼為樂令，比監郊享，御史有怒於紹夔，欲以樂不和為之罪。雜叩鐘磐，使暗別之，無誤者，由是反叹服其能。洛陽有僧，房中磬子夜辄自鳴，僧以為怪，懼而成疾，求術士百方禁之，終不能已。曹紹夔素與僧善，適來問疾，僧遽以告。俄頃，輕击斋鐘，磬复作聲。紹夔笑曰：\"明日盛設饌，餘當為除之。\"僧雖不信其言，冀其或效，乃置饌以待。紹夔食訖，出懷中错，钅慮磬數處，其聲遂絕。僧苦問其所以，紹夔曰：\"此磬與鐘律合，故击彼應此。\"僧大喜，其疾便愈。","sortOrder":37},
  {"id":"s_work_dnl_20_38","chapterId":"ch_work_dnl_20","text":"裴知古，自中宗、武後朝以知音律直太常。路逢乘馬，聞其聲，竊曰：\"此人即當墜馬。\"好事者隨而觀之，行未半坊，馬忽驚墜，殆死。又嘗觀人迎婦，聞婦佩玉聲，曰：\"此婦不利姑。\"是日有疾，竟亡。其知音，皆此類也。又善攝衛，开元十三年終，且百歲。","sortOrder":38},
  {"id":"s_work_dnl_20_39","chapterId":"ch_work_dnl_20","text":"曹懷舜，金乡人。父繼叔，死王事。懷舜授遊击將軍，歷內外兩官。則天嘗雲：\"懷舜久歷清資，屈武職。\"後轉右玉鈐衛將軍。","sortOrder":39},
  {"id":"s_work_dnl_20_40","chapterId":"ch_work_dnl_20","text":"則天時，郎吏王上客自恃才藝，意在前行外郎，後除水部員外，頗懷憤惋。同列張敬忠以詩戲曰：\"有意嫌工部，专心觅考功。誰知腳蹭蹬，幾落省牆東。\"","sortOrder":40},
  {"id":"s_work_dnl_20_41","chapterId":"ch_work_dnl_20","text":"議者戲雲：\"畿尉有六道：入御史為佛道，入評事為仙道，入京尉為人道，入畿丞為苦海道，入縣令為畜生道，入判司為饿鬼道。\"","sortOrder":41},
  {"id":"s_work_dnl_20_42","chapterId":"ch_work_dnl_20","text":"左史東方虬，每雲：\"二百年後，乞爾西門豹作對。\"","sortOrder":42},
  {"id":"s_work_dnl_20_43","chapterId":"ch_work_dnl_20","text":"蘇味道詞亚於李峤，時稱蘇、李。崔融嘗戲蘇曰：\"我詞不如公有'銀花合'也。\"蘇即答：\"猶不及公'金銅釘'。\"謂\"今同丁令威\"也。","sortOrder":43},
  {"id":"s_work_dnl_20_44","chapterId":"ch_work_dnl_20","text":"劉希夷詩曰：\"年年歲歲花相似，歲歲年年人不同。\"其舅即宋之問也，苦愛此兩句，知其未示人，恳乞此兩句，許而不與。之問怒，以土囊壓殺之。劉禹錫曰：\"宋生不得死，天報之矣！\"","sortOrder":44},
  {"id":"s_work_dnl_20_45","chapterId":"ch_work_dnl_20","text":"張文之為大理，獲罪者皆曰：\"為張卿所罰，不枉也。\"","sortOrder":45},
  {"id":"s_work_dnl_20_46","chapterId":"ch_work_dnl_20","text":"張柬之等既遷則天於上陽宮，中宗猶以皇太子監國，告武氏之廟。時，累日陰翳，侍御史崔浑奏曰：\"方今國命初复，當正徽號稱唐，順萬姓之心，奈何告武氏廟？廟宜毀之，复唐鸿業，天下幸甚！\"中宗深納之。製命既行，陰雲四霁，萬里澄廓，鹹謂天人之應。","sortOrder":46},
  {"id":"s_work_dnl_20_47","chapterId":"ch_work_dnl_20","text":"中宗時，兵部尚書韦嗣立，新入三品。侍郎趙彦昭，假金紫。吏部侍郎崔，复舊官。上命燒尾，令於興慶池設食。至時，敕衛尉陳設，尚書省諸司各具彩舟遊勝。飛樓結艦，光奪霞日。上與侍臣親臨焉。既而吏部船為仗所隔，兵部船先至，嗣立奉觴獻寿。上問：\"吏部船何在？\"崔步自北岸呼之，遇戶部双舸，上結重樓，兼聲樂一部，即呼至岸，以紙書作\"吏部\"字貼牌上，引至御前。上大悅，以為兵部不逮也。俄有風吹所帖之紙，為嗣立所見，遽奏雲：\"非吏部船。\"上令取牌，探紙見\"戶\"字，大笑。嗣立請科罪，上不許，但罰酒而已。","sortOrder":47},
  {"id":"s_work_dnl_20_48","chapterId":"ch_work_dnl_20","text":"薛令之，閩之長溪人。神龍二年，趙彦昭下進士及第，後為左補闕兼太子侍講。時東宮官冷落，之次難進，令之有詩曰：\"明月夜团团，照見先生盤。盤中何所有？苜蓿長阑幹。飯涩匙難綰，羹稀箸易宽。只可謀朝夕，那能度歲寒？\"明皇幸東宮，見之不悅，以為諷上。援筆酬曰：\"啄木觜距長，鳳凰毛羽短；若嫌松桂寒，任逐桑榆暖。\"令之遂謝病歸。及肅宗即位，召之。詔下，而令之已卒。","sortOrder":48},
  {"id":"s_work_dnl_20_49","chapterId":"ch_work_dnl_20","text":"景龍初，有韓令起自細微，好以行第呼朝士。尋坐罪，為薑武略所按，以枷錮之。乃謂：\"薑五公名流，何故遽行此？\"薑武略應雲：\"且抵承曹大，無煩唤薑五。\"","sortOrder":49},
  {"id":"s_work_dnl_20_50","chapterId":"ch_work_dnl_20","text":"兵部尚書韦嗣立，景龍中中宗與韦後幸其莊，封嗣立為\"逍遙公\"，又改其所居\"鳳凰原\"為\"清虛原\"，\"鸚鵡穀\"為\"幽栖穀\"。","sortOrder":50},
  {"id":"s_work_dnl_20_51","chapterId":"ch_work_dnl_20","text":"中宗崩，既除丧，吐蕃來弔。或曰：\"若擇宗室最長者，素服受禮於彼，其可乎？\"舉朝稱善而從之。","sortOrder":51},
  {"id":"s_work_dnl_20_52","chapterId":"ch_work_dnl_20","text":"徐彦伯常侍，睿宗朝以相府之舊，拜羽林將軍。徐既文士，不悅武職，及遷，謂贺者曰：\"不喜有遷，且喜出軍。\"","sortOrder":52},
  {"id":"s_work_dnl_20_53","chapterId":"ch_work_dnl_20","text":"和元為貞化府長史。景龍末，元獻詩十首，其詞猥陋，皆寓言嬖幸，而意及兵戍。韦氏命鞫於大理，而將戮之，月餘而韦氏伏誅。其詩言若符讖。景雲初，以元為千牛衛長史。","sortOrder":53},
  {"id":"s_work_dnl_20_54","chapterId":"ch_work_dnl_20","text":"韦铿初在憲司，邵炅、萧嵩同升殿。神武皇帝即位，及詔出，炅、嵩俱加朝散，獨铿不及。炅鼻高，嵩須多，併類鮮卑。铿嘲之雲：\"一双獠子著緋袍，一个須多一鼻高。相對衙前捺且立，自言身品世間毛。\"铿白肥而短，他日忽於承天門風眩踣地，炅詠曰：\"飄風忽起团团回，倒地還如腳被錘。莫怪殿上空行事，直為元非五品才。\"","sortOrder":54},
  {"id":"s_work_dnl_20_55","chapterId":"ch_work_dnl_20","text":"郗昂性捷直，源乾曜嘗戲之曰：\"謝安雲'郗生可謂入幕之賓矣'，豈非遠祖否？\"郗曰：\"猶勝以氏為禿發。若不遇後魏道武，稱曰同源，賜之源氏，豈可列《姓苑》乎？\"源遂屈。後與杜黃裳同學於嵩陽，二人同中第。郗以安祿山伪官貶歙縣尉，黃裳入相後，除中書舍人。","sortOrder":55},
  {"id":"s_work_dnl_20_56","chapterId":"ch_work_dnl_20","text":"源乾曜因奏事稱旨，上悅之，骤拔用，歷戶部侍郎、京兆尹，以至宰相。暇日，上獨與力士語曰：\"汝知吾拔用乾曜之速乎？\"曰：\"不知也。\"上曰：\"吾以其言語容貌類萧至忠，故用之。\"力士對曰：\"至忠豈不嘗負陛下，何念之深？\"上曰：\"至忠晚乃谬耳。其初立朝，得不為賢相乎？\"上之愛才宥過，聞之者莫不感悅。","sortOrder":56},
  {"id":"s_work_dnl_20_57","chapterId":"ch_work_dnl_20","text":"魏知古，性方直。景雲末，為侍中。明皇初即位，獵於渭川，時知古從駕，因獻詩以諷。手詔褒美，賜物五十段，後兼知吏部尚書，典選事，深為稱職。所荐用人，鹹至大官。","sortOrder":57},
  {"id":"s_work_dnl_20_58","chapterId":"ch_work_dnl_20","text":"倪若水為汴州刺史，明皇嘗遣中官往淮南采捕及諸水禽。上疏諫。手詔答曰：\"朕先使人取少雜鳥，其使不識朕意，將鳥稍多，卿具奏之，詞誠忠恳，深稱朕意。卿達識周材，義方敬直，故輟綱轄之重，委方面之權。果能閒邪存誠，守節弥固，骨鯁忠烈，遇事無隱。言念忠谠，深用喜慰。今賜物四十段，用答至言。\"","sortOrder":58},
  {"id":"s_work_dnl_20_59","chapterId":"ch_work_dnl_20","text":"汝南王，寧王長子也。姿容妍美，明皇鐘愛，授之音律，能達其旨。每隨遊幸，常戴砑絹帽打曲，上摘紅槿花一朵，置於帽上笪處，二物皆極滑，久之方安。遂奏《舞山香》一曲，而花不墜。樂家雲：\"定頭項難在不動搖。\"上大喜，賜金器一厨，因曰：\"花奴（原註：小字）資质明媚，肌發光細，非人間人。\"寧王謙謝，隨而短斥之。上笑曰：\"大哥過慮，阿瞞自是相師（原註：上於諸親，嘗親稱此號）。夫帝王之相，且須有英特越逸之氣，不然須有深沉包育之度。若花奴，但英秀過人，悉無此状，故無猜也。而又舉止淹雅，當更得公卿間令譽耳！\"寧王又笑曰：\"若如此，臣乃输之。\"上曰：\"若此一條，阿瞞亦输大哥矣。\"寧王又謝。上笑曰：\"阿瞞贏處多，大哥亦不用挹。\"眾皆歡贺。","sortOrder":59},
  {"id":"s_work_dnl_20_60","chapterId":"ch_work_dnl_20","text":"开元二十七年八月，詔策夫子為文宣王，改修殿宇。封夫子後為文宣公，仍長任本州長史，代不絕。先時廟，夫子在西牖之下；武德初，併祀周公。周公南面，故夫子配坐西方。貞觀中，废祀周公，而夫子西位不改。至是移就兩楹南面正位，十哲東西侍立。又封顏子為兖公，闵子為費侯，伯牛為鄆侯，仲弓為薛侯，冉有為徐侯，子路為衛侯，宰我為齊侯，子貢為黎侯，子遊為吳侯，子夏為魏侯，曾參以下併為伯。其兩京文宣廟，春秋二仲釋奠，軒懸之樂，八佾之舞，牲以太牢；州縣以少牢而無樂。","sortOrder":60},
  {"id":"s_work_dnl_20_61","chapterId":"ch_work_dnl_20","text":"學舊六馆：有國子馆、太學馆、四門馆、書馆、律馆、算馆，國子監都領之。每馆各有博士、助教，謂之學官。國子監有祭酒、司業、丞、簿，謂之監官。太學諸生三千員，新羅、日本諸國，皆遣子入朝受業。天寶中，國學增置廣文馆，在國學西北隅，與安上門相對。廊宇粗建。會十三年，秋霖一百餘日，多有倒塌。主司稍稍毀撒，將充他用，而廣文寄在國子馆中。尋屬邊戈內扰，馆宇至今不立。","sortOrder":61},
  {"id":"s_work_dnl_20_62","chapterId":"ch_work_dnl_20","text":"玄宗時，羽林將劉洪善騎射。嘗對御，使人於風中掷鹅毛，洪連箭射之，無有不中。","sortOrder":62},
  {"id":"s_work_dnl_20_63","chapterId":"ch_work_dnl_20","text":"蘇味道初拜相，門人問曰：\"方事之殷，相公何以燮和？\"味道但以手摸床稜而已。時謂\"摸床稜宰相\"。","sortOrder":63},
  {"id":"s_work_dnl_20_64","chapterId":"ch_work_dnl_20","text":"玄宗在東都，宮中有怪。明日召宰相，欲西幸。裴稷山、張曲江諫曰：\"百姓場圃未畢，請待冬仲。\"是時李林甫初為相，竊知上意，及旅退，佯為蹇步，上問\"何故腳疾\"？對曰：\"非疾，願獨奏事。\"乃言：\"二京，陛下東、西宮也。將欲駕幸，焉用選時？假使有妨刈獲，獨可蠲免沿路租稅。臣請宣示有司，即日西幸。\"上大悅。自此車駕至長安，不复東。旬日，耀卿、九齡俱罢，而牛仙客進。","sortOrder":64},
  {"id":"s_work_dnl_20_65","chapterId":"ch_work_dnl_20","text":"自古帝王五運之次，凡有二說：邹衍則以五行相勝為義，劉向則以五行相生為義。漢、魏共遵劉說。唐承隋代火運，故為土德，衣服尚黃，旗幟尚赤，常服赭赤也。赭，黃色之多赤者，或謂之柘木，其義無取。高宗時，王勃著《大唐千年歷》：\"國家土運，當承漢氏火德；上自曹魏，下至隋室，南北兩朝，鹹非一統，不得承五運之次。\"勃言迂闊，未為當時所許。天寶中，上書言事者，多為诡異，以冀進用。有崔昌，采勃舊說，遂以上聞，玄宗納焉。下詔以唐承漢，自隋以前歷代帝王皆屏黜，更以周、漢為二王後。是歲禮部试《土德惟新賦》，即其事也。及楊國忠秉政，自以為隋氏之宗，乃追貶崔昌併當時議者，而复阝、介二公焉。","sortOrder":65},
  {"id":"s_work_dnl_20_66","chapterId":"ch_work_dnl_20","text":"扶風太守房，申當郡苗損，國忠怒以他事推之。自是天下有事，皆潛申國忠，以取可否。","sortOrder":66},
  {"id":"s_work_dnl_20_67","chapterId":"ch_work_dnl_20","text":"楊國忠嘗會親，知吏部铨事，且欲噱以娱之。呼選人名，引入於中庭，不問資序：短小者道州參軍，胡者與湖州文學。帘中大笑。","sortOrder":67},
  {"id":"s_work_dnl_20_68","chapterId":"ch_work_dnl_20","text":"玄宗好神仙，往往詔郡國征奇異之士。有張果者，則天時聞其名，不能致，上亟召之，乃與使俱來。其所為，变怪不测。有邢和璞者，善算術；视人投算，而究其善、惡、夭、寿。上使算果，懵然莫知其甲子。又有師夜光者，善视鬼。後召果與坐，密令夜光视之，夜光奏曰：\"果今安在？臣願見之。\"而果坐於上前久矣，夜光終莫能見。上謂力士曰：\"吾聞奇士至人，外物不足以败其中。试飲以堇汁，無苦者，真奇士也。\"會天寒方甚，便以汁進果，果遂引飲三卮，醺然如醉，顧侍者曰：\"非佳酒也。\"乃寢。頃之，引鏡视其齒，盡焦且黧。命左右取鐵如意，击齒盡墮，藏之於帶。乃於懷中出神膏，色微紅，傅諸墮齒空中，复寢。久之，视鏡，齒皆生，粲然絜白。上方信其不誣也。","sortOrder":68},
  {"id":"s_work_dnl_20_69","chapterId":"ch_work_dnl_20","text":"玄宗時，亢旱，禁中筑龍堂祈雨。命少監冯紹正畫西方，未畢，如覺雲氣生梁棟間，俄而大雨。","sortOrder":69},
  {"id":"s_work_dnl_20_70","chapterId":"ch_work_dnl_20","text":"羅公遠多秘異之術，最善隱形。玄宗樂隱形之術，就公遠勤求而學。公遠雖傳，不盡其妙。上海與公遠同為之，則隱没，人莫能测；若自為之，則或遺衣帶，或露頭巾腳，宮人每知上之所在也。百萬錫赉，或臨之以死，公遠終不盡傳其術。上怒，命力士裹以油幞，置於榨下壓殺而埋弃之。不經旬，有中官從蜀使回，逢公遠乘騾於路，笑而謂曰：\"上之為戲，一何虐耶！\"","sortOrder":70},
  {"id":"s_work_dnl_20_71","chapterId":"ch_work_dnl_20","text":"明皇幸東都。秋宵，與一行師登天宮寺閣，臨眺久之。上四顧凄然，叹息，謂一行曰：\"吾甲子得終無患乎？\"一行曰：\"陛下行幸萬里，聖祚無疆。\"及西巡至成都，前望大桥，上乃舉鞭問左右曰：\"是何桥也？\"節度使崔圓躍馬進曰：\"萬里桥。\"上叹曰：\"一行之言今果符合，吾無忧矣。\"","sortOrder":71},
  {"id":"s_work_dnl_20_72","chapterId":"ch_work_dnl_20","text":"或曰：一行，开元中嘗奏上雲：\"陛下行幸萬里，聖祚無疆。\"故天寶中幸東都，庶盈萬數。及上幸蜀，至萬里桥，方悟焉。","sortOrder":72},
  {"id":"s_work_dnl_20_73","chapterId":"ch_work_dnl_20","text":"一行和尚滅度，留一物封識，命弟子進於上。發而视之，乃\"蜀當歸\"也。上不諭其意。及幸蜀間，乃知其深意，方叹異之。","sortOrder":73},
  {"id":"s_work_dnl_20_74","chapterId":"ch_work_dnl_20","text":"玄宗嘗幸東都，天大旱，且暑。時聖善寺有竺乾僧無畏，號曰三藏，善召龍致雨之術。上遺力士疾召無畏請雨，無畏奏曰：\"今旱，數當然爾。召龍興烈風雷雨，適足暴物，不可為也。\"上使強之，曰：\"人苦暑久矣！雖暴風疾雷，亦足快意。\"無畏辭不獲已，遂奉詔。有司為陳請雨具，而幡幢像設甚備。無畏笑曰：\"斯不足以致雨。\"悉令撤之。獨盛一鉢水，無畏以小刀於水鉢中搅旋之，胡言數百咒水。須臾之間，有龍，其状如指，赤色，首瞰水上。俄頃，没於水鉢中。無畏复以刀搅水，咒者三。有頃，白氣自鉢中興，如爐煙，径上數尺，稍引去講堂外。無畏謂力士曰：\"亟去，雨至矣！\"力士馳馬，去而四顧，見白氣疾旋，自講堂而西，若尺素騰上。既而昏霾，大風震雷，暴雨如泻。力士馳及天津之南，風雨亦隨馬而至矣。街中大树多拔。力士复奏，衣盡沾濕。孟溫禮為河南尹，目見其事。溫禮子嘗言於李栖筠，與力士同在先朝，吏部員外郎李華撰《無畏碑》，亦雲前後奉詔，禳旱致雨，滅火回風，昭昭然遍諸耳目也。","sortOrder":74},
  {"id":"s_work_dnl_20_75","chapterId":"ch_work_dnl_20","text":"玄宗紫宸殿櫻桃熟，命百官口摘之。","sortOrder":75},
  {"id":"s_work_dnl_20_76","chapterId":"ch_work_dnl_20","text":"玄宗命射生官射鮮鹿，取血煎鹿腸食之，賜安祿山、哥舒翰。","sortOrder":76},
  {"id":"s_work_dnl_20_77","chapterId":"ch_work_dnl_20","text":"虢國夫人就屋梁懸鹿腸，其中結之。有宴則解开，於梁上註酒，號\"洞天聖酒\"。","sortOrder":77},
  {"id":"s_work_dnl_20_78","chapterId":"ch_work_dnl_20","text":"玄宗時，以林邑國進白鸚鵡，慧利之性特異常者，因暇日以金籠飾之，示於三相。上再三美之。時蘇初入相，每以忠谠厲己，因前進曰：\"《記》雲：'鸚鵡能言，不離飛鳥。'臣願陛下深以為志。\"","sortOrder":78},
  {"id":"s_work_dnl_20_79","chapterId":"ch_work_dnl_20","text":"申王有高麗赤鷹，每獵，必置之駕前，目之為\"抉雲兒\"。","sortOrder":79},
  {"id":"s_work_dnl_20_80","chapterId":"ch_work_dnl_20","text":"玄宗嘗三殿打球，榮王墮馬悶絕。黃幡綽奏曰：\"大家年幾不為小，聖體又重，傥馬力既極，以至顛踬，天下何望！何不看女婿等與諸色人為之？如人對食盤，口眼俱飽，此為樂耳。傍觀大家馳逐忙遽，何暇知樂？\"上曰：\"爾言大有理，後當不复自為也。\"","sortOrder":80},
  {"id":"s_work_dnl_20_81","chapterId":"ch_work_dnl_20","text":"玄宗問黃幡綽：\"是物兒得人怜？\"\"是物兒\"者，猶\"何人兒\"也。對曰：\"自家兒得人怜。\"時楊妃號安祿山為子，肅宗在東宮，常危懼。上亻免首久之。上又嘗登北樓望渭，見一醉人臨水臥，問左右是何人。左右不對。幡綽曰：\"是年滿令史。\"又問曰：\"爾何以知之？\"對曰：\"更一轉，入流。\"上大笑。上又與諸王會食，寧王喷飯，直及上前。上曰：\"寧哥何故错喉？\"幡綽曰：\"此非错喉，是喷帝。\"","sortOrder":81},
  {"id":"s_work_dnl_20_82","chapterId":"ch_work_dnl_20","text":"或曰：鄭滁州臚於曲江見令史醉臥池岸，雲：\"更一轉，入流。\"","sortOrder":82},
  {"id":"s_work_dnl_20_83","chapterId":"ch_work_dnl_20","text":"又开元中，上與內臣作《歷日令》。高力士挟大，置黃幡綽口中，曰：\"塞穴吉！\"幡綽遽取上前叵羅內靴中，走下，曰：\"內财吉。\"上歡甚，即賜之。","sortOrder":83},
  {"id":"s_work_dnl_20_84","chapterId":"ch_work_dnl_20","text":"上好击球。內廄所養馬，猶未甚適，與幡綽語曰：\"吾欲良馬久矣，誰能通《馬經》者？\"幡綽奏：\"臣能知之，今丞相悉善《馬經》。\"上曰：\"吾與丞相言，政事外，悉究其旁學，不聞有通《馬經》者。爾焉知之？\"幡綽曰：\"臣每日沙堤上見丞相所乘，皆良馬。是必能通知。\"上大笑。","sortOrder":84},
  {"id":"s_work_dnl_20_85","chapterId":"ch_work_dnl_20","text":"又黃幡綽滑稽不窮，嘗為戲，上悅，假以緋衣。忽一日，佩一兔尾，上怪問，答曰：\"賜緋毛魚袋。\"上謂曰：\"魚袋本朝官入僩合符方佩之，不為汝惜。\"竟不賜。","sortOrder":85},
  {"id":"s_work_dnl_20_86","chapterId":"ch_work_dnl_20","text":"打球，古之蹴鞠也。《漢書·藝文志》\"《蹴鞠》二十五篇\"，顏註雲：\"鞠，以韦為之，實之以物，蹴蹋為戲。鞠，陳力之事，故附於兵法。蹴音千六切。鞠音距六切，近俗聲訛，謂鞠為球，字亦從而变焉，非古也。\"开元天寶中，上數御觀打球為事，能者左萦右拂，盤旋宛轉，殊有可觀，然馬或奔逸，時致傷毙。永泰中，蘇門山人劉鋼於鄴下上書於刑部尚書薛公雲：\"打球一則損人，二則損馬。為樂之方甚眾，何乘茲至危，以邀晷刻之歡耶？\"薛公悅其言，圖鋼之形，置於左右，命掌記陆長源為贊以美之。然打球乃軍州常戲，雖不能废，時复為之耳。今樂人又有蹋球之戲，作彩畫木球，高一二尺，女妓登躡，球轉而行，萦回去來，無不如意，蓋古蹋鞠之遺事也。","sortOrder":86},
  {"id":"s_work_dnl_20_87","chapterId":"ch_work_dnl_20","text":"拔河，古謂之牵鉤。襄漢風俗，常以正月望日為之。相傳楚將伐吳，以為教戰。梁簡文臨雍部，禁之而不能絕。古用篾纜，今代以大麻ㄌ，長四五十丈，兩頭分系小索數百條，掛於胸前，分兩朋，兩向齊挽。當大ㄌ之中，立大旗為界，震聲叫噪，使相牵引，以却者為勝，就者為输。名曰\"拔河\"。中宗曾以清明日御梨園球場，命侍臣為拔河之戲。時七宰相、二駙馬為東朋，三宰相、五將軍為西朋。東朋貴人多，西朋奏\"勝不平\"，請重定，不為改。西朋竟输。韦巨源、唐休年老，隨ㄌ而踣，久不能興。上大笑，令左右扶起。明皇數御樓設此戲，挽者至千餘人，喧呼動地，蕃客庶士，觀者莫不震駭。進士河東薛勝為《拔河賦》，其詞甚美，時人競傳之。","sortOrder":87},
  {"id":"s_work_dnl_20_88","chapterId":"ch_work_dnl_20","text":"明皇开元二十四年八月五日，御樓設繩技。技者先引長繩，兩端屬地，埋鹿盧以系之。鹿盧內數丈，立柱以起，繩之直如絃。然後技女自繩端躡足而上，往來倏忽，望若飛仙。有中路相遇，侧身而過者；有著履而行，從容俯仰者；或以畫竿接胫，高六尺；或蹋肩蹋顶，至三四重；既而翻身直倒至繩，還往曾無蹉趺，皆應嚴鼓之節，真可觀也。衛士胡嘉隱作《繩技賦》獻之，詞甚宏畅，上覽之大悅，擢拜金吾衛仓曹參軍。自兵寇覆荡，伶官分散，外方始有此技。軍州宴會，時或為之。","sortOrder":88},
  {"id":"s_work_dnl_20_89","chapterId":"ch_work_dnl_20","text":"明皇在禁中，欲與姚元之論事。時七月十五日，苦雨不止，泥濘盈尺，上令左右以步輦召之。","sortOrder":89},
  {"id":"s_work_dnl_20_90","chapterId":"ch_work_dnl_20","text":"宋开府雖耿介不群，亦知音樂，尤善羯鼓（原註：鼓樂部行丐亂雲：\"南山起雲、北山起雨\"者，是宋开府所為）。嘗與明皇論羯鼓事曰：\"不是青州石末，即須魯山花瓷、捻小碧上，掌下須有朋（原註：去聲）肯（原註：去聲）聲。\"據此，乃漢震第二鼓也。且顙用石末、花磁。固是腰鼓，掌下朋肯聲，是以手拍鼓，非羯鼓明矣（原註：第二鼓左以杖，右以指）。开府又曰：\"頭如青山峰，手如白雨點。\"此即羯鼓之能事。山峰取不動，雨點取碎急。上與开府兼善兩鼓，而羯鼓偏好，以其比漢震稍雅細焉。开府之家悉傳之。東都留守鄭叔則祖母，即开府之女。今尊賢里鄭氏第，有小樓，即宋夫人習鼓之所也。开府孫沈亦知音。貞元中，集《樂錄》三卷，德宗覽而善焉。又知是开府之孫，遂召對賜坐，與論音樂。又召至宣徽，張樂使觀焉，曰：\"設有舛乖，悉可言之。\"氵允沈吟曰：\"容臣與樂官商摧條奏。\"上使宣徽使就教坊與樂官參議數日，二使奏上：\"樂工多言沈曾不留意，不解聲調，不審節拍，兼有聩病，不可議樂。\"上頗異之。久之召對，且曰：\"臣年老多病，耳實失聽，若迨於聲律，不致無業。\"上又使作樂曲，問其得失，承禀舒遲，眾工多笑之。氵允顧笑者，忽忿怒作色，奏曰：\"曲雖妙，其間有不可者。\"上驚問之，即指一琵琶雲：\"此人大逆戕忍，當即去，不宜在至尊前。\"又指一笙雲：\"此人神魂已遊墟墓，不可更留供奉。\"上大駭，令主司潛伺察之。既而琵琶工為人訴，稱六七年前其母自縊，不得端由；即令按鞫，遂伏罪。其笙者乃忧恐不食，旬日而卒。上益加知遇，面賜章綬，累召對。每令氵允察樂，樂工悉惴恐，不敢正视。氵允懼罹禍，辭病而退。","sortOrder":90},
  {"id":"s_work_dnl_20_91","chapterId":"ch_work_dnl_20","text":"李龟年、彭年、鶴年弟兄三人，开元中皆有才學盛名。鶴年能歌詞，尤妙製《渭州》。彭年善舞。龟年善打羯鼓。明皇問：\"卿打多少杖？\"對曰：\"臣打五千杖訖。\"上曰：\"汝殊未，我打却三竖櫃也。\"後數年，又聞打一竖櫃，因賜一拂枝杖羯鼓卷。後留傳至建中三年，任使君又傳一弟子，使君令取江陵漆盤底泻水卷中，竟不散，以其至平故也。又雲：\"人聞鼓卷只在調竖慢。此卷一調之後，經月如初，今不如也。\"","sortOrder":91},
  {"id":"s_work_dnl_20_92","chapterId":"ch_work_dnl_20","text":"天寶中，樂章多以邊地為名，若《涼州》、《甘州》、《伊州》之類是焉。其曲遍繁聲為\"破\"，後其地盡為西蕃所没；破，其兆矣。","sortOrder":92},
  {"id":"s_work_dnl_20_93","chapterId":"ch_work_dnl_20","text":"上愛幸安祿山，呼之為兒，常於便殿與楊妃同樂之。祿山每就坐，不拜上而拜楊妃，上顧而問之：\"不拜我而拜妃子，何也？\"祿山奏雲：\"外國人不知有父，只知有母。\"上笑而赦之。祿山丰肥大腹，上嘗問：\"此腹中何物而大？\"祿山尋聲而對：\"腹中但無他物，唯赤心而已。\"上以其真而益親之。","sortOrder":93},
  {"id":"s_work_dnl_20_94","chapterId":"ch_work_dnl_20","text":"張巡將雷萬春於城上與巡語次，被賊伏弩射之，中萬春面，不動。令狐潮疑是木人，諜問之，知是萬春，乃言曰：\"向見雷萬春，方知足下軍令矣。然其如天理何！\"巡與潮書曰：\"仆誠下材，亦天下一男子耳。今遇明君聖主，畴則屈腰；逢豺狼犬羊，今須展志\"雲雲，\"請足下多服續命之散，數加益智之丸，無令病入膏盲，坐親斧也。\"","sortOrder":94},
  {"id":"s_work_dnl_20_95","chapterId":"ch_work_dnl_20","text":"張巡之守睢陽，玄宗已幸蜀，賊氛方炽，孤城势蹙，人困食竭，以紙布煮而食之，時以茶汁和之，而意自如。其《謝金吾將軍表》曰：\"想峨眉之碧峰，豫遊西蜀；追绿耳於懸圃，保寿南山。逆賊祿山，戮辱黎獻，膻臊闕庭。臣被围四十七日，凡一千二百餘陣。主辱臣死，當臣致命之時；惡稔罪盈，是賊滅亡之日。\"忠勇如此。激励將士，嘗賦詩曰：\"接戰春來苦，孤城日漸危。合围侔月晕，分守效魚麗。屢厭黃尘起，時將白羽揮。裹瘡猶出戰，飲血更登陴。忠信應難敵，堅貞谅不移。無人報天子，心計欲何施？\"又《聞笛》詩曰：\"试一臨，虜騎附城陰。不辨風尘色，安知天地心？營开星月近，戰苦陣雲深。旦夕更樓上，遙聞橫笛吟。\"時雍邱令令狐潮以書勸誘，不納。其書有曰：\"宋七崑季，衛九諸子，昔斷金成契，今乃刎頸相圖\"雲雲。時劉禹錫具知宋、衛，耳剽所得，濡毫有遺，所冀多聞補其闕也。又說：許遠亦有文，其《祭纛文》，為時所稱，所謂：\"太一先鋒，蚩尤後殿。蒼龍持弓，白虎捧箭。\"又《祭城隍文》雲：\"眢井鳩翔，危堞龍護。\"皆文武雄健，士氣不衰，真忠烈之士也。劉禹錫曰：\"此二公，天贊其心，俾之守死善道。向若救至身存，不過是一張仆射耳，則張巡、許遠之名，焉得以光扬於萬古哉？\"巡性明達，不以簿書介意；為真源宰，縣有豪華南金，悉委之。故時人語曰：\"南金口，明府手。\"及巡聞之，不以為事。","sortOrder":95},
  {"id":"s_work_dnl_20_96","chapterId":"ch_work_dnl_20","text":"吳道子訪僧，不見禮，遂於壁上畫一驢。其僧房器用無不踏踐。僧知道子所為，謝之，乃涂去。","sortOrder":96},
  {"id":"s_work_dnl_20_97","chapterId":"ch_work_dnl_20","text":"王維畫品妙絕，工水墨平遠，昭國坊庾敬休所居室壁有之。人有畫《樂圖》，維熟视而笑，或問其故，維曰：\"此是《霓裳羽衣曲》第三叠第一拍。\"好事者集樂工验之，一無差舛。","sortOrder":97},
  {"id":"s_work_dnl_20_98","chapterId":"ch_work_dnl_20","text":"王維為大樂丞，被人嗾令舞《黃獅子》，坐是出官。《黃獅子》者，非天子不舞也，後辈慎之。","sortOrder":98},
  {"id":"s_work_dnl_20_99","chapterId":"ch_work_dnl_20","text":"或有人報王維雲：\"公除右丞。\"王曰：\"吾畏此官，屢被人呼'不解作詩王右丞'。\"","sortOrder":99},
  {"id":"s_work_dnl_20_100","chapterId":"ch_work_dnl_20","text":"王縉多與人作碑志。有送润筆者，誤致王右丞院。右丞曰：\"大作家在那邊！\"","sortOrder":100},
  {"id":"s_work_dnl_20_101","chapterId":"ch_work_dnl_20","text":"天寶中，天下無事。選六宮風流艳態者，名\"花鳥使\"，主飲宴。","sortOrder":101},
  {"id":"s_work_dnl_20_102","chapterId":"ch_work_dnl_20","text":"杭州房為鹽官令，於縣內凿池構亭，曰\"房公亭\"，後废。（案：《唐·房傳》：，河南人，亦未為鹽官令，此疑有誤）","sortOrder":102},
  {"id":"s_work_dnl_20_103","chapterId":"ch_work_dnl_20","text":"驪山華清宮，天寶中植松柏遍滿巖穀，望之鬱然。朝元閣在北嶺之上，最為嶄絕。次南即長生殿。殿東南，湯泉凡一十八所。第一即御湯，周環數丈，悉砌白石，瑩彻如玉，石面皆隱起魚龍花鳥之状。四面石座，階級而下，中有双白石瓮，連腹異口，瓮口中复植双白石莲，泉眼自莲中涌出，註白石之面。御湯西南，即妃子湯，湯稍狹，湯侧有紅石盆四所，刻作菡萏於白石之面。餘湯迤逦，相屬而下，凿作暗窦走水；出東南數十步，复立一石表，涌出，灌註一石盆中，後人為也。","sortOrder":103},
  {"id":"s_work_dnl_20_104","chapterId":"ch_work_dnl_20","text":"潞州啟聖宮，有明皇欹枕斜書壁處，併腰鼓馬槽併存。張宏靖為潞州從事，皆見之。","sortOrder":104},
  {"id":"s_work_dnl_20_105","chapterId":"ch_work_dnl_20","text":"北邙山玄元觀，南有老君廟。殿台高敞，下瞰伊洛。神仙塑像，皆开元中楊惠之所製，世稱奇巧。","sortOrder":105},
  {"id":"s_work_dnl_20_106","chapterId":"ch_work_dnl_20","text":"鄴西鼓山東北，有石鼓，俗傳石鼓鳴則兵起。左思《魏都賦》雲：\"神鉦迢遞於高峦，靈响特驚於四表。\"案《說文》：\"鉦似鈴\"，小者為鐃。《周禮》：\"以金鐃止鼓\"。然則鉦、鼓雖同類，鉦乃以金為之，直謂石鼓為神鉦，失其義矣。高齊時石鼓鳴，未幾而齊滅；隋季又鳴，無何海內崩亂；近天寶末，石鼓复鳴，俄而幽燕ㄈ扰。記傳臨海、零陵、南康、建平、天水諸處，皆有石鼓，其說多同。晉武帝時，吳郡臨平湖岸崩，出一石鼓，扣之不鳴，張華雲：\"取蜀郡桐木作魚形，击之則鳴。\"於是聲聞數十里。後十六國迭據，三百餘年攻戰不息，是石鼓之鳴，鹹非吉徵也。","sortOrder":106},
  {"id":"s_work_dnl_20_107","chapterId":"ch_work_dnl_20","text":"費縣西漏泽者，漫數十里。每歲時雨降，即自浮溢，蒲魚之利，人實賴焉。至白露應節即如埽，一夕而乾焉。萧穎士以年代莫詳，記載所闕，信殊異也。","sortOrder":107},
  {"id":"s_work_dnl_20_108","chapterId":"ch_work_dnl_20","text":"萧功曹穎士、趙員外驊，开元中同居興敬里肄業，共有一靴。久而見東郭之跡。趙曰：\"可謂疲於道路矣。\"萧曰：\"無乃祿在其中。\"","sortOrder":108},
  {"id":"s_work_dnl_20_109","chapterId":"ch_work_dnl_20","text":"贺監為禮部侍郎，時祁王赠製雲惠昭太子，補斋挽郎。贺大納苞苴，為豪子相率詬辱之。吏遽掩門，贺梯牆謂曰：\"諸君且散，見說寧王亦甚惨澹矣！\"","sortOrder":109},
  {"id":"s_work_dnl_20_110","chapterId":"ch_work_dnl_20","text":"李白开元中謁宰相，封一板，上題曰：\"海上釣鰲客李白。\"宰相問曰：\"先生臨沧海，釣巨鰲，以何物為鉤線？\"白曰：\"風波逸其情，乾坤縱其志，以虹霓為線，明月為鉤。\"又曰：\"何物為餌？\"白曰：\"以天下無義氣丈夫為餌。\"宰相竦然。","sortOrder":110},
  {"id":"s_work_dnl_20_111","chapterId":"ch_work_dnl_20","text":"宋昌藻，考功員外郎之問之子，天寶中為滏陽尉。刺史房以其名父之子，常接遇。會中使至州，使昌藻郊外接候。須臾却還，雲\"被額。\"房公顧左右：\"何名為'額'？\"有參軍亦名家子，斂笏對曰：\"查名詆诃為額。\"房怅然曰：\"道額者已可笑，識額者更奇。\"近代流俗：呼丈夫、婦人縱放不拘禮度者為\"查\"。又有百數十种語，自相通解，謂之\"查語\"。大抵多近猥僻。","sortOrder":111},
  {"id":"s_work_dnl_20_112","chapterId":"ch_work_dnl_20","text":"肅宗在春宮，嘗與諸王從玄宗詣太清官，有龍見於殿之東梁。上目之，問諸王\"有所見乎\"？皆曰\"無之\"。問太子，太子亻免而未對，上問；\"頭在何處？\"曰：\"在東。\"上撫之曰：\"真我兒也。\"","sortOrder":112},
  {"id":"s_work_dnl_20_113","chapterId":"ch_work_dnl_20","text":"《禮記·祭法》累代祭名，不聞有戟神、節神，是知無拜祭之禮也。近代受節，置於一室，朔望必祭之，非也。凡戟：天子二十四，諸侯十；今之藩镇，即古之諸侯。在其地，則於衙門；及罢守藩阃，雖爵位崇高，亦不許列於私第。上元元年，宰相呂立戟，有司載戟及門，方惨服，乃更吉服迎而拜之，頗為有識者所嗤，則知辱命拜賜可也。拜戟祭節，大乖於禮。","sortOrder":113},
  {"id":"s_work_dnl_20_114","chapterId":"ch_work_dnl_20","text":"海州南有溝水，上通淮楚，公私漕運之路也。寶應中，堰破水涸，魚商絕行。州差東海令李知遠主役修复，堰將成辄坏，如此者數四，勞費頗多，知遠甚以為忧。或說：梁代筑浮山堰，頻有坏决，乃以鐵數千萬片填積其下，堰乃成。知遠聞之，即依其言，而堰果立。初，堰之將坏也，辄聞其下殷如雷聲，至是其聲移於上流數里。蓋金鐵味辛，辛能害目，蛟龍護其目，避之而去，故堰可成。","sortOrder":114},
  {"id":"s_work_dnl_20_115","chapterId":"ch_work_dnl_20","text":"越僧靈澈，得莲花漏於庐山，傳江西觀察使韦丹。初，惠遠以山中不知更漏，乃取銅葉製器，状如莲花，置盆水之上，底孔漏水，半之則沈。每一晝夜十二沈，為行道之節。冬夏短長，雲陰月晦，一無所差。","sortOrder":115},
  {"id":"s_work_dnl_20_116","chapterId":"ch_work_dnl_20","text":"嚴武少以強俊知名。蜀中坐衙，杜甫袒跣登其幾案，武愛其才，終不害。然與章彝善，再入蜀，談笑殺之。及卒，其母喜曰：\"而後吾知免為宮婢矣！\"","sortOrder":116},
  {"id":"s_work_dnl_20_117","chapterId":"ch_work_dnl_20","text":"杜相鸿漸之父名鵬舉。父子而似弟兄之名，蓋有由也。鵬舉父嘗夢有所之，見一大碑，雲是\"宰相碑\"。已作者金填其字，未作者刊名於柱上。因問有杜家兒否，曰：\"有。任自看之。\"記得姓下有鳥偏旁曳腳，而忘其字。乃名子為鵬舉，而謂之曰：\"汝不為相，世世名鳥旁而曳腳也。\"鵬舉生鸿漸，而名字且前定矣。况官與寿乎？","sortOrder":117},
  {"id":"s_work_dnl_20_118","chapterId":"ch_work_dnl_20","text":"杜亚在淮南競渡采莲，龍舟錦纜之戲，費金千萬。","sortOrder":118},
  {"id":"s_work_dnl_20_119","chapterId":"ch_work_dnl_20","text":"杜鸿漸為都統併副元帥，王縉代之。鸿漸謂人曰：\"一个月乞索兒一萬貫錢。\"蓋計使料多，以此詰俸錢都數也。","sortOrder":119},
  {"id":"s_work_dnl_20_120","chapterId":"ch_work_dnl_20","text":"代宗賜郭汾陽九花虬馬，子儀陳讓者久之。上曰：\"此馬高大，稱卿儀质，不必讓也。\"子儀身長六尺餘。九花虬，即范陽節度使李懷仙所獻。額高九寸，毛拳如鱗，頭頸鬃鬣如龍；每一嘶，群馬耸耳。身被九花，故以為名。","sortOrder":120},
  {"id":"s_work_dnl_20_121","chapterId":"ch_work_dnl_20","text":"郭汾陽雖度量廓落，然而有陶侃之僻，動無废物。每收書皮之右嫠下者，以為逐日須，至文帖餘悉卷貯。每至歲終，則散與主守吏，俾作一年之簿。所嫠處多不端直，文帖且又繁積，吏不暇翦正，隨斜曲聯糊。一日，所用嫠刀忽折，不餘寸許，吏乃以應召，覺愈於全時。漸出新意，因削木如半势，加於折刃之上，使才露鋒，其書而嫠之。汾陽嘉其用心，曰：\"真郭子儀部吏也。\"（原註：言不废折刃也）時人遂效之，其製益妙。","sortOrder":121},
  {"id":"s_work_dnl_20_122","chapterId":"ch_work_dnl_20","text":"武後已後，王侯妃主京城第宅日加崇麗。天寶中，御史大夫王钅共有罪賜死，縣官簿錄钅共太平坊宅，數日不能遍。宅內有自雨亭子，簷上飛流四註，當夏處之，凛若高秋。又有寶钿井欄，不知其价。他物稱是。安祿山初承寵遇，敕營甲第，瑰材之美，為京城第一。太真妃諸姊妹第宅，競為宏壮，曾不十年，皆相次覆滅。肅宗時，京都第宅，屢經殘毀。代宗即位，宰辅及朝士當權，爭修第舍，頗為煩弊，議者以為土木之妖。無何，皆易其主矣。（原註：《續世說》：明皇為安祿山起第於親仁坊，敕令但窮極壮麗，不限财力。既成，具幄器皿充刃其中。布帖白檀床二，皆長一丈，闊六尺。銀平脱屏風帳一，方一丈八尺。於厨廄之物，皆飾以金銀。全飯瓮一，銀淘盆二，皆受五斗。織銀絲筐及笊篱各一。他物稱是。雖禁中服御之物，殆不及也。上令中使護役，常戒之曰：\"彼眼大，勿令笑我。\"）中書令郭子儀勋伐蓋代，所居宅內諸院往來乘車馬，僮客於大門出入，各不相識。詞人梁嘗賦詩曰：\"堂高凭上望，宅廣乘車行。\"蓋此之謂。郭令曾將出，見修宅者，謂曰：\"好筑此牆，勿令不牢。\"筑者釋锸而對曰：\"數十年來，京城達官家牆皆是某筑。只見人改換，牆皆見在。\"郭令聞之怆然。遂入奏其事，因固請老。","sortOrder":122},
  {"id":"s_work_dnl_20_123","chapterId":"ch_work_dnl_20","text":"張曇為郭汾陽從事，家嘗有怪，問於術者，對曰：\"大禍將至，唯休退可免。\"曇不之信，及方宴，席上見血，有尼者聞之，勸其杜門不納賓客，屏遊宴，曇怒而杖之。其後曇言語有失，汾陽衔之。又屢言同列事，或獨後見，多值方宴罢在姬所，不可白事，必抑門者令通。汾陽謂其以武臣輕忽己，益不平。後因謂公去所任吏，遂發怒，囚之以聞，竟杖死。","sortOrder":123},
  {"id":"s_work_dnl_20_124","chapterId":"ch_work_dnl_20","text":"李太尉光弼镇徐，北拒賊冲急，總諸道兵馬。征讨之務，皆自處置。仓储府库，軍州差補，一切併委判官張亻參。亻參明練庶務，應接如流。欲見太尉論事，太尉辄令判官商量。將校見亻參，禮數如見太尉。由是上下清肅，東方晏然，天下皆謂太尉能任人。","sortOrder":124},
  {"id":"s_work_dnl_20_125","chapterId":"ch_work_dnl_20","text":"代宗時，百寮立班良久，阖門不开。魚朝恩忽擁白刃十餘人而出，曰：\"西蕃頻犯郊圻，欲幸河中，如何？\"宰臣以下，不知所對。給事劉某出班抗聲曰：\"敕使反也！屯兵無數，何不捍寇？而欲胁天子去宗廟？\"仗內震耸，朝恩大駭而退，因此罢議。","sortOrder":125},
  {"id":"s_work_dnl_20_126","chapterId":"ch_work_dnl_20","text":"顏真卿為尚書左丞。代宗車駕自陝府還，真卿請先謁五陵、孔廟，而後還宮。宰相元載謂真卿曰：\"公所見雖美，其如不合時宜何？\"真卿怒而前曰：\"用舍在相公，言者何罪？然朝廷事豈堪相公再破除耶！\"載深衔之。","sortOrder":126},
  {"id":"s_work_dnl_20_127","chapterId":"ch_work_dnl_20","text":"代宗欲相李泌，元載忌之。帝不得已。出泌，約曰：\"後召當以銀為信。\"忽除銀青光祿大夫，泌知載败，己且相矣。未幾果然。","sortOrder":127},
  {"id":"s_work_dnl_20_128","chapterId":"ch_work_dnl_20","text":"柳相初名載，後改為浑。佐江西幕，嗜酒，好入廛市，不事拘檢。時，路嗣恭初平五嶺。元載奏言：\"嗣恭多取南人金寶，是欲為亂。陛下不信，试召，必不入朝。\"三伏中追詔至，嗣恭不慮，請待秋涼以修觐禮。浑入，泣諫曰：\"公有功，方暑而追，是為執政所中。今少遷延，必族滅矣！\"嗣恭懼曰：\"為之奈何？\"浑曰：\"健步追還表緘。公今日過江，宿石頭驿，乃可。\"從之。代宗謂元載曰：\"嗣恭不俟駕行矣。\"載無以對。","sortOrder":128},
  {"id":"s_work_dnl_20_129","chapterId":"ch_work_dnl_20","text":"元相載用李纾侍郎知製誥。元败，欲出官。王相縉曰：\"且留作誥。\"待發遣諸人盡，始出為婺州刺史。又曰：獨孤侍郎求知製誥，试見元相，元相知其所欲，迎謂常州曰：\"知製誥可難堪。\"心知不我與也。乃荐李侍郎纾。時楊炎在閣下，忌常州之來，元阻之，乃二人之力也。","sortOrder":129},
  {"id":"s_work_dnl_20_130","chapterId":"ch_work_dnl_20","text":"元伯和、李騰、騰弟淮、王縉，時人謂之\"四凶\"。劉宗經、執經兄弟，入\"八元\"數。","sortOrder":130},
  {"id":"s_work_dnl_20_131","chapterId":"ch_work_dnl_20","text":"李纾侍郎好諧戲，又服用華鮮。嘗朝回，與同列入坊門，有負販者诃不避，李骂雲：\"頭錢价奴兵辄冲官長！\"負者顧而言曰：\"八錢价措大漫作威風。\"纾樂采異語，使仆者訪\"八錢\"之義。答：\"只是衣短七耳。\"同列為言，纾甚慚。","sortOrder":131},
  {"id":"s_work_dnl_20_132","chapterId":"ch_work_dnl_20","text":"元載擅權多年，客有為《都盧緣ㄅ歌》，欲諷其至危之势。覽之泣下。","sortOrder":132},
  {"id":"s_work_dnl_20_133","chapterId":"ch_work_dnl_20","text":"鄭相瑜方上堂食，王叔文至，韦執誼遽起延入閣內。瑜叹曰：\"可以歸矣！\"遂命駕，不終食而出。自是罢免。","sortOrder":133},
  {"id":"s_work_dnl_20_134","chapterId":"ch_work_dnl_20","text":"元載败，妻王氏曰：\"某四道節度使女，十八年宰相妻。今日相公犯罪，死即甘心。使妾為舂婢，不如死也。\"主司上聞，俄而亦賜死。","sortOrder":134},
  {"id":"s_work_dnl_20_135","chapterId":"ch_work_dnl_20","text":"元載於萬年縣佛堂子中，謂主者：\"乞一快死也。\"主者曰：\"相公今日受些污泥，不怪也。\"乃脱秽襪塞其口而終。","sortOrder":135},
  {"id":"s_work_dnl_20_136","chapterId":"ch_work_dnl_20","text":"《顏真卿集·和政公主神道碑》：\"《詩》美下嫁，《書》傳筑馆，貴其中禮，載籍稱焉。漢魏已還，寂寥罕嗣，以荡陵德，則維其常。皇唐勃興，王道丕变：平陽起娘子之軍於司竹，襄城行匹庶之禮於宋公，常樂糾匡後之師於武後，皆前古之所未有。其或生知禮樂，周旋法度，躬行婦道，以懋大倫，克順天經，光昭懿烈，名言之所莫究，書記之所未聞，聚眾美於一身，鄰太虛而獨立者，其唯和政公主乎！公主姓李氏，隴西成紀人，皇唐元宗大聖大明孝皇帝之孫，肅宗文明武德大聖大宣孝皇帝之第二女。帝女之崇，於斯為盛。今天子之同母，曰章敬皇太後。後之在襁褓也，後父赠太尉吳君，曰令，嘗遊宦蜀中，使道士勾規占之。規驚起曰：'此女貴不可言。是生二子，男為人君，女為公主，'嫁於柳氏。其後竟配肅宗，生今上及公主，神所命也。厥惟舊哉！公主三歲而孤，即能孺慕，育於储妃韦氏，純孝過人。幼而聰惠，長而韶敏。華秀整，令德芬馨。婉發於天姿，肅雍形於鑒寐。奉今上以悌達，事韦妃如所生，繇是特為肅宗之所賞愛。至若左右圖史，开示佛經，金石絲竹之音，缋畫工巧之事，耳目之所聞見，心靈之所領略，莫不一覽懸解，終身不忘。天寶九載春三月既望，封和政公主，降於河東柳潭，既笄之三載矣。潭，周太保敏之五代孫，皇唐蘄州刺史懷素之曾孫，赠秘書監岑之第四子；衣冠地胄，辉映當朝。初以美秀承家，中以名聲華國，道勝而貴能下善，謙尊而休有烈光，士林伟之。解褐左內率府胄曹，轉潁王府戶曹，陳留郡司功參軍。以人門第一，選尚公主，拜太子洗馬。跡既好合，雅相敬貴。雖柳侯秉彝有度，能降帝女之心，而公主率履由衷，每抗古人之節。故宗族胥睦，不獨親其親；先後大同，莫敢私其子。竭力供侍，不務華采，服五金翠之飾，居有冰雪之容。每至朔月六參，朝天旅進，嫣然班叙之內，迥出神仙之表，亦非希企之所及也！洎凶羯亂常，潼關不守，玄宗幸蜀，妃後駿奔。姊曰寧國公主，孀嫠屏居，誰或訃告？乃弃其三子，取其夫之乘以乘之。柳侯徒行，公主愧焉，下而同趨者日且百里。每臻坎险，必先濟寧國而後從之。柳侯辭，公主曰：'我若先涉，脱有危急，不能俱全，則弃我姊矣！'柳侯感叹，躬負薪之役；公主怡然，親饋饩之事。伯姒華陰楊氏，太真妃之姊也，貴幸前朝，势傾天下。公主交無諂黷，思未綢缪。楊且雲亡，以孤見托。馬嵬之役，無噍類焉。感其一言，悉力營贍。男登服冕之位，女獲乘龍之匹。出入存恤，過於己子，雖其密親，罔或能辨。柳之親昵，伯仲姑姊，隱親將迎，唯恐不至。糾逖疏屬，撫循嫠，繇內及外，終始如一。孤窮滿目，榮悴殊倫，居薄推厚，未嘗懈倦。衣服飲食，等無有差。互或未周，婴孩罔及。每至伏腊，礻勺祠蒸嘗，必具禮衣花儀之飾，以躬中饋堂室之奠。式燕孫謀，豈無婢使？姿性純俭，不以迄成。先聖休之，寶書清問。秋八月，玄宗至蜀，仍舊邑而册公主，以潭為駙馬都尉、銀青光祿大夫、太仆卿。屬狂將興禍，稱兵向闕。玄宗親御堙，臨视誅讨。駙馬率領家竖、折冲張義童等，斗於門中，公主及寧國彀弓迭進。駙馬乘勝突刃，所向無前，斬馘擒生，殆逾五十。節使時宰具以表聞。玄宗自系誥示先帝，恳讓莫當，策勋遂寢。今上之為元帥也，躬擐甲胄，率先將卒。舉兩京若拾遺，摧凶寇如振槁。勞旋方及，帑藏其空。公主貿遷有無，亿則屢中，數逾千萬，悉畀縣官，論者難之。肅宗弥留，眾皆迭侍，主獨贍依，不去於旁。帝有間書而謂之曰：'汝之純孝，乃能至是！'遂赉莊一區。帝愛季女，曰寶貞公主，因奏曰：'八妹未有，請以賜之。'泣而諫焉，哀動左右。西陵遷窆，上戒主曰：'凡厥親身之物，必誠必信，勿之悔焉。'主罄家有無，以邑入千萬，潛充經費，上深感叹焉。上既宅亮陰，未忍臨政，人之疾苦，事之得失，豈嘗私謁，動必以聞，上敬異之，朝廷賴焉。廣德元年冬，上既東幸，主志期扈跸，回兵充斥，咫尺不通，因至荆南，慰荐諸將。方隅載謐，職貢以修，主有力焉。上之在陝，忧主乏匮，乃命中使，屢敕節度及轉運使，隨主所須，務令肅給。主以國用罄空，退而叹曰：'吾方竭家财以資戰士，其能饕餮，首冒國經？'唯請名香數斤，施於佛寺，為上祈福而已。王公戚屬，相携而至者，藍縷腻囊，襁負鱗次，竭其資斧，親自贍恤。聚而泣之，悲感行路。初次商於，頓於傳置，群盜猬起，奄及驿亭，呼而犒之，晓以禍福。一言革面，願比家奴；之死靡他，至今猶在。緬惟罔極，無所哀。從母薛氏，遺孤四人，分宅居之，皆俾成立。萊、莘兄弟，盡列通班；二女有行，克配良士：主之慈忠，悉皆若是。親臨稼穡，躬俭節用。不憚煩縟，雅好組訓，駙馬裳衣，必親裁纟失。爰及子女，罔衣綺紈，綻新皆成主手。每加訓誨，迪檢押。廣德二年春二月，歸於上都。諸主高會，議际夫党，觌其親族，多曠周旋。鹹以為時經百罹，粗略可也。主抗詞曰：'女之移天，遂成他族。怙貴長傲，何以律人？上方理定，聞必不悅。'諸主蹶然，競崇讨習，禮之降殺，親之薄厚，翕然一变，職主之由。夏六月，才生魄，屬邊候不謹，烽及京師，城中震驚，圜视五色。主既弥月，體未甚安，曰：'事亟矣，其入言之！'駙馬請聞，主曰：'吾業已行矣！駙馬獨無兄乎？'因乘簷子，直至寢殿，乃悉索闕遺，備陳利病以奏之。上欣然嘉納。所言未究，傍或負來，因爾退歸。遲明誕育，展轉怊怅，不能弥忘。時屬炎喝，熱病有加。聖情忧軫，起坐失次，天医內官，相繼旁午。彼蒼不惠，以其月二十有五日辛卯，薨於常樂坊之私第，春秋三十有六。呜呼！皇上友愛天深，痛毒兼至，砉然一叫，聲淚俱咽，哀動木石，豈伊人倫？涟涟孔懷，如失於臂。曰：'予此妹，國之鸿寶。方期同樂，雲如何殂？嗟哉！天實為之，胡寧忍予！'乃輟朝三日，命京兆尹監護丧事，一以官供，務從優厚。柳侯掐膺永悼，氣索神傷；心苦而忽然忘生，泣盡而繼之以血。况乎五男三女，或龀或孩，呼阿母而哭無常聲，吁昊天而仁覆永絕。哺以滋旨，嗌而莫就，其為酷痛，曷愈於斯。以是思哀，哀可知矣！自朝及野，知與不知，聞之失聲，罔不震悼。栈有青牛，素服轅軛，主之薨也，踣地哀鳴，仰天屑淚，三日不秣；畜猶若是，臣仆可知。主之將薨，馭馬先殒。捐馆之夕，遊神別墅，乘之周麾，遍勞遺，俾屏不逮。田客兼從數騎，久已雲亡，眾皆驚起，仿佛猶見。雖所凭則厚，而精氣何多？主於駙馬，大義敦肅，不恃見天之貴，每極家人之禮。駙馬雅性夷簡，恬於名利，願究衛生之經，庶臻久视之道；主志深婉順，始慕真宗，故於他時，併受法錄。嘗謂之曰：'《易》崇積善，《詩》貴起予。不以忠孝數事迭相告勖者，則心有慊焉。'率而行之，曷嘗废墜？又以為'死生恒理，先後之間。若幸啟手足，必當衤遂我以道服，瘞我於支提，往來行言，時見存恤，則所懷足矣！子若不讳，我若此身未亡，洒埽塋垅，出入窀穸，奉君周旋。'噫嘻！於斯之時，以為謔浪，豈悟今者，皆符昔言。有司奉詔，將厚其禮。駙馬疏陳，皆蒙允許。粵以秋八月十九日甲申，其男试太常少卿賜紫金魚袋晟、鸿臚少卿晕、试秘書丞賜紫金魚袋杲、试殿中丞昱及三女等，虔窆公主於萬年縣義丰之銅人原，從理命也。呜呼！《風》詠裳，史稱彤管，纖微之善，載籍猶稱。况乎七葉帝女，分形《歸妹》，貴能逮下，忠以导君，躬德言容功之美，服女師母儀之訓，订之綿古，孰與我京？昔馬遷著記，謂之實錄，有道見述，亦雲無愧。某學於舊史，少識前載。歷考往代厘降之盛，未有如公主者焉。雖壶則家風，每挹如賓之敬，而勤崇垂懿，敢忘傳信之辭！銘曰：'矣公主！元元之緒。聖皇之孫，肅宗之女，今上之妹，生人之矩。德言容功，義仁孝忠，溫良恭俭，敬讓弘通。率履弗越，高明有融。下嫁於柳，猗那自久，金石著盟，琴瑟斯友。家道以正，人倫斯厚。鳳凰於飛，梧桐是依，．喈喈，福祿攸歸，和樂既孺，德音莫违。麟之趾定，振振子姓，方紹母師，奄摧邦令，一人痛毒，九有悲詠。詔葬於何？銅人之阿。支提鬱起，宰树誰過？空餘好合，來往滂沱。'\"","sortOrder":136},
  {"id":"s_work_dnl_20_137","chapterId":"ch_work_dnl_20","text":"永泰中，大理評事孫廣著《嘯旨》一篇，雲：\"其氣激於喉中而濁，謂之言；激於舌端而清，謂之嘯。言之濁，可以通人事、達情性；嘯之清，可以感鬼神、致不死。故太上老君授南極真人，真人授廣成子，廣成子授風後，風後授務光，務光授舜，舜演之為琴，以授禹。自後或废或續，有晉大行仙君孫公得之以得道，無所授，阮嗣宗所得少分，其後不复聞矣！\"按高氏《緯略》，嘯有十五章：一曰《權舆》；二曰《流雲》；三曰《深溪虎》；四曰《高柳蝉》；五曰《空林鬼》；六曰《巫峡猿》；七曰《下鸿鵠》；八曰《古木鳶》；九曰《龍吟》；十曰《動地》；十一曰《蘇門》，孫登隱蘇門山所作也；十二曰《劉公命鬼》，仙人劉根所作也；十三曰《阮氏逸韻》，阮籍所作也；十四曰《正章》；十五曰《深遠極大》，非常聲也。畢盡五音之極，而大道備矣。廣雲：\"其事出道書。\"餘按：人有所思則長嘯，故樂則詠歌，忧則嗟叹，思則嘯吟。《詩》雲：\"有女仳離，條其嘯矣！\"顏延之《五君詠》雲：\"長嘯若懷人。\"皆是也。廣所雲《深溪虎》、《古木鳶》，状其聲氣可知矣。若太上老君相次傳授，舜演為琴，崇飾過甚，餘不敢聞也。按《詩箋》雲：\"嘯，蹙口出聲也。\"成公綏《嘯賦》雲：\"動唇有曲，發口成音。\"而今之嘯者，开口卷舌，略無蹙舌之法。孫氏雲\"激於舌\"，非動唇之謂也。天寶末，峨眉山道士姓陳，來遊京師，善長嘯，能作鼓霹靂之引。初則聲發調畅，稍加散越；須臾穹窿砰磕，寫雷鼓之音；忽复震駭，聲如霹靂，聞者莫不傾忄栗。","sortOrder":137},
  {"id":"s_work_dnl_20_138","chapterId":"ch_work_dnl_20","text":"至德二年，敕天下州縣重定酤酒，隨月納稅。建中二年，更加青苗。大歷初，稅每十文；三年，加五文；敕以御史大夫充使。其後割歸度支使。","sortOrder":138},
  {"id":"s_work_dnl_20_139","chapterId":"ch_work_dnl_20","text":"开元已前，有事於外則命使臣，否則止罢。自置八節度、十采訪，始有坐而為使者。其後名號益廣。大抵生於置兵，盛於興利，普於衔命，於是為使則重，為官則輕。故天下佩印有至四十者，大歷中請俸有至百萬者。在朝有太清宮、太微宮、度支、鹽鐵、轉運、知匦、宮苑、閒廄、左右巡、分案、監察、馆驿、監仓、監库、左右衔，外任則節度、觀察、諸軍、押蕃、防御、团練、經略、镇遏、招讨、榷鹽、水陆運、營田、給納、監牧、長春宮。有因時而置者：則大禮、禮儀、禮會、删定、三司、黜陟、巡撫、宣慰、推复、選補、會盟、册立、弔祭、供軍、糧料、和籴。此其大略。經置而废者，不錄。宦官內外悉謂之使。舊為權臣所綰，州縣所理，後屬中人者有之。","sortOrder":139},
  {"id":"s_work_dnl_20_140","chapterId":"ch_work_dnl_20","text":"大歷中，刑部郎中程皓家在相州，宅前有小池。有人造劍，於池內淬之，池魚皆死。餘家井中有魚數十頭，因有急，家人以藥臼投之，信宿魚皆浮出，知魚亦畏鐵焉。","sortOrder":140},
  {"id":"s_work_dnl_20_141","chapterId":"ch_work_dnl_20","text":"大歷末，北方有白虹夜見，東西屬地。封演曰：凡虹見，皆當日之冲。朝見則在西，常與日相近，不差分毫。今此虹見之時，日在癸，則虹見當在丙。常時虹影穹崇，舉目而望，今虹在北，又可平视，知日在北方，去茲遠矣。略計此當在斗極之北。斗極，天中也，故北萬可得而見，而日更在虹之北，又甚遼闊，故北方不得而見之。","sortOrder":141},
  {"id":"s_work_dnl_20_142","chapterId":"ch_work_dnl_20","text":"苗夫人，其父太師也，舅張河東也，夫延賞也，子宏靖也，婿韦太尉也。近代衣冠婦人之貴，無如苗氏者。","sortOrder":142},
  {"id":"s_work_dnl_21_1","chapterId":"ch_work_dnl_21","text":"●卷五·補遺（起德宗至文宗）","sortOrder":1},
  {"id":"s_work_dnl_21_2","chapterId":"ch_work_dnl_21","text":"德宗降誕日，內殿三教講論，以僧鑒虛對韦渠牟，以許孟容對趙需，以僧覃延對道士郄惟素。諸人皆談畢，鑒虛曰：\"諸奏事雲：玄元皇帝，天下之聖人；文宣王，古今之聖人；釋迦如來，西方之聖人；今皇帝陛下，是南贍部洲之聖人。臣請講御製《賜新羅銘》。\"講罢，德宗有喜色。","sortOrder":2},
  {"id":"s_work_dnl_21_3","chapterId":"ch_work_dnl_21","text":"德宗降誕日，三教講論。儒者第一超需，第二許孟容，第三韦渠牟，與僧覃延嘲謔，因此承恩也。渠牟荐一崔阡，拜諭德，為侍書於東宮。東宮，順宗也。阡觸事面牆，對東宮曰：\"臣山野人，不識朝典，見陛下合稱臣否？\"東宮曰：\"卿是宮寮，自合知也。\"","sortOrder":3},
  {"id":"s_work_dnl_21_4","chapterId":"ch_work_dnl_21","text":"李丞相泌，謂德宗曰：\"肅宗師臣，豈不呼陛下為{山忍}郎？\"（案：{山忍}字，字書無之，疑誤）聖顏不悅，泌曰：\"陛下天寶元年生，向外言改年之由，或以宏農得寶，此乃谬也。以陛下此年降誕，故玄宗帝以天降之寶，因改年號為天寶也。\"聖顏然後大悅。又韦渠牟曾為道士及僧，德宗問：\"卿從道門，本師复是誰？\"渠牟曰：\"臣師李仙師，仙師師張果老先生。肅宗皇帝師李仙師為仙帝，臣道合為陛下師。由跡微官卑，故不足為陛下師。\"渠牟亦效李相泌之對也。","sortOrder":4},
  {"id":"s_work_dnl_21_5","chapterId":"ch_work_dnl_21","text":"趙涓為監察御史。時禁中失火，火發處與東宮相近，代宗疑之。涓為巡使，俾令即訊。涓因歷僡囿，按據跡状，乃上直中官遺火所致也。既奏，代宗稱賞。德宗時在東宮，常感涓究理詳明。及刺衢州，所考既深，與觀察使韓不相得，奏免涓官。德宗見名，謂宰相曰：\"豈非永泰初御史趙涓乎？\"對曰：\"然。\"即日拜尚書左丞。","sortOrder":5},
  {"id":"s_work_dnl_21_6","chapterId":"ch_work_dnl_21","text":"司徒鄭貞公，每在方镇，公廳陳設，器用無不精備，宴犒未嘗刻薄。其平居奉身過於俭素，中外婚嫁甚多，禮物皆經處畫。公與其宗叔太子太傅綱居昭國坊。太傅第在南，出自南祖；司徒第在北，出自北祖：時人謂之\"南鄭相、北鄭相\"。司徒堂兄文憲公，前後相德宗，亦謂之\"大鄭相\"、\"小鄭相\"焉。","sortOrder":6},
  {"id":"s_work_dnl_21_7","chapterId":"ch_work_dnl_21","text":"德宗西幸，所乘馬，一號神智驄，一號如意骝。","sortOrder":7},
  {"id":"s_work_dnl_21_8","chapterId":"ch_work_dnl_21","text":"王承升有妹，國色，德宗納之，不恋宮室。德宗曰：\"窮相女子。\"乃出之。敕其母兄不得嫁進士朝官，任配軍將親情。後適元士會，以流落終。","sortOrder":8},
  {"id":"s_work_dnl_21_9","chapterId":"ch_work_dnl_21","text":"顏魯公嘗得方土名藥服之，雖老，氣力壮健如年年三四十人。至奉使李希烈，春秋七十五矣。臨行，告人曰：\"吾之死，固為賊所殺必矣。且元載所得藥方，亦與吾同；但載貪甚，等是死，而載不如吾。吾得死於忠耶？\"於是，命取席固圜其身，挺立一躍而出。又立兩藤倚子相背，以兩手握其倚處，懸足點空，不至地三二寸，數千百下。又手按床東南隅，跳至西北者，亦不啻五六。乃曰：\"既如此，疾焉得死吾耶？異日幸得歸骨來秦，吾侄女為裴郾妻者（原註：郾，即魯公之親表侄），此女最仁孝，及吾小青衣翦彩者，頗善承事；是的，汝必與二人同啟吾棺，知有異於常人之死爾！如穆護（原註：穆護，即魯公男硕之小名也）天性之道，難言至此。\"至蔡州，责希烈反逆無状。竟不敢以面目相見，亦不敢以兵刃相恐，潛命獻食者饋空器而已。翌日，賊令官翌來縊之。魯公曰：\"老夫受錄及服藥，皆有所得。若斷吭，道家所忌。今赠使人一黃金帶。吾死之後，但割吾他支節，為吾吭血以绐之，死無所恨。\"且曰：\"使人悟慧如此，不事明天子，反事逆賊，何所圖也？\"官翌從其言。至明年，希烈死，蔡帥陳仙奇奉魯公丧歸京。猶子顏峴實從柳常侍與裴氏女及翦彩同迎丧於镇國仁寺。鹹遵遺旨，啟棺如生。（原註：柳製魯公挽歌詞曰：\"殺身終不恨，歸丧遂如生。\"）","sortOrder":9},
  {"id":"s_work_dnl_21_10","chapterId":"ch_work_dnl_21","text":"顏真卿為平原太守，立三碑，皆自撰書。其一立於郡門內，紀同時台省擢授諸郡者十餘人；其一立於郭門之西，紀顏氏：曹魏時顏裴、高齊顏之推，俱為平原太守，至真卿，凡三典茲郡；其一是《東方朔廟碑》。镌刻既畢，屬祿山亂，未之立也。及真卿南渡，蕃寇陷城，州人埋匿此碑。河朔克平，別駕吳子晁，好事者也，掘碑使立於廟所。其二碑求得舊文，買石镌勒，树之郡門。時顏任撫州，子晁拓三碑本寄之。顏經艱難，對之怆然，曰：\"碑者，往年一時之事，何期大賢再為修立，非所望也。\"即日，专使赍書至平原致謝。子晁後至相州刺史兼御史大夫。","sortOrder":10},
  {"id":"s_work_dnl_21_11","chapterId":"ch_work_dnl_21","text":"天寶初，有范氏尼者，知人休咎。顏魯公妻党之親也。魯公尉醴泉日，詣范問曰：\"某欲就製科试，乞師姨一言。\"范尼曰：\"顏郎事必成。自後一兩月朝拜，但半月內慎勿與國外人爭竟，恐有譴謫。\"魯公曰：\"官階盡五品，身著緋衫，帶銀魚，兒子得補斋郎，其望滿矣。\"范尼指座上紫絲布食单曰：\"顏郎衫色如此，有功業名節皆稱是。過七十，已後不須苦問。\"魯公再三窮詰，范曰：\"顏郎聰明過人，問事不必到底。\"逾日大。魯公製科高第，授長安尉，遷監察御史。因押班，责武班中喧哗者，命小吏錄奏次，即哥舒翰也。翰恃有新破石壁城功，泣訴明皇，坐魯公輕侮功臣，貶蒲州掾。及魯公為太子太師，使蔡，叹曰：\"范師之言，吾命懸於賊庭必矣！\"","sortOrder":11},
  {"id":"s_work_dnl_21_12","chapterId":"ch_work_dnl_21","text":"建中初，關播為給事中尉。以諸司甲库皆是胥吏掌，為弊頗久，因播議，用士人知之，謂之\"掌库\"。","sortOrder":12},
  {"id":"s_work_dnl_21_13","chapterId":"ch_work_dnl_21","text":"興元中，有知馬者曰李幼清，暇日常取適於馬肆。有致悍馬於肆者，結鎖交絡其頭，二力士以木耒支其颐，三四辈執抓而從之，馬氣色如將噬，有不可馭之状。幼清逼而察之，訊於主者，且曰：\"馬之惡，無不具也。將货焉，唯其所酬耳。\"幼清以二萬易之，馬主尚慚其多。既而聚觀者數百辈，訝幼清之决也。幼清曰：\"此馬氣色駿異，體骨德度非凡馬。是必主者不知馬，俾雜駑辈槽栈，陷败狼藉，刷涤不時，刍秣不適，虎嚙蹂奋，蹇破唐突，志性鬱塞，終不可久，無所顧賴，發而為狂躁，則無不為也。\"既晡，觀者少間。乃別市一新絡頭。幼清自持，徐徐而前，語之曰：\"爾材性不為人知，吾為汝易是鎖，結雜秽之物。\"馬弭耳引首。幼清自負其知，乃湯沐翦飾，別其皂栈，異其刍秣。數日而神氣一小变，逾月而大变。志性如君子，步骤如俊，嘶如龍，顧如鳳，乃天下之駿乘也。","sortOrder":13},
  {"id":"s_work_dnl_21_14","chapterId":"ch_work_dnl_21","text":"嗣曹王皋有巧思，精於器用。為荆州節度使，有羁旅士，持二羯鼓卷謁皋。皋見卷曰：\"此至寶也！\"指鋼匀之状，賓佐皆莫晓。皋曰：\"諸公未必信。\"命取食半，自選其極平者，遂量重二卷於半心，油註卷中，滿不浸漏，其吻合無际。皋曰：\"此必开元中供御卷，不然，無以至此。\"問其所自，客曰：\"某先人在黔中，得於高力士之家。\"眾服其識。賓府潛問客：\"宜偿幾何？\"答曰：\"不過二百五缗。\"及遺财帛器物，其直果稱焉。張敦素《夷堅錄》雲：\"宗正卿李琬善羯鼓，有士子以双鐵卷賣之，還二十缗，其人怏怏，琬复資之。客有怪其厚价，琬乃取一盤底至平者，以二卷重重安盤中，灌水其中，曾無泄漏。琬曰：'至精所至，其貴在茲。'\"某案：南卓郎中《羯鼓錄》但雲李卿妙於羯鼓，不言有得卷事，則敦素之記非耶？","sortOrder":14},
  {"id":"s_work_dnl_21_15","chapterId":"ch_work_dnl_21","text":"宋氵允為太常丞，每言諸懸鐘磬亡墜至多，補之者又乖律呂。忽因於光宅佛寺侍漏，聞塔上铎聲，傾聽久之。朝回，复止寺舍，問寺主僧曰：\"上人塔上铎，皆知所自乎？\"曰：\"不能知之。\"曰：\"某聞有一是近製。某請一人循鈴索歷扣以辨之，可乎？\"初，僧難，後許。乃扣而辨焉。寺眾即言：\"往往無風自搖，洋洋有聲，非此也耶？\"氵允曰：\"是也。必因祠祭考本縣鐘而應也。\"因求摘取而觀之，曰：\"此姑洗編鐘耳。\"且請獨缀於僧庭。歸太常，令樂人與僧同臨之；約其時彼扣本樂懸，此果應之，遂購而獲。又曾送客至通化門，逢度支運乘。駐馬俄頃，忽草草揖客別，乃隨乘至左藏門，認一鈴，亦言編鐘也。他人但見鑄獨工，不與眾者埒，莫知其餘。及配懸，音形皆合其度，異乎！","sortOrder":15},
  {"id":"s_work_dnl_21_16","chapterId":"ch_work_dnl_21","text":"貞元中，張茂宗尚義章公主，赠鄭國公主，謚為貞穆，有司擇日策命。唐已來，公主即有追封者，未有加謚者，公主追謚，自此始也。","sortOrder":16},
  {"id":"s_work_dnl_21_17","chapterId":"ch_work_dnl_21","text":"貞元十二年六月乙丑，始以窦文場為左神策護中尉，霍仙鳴為右神策護中尉；某月，又以張尚進為神武中護軍，左右辟仗使之始也。","sortOrder":17},
  {"id":"s_work_dnl_21_18","chapterId":"ch_work_dnl_21","text":"貞元中，贾全為杭州，於西湖造亭，為\"贾公亭\"，未五六十年废。（案：卷五一條：杭州房為鹽官令，於縣內凿池構亭，曰\"房公亭\"，後废。全與此條相類，當是編辑者以贾全事誤作房，而王谠采據各書，遂兩著之。今無可參校，亦姑併存）","sortOrder":18},
  {"id":"s_work_dnl_21_19","chapterId":"ch_work_dnl_21","text":"貞元中，郎中史牟為榷鹽使。有表生二人自來謁，其母仍使子赍一青鹽枕以奉牟，牟封枕付库，杖殺二表生。","sortOrder":19},
  {"id":"s_work_dnl_21_20","chapterId":"ch_work_dnl_21","text":"德宗非時召拜吳凑為京兆尹，便令赴上。疾驅，請客至府，已列筵矣。或問：\"何速？\"吏曰：\"兩市日有禮席，舉鐺釜而取之，故三、五百人之饌，常可立辦。\"","sortOrder":20},
  {"id":"s_work_dnl_21_21","chapterId":"ch_work_dnl_21","text":"韓皋自中書舍人除御史丞。西省故事：閣老改官，則詞頭送以次舍人。是時呂渭草敕，皋忧恐，問曰：\"仆有何命？\"渭不告，皋劫之曰：\"與公俱左降。\"乃告之。皋又欲訴宰相，渭執之，奪其靴笏，靴笏至午後三刻乃止。","sortOrder":21},
  {"id":"s_work_dnl_21_22","chapterId":"ch_work_dnl_21","text":"德宗复京師，賜勋臣第宅妓樂。李令為首，浑侍中次之。","sortOrder":22},
  {"id":"s_work_dnl_21_23","chapterId":"ch_work_dnl_21","text":"馬司徒面斥李懷光，德宗正色曰：\"惟卿不合斥人。\"惶恐而退。李令聞之，請全軍自備資糧以讨凶逆，因此李、馬不平。","sortOrder":23},
  {"id":"s_work_dnl_21_24","chapterId":"ch_work_dnl_21","text":"李令常為製將，至西川，與張延賞有隙。及延賞作相，二勋臣在朝，德宗嘗令韓晉公和解。宴樂則宰臣盡在，而太常教坊音樂皆至，恩賜酒饌，相望於路。","sortOrder":24},
  {"id":"s_work_dnl_21_25","chapterId":"ch_work_dnl_21","text":"張、李二家，日出無音樂之聲，金吾必奏。俄頃，有中使來，問：\"大臣今日何不舉樂？\"","sortOrder":25},
  {"id":"s_work_dnl_21_26","chapterId":"ch_work_dnl_21","text":"韓晉公聞德宗在奉天，以夹練囊緘茶末，使步以進。又發軍食，嘗自負米一石登舟，大將以下皆運。一日之中，積載數萬斛。後大修石頭五城，召補迎駕子弟，時論疑之。","sortOrder":26},
  {"id":"s_work_dnl_21_27","chapterId":"ch_work_dnl_21","text":"張鳳翔镒聞難，盡出所有衣服，併其家钿釵枕鏡，列於小廳，將獻行在。俄頃，後院火起，妻女出，而镒從判官田承窦得出，匿村舍中，數日稍定。會镒家知之，走告軍中，計議迎镒，遂遇害。","sortOrder":27},
  {"id":"s_work_dnl_21_28","chapterId":"ch_work_dnl_21","text":"德宗幸奉天，朱米月時劣诔竅隆Ｓ形骱律菰谠糝校陨躉桑堂造攻城雲梯，其高九十餘尺，上施板屋樓橹，可以下瞰城中。浑中令、李司徒奏曰：\"賊鋒既盛，雲梯又壮。縱之，恐不能御；及其尚遠，請以銳兵挫之。\"遂出師五千，束居後，約戰酣而燎。風逆，不能舉火，二公酹酒祝之，詞氣慷慨，千百其勇。須臾，風回，舉火縱之，鼓噪而進，梯遂荡盡。德宗御城樓以觀，眾呼萬歲。","sortOrder":28},
  {"id":"s_work_dnl_21_29","chapterId":"ch_work_dnl_21","text":"朱孟菥┦Γ熳有伊貉螅橇帳檀印Ｖ聋頗瞎瓤冢嗟倫谠唬?\"臣為陛下仙遊寺出家以禳灾。\"上甚喜，惜其去，不能阻，乃聽之。至仙遊不逾月，入京師持杯乞吝。人有布施者，琳戲之曰：\"尚有常施。\"後反為米骼舨可惺椋?選事。有選人通官，雲\"不穩便\"。又戲雲：\"只公此選得穩便否？\"冒埽?親點逆人簿，至琳。上曰：\"與卿平昔分深，相舍，甚欲赦卿，其如法何？持杯判官選，言猶在耳。當時戲談時，朕於爾時惶惶也。\"左右喝琳付法。","sortOrder":29},
  {"id":"s_work_dnl_21_30","chapterId":"ch_work_dnl_21","text":"李相國揆，以進士調集在京師，聞宣平坊王生善筮，往問之。王每以镪五百决一局，而來者甚多，自辰及酉，有未筮而空返者。揆持一缣晨往，生為之开卦，曰：\"君非文字之選乎？當河南道一尉。\"揆負才與門籍，不宜為此，頗忿而去。生曰：\"君無怏怏，自此數月，當拜左拾遺。前事固不准也。\"揆怒未解。生曰：\"若事验後，一過我。\"揆以書判不中第，補汴州陳留尉。以生之言有徵，复詣之。生於幾下取一卷書以授之，曰：\"君除拾遺，可视此書；不爾，當有大咎。\"得而藏之。既至陳留，時采訪使倪若水以揆才品族望，留假府職。會郡有事，須上請，擇與中朝通者無如揆，乃請行。關中郡府上書，姓李皆先謁宗正僊丅瘟嬾忋懜崋丆僊請為表三通，以次上之。明皇召僊曰：\"百官上表，無如卿者。\"僊頓首謝曰：\"此非臣所為，是臣從子陳留尉揆所為。\"乃召揆。時揆寓於遠房盧氏姑之舍。子弟聞召，且未敢出，及知上意，欲以推擇，遂出。既見，命宰臣试文詞。時陳黃門為題目三篇：其一曰《紫絲盛露囊賦》，二曰《答吐蕃書》，三曰《代南越獻白孔雀表》。既封，請曰：\"前二首無所恨，後一首或有所疑，願得詳之。\"乃許涂八字旁註。翌日，授左拾遺。旬餘，乃發王生書，三篇皆在其中，而涂註者亦如之。遽往宣平里訪王生，不复見矣。","sortOrder":30},
  {"id":"s_work_dnl_21_31","chapterId":"ch_work_dnl_21","text":"德宗時，楊炎、盧杞為宰相，皆奸邪用事，树立朋党，以至天子播遷，宗社幾覆。德宗懲辅相之失，自是除拜命令，不专委於中書。凡奏擬用人，十阻其七。貞元以後，宰相備位而已。每擇官，再三審覆，事多中輟。貞元三年八月，中書省無舍人，每有詔敕，宰相追他官為之。及兵部侍郎陆贽知政事，以上艱於選用，乃上疏論之。","sortOrder":31},
  {"id":"s_work_dnl_21_32","chapterId":"ch_work_dnl_21","text":"盧杞除虢州刺史，有奏\"虢州有官猪數千，常為人患。\"德宗曰：\"可移沙苑。\"杞對曰：\"同州豈非陛下百姓？為患一也。臣謂無用之物，與人食之為便。\"循宗叹曰：\"卿理虢州，而忧他郡百姓，宰相才也！\"由是有意作相。","sortOrder":32},
  {"id":"s_work_dnl_21_33","chapterId":"ch_work_dnl_21","text":"裴延齡恃恩輕躁，班列懼之，惟顧少連不避延齡。嘗畫一雕，群鳥噪之，以獻。上知眾怒，益信之，而竟不大用。","sortOrder":33},
  {"id":"s_work_dnl_21_34","chapterId":"ch_work_dnl_21","text":"相國窦參之败，給事中窦申配流。德宗曰：\"吾聞申欲至人家，則鵲喜。\"遂賜死。","sortOrder":34},
  {"id":"s_work_dnl_21_35","chapterId":"ch_work_dnl_21","text":"參貞元壬申三月，居光福里第，月夜閒步中庭，有寵妾上清者曰：\"今欲啟事。郎須到堂前，方敢言。\"窦亟上堂，上清曰：\"庭树上有人，請為避之。\"窦公曰：\"陆贽久欲傾奪吾權位，有人在庭树上，吾死之將至。具奏與不奏，皆受禍，必竄死於道路。汝辈流中不可多得，身死破家，汝定為宮婢。聖君如顧問，當為我辭。\"上清泣曰：\"誠如是，死生以之。\"窦公下階，大呼：\"树上人應是陆贽使來，能全老夫性命，敢不厚報！\"其人遂下，乃衣服者，曰：\"家有大丧，貧甚，不辦葬禮。伏知相公推心濟物，所以卜夜而來。\"參曰：\"某罄所有，當封絹千匹而已，方具修家廟赀，今以為赠。\"其人曰：\"請左右赍所賜絹，掷於牆外，某於街中俟之。\"參依其言。翌日，執金吾先奏之。德宗怒曰：\"卿交通節將，蓄養俠刺。位崇台鼎，更欲何求！\"參頓首曰：\"臣起自布衣小才，官已至貴，皆陛下奖拔，實不因人。今不幸至此，乃仇人所為爾！\"中使下殿，宣\"卿且歸私第，候進止。\"越月，貶郴州別駕。會宣武節度劉士寧通好於郴州，觀察使上聞。德宗曰：\"交通節度將，信而有徵。\"乃流參於州，以籍其家。未達流所，詔賜自盡。上清果隸掖庭。後數年，善應對，能煎茶，在帝左右。德宗曰：\"宮內人數不少，汝最了事。從何得至此？\"上清對曰：\"妾本故宰相窦參女奴。窦參家破填宮，得侍上。\"德宗曰：\"窦某罪不止養俠刺，亦甚有贓污，前納官銀器至多。\"上清流泣而言曰：\"窦參自御史丞，歷度支、戶部、鹽鐵三使，至宰相，首尾六年，月入數十萬。前後非時賞賜甚厚。乃者郴州所送納官贓物，皆是恩賜。當部錄日，妾在郴州，親見州縣希贽意旨，盡刮去所進銀器上刻藩镇官衔姓名，誣為贓物。乞陛下验之。\"於是宣索窦參没官銀器，覆其刻處，皆如上清言。德宗又問蓄養俠刺事，上清曰：\"本實無。此悉是陆贽陷害，使人為之。\"德宗怒陆曰：\"者獠奴！我脱却伊绿衫便與紫著，又常唤伊作陆九。我任使窦參，方稱意次，須教我枉殺却。及至權入伊手，其為软弱，甚於泥团。\"乃下詔雪參。時裴延齡探知陆贽恩衰，恣行媒孽，竟受譴不回。後上清特敕度為道士，終嫁為金忠義妻。世以陆贽門生多位顯者，不敢說，故此事絕無人知。","sortOrder":35},
  {"id":"s_work_dnl_21_36","chapterId":"ch_work_dnl_21","text":"裴佶常話：少時姑夫為朝官，有清望。佶至其居，會退朝，浩叹曰：\"崔昭何人，眾口稱美！此必行货賂者也。如此，安得不亂？\"言未訖，門者報曰：\"寿州崔使君候。\"姑夫怒，呵門者，將鞭之。良久，束帶強出。須臾，命茶甚急，又命饌，又令秣馬飯仆。佶曰：\"前何倨，後何恭？\"及入門，有喜色，揖佶而曰：\"憩外舍。\"未下階，出懷中一紙，乃赠官紇千匹。","sortOrder":36},
  {"id":"s_work_dnl_21_37","chapterId":"ch_work_dnl_21","text":"李司徒勉為开封縣尉，特善捕賊。時有不良试公之宽猛，乃潛納人賄，俾公知之。公召告吏卒曰：\"有納其賄者，我皆知之。任公等自陳首，不得過三日，過則舁榇相見。\"其納賄不良故逾限，而忻然自赍其榇。公令取石灰棘刺置於中，令不良入，命取釘釘之，送汴河訖。乃請見廉使，廉使叹賞久之。後公為大梁節度使，人問公曰：\"今有官人如此，如何待之？\"公曰：\"即打腿。\"","sortOrder":37},
  {"id":"s_work_dnl_21_38","chapterId":"ch_work_dnl_21","text":"盧舍人群、盧給事宏正相友善。群清瘦古淡，未嘗言朝市；宏正魁梧富貴，未嘗言山水。群日飲高臥，製詔多就宅草之；宏正未嘗在假告，有賓客皆就省相見。一日雪中，群在假，宏正將欲入省，因過群。群方道服，於南垣茅亭望山雪，促命延入，群曰：\"盧六盧六！曾莫顧我，何也？\"宏正曰：\"月限向滿，家食相仍，且詣宰府，以求外任。\"群曰：\"奔走權門，所不忍视，腊酒一壶，能共醉否？\"宏正曰：\"切欲詣省。\"群又呼侍兒曰：\"盧六待去，早來藥糜宜匀越器中，我與給事公對食。\"宏正曰：\"不可，今旦犯冷，已買血蒜羹餐矣！\"","sortOrder":38},
  {"id":"s_work_dnl_21_39","chapterId":"ch_work_dnl_21","text":"劉太真為《陳少遊行状》，比之齊桓、晉文，時議喧騰。後坐貢院用情，追责前事，貶信州刺史。","sortOrder":39},
  {"id":"s_work_dnl_21_40","chapterId":"ch_work_dnl_21","text":"韦太尉之在西川，凡軍士將有婚嫁，則以熟錦衣給其夫，以銀泥衣給其妻，又各給錢一萬，死丧稱是。精訓練，待之如敬客。極其聚斂，軍府浸盛，而民困矣！晚年終至劉辟之亂，天下譏之。","sortOrder":40},
  {"id":"s_work_dnl_21_41","chapterId":"ch_work_dnl_21","text":"劉辟初有心疾，人自外至，辄辟而吞之。同府崔佐特硕大，辟據地而吞，背裂血流。獨盧文若至不吞，故後自惑。","sortOrder":41},
  {"id":"s_work_dnl_21_42","chapterId":"ch_work_dnl_21","text":"國子司業韦聿者，皋之兄也。朝中以為戲弄。或言九宮休咎，聿曰：\"我家白方常在西南，二十年矣！\"","sortOrder":42},
  {"id":"s_work_dnl_21_43","chapterId":"ch_work_dnl_21","text":"權相為舍人，以門望自處，常戲同僚曰：\"未嘗以科第為資。\"鄭雲逵謔曰：\"更有一人。\"遽問：\"誰？\"答曰：\"韦聿。\"滿座皆笑。","sortOrder":43},
  {"id":"s_work_dnl_21_44","chapterId":"ch_work_dnl_21","text":"汴州相國寺，言佛像有流汗。劉元佐遽命駕，自持金帛以施。日中，其妻亦至。明日，复起斋場。由是將吏商贾，奔走道路，如恐不及。因令官為簿書，以籍所入。十日，乃閉寺門，曰：\"汗止矣！\"所得蓋鉅萬，計以贍軍。","sortOrder":44},
  {"id":"s_work_dnl_21_45","chapterId":"ch_work_dnl_21","text":"崔膺性狂，張建封愛其文，引為客，隨建封行營。夜中大叫驚軍，軍士皆怒，欲食其肉，建封藏之。明日置宴，監軍曰：\"某與尚書約，彼此不得相违。\"建封曰：\"唯。\"監軍曰：\"某有請，請崔膺。\"建封曰：\"如約。\"逡巡，建封又曰：\"某有請，亦請崔膺。\"坐中皆笑，乃得免。","sortOrder":45},
  {"id":"s_work_dnl_21_46","chapterId":"ch_work_dnl_21","text":"李實為司農卿，督责官租。萧居丧，输不及期，實怒，召至，租車亦至，得不罪。會有賜與，當謝状，秉筆者有故未至，實乃曰：\"召衣齊衰者。\"至，立為草状，實大喜，延英面荐。德宗令問丧期，屈指以待。及釋服日，以處士拜拾遺。有文學，喜書畫，好彈琴，其拔擢乃偶然耳。","sortOrder":46},
  {"id":"s_work_dnl_21_47","chapterId":"ch_work_dnl_21","text":"鄭雲逵與王彦伯鄰，嘗有客求医，誤造雲逵，诊曰：\"熱風。\"客又請藥方，雲逵曰：\"藥方即不如東家王供奉。\"客驚而去。自是京城目乖宜者為\"熱風\"。","sortOrder":47},
  {"id":"s_work_dnl_21_48","chapterId":"ch_work_dnl_21","text":"王仲舒為郎中，與馬逢友善。每责逢曰：\"貧不可堪，何不求碑志相救？\"逢笑曰：\"適見人家走馬呼医，立可得也。\"","sortOrder":48},
  {"id":"s_work_dnl_21_49","chapterId":"ch_work_dnl_21","text":"許尚書孟容與宋濟為布衣交。及許知舉，宋不中第。放榜後，許自愧，累請人致意，兼令門生就見，宋乃謁許。深謝之。因置酒，酣，乃曰：\"某今年為國家取卿相。\"時有姚嗣及第，數日卒。乃起慰許曰：\"邦國不幸，姚令公薨謝。\"","sortOrder":49},
  {"id":"s_work_dnl_21_50","chapterId":"ch_work_dnl_21","text":"鄭戶性通脱，與諸甥侄談笑無間。曾被飄瓦所击，頭血淋漓，兩玉簪俱碎。家人惶遽來视，外甥王某在後至，曰：\"二十舅，今日頭璧俱碎。\"戶大叫曰：\"我不痛！\"裹傷命酒，酣飲盡興。","sortOrder":50},
  {"id":"s_work_dnl_21_51","chapterId":"ch_work_dnl_21","text":"顧况從辟，與府公相失，揖出幕，况曰：\"某夢口與鼻爭高下。口曰：'我談今古是非，爾何能居我上？'鼻曰：'飲食非我不能辨。'眼謂鼻曰：'我近鑒豪端，遠察天际；惟我當先。'又謂眉曰：'爾有何功，居我上？'眉曰：'我雖無用，亦如世有賓客，何益主人？無即不成禮儀；若無眉，成何面目？'\"府公悟其譏，待之如初。又舊說：顧况與韦夏卿飲酒，時金氣已殘，夏卿請席徵秋後意，或曰\"寒蝉鳴\"，或曰\"班姬扇\"，而况雲\"馬尾\"，眾哂之，曰：\"此非在秋後乎？\"","sortOrder":51},
  {"id":"s_work_dnl_21_52","chapterId":"ch_work_dnl_21","text":"郎中故事：吏部郎中二廳，先南曹，次废置。刑部分兩賦，其製尚矣。","sortOrder":52},
  {"id":"s_work_dnl_21_53","chapterId":"ch_work_dnl_21","text":"舊說：吏部為\"南省舍人\"，考功、度支為\"振行\"，比部得廊下食，以飯。從者號曰\"比盤\"。二十四曹呼左右司為\"都公\"，省中語曰：\"後行祠、屯，不博中行都門；中行刑部，不博前行駕、库。\"","sortOrder":53},
  {"id":"s_work_dnl_21_54","chapterId":"ch_work_dnl_21","text":"故事：度支郎中判入，員外判出，侍郎總統，押案而已。乾元已後始為使額。","sortOrder":54},
  {"id":"s_work_dnl_21_55","chapterId":"ch_work_dnl_21","text":"郎官當直，發敕為重。水部員外劉約直宿，會河內系囚配流嶺表，夜發敕符，直宿令史又不更事，惟下嶺表，不下河北。旬月後，本州聞後，約遂出官。","sortOrder":55},
  {"id":"s_work_dnl_21_56","chapterId":"ch_work_dnl_21","text":"貞元末，有郎官四人，自行軍司馬賜紫而登郎署，省中謔為\"四君子\"。","sortOrder":56},
  {"id":"s_work_dnl_21_57","chapterId":"ch_work_dnl_21","text":"郎士元詩句清絕輕薄，好為剧語，每雲：\"郭令公不入琴，馬镇西不入茶，田承嗣不入朝。\"馬知此，語之曰：\"郎中言燧不入茶，請左顧為設也。\"即依期而往。時豪家食次，起羊肉一斤，層布於巨胡餅，隔中以椒豉，润以酥，入爐迫之，候肉半熟食之，呼為\"古樓子\"。馬晨起啖古樓子以佇，士元至，馬喉乾如窯，即命急烹茶，各啜二十餘甌。士元已老，虛冷腹脹，屢辭，馬辄曰：\"'馬镇西不入茶'，何遽辭也？\"如此又七甌。士元固辭而起，及馬，氣液俱下。因病數旬，馬乃遺絹二百匹。","sortOrder":57},
  {"id":"s_work_dnl_21_58","chapterId":"ch_work_dnl_21","text":"貞元初，穆寧為和州刺史，其子故宛陵尚書及給事列侍寧前。時穆家法最峻，寧命諸子直饌，稍不如意，則杖之。諸子至直日，必探求珍異，羅列鼎俎，或不中意，未嘗免笞。一日給事直饌，鼎前有熊白及鹿，曰：\"白肥而瘠相滋，其宜乎？\"遂试以白裹改進，寧果再飯。宛陵諸季视之，喜形於色，曰：\"非惟免笞，兼當受賞。\"寧飯訖，曰：\"今日誰直？可與杖俱來。有此佳味，奚進之晚？\"","sortOrder":58},
  {"id":"s_work_dnl_21_59","chapterId":"ch_work_dnl_21","text":"寶應中，員外郎窦庭芝分司東都，敬事卜者葫芦生，言吉凶多中，往來甚頻。一日，入門甚叹惋，庭芝問之，曰：\"君家大禍將至，舉族恐無遺類。\"庭芝惶恐，問所以避之者。雲：\"非遇黃中君、鬼穀子，不可救。然黃中君難見，但見鬼穀子，當無患矣。\"具說形貌服飾，令浃旬求之。於是窦與兄弟群從，洎妻子奴仆，晓夕求訪於洛下。時李鄴侯居忧於河清縣，騎驢入洛，至中桥南，遇大尹避道，驢驚逸而走，径入庭芝所居，與仆者共造其門。值車馬將出，忽見鄴侯，皆驚视之。俄有人出雲：\"此是分司窦員外宅，所失驢收在馬廄，請客入座，員外嘗願修謁。\"如此者數四。不獲已，就其第。庭芝出，降階而拜，延接殷勤，遂至信宿。至於妻孥，鹹備家人之禮。數日告去，赠送甚厚，但雲：\"貴達之日，願以一家為托。\"鄴侯居於河清，信使旁午於道。（原註：庭芝初與鄴侯相值，葫芦生遽至其家，雲：\"既遇此人，無复忧矣！\"）及朱弥遙ブシ轎賂?觀察，德宗幸奉天，遂降；賊平，德宗首命誅之。鄴侯自南嶽徵回，因第賊臣罪状，請庭芝减死。上不許，雲：\"卿以為寧王姻党乎？\"（原註：庭芝姊為寧王妃）鄴侯具白以舊事，上乃原其罪。鄴侯始奏，上密使中官夜乘傳陝州問之，與庭芝雲符合。德宗曰：\"黃中君，蓋我也；謂卿為鬼穀子，何也？\"（原註或雲：李氏之先君靈城，在清穀前、濁穀後，恐以此言之）","sortOrder":59},
  {"id":"s_work_dnl_21_60","chapterId":"ch_work_dnl_21","text":"窦相易直，幼時名秘。家貧，就業田里，其師事老叟有道術，而人不知。一日，忽風雪暴至，學童皆不果歸，宿於漏屋下。天寒，爭近火，唯窦相寢於榻。夜深方覺，叟撫公令起，曰：\"窦秘，君後為人臣，貴寿之極，勉自愛也！\"及德宗幸奉天，易直方舉進士，亦隨駕西行。乘一蹇驢至开遠門，路隘，門將阖，公懼势不可進，聞一人叱驢，兼其後，得疾馳而出。顧見一黑衣卒呼曰：\"秀才！他日莫忘闾倩。\"及拜相，訪得其子，提挈累至大官。","sortOrder":60},
  {"id":"s_work_dnl_21_61","chapterId":"ch_work_dnl_21","text":"趙、盧邁二相，皆吉州旅客，人人呼趙七、盧三。趙相自微而著，蓋為是姚廣女婿。姚與獨孤問俗善，因托之，得作湖南判官，累授官至監察。萧复相代問俗為潭州，有人又荐於萧，萧留為判官，至侍御史。萧入，主留務，有美聲，聞於德宗，遂兼中丞，為湖南廉使。及李泌入相，不知之，俄而除替。既罢任，遂入京。李玄素知湖南政事多善，意甚慕之。閒居慕靜，深巷杜門不出，玄素訪之甚頻。玄素乃是泌相之徒弟也，原因其相訪，引玄素於青龍寺，謂之曰：\"趙亦自有官職，誓不敢怨他人也。非偶然耳，蓋得於日者焉。\"遂同訪之，問玄素年命，謂之曰：\"公亦富貴人也。\"玄素因自負，亦不言於泌相兄也。德宗忽記得，賜拜給事中。泌相不测其由。會有和戎使事，出新相關播為大使，張荐、張式為判官，泌因乃奏為副使。未至西蕃，右丞有闕，宰相上名，德宗曰：\"趙堪為此官。\"進拜右丞。不數月，遷尚書左丞平章事，五年，薨於位。此乃吉州旅人趙七郎之变化也。","sortOrder":61},
  {"id":"s_work_dnl_21_62","chapterId":"ch_work_dnl_21","text":"苗晉卿困於科舉。一年，似得复落。春時，携酒乘驢出都門，藉草而眠。既覺，有老父坐於旁，因以餘杯飲之。老父愧謝曰：\"郎君萦悒耶？要知前事乎？\"晉卿曰：\"某應舉已久，有一第乎？\"曰：\"大有事，但問之。\"苗曰：\"某久窮，羨一郡，寧可及乎？\"曰：\"更向上。\"\"廉察乎？\"曰：\"更向上。\"苗乘酒，遂曰：\"將相乎？\"曰：\"更向上。\"苗怒而不信，因扬言曰：\"將相更向上，天子也？\"老父曰：\"真者不得，假者即得。\"苗以為怪誕，揖之而去。後果為將相。及德宗崩，攝冢宰三日。","sortOrder":62},
  {"id":"s_work_dnl_21_63","chapterId":"ch_work_dnl_21","text":"司空曾為楊丞相炎判官，故盧新州見忌，欲出之。公見桑道茂，道茂曰：\"年內出官。\"官名遺忘。福寿果然。","sortOrder":63},
  {"id":"s_work_dnl_21_64","chapterId":"ch_work_dnl_21","text":"盧華州，予之堂舅氏也。嘗於元載宅門，見一人頻至其門，上下瞻顧。盧疑其人，乃邀以歸，且問\"元相何如\"？曰：\"新相將出，舊者須去。吾已見新相矣，一人緋，一人紫；一人街西住，一人街東住：皆惨服也。然二人皆身小而不知姓名。\"不經旬日，王、元二相下獄。德宗以劉晏為門下，楊炎為中書，外皆傳說必定，疑其言不中。時國舅吳凑見王、元事訖，因贺德宗而啟之，曰：\"新相欲用誰人？\"德宗曰：\"劉、楊。\"凑不語。上曰：\"五舅意如何？言之無妨。\"吳曰：\"二人俱曾用也，行當可見。陛下何不用後來俊杰？\"上曰：\"為誰？\"吳乃奏常袞及某乙。翌日併用，拜二人為相，以代王、元，果如其說。緋紫、短小，街之東西，無不验者。","sortOrder":64},
  {"id":"s_work_dnl_21_65","chapterId":"ch_work_dnl_21","text":"桑道茂之門有一嫗，無所知，大开卜肆。自桑而卜回者，必曰：\"嫗於桑門賣卜，必有異也。\"筮畢必來覆之。桑言休，則嫗言咎；桑言咎，則嫗言休。厥後中否，嫗、桑各半。","sortOrder":65},
  {"id":"s_work_dnl_21_66","chapterId":"ch_work_dnl_21","text":"長安風俗：貞元侈於遊宴，其後或侈於書法、圖畫，或侈於博奕，或侈於卜咒，或侈於服食，各有自也。","sortOrder":66},
  {"id":"s_work_dnl_21_67","chapterId":"ch_work_dnl_21","text":"順宗時，五坊鷹犬恣橫，州縣不能製。多於民間張罘，或有誤傷一鳥雀者，必多得金帛乃止，時謂\"供奉鳥雀\"。","sortOrder":67},
  {"id":"s_work_dnl_21_68","chapterId":"ch_work_dnl_21","text":"劉禹錫為屯田員外郎，旦夕有騰超之势。知一僧有術數，寓直日邀至省。方欲問命，報韦秀才在門外，不得已見之，令僧坐帘下。韦獻卷已，略省之，意色頗倦。韦覺告去，僧吁叹良久，曰：\"某欲言，員外心不愜，如何？員外後遷，乃本曹郎中也。然須待適來韦秀才知印處置。\"禹錫大怒，揖出之。不旬日，貶官。韦乃處厚相，二十餘年，在中書。禹錫轉為屯田郎中。","sortOrder":68},
  {"id":"s_work_dnl_21_69","chapterId":"ch_work_dnl_21","text":"韦崖州執誼自幼不喜聞嶺南州縣。拜相日，出外舍，一見《州郡圖》，遲回不敢看。良久，臨起誤视，乃《崖州圖》。後竟貶於此。","sortOrder":69},
  {"id":"s_work_dnl_21_70","chapterId":"ch_work_dnl_21","text":"裴晉公度少時羁寓洛中，嘗乘驢入皇城，上天津桥。時淮西用兵已數年矣。有二老人傍桥柱立，相語雲：\"蔡州用兵日久，徵發正困於人，未知何時得平定？\"忽睹裴公，驚愕而退。有仆携書囊後行，相去稍遠，聞老人雲：\"適忧蔡州未平，須待此人為將。\"既歸，其仆白之，裴曰：\"見我龍鐘，相戲爾！\"其秋東府乡荐，明年登第。及為相，請讨伐淮西，遂平。後守洛時，對客每話天津桥老人事。","sortOrder":70},
  {"id":"s_work_dnl_21_71","chapterId":"ch_work_dnl_21","text":"裴中令應舉，詣葫芦生問命。未之許，謂無科級之分。试日，排高上門，人馬擁併。見一婦人，類贾客之妻，從女奴皆衣服鮮絜，挈一合，以紫帕封。女奴力倦，置於門，門辟，失婦人所在，合复在傍，公以衫裾衛之，意為他人所購，冀其主复至。舉人悉集，公獨在門，日晏終不去。久之，婦人方悲號，公詰其冤抑，以状答曰：\"夫犯刑憲，其案已圓在朝夕。某家素丰，蓄一寶帶，會有能救護者，與數萬缗，至羅錦，悉不取，唯須此帶。今早晨親遣女使更持送，忽失所在，吾夫不免矣！\"公識其主，即以予之。婦人再拜，泣謝而去。试不及，免罢一舉。他日复訪葫芦生，生見公，驚曰：\"君非去年相遇者耶？君將來及第，兼位極人臣，蓋近有陰德。\"","sortOrder":71},
  {"id":"s_work_dnl_21_72","chapterId":"ch_work_dnl_21","text":"裴晉公為盜所傷，隸人王義刃死之，乃自為文以祭之，厚給妻孥。是歲進士為《王義傳》者甚眾。","sortOrder":72},
  {"id":"s_work_dnl_21_73","chapterId":"ch_work_dnl_21","text":"皇甫氣貌刚质，性褊直。為尚書郎，乘酒使氣，忤同列；及醒，不自適，求分務洛都。值洛中仍歲乏食，正郎滯曹不遷，俸甚微，困悴甚。嘗因積雪，門無轍跡，厨突無煙。裴晉公保厘洛宅，人有以為言者，由是辟為留府從事，公常優容之。先是，公讨淮西日，恩賜鉅萬，貯於集賢私第。公素奉佛，因盡舍所得，再修福先寺。既成，將請白居易為碑。曰：\"近舍而遠徵白，信獲戾於門下矣！\"公曰：\"初不敢以仰煩，慮為大手筆見拒，是所願也。\"因請斗酒而歸，獨飲其半，乘醉揮毫，立就。又明日，挈本以獻。文思高古，字复怪僻、公尋繹久之，叹曰：\"木玄虛、郭景純、《江》、《海》之流也！\"（原註：其碑在寺西北廊玉石童院，洛中人家往往有本）命小將以車馬繒彩器玩約千餘缗酬之。省書，掷於地，面叱小將曰：\"寄謝侍中，何相待之薄也！之文，非常流之文也，曾與顧况為《集序》外，未嘗造次許人者；請製此碑，蓋受恩深厚耳，其詞約三千餘字，每字三匹絹，更减五分錢不得。\"小校具以白，公笑曰：\"真不羁之才。\"立遣依數酬之（原註：其字共三千二百五十有四，計送絹九千七百六十有二。後寺之老僧曰師約者，細為人說，其數亦同）。自居守府及里第，輦負相屬，洛人聚觀之。褊急之性，獨異於人。嘗為蜂螫手指，因大躁忿，命奴仆及里中小兒，箕斂蜂窠，以厚价購之。頃之，聚於庭，則命以砧臼絞取其汁，以涂所痛。又其子松，嘗錄詩數首，字小誤，大骂躍呼，取杖不及，齒嚙其臂，血流及肘。","sortOrder":73},
  {"id":"s_work_dnl_21_74","chapterId":"ch_work_dnl_21","text":"李公镇宣武，好琴書。自造琴，取新舊桐材扣之，合律者裁而膠缀。所蓄二琴殊絕，其名\"响泉\"、\"韻磬\"者也。性不喜俗間聲音，有二寵奴，號秀奴、七七，善琴筝與歌，時遣奏之。有撰琴譜。兵部員外郎約，公之子也。以近屬宰相子，而有德量，多材藝，不邇聲色，善接引人物，而不好俗談。晨起，草裹頭，對客蹙容，便過一日。多蓄古器，在润州嘗得古鐵一片，击之清越。養一猿，名山公，常與相隨。嘗月夜獨泛江，登金山，击鐵鼓琴，猿必嘯和。高陆令趙亻參夫人韦氏，即兵部之姨妹也。說公徐夫人生二子；中年於徐夫人小乖，及兵部生，情好复初，而君於諸子中寶愛懸隔。在官所俸祿，付與從子，一不問數，唯給奉崔氏、元氏二孀姊。元氏亦有美行，祭酒華陰公為之傳。君初至金陵，於李亻參坐，屢贊招隱寺之美。一日，宴於寺中，明日謂君曰：\"十郎常夸招隱寺，昨遊宴細看，何殊州中？\"君笑曰：\"某所賞者疏野耳！若遠山將翠幕遮，古松用彩物裹，腥膻僱鹿踣泉，音樂亂山鳥聲，此則實不如在叔父大廳也。\"大笑。性又嗜茶，能自煎，曰：\"茶須缓火炙，活火煎。\"活火，謂炭火之有焰者也。客至不限甌數，竟日執茶器不倦。嘗奉使行至陝州石硤縣東，愛渠水，留旬日，忘發。","sortOrder":74},
  {"id":"s_work_dnl_21_75","chapterId":"ch_work_dnl_21","text":"李之擒也，侍婢一人隨之，裂帛自書管攉之功，言為張子良所賣。教侍婢曰：\"結之於帶。吾若從容奏對，當為宰相，扬、益節度；不得，受極刑矣。我死，汝必入禁中。上問汝，當以此進。\"及伏法，京師大霧，三日不解。憲宗得帛書，頗疑其冤，內出黃衣一袭賜子，敕京兆收葬。","sortOrder":75},
  {"id":"s_work_dnl_21_76","chapterId":"ch_work_dnl_21","text":"孝明鄭太後，润州人也，本姓爾朱氏。相者言其當生天子。李據浙西反，納之。誅後，入掖庭，為郭太後侍兒。憲宗皇帝幸之，生宣宗，即位，尊為太後。懿宗立，尊為太皇太後。又七年崩，以郭太後配饗，出祭別廟。","sortOrder":76},
  {"id":"s_work_dnl_21_77","chapterId":"ch_work_dnl_21","text":"段相文昌，少寓江陵，甚貧窭。每聽曾口寺斋鐘動，詣寺求食，寺僧厭之，乃斋後扣鐘，冀其來不逮食。後登台辅，出镇荆南，題詩曰：\"曾遇梨飯後鐘。\"文昌晚貴，以金連花盆盛水濯足，徐相商以書規之。文昌曰：\"人生幾何，要酬平生不足也！\"（原註：或曰，此詩是王相播事）","sortOrder":77},
  {"id":"s_work_dnl_21_78","chapterId":"ch_work_dnl_21","text":"文昌少孤，寓居廣陵之瓜洲，家貧力學。夏月訪親知於城中，不遇，飢甚，於路中拾得一錢，道旁買瓜，置於袖中。至一宅，門阒然，入其廄內，以瓜就馬槽破之。方次，老仆聞击槽聲，躍出，责以擅入廄；驚懼，弃之而出。镇淮海，常對賓客說之。在中書廳事，地衣皆錦繡，諸公多撤去，而文昌每令整飭。方踐履。同列或勸之，文昌曰：\"吾非不知，常恨少貧太甚，聊以自慰爾。\"","sortOrder":78},
  {"id":"s_work_dnl_21_79","chapterId":"ch_work_dnl_21","text":"元和中，有老卒推倒《平淮西碑》，官司钅鹹其項，又以枷击守獄者。憲宗怒，命縛來殺之。既至京，上曰：\"小卒何故毀大臣所撰碑？\"卒曰：\"乞一言而死。碑文中有不了語，又击殺陛下獄卒，所願於聞奏。文中美裴度，不還李功，是以不平。\"上命釋縛賜酒食，敕翰林學士段文昌別撰。案：妻入訴禁中，乃命段文昌撰文，其時碑尚未立，安得推倒？","sortOrder":79},
  {"id":"s_work_dnl_21_80","chapterId":"ch_work_dnl_21","text":"於襄陽雲：\"今之方面，權勝於列國諸侯遠矣。且硌閡蛔鄭禾煜拢?供給承禀；列國止於我疆而已，不亦勝乎！\"","sortOrder":80},
  {"id":"s_work_dnl_21_81","chapterId":"ch_work_dnl_21","text":"於司空以樂曲有《想夫怜》，其名不雅，將改之，客笑曰：\"南朝相府曾有瑞莲，故歌曰'相府莲'，自是後人語訛。\"乃不改。古解題曰：\"《相府莲》者，王俭為南齊相，一時所辟皆才名之士，時人以入俭府為入莲花池，謂如紅莲映绿水，今號'莲幕'者自俭始。其後語訛為《想夫怜》，亦名之丑爾。\"又有《簇拍相府莲》，《樂苑》曰：\"《想夫怜》，羽調曲也。\"白居易詩曰：\"玉管朱絃莫急催，客廳歌送十分杯；長愛夫怜第二句，倩君重唱夕陽开。\"王維右丞詞雲\"秦川一半夕陽开\"是也。\"夜聞鄰婦泣，切切有餘哀。即問緣何事，征人戰未回。\"《簇拍相府莲》：\"莫以今時寵，寧忘舊日恩。看花滿眼淚，不共楚王言。\"\"閨燭無人影，羅屏有夢魂。近來音耗絕，終日望應門。\"","sortOrder":81},
  {"id":"s_work_dnl_21_82","chapterId":"ch_work_dnl_21","text":"衛侍郎次公在吏部，避嫌，宗從皆不註擬。有從於申甫，自江淮來調選，因告主吏曰：\"但得官，便出城。即可矣。\"遂馆申甫於別第。未幾，拨江南令，將出城，為次公老仆所遇，不得已，見次公。次公詰其由，申甫以實對。次公曰：\"今年所註，不省有汝姓名。\"验其签名，則次公署之也，乃召主吏，貸其罪以問之。吏曰：\"凡所取押，皆冒。\"次公叹曰：\"某慮不及此！\"遂遣赴官。","sortOrder":82},
  {"id":"s_work_dnl_21_83","chapterId":"ch_work_dnl_21","text":"王智興以使侍中罢镇歸京，親情有以選事求嘱，智興固不肯應。選人恳請，遂致一衔與吏部侍郎。吏部印尾状雲：\"選人名衔謹領訖。\"智興曰：\"不知侍中亦有用處。\"","sortOrder":83},
  {"id":"s_work_dnl_21_84","chapterId":"ch_work_dnl_21","text":"崔相群之镇徐州，嘗以《焦氏易林》自筮，遇《乾》之《大畜》，其繇曰：\"曲束法書，藏在蘭台。雖遭亂潰，獨不遇灾。\"及經王智興之变，果除秘書監。","sortOrder":84},
  {"id":"s_work_dnl_21_85","chapterId":"ch_work_dnl_21","text":"元和十五年，太常少卿李建知舉，放進士二十九人。時崔嘏舍人與施肩吾同榜。肩吾寒進。為嘏瞽一目，曲江宴賦詩，肩吾雲：\"去古成，著虫為虾。二十九人及第，五十七眼看花。\"","sortOrder":85},
  {"id":"s_work_dnl_21_86","chapterId":"ch_work_dnl_21","text":"裴坦為職方郎中、知製誥，裴相休以坦非才，不稱，力拒之，不能得。命既行，坦至政事堂謁謝丞相。故事：謝畢便於本院上事，宰臣送之，施一榻壓角坐，而坦巡謁執政，至休多输感激。休曰：\"此乃首台谬選，非休力也。\"立命肩舆便出，不與之坐。兩閣老吏雲：\"自有中書，未有此事。\"人為坦恥之。至坦知貢舉，擢休子宏上第，時人稱欲蓋而彰。","sortOrder":86},
  {"id":"s_work_dnl_21_87","chapterId":"ch_work_dnl_21","text":"劉虛白與太平裴坦相知。坦知舉，虛白就试，因投詩曰：\"三十年前此夜中，一般燈燭一般風。不知人世能多許，猶著麻衣待至公。\"坦感之，與及第。","sortOrder":87},
  {"id":"s_work_dnl_21_88","chapterId":"ch_work_dnl_21","text":"安邑李相公吉甫，初自省郎為信州刺史。時吳武陵郎中，貴溪人也，將欲赴舉，以哀情告州牧；赠布帛數端。吳以輕鮮，以書讓焉。其詞唐突，不存桑梓之分，併却其禮，李公不悅，妻諫曰：\"小兒方求成人，何得與舉子相忤？\"遂與米二百斛，李公果憾之。元和二年，崔侍郎重知貢舉，酷搜江湖之士。初春，將放二十七人及第，持名來呈相府。才見首座李公，公問；\"吳武陵及第否？\"主司恐是舊知，遽言及第，其榜尚在懷袖。忽報中使宣口敕，且揖禮部從容，遂註武陵姓字呈李公，公謂曰：\"吳武陵至粗人，何以當科第？\"禮部曰：\"吳武陵德行未聞，文筆乃堪扌采錄。名已上榜，不可却也。\"相府不能移，唯唯而從之。吳君不附國庠，名第在於榜末。是日，既集省門，謂同年曰：\"不期崔侍郎今年倒排榜也。\"觀者皆訝焉。","sortOrder":88},
  {"id":"s_work_dnl_21_89","chapterId":"ch_work_dnl_21","text":"永寧王二十、光福王八二相，皆出於先安邑李丞相之門。安邑薨於位，一王素服受慰；一王則不然，中有变色，是誰過欤？又曰：\"李安邑之為淮海也，树置裴光德，及去則除授不同。\"李再入相，對憲宗曰：\"臣路逢中人送節與吳少陽，不勝憤憤。\"聖顏然。翌日，罢李丞相蕃為太子詹事，蓋與節是蕃之謀也。又論：征元濟時饋運使皆不得其人，數日，罢光德為太子賓客；主饋運者，裴之所除也。劉禹錫曰：\"宰相皆用此势，自公孫弘始，而增穩妙焉。但看其《傳》，當自知之。萧曹之時，未有斯作。\"","sortOrder":89},
  {"id":"s_work_dnl_21_90","chapterId":"ch_work_dnl_21","text":"劉禹錫守連州，替高霞寓，後入為羽林將軍（案《唐書·高霞寓傳》：霞寓由歸州刺史，入為右衛大將軍，與劉禹錫之守連州無涉，疑有脱誤）。自京附書，曰：\"以承眷，辄請自代矣。\"公曰：\"感。然有一話：曾有老嫗山行，見一獸，如大虫，羸然跬步而不進，若傷其足者。嫗因即之，而虎舉前足以示嫗，嫗看之，乃有芒刺在掌下，因為拔之。俄而奋迅阚吼，別嫗而去，似愧其恩者。及歸，翌日，自外掷麋鹿狐兔至於庭者，日無闕焉。嫗登垣视之，乃前傷虎也，因為親族具言其事，而心異之。一旦，忽掷一死人，血肉狼藉，乃被村人凶者呵捕，雲'殺人\"。嫗具說其由，始得釋縛。乃登垣伺其虎至而語之，曰：'感則感矣。叩頭大王，已後更莫抛人來也！'\"","sortOrder":90},
  {"id":"s_work_dnl_21_91","chapterId":"ch_work_dnl_21","text":"劉禹錫曰：\"史氏所貴著作起居註，橐筆於螭首之下，人君言動皆書之，君臣啟沃皆記之，後付史氏記之，故事也。今起居惟寫除目，著作局可張雀羅，不亦倒置乎？\"","sortOrder":91},
  {"id":"s_work_dnl_21_92","chapterId":"ch_work_dnl_21","text":"劉禹錫曰：\"大抵諸物須酷好則無不佳，有好騎者必蓄好馬，曰好瑟者必善彈。皆好而別之，不必富貴而亦獲之。\"韦絢曰：\"蔡邕焦尾，王戎牙筹，若不酷好，豈可得哉！\"","sortOrder":92},
  {"id":"s_work_dnl_21_93","chapterId":"ch_work_dnl_21","text":"劉禹錫雲：\"韓十八愈直是太輕簿。謂李二十六程曰：'某與丞相崔大群同年往還，直是聰明過人。'李曰：'何處是過人者？'韓曰：'共愈往還二十餘年，不曾過愈論著文章，此是敏慧過人也。'\"","sortOrder":93},
  {"id":"s_work_dnl_21_94","chapterId":"ch_work_dnl_21","text":"韓十八初貶之製，席十八舍人為之詞，曰：\"早登科第，亦有聲名。\"席既物故，友人曰：\"席無令子弟，豈有病陰毒傷寒而與不絜吃耶？\"韓曰：\"席十八吃不絜太遲。\"人問曰：\"何也？\"曰：\"出語不是當。\"蓋忿其责詞雲\"亦有聲名\"耳。","sortOrder":94},
  {"id":"s_work_dnl_21_95","chapterId":"ch_work_dnl_21","text":"韓退之有二妾，一曰絳桃，一曰柳枝，皆能歌舞。初使王庭凑，至寿陽驿，絕句雲：\"風光欲動別長安，春半邊城特地寒；不見園花兼巷柳，馬頭惟有月团团。\"蓋有所屬也。柳枝後逾垣遁去，家人追獲。及镇州初歸，詩曰：\"別來楊柳街頭树，摆弄春風只欲飛。還有小園桃李在，留花不放待郎歸。\"自是，专寵絳桃矣。","sortOrder":95},
  {"id":"s_work_dnl_21_96","chapterId":"ch_work_dnl_21","text":"元和中，郎吏數人，省中縱酒話平生，各言愛尚及憎怕者。或言愛圖畫及博奕，或怕妄與。工部員外汝南周願獨雲：\"愛宣州觀察使，怕大虫。\"","sortOrder":96},
  {"id":"s_work_dnl_21_97","chapterId":"ch_work_dnl_21","text":"初，百官早朝，必立馬建福望仙門外，宰相則於光宅車坊，以避風雨。元和初，始置待漏院。","sortOrder":97},
  {"id":"s_work_dnl_21_98","chapterId":"ch_work_dnl_21","text":"元和末，有敕申明父子兄弟無同省之嫌。自是楊於陵任尚書，其子侄兄弟分曹者，亦有數人。","sortOrder":98},
  {"id":"s_work_dnl_21_99","chapterId":"ch_work_dnl_21","text":"沙陀本突厥餘种。元和中，三千人歸順，隸京西，節度使范希朝主之。弓馬雄勇，冠於諸蕃。","sortOrder":99},
  {"id":"s_work_dnl_21_100","chapterId":"ch_work_dnl_21","text":"進士何儒亮，自外方至京師，將謁從叔，誤造郎中趙需宅。自雲同房。會冬，需欲家宴，揮霍之际，既是同房，便入宴。姑姊妹盡在列，儒亮饌彻徐出，細察，乃何氏子，需笑而遣之。某按：此事是趙贊侍郎與何文哲尚書。相與鄰居時，俱侍御史，水部趙郎中需方應舉，自江淮來，投刺於贊，誤造何侍御第。何，武臣也，以需進士，稱猶子謁之，大喜，因召入宅。不數日，值元日，骨肉皆在坐，文哲因謂需曰：\"侄之名宜改之。且'何需'，似涉戲於姓也。\"需乃以本氏告，文哲大愧，乃厚遣之而促去。需之孫頊，前國學明經；文哲侄孫繼，為杭之戎吏，皆說之相符，而併無儒亮之說。《國史補》所記乃誤耶？","sortOrder":100},
  {"id":"s_work_dnl_21_101","chapterId":"ch_work_dnl_21","text":"西蜀官妓曰薛涛者，辯慧知詩。嘗有黎州刺史（原註：失姓名）作《千字文令》，帶禽魚鳥獸，乃曰：\"有虞陶唐。\"坐客忍笑不罰。至薛涛雲：\"佐時阿衡。\"其人謂語中無魚鳥，請罰。薛笑曰：\"'衡'字尚有小魚子；使君'有虞陶唐'，都無一魚。\"賓客大笑，刺史初不知覺。","sortOrder":101},
  {"id":"s_work_dnl_21_102","chapterId":"ch_work_dnl_21","text":"白太傅與元相國友善，以詩道著名，時號\"元白\"。其集內有詩說元相公雲：\"相看掩淚應無說，離別傷心事豈知？想得鹹陽原上树，已抽三丈白楊枝。\"洎自撰墓志，雲與劉夢得為詩友，殊不言元相公，時人疑其隙終也。","sortOrder":102},
  {"id":"s_work_dnl_21_103","chapterId":"ch_work_dnl_21","text":"李贺為韓文公所知，名聞紳。時元相稹以明經擢第，亦善詩，願與贺交。詣贺，贺還刺，曰：\"明經及第，何事看李贺？\"元恨之。製策登科。及為禮部郎中，因議贺父名晉肅，不合應進士，竟以輕薄為眾所排。文公惜之，為著《讳辯》，竟不能上。","sortOrder":103},
  {"id":"s_work_dnl_21_104","chapterId":"ch_work_dnl_21","text":"長慶初，李尚書絳議置郎官十人，分判南曹，吏人不便。旬日出為東都留守。自是選曹成状，常亦速畢。","sortOrder":104},
  {"id":"s_work_dnl_21_105","chapterId":"ch_work_dnl_21","text":"山甫以石留黃濟人嗜欲，多暴死者。其徒盛言山甫與陶貞白同壇受錄以神之。長慶二年，卒於餘幹。江西觀察使王仲舒遍告人：山甫老病而死速朽，無少異於人者。","sortOrder":105},
  {"id":"s_work_dnl_21_106","chapterId":"ch_work_dnl_21","text":"令狐楚镇東平，侍行。嘗送親郊外逆旅中。時久旱，因問民間疾苦。有老父曰：\"天旱，盜賊且起。\"复曰：\"今風不鳴條，雨不破塊。\"以相反詰之，答曰：\"自某日不雨，至於是月，豈非不破塊乎？賦稅徵迫，販妻鬻子，不給；繼以桑枝，豈非不鳴條乎？\"","sortOrder":106},
  {"id":"s_work_dnl_21_107","chapterId":"ch_work_dnl_21","text":"镇州王庭凑始生，嘗有鳩數十只，朝集庭树，暮集簷下，里人骆德播異之。及長，骈协，善《陰符經》、《鬼穀子》。初仕軍中，曾使河陽，道中被酒，寢於路傍。忽有一人，荷策而過，熟视之，曰：\"貴當列土，非常人也！\"從者告之。庭凑馳數里追及，致敬而問。自雲：\"濟源骆山人也。向見君鼻中之氣，左如龍，右如虎；龍虎交王，應在今秋。（原註：一雲：\"吾相人未有如此者。\"）子孫相繼，滿一百年。\"又雲：\"家之庭合有大树，树及於堂，是其兆也。\"是年，庭凑為三軍所立。歸省別墅，而庭树婆娑，陰已合矣。","sortOrder":107},
  {"id":"s_work_dnl_21_108","chapterId":"ch_work_dnl_21","text":"田令既為王庭凑所害，天子召其子布於涇州，與之發哀，授魏博之節。布乃盡出妓樂，扌舍鷹犬，哭曰：\"吾不回矣！\"次魏郊三十里，跣行被發而入。後知力不可執，密為遺表，伏劍而死。","sortOrder":108},
  {"id":"s_work_dnl_21_109","chapterId":"ch_work_dnl_21","text":"長慶中，京城婦人首飾，有以金碧珠翠；笄櫛步搖，無不具美，謂之\"百不知\"。婦人去眉，以丹紫三四橫約於目上下，謂之\"血晕妆\"。","sortOrder":109},
  {"id":"s_work_dnl_21_110","chapterId":"ch_work_dnl_21","text":"寶歷中，敬宗皇帝欲幸驪山，時諫者至多，上意不决。拾遺張權舆伏紫宸殿下，叩頭諫曰：\"昔周幽王幸驪山，為戎所殺；秦始皇葬驪山，國亡；明皇帝宮驪山，而祿山亂；先皇帝幸驪山，而享年不長。\"帝曰：\"驪山若此之凶耶？我宜往以验彼言。\"後數日，自驪山回，語親幸曰：\"叩頭者之言，安足信哉！\"","sortOrder":110},
  {"id":"s_work_dnl_21_111","chapterId":"ch_work_dnl_21","text":"文宗在藩邸，好讀書。王邸無《禮記》、《春秋》、《史記》、《周易》、《尚書》、《毛詩》、《論語》；雖有，少成部帙。宮中內官，得《周易》一部，密獻。上即位後，捧以隨輦。及朝廷無事，覽書目，間取書便殿讀之。乃詔兵部尚書王起、禮部尚書許康佐為侍講學士，中書舍人柳公權為侍讀學士。每有疑義，召學士入便殿，顧問讨論，率以為常，時謂\"三侍學士\"，恩寵異等。於是，康佐進《春秋列國經傳》六十卷，上善之，問康佐曰：\"吳人伐越，獲俘以為閽，使守舟；餘祭觀舟，閽以戈殺之。閽是何人？殺吳子复是何人？\"康佐遲疑久之，對曰：\"《春秋》義奧，臣窮究未精，不敢遽解。\"上笑而釋卷。","sortOrder":111},
  {"id":"s_work_dnl_21_112","chapterId":"ch_work_dnl_21","text":"藍田縣尉直宏文馆柳，擢為右拾遺、宏文直學士，給事中萧仿、鄭裔綽驳還製，曰：\"陛下懸爵位，本待賢良；今命浇浮，恐非懲勸。柳居家不禀義方，奉國豈盡忠節？\"刑部尚書柳仲郢，詣東上僩門進表，稱\"子才器庸劣，不當玷居諫垣；若誣以不孝，即非其實。\"太子少師柳公權亦訟侵毀之枉。上令免官，家居修省。貞元、元和已來，士林家禮法，推韓、韓皋、柳公綽、柳仲郢，一旦子稱不孝，為士叹之。","sortOrder":112},
  {"id":"s_work_dnl_21_113","chapterId":"ch_work_dnl_21","text":"韦溫遷右丞。文宗時，姚勖按大獄，帝以為能，擢職方員外郎。溫上言：\"郎官清選，不可賞能吏。\"帝問故，楊嗣复對曰：\"勖名臣後，治行無疵。若吏才幹而不入清選，他日孰肯當剧事者？此衰晉風，不可以法。\"","sortOrder":113},
  {"id":"s_work_dnl_21_114","chapterId":"ch_work_dnl_21","text":"太和三年，左拾遺舒元褒等奏中丞溫造凌供奉官事：\"今月四日，左補闕李虞仲與溫造街中相逢，造怒不回避，遂擒李虞仲祗奉人，笞其背者。臣等謹按國朝故事：供奉官街中，除宰相外，無所回避。\"","sortOrder":114},
  {"id":"s_work_dnl_21_115","chapterId":"ch_work_dnl_21","text":"陳夷行，字周道。文宗時，仙韶樂工尉遲璋授王府率，右拾遺李洵直當衙論奏。鄭覃、楊嗣复嫌以細故，謂洵直近名。夷行曰：\"諫官當衙，正須論宰相得失，彼賤工安足言？然亦不可置不用。\"帝即徙璋。","sortOrder":115},
  {"id":"s_work_dnl_21_116","chapterId":"ch_work_dnl_21","text":"新昌李相紳性暴不禮士。镇宣武，有士人遇於中道，不避，乃為前騶所拘。紳命鞫之，乃宗室也，答款曰：\"勤政樓前，尚容缓步；开封桥上，不許徐行。汴州豈大於帝都？尚書未尊於天子。\"公覽之，失色，使逸去。","sortOrder":116},
  {"id":"s_work_dnl_21_117","chapterId":"ch_work_dnl_21","text":"武翊黃，府送為解頭，及第為状頭，宏詞為敕頭，時謂\"武三頭\"，冠於一時。後惑於媵嬖薛荔，苦其冢婦盧氏。雖新昌李相紳以同年蔽之，而眾論不容，終至流竄。","sortOrder":117},
  {"id":"s_work_dnl_21_118","chapterId":"ch_work_dnl_21","text":"王併州，自河南尹拜右丞相。除目才到，少尹侯繼有宴，以書邀之。王判後雲：\"新命雖聞，舊衔尚在，遽為招命，堪入《笑林》。\"洛中以為口實。故事：少尹與大尹遊宴禮隔。雖除官，亦當俟正敕也。","sortOrder":118},
  {"id":"s_work_dnl_21_119","chapterId":"ch_work_dnl_21","text":"王沐，王涯之再從弟也。家於江南，老且窮。以涯作相，騎驢至京師，三十日始得見涯，所望不過一簿尉耳。而涯見其潦倒，無推引意。太和九年秋，沐幹涯之嬖奴，导以所欲，涯始一召，許以微官處之。自是旦夕造涯。及涯誅，仇士良收捕涯家族時，沐方在涯宅，以王氏之宗同坐。","sortOrder":119},
  {"id":"s_work_dnl_21_120","chapterId":"ch_work_dnl_21","text":"舒守謙即元舆之宗，十年居元舆舍，未嘗一日有間。至於車服飲饌，亦無異等。元舆謂之從子，取明經及第，歷秘書郎。及持相印，許列清曹命之。無何，忽以非過怒守謙，朔旦伏謁，皆不得見，僮仆皆拒之。守謙乃辭往江南，元舆亦不問。翌日，出長安，咨嗟自失，行及昭應，聞元舆之禍（原註：時宰相收捕，家族不問親疏皆戮）。論者以王、舒福禍之異，皆若分定焉。","sortOrder":120},
  {"id":"s_work_dnl_21_121","chapterId":"ch_work_dnl_21","text":"鄭註以方術進，舉引朋党，荐《周易》博士李訓，召入內署，為侍講《周易》學士。敏捷有口辯，涉獵五經，言及《左氏》，以探上意。上幸蓬萊殿閱書，召訓問曰：\"康佐所進《春秋列國經傳》，朕覽之久矣。戰國時事，歷歷明白。朕曾問康佐：吳人伐越，獲俘以為閽，殺吳子餘祭。康佐雲'窮究未精'，卿謂如何？\"訓曰：\"吳人伐越獲俘，俘即罪人，如今之所謂生口也。不殺，下蠶室肉刑，古謂之閽寺，即今之中使也。吳子是國君長。餘祭，名也。使中使主守舟楫，餘祭往觀之，為中使所殺。\"上嗟叹。訓曰：\"君不近刑臣，近刑臣即輕死之道也。吳子遠賢良，親刑臣，而有斯禍。魯史書之，以垂鑒戒。\"上曰：\"左右密近刑臣多矣，餘祭之禍，安得不慮？\"訓曰：\"陛下睿聖，留意於未萌。若欲去泰去甚，臣願遵聖算。累聖知之而不能遠，惡之而不能去，睿旨如此，天下幸甚！\"時鄭註任工部尚書侍講學士，乃與訓斥逐賢良，陰篝奸蠹，遂有甘露之事。","sortOrder":121},
  {"id":"s_work_dnl_21_122","chapterId":"ch_work_dnl_21","text":"太和初，京師有輕薄徒，取貢士姓名，以義理編飾為詞，號為\"舉人露布\"。九年冬，就戮者多是儒士。","sortOrder":122},
  {"id":"s_work_dnl_21_123","chapterId":"ch_work_dnl_21","text":"李瓒，故相宗闵之子。自桂州失守，貶昭州司戶，後量移衛州刺史；給事中柳韜疏之，复貶。韜始與瓒相善，瓒先達而弃韜。瓒既重為所貶，性強躁，憤且死。鄭舍人之父，瓒座主也，乃為書曰：\"與，受恩；未，極苦。\"累十點，筆落而卒。","sortOrder":123},
  {"id":"s_work_dnl_21_124","chapterId":"ch_work_dnl_21","text":"李司徒程善謔。為夏口日，有客辭焉，相留住三兩日，客曰：\"業已行矣，舟船已在漢口。\"曰：\"此漢口不足信。\"又因與堂弟居守相石投盤飲酒，居守誤收頭子，糾者罰之，司徒曰：\"汝向忙鬧時把堂印將去，又何辭焉？\"飲家謂重四為堂印，蓋譏居守太和九年冬朝廷有事之际而登庸也。又與石話服食，雲：\"汝服鐘乳否？\"曰：\"近服，甚覺得力。\"司徒曰：\"吾一不得乳力。\"蓋譏其作相日，無急難之效也。又嘗於街西遊宴，貪在博局，時已昏黑，從者迭報雲：\"鼓動。\"司徒應聲曰：\"靴！靴！\"其意謔鼓動似受慰之聲，以弔客\"靴\"、\"靴\"答之，連聲索靴，言欲速去也。又在夏口時，官園納苎頭而餘者分給將校，其主將報之，軍將謝苎頭，司徒手拍頭雲：\"著他了也。\"然後傳語：\"此苎頭不必謝也！\"","sortOrder":124},
  {"id":"s_work_dnl_21_125","chapterId":"ch_work_dnl_21","text":"徐晦嗜酒，沈傳師善餐。楊嗣复雲：\"徐家肺，沈家脾，其安穩耶？\"","sortOrder":125},
  {"id":"s_work_dnl_21_126","chapterId":"ch_work_dnl_21","text":"杜通貴日久，門下有術士李生者，甚異。驚任四川節度，馬植罢黔中，方赴闕，李一見，謂曰：\"受相公恩久，思以報答。今有所報矣！黔中馬中丞，非常人也，相公當厚遇之。\"未之信。他日，又謂曰：\"相公將有禍，非馬中丞不能救，乞厚結之。\"始驚，乃用其言，發日，厚幣赠之；乃令邸吏為植於闕下買宅，為生之費無闕焉。尋除光祿卿，報状至蜀，謂李曰：\"貴人赴闕作光祿勋矣。\"李曰：\"姑待之。\"稍進大理卿，遷刑部侍郎，充鹽鐵使，始信之。未幾拜相。懿安皇太後崩。，懿安子婿也。忽內榜子索檢责宰相元載故事，植諭旨，延英力營救。植素能回上意，事遂止。","sortOrder":126},
  {"id":"s_work_dnl_21_127","chapterId":"ch_work_dnl_21","text":"杜公嘗與同列言，平生不稱意有三：其一為澧州刺史；其二貶司農卿；其三自西川移镇廣陵，舟次瞿塘遇風，侍者驚废，渴甚，自泼茶飲。後镇荆南，諸院姊妹多在渚宮寄寓，相國未嘗拯濟，節腊一無沾遺，有乘肩舆至府門詬骂者，亦不省問。所莅方镇，不理獄訟。在鳳翔洎西川，系囚無輕重，任其殍。人有從劍門得漆器文書，乃成都具獄案牍也。","sortOrder":127},
  {"id":"s_work_dnl_21_128","chapterId":"ch_work_dnl_21","text":"欧陽琳父袞，亦中進士。琳與弟比同在場屋，苦其貧匮，每詣先達，刺辄同幅，時人稱之。杜公在岐下，以子裔休同年謁之。嘗以事怪琳，客或有為琳釋解者，且言\"琳，袞之子\"。不答，久之，曰：\"某自淮南赴闕，舟次龟山，風不可進。因策杖登岸徐步。適見一僧，方修道，前曰：'雪山和尚弟子教化。'某謂之曰：'何言弟子，饒你和尚也。'\"","sortOrder":128},
  {"id":"s_work_dnl_21_129","chapterId":"ch_work_dnl_21","text":"开成中，有龍复本者，無目，善聽揣骨，言休咎；象簡、竹笏，以手循之，必知官祿年寿。宋元阝補闕有時名，紳靡不傾屬，時永樂萧相亦居諫官，同日詣之，授以所持笏。复本聽萧笏良久，置於案上，曰：\"宰相笏。\"次至宋笏，曰：\"長官笏。\"元阝不樂。月餘，同列於中書，候見宰相。時李衛公方秉政。未見間，佇立談謔。頃之，丞相出。宋以手板障面，笑未已。李公目之，謂左右曰：\"宋補闕笑某何事？\"聞者為忧之，數日，出為河清縣令，歲餘死。其後萧公自浙西觀察使入判戶部，頃之，為宰相。","sortOrder":129},
  {"id":"s_work_dnl_21_130","chapterId":"ch_work_dnl_21","text":"文宗時，有沙門能改塔。履险若平。換塔杪一柱，人以為神。上聞之曰：\"塔固當人功所建，然當時匠者豈亦有神？\"沙門後果以妖妄伏法。","sortOrder":130},
  {"id":"s_work_dnl_21_131","chapterId":"ch_work_dnl_21","text":"盧尚書宏宣與弟衢州簡辭同在京師。一日，衢州早出，尚書問\"有何除改\"？答曰：\"無大除改，唯皮遐叔蜀中刺史。\"尚書不知皮是遐叔姓，謂是宗人，曰：\"我弥當家没處得'盧皮遐'來。\"衢州為辨之，皆大笑。","sortOrder":131},
  {"id":"s_work_dnl_22_1","chapterId":"ch_work_dnl_22","text":"●卷七·補遺（起武宗至昭宗）","sortOrder":1},
  {"id":"s_work_dnl_22_2","chapterId":"ch_work_dnl_22","text":"武宗時，李衛公嘗奏處士王龟有志業，堪為諫官。上曰：\"龟是誰子？\"對曰：\"王起之子。\"上曰：\"凡言處士者，當是山野之人；王龟父為大僚，豈不自合有官？\"","sortOrder":2},
  {"id":"s_work_dnl_22_3","chapterId":"ch_work_dnl_22","text":"李吉甫安邑宅，及牛僧孺新昌宅。泓師號李宅為\"玉杯\"，牛宅為\"金杯\"；玉一破無复全，金或傷尚可再製。牛宅本將作大匠康宅，自辨岡阜形势，謂其宅當出宰相，每命相有案，必延頸望之。宅竟為牛相所得。","sortOrder":3},
  {"id":"s_work_dnl_22_4","chapterId":"ch_work_dnl_22","text":"李衛公宅在安邑，桑道茂謂之\"玉碗\"。韦相宅在新昌北街，謂之\"金杯\"。","sortOrder":4},
  {"id":"s_work_dnl_22_5","chapterId":"ch_work_dnl_22","text":"《盧氏雜記》：泓師雲長安永寧坊東南是金盏地，安邑里西是玉杯地。後永寧為王鍔宅，安邑為馬燧宅。後入官，王宅賜袁弘及史憲誠等，所謂\"金盏破而成\"；馬燧宅為奉誠園，所謂\"玉杯破而不完\"矣。","sortOrder":5},
  {"id":"s_work_dnl_22_6","chapterId":"ch_work_dnl_22","text":"李衛公在淮扬，李宗闵在湖州拜賓客分司。衛公懼，遣专使致信好，宗闵不受，取路江西而過。頃之，衛公入相，過洛，宗闵忧懼，求厚善者致書，乞一見，欲自解。後書曰：\"怨即不怨，見即無端。\"初，衛公與宗闵早相善，中外致力。後位高，稍稍相傾。及宗闵在位，衛公為兵部尚書，次當大用，宗闵沮之，未效。衛公知而忧之。京兆尹杜即宗闵党，一日，見宗闵，曰：\"何感感也？\"宗闵曰：\"君揣我何念？\"杜曰：\"非大戎乎？\"曰：\"是也，何以相救？\"曰：\"某即有策，顧相公不能用。\"曰：\"請言之。\"杜曰：\"大戎有詞學而不由科第，至今怏怏。若令知貢舉，必喜。\"宗闵默然，曰：\"更思其次。\"曰：\"與御史大夫，亦可平治慊恨。\"宗闵曰：\"此即得。\"再三與約。遂詣安邑第，衛公迎之，曰：\"安得訪此寂寞？\"對曰：\"靖安相公有意旨，令某傳達。\"遂言亚相之拜。衛公驚喜垂涕，曰：\"大門官，小子豈敢當此荐拔？\"寄謝重叠。其後宗闵复與楊虞卿議之，其事遂格。","sortOrder":6},
  {"id":"s_work_dnl_22_7","chapterId":"ch_work_dnl_22","text":"元和已來，宰相有兩李少師，故以所居別之。永寧少師固言，性狷急，不為士大夫所稱；靖安少師者，宗闵也。","sortOrder":7},
  {"id":"s_work_dnl_22_8","chapterId":"ch_work_dnl_22","text":"李衛公性簡俭，不好聲妓，往往經旬不飲酒，但好奇功名。在中書，不飲京城水，茶湯悉用常州惠山泉，時謂之\"水遞\"。有相知僧允躬白公曰：\"公跡併伊、皋，但有末節尚損盛德。萬里汲水，無乃勞乎？\"公曰：\"大凡末世淺俗，安有不嗜不欲者？扌舍此即物外世網，豈可萦系？然弟子於世，無常人嗜欲：不求货殖，不邇聲色，無長夜之歡，未嘗大醉。和尚又不許飲水，無乃虐乎？若敬從上人之命，即止水後，誅求聚斂，廣畜姬侍，坐於鐘鼓之間，使家败而身疾，又如之何？\"允躬曰：\"公不晓此意。公博識多聞，止知常州有惠山寺，不知腳下有惠山寺井泉。\"公曰：\"何也？\"曰：\"公見極南物極北有，即此義也。蘇州所產，與、雍同；隴豈無吳縣耶？所出蒲魚菰鱉既同，彼人又能效蘇之織，其他不可遍舉。京中昊天觀厨後井，俗傳與惠山泉脈相通。\"因取諸流水，與昊天水、惠山水稱量，唯惠山與昊天等。公遂罢取惠山水。","sortOrder":8},
  {"id":"s_work_dnl_22_9","chapterId":"ch_work_dnl_22","text":"李衛公頗升寒素。舊府解有等第，衛公既貶，崔少保龟從在省，子殷夢為府解元。廣文諸生為詩曰：\"省司府局正綢缪，殷夢元知作解頭。三百孤寒齊下淚，一時南望李崖州。\"盧渥司徒以府元為第五人，自此废等第。","sortOrder":9},
  {"id":"s_work_dnl_22_10","chapterId":"ch_work_dnl_22","text":"周瞻舉進士，謁李衛公，月餘未得見。閽者曰：\"公讳'吉'，君姓中有之。公每見名紙，即顰蹙。\"瞻俟公歸，突出肩舆前，訟曰：\"君讳偏傍，則趙壹之後數不至'三'，贾山之冢語不言'出'，謝石之子何以立碑？李牧之男豈合書姓？\"衛公遂入。論者謂兩失之。","sortOrder":10},
  {"id":"s_work_dnl_22_11","chapterId":"ch_work_dnl_22","text":"李衛公德裕以己非科第，常嫉進士。及為丞相，權要束手。或曰，德裕初為某處從事時，同院有李評事者，進士也，與德裕官同。有舉子投卷，誤與德裕；舉子即悟，复請之曰：\"文軸當與及第李評事，非公也。\"由是德裕多排斥之。","sortOrder":11},
  {"id":"s_work_dnl_22_12","chapterId":"ch_work_dnl_22","text":"李德裕自金陵追入朝，且欲大用，慮為人所先，且欲急行。至平泉別墅，一夕秉燭周遊，不暇久留。及南貶，有甘露寺僧允躬者記其行事。空言無行實，盡仇怨假托為之。","sortOrder":12},
  {"id":"s_work_dnl_22_13","chapterId":"ch_work_dnl_22","text":"平泉莊在洛城三十里，卉木台榭甚佳。有虛槛，引泉水，萦回穿凿，像巴峡洞庭十二峰九派，迄於海門。有巨魚胁骨一條，長二丈五尺，其上刻雲：\"會昌二年，海州送到。\"在東南隅。平泉，即征士韦楚老拾遺別墅。楚老風韻高邈，好山水。衛公為丞相，以白衣擢升諫官，後歸平泉，造門訪之，楚老避於山穀。衛公題詩雲：\"昔日征黃綺，餘慚在鳳池。今來招隱逸，恨不見琼枝。\"","sortOrder":13},
  {"id":"s_work_dnl_22_14","chapterId":"ch_work_dnl_22","text":"平泉莊周围十餘里，台榭百餘所，四方奇花異草與松石，靡不置其後。石上皆刻\"支遁\"二字，後為人取去。其所傳雁翅桧、珠子柏、莲房玉蕊等，仅有存者。（原註：桧葉婆娑，如鸿雁之翅。柏實皆如珠子，丛生葉上，香聞數十步。莲房玉蕊，每跗萼之上，花分五朵，而實同其一房也）怪石名品甚眾，各為洛陽城族有力者取去。有禮星石、獅子石，好事者傳玩之。（原註：禮星石，從廣一丈，厚尺餘，上有斗極之象。獅子石，高三四尺，孔竅千萬，遞相通貫，如獅子，首、尾、眼、鼻皆全）","sortOrder":14},
  {"id":"s_work_dnl_22_15","chapterId":"ch_work_dnl_22","text":"李衛公歷三朝，大權出門下者多矣。及南竄，怨嫌併集。途中感憤，有\"十五餘年車馬客，無人相送到崖州\"之句。又書稱\"天下窮人，物情所弃。\"镇浙西，甘露寺僧允躬頗受知。允躬迫於物議，不得已送至謫所。及歸作書，言天厭神怒，百禍皆作：金幣為鱷魚所溺，室宇為天火所焚。談者藉以傳布，由允躬背恩所致。衛公既殁，子煜自象州武仙尉量移郴州郴尉，亦死貶所。劉相鄴為諫官，先世受恩，獨上疏請复官爵，乞歸葬。衛公門人，惟蹇士能報其德。","sortOrder":15},
  {"id":"s_work_dnl_22_16","chapterId":"ch_work_dnl_22","text":"李衛公在珠崖郡，北亭謂之望闕亭。公每登臨，未嘗不北睇悲咽。題詩雲：\"獨上江亭望帝京，鳥飛猶是半年程。碧山也恐人歸去，百匝千遭繞郡城。\"又郡有一古寺，公因步遊之，至一老禪院，坐久，見其內壁掛十餘葫芦，指曰：\"中有藥物乎？弟子頗足疲，願得以救。\"僧叹曰：\"此非藥也，皆人骼灰耳！此太尉當朝時，為私憾黜於此者，貧道悯之，因收其骸焚之，以貯其灰，俟其子孫來訪耳！\"公帳然如失，返步心痛。是夜卒。","sortOrder":16},
  {"id":"s_work_dnl_22_17","chapterId":"ch_work_dnl_22","text":"隴西李膠，年少持才俊，歷尚書郎。李太尉稱之，欲處之兩掖。江夏盧相判大計，白中書，欲取員外郎李膠權鹽使，太尉不答，盧不敢再請膠。太尉曰：\"某不識此人，亦無因緣，但見風儀標品，欲與諫議大夫。何為有此事？\"盧曰：\"某亦不識，但以要地嘱論。\"因於袖中出文，乃仇士良書也。太尉歸戒閽者，此人來不要通。後竟坐他罪，出為峡內郡丞。","sortOrder":17},
  {"id":"s_work_dnl_22_18","chapterId":"ch_work_dnl_22","text":"李衛公性簡傲，多獨居。閱覽之倦，即效攻作庀器，其自修琴阮。唯與中書舍人裴相見，亦中表也。多訪裴以外事。裴坡下送客還，公問：\"今日有何新事？\"曰：\"今日坡下郎官集，送蘇湖郡守，有飲餞。見一郎官，不容一同列，滿坐嗤訝。\"公曰：\"誰？\"曰：\"仓部郎中崔骈作酒錄事，不容仓部員外白敏中。\"公問：\"不容有由乎？\"曰：\"白員外後至。崔下四簿：三，白不敢辭；其一，遣自請罪名從命。崔曰：'也用到處出頭出腦？'白委頓而回去，兼不叙別。\"衛公不悅。遣馬屈白員外至，曰：\"公在員外，藝譽時稱，久欲荐引。今翰林有闕，三兩日行出。\"尋以本官充學土。出崔為申州，又徙邢、洛、汾三州，後以疾废洛下。","sortOrder":18},
  {"id":"s_work_dnl_22_19","chapterId":"ch_work_dnl_22","text":"宣宗即位於太極殿。時宰臣李德裕行册禮，及退，上謂宮侍曰：\"適行近我者非太尉耶？此人每顧我，使我毛發森竖。\"後二日，遂出為荆南節度。","sortOrder":19},
  {"id":"s_work_dnl_22_20","chapterId":"ch_work_dnl_22","text":"杜牧少登第，恃才，喜酒色。初辟淮南牛僧孺幕，夜即遊妓舍。厢虞候不敢禁，常以榜子申僧孺，僧孺不怪。逾年，因朔望起居，公留諸從事從容，謂牧曰：\"風聲婦人若有顧僣者，可取置之所居，不可夜中獨遊。或昏夜不虞，奈何？\"牧初拒讳，僧孺顧左右取一箧至，其間榜子百餘，皆厢司所申，牧乃愧謝。","sortOrder":20},
  {"id":"s_work_dnl_22_21","chapterId":"ch_work_dnl_22","text":"杜牧，太師佑之孫，有名當世。臨終又為詩誨其二子曹師等。曹師，名晦辭；曹師弟，名德祥。晦辭終淮南節度判官。德祥，昭宗時為禮部侍郎，知貢舉，亦有名聲。","sortOrder":21},
  {"id":"s_work_dnl_22_22","chapterId":"ch_work_dnl_22","text":"杜晦辭自吏部員外郎入浙西趙隱幕，王郢叛，趙相以撫御失宜致仕，晦辭罢。時北門李相蔚在淮南，辟為判官，晦辭辭不就，隱居於陽羨別墅，時論稱之。永寧劉相鄴在淮西，辟為判官，方應召。晦辭亦好色，赴淮南，路經常州，李贍給事為郡守，晦辭於坐間與官妓朱良別，因掩袂大哭。贍曰：\"此風聲賤人，員外何必如此？\"乃以步輦隨而遺之。晦辭飲散，不及易服，步歸舟中，以告其妻。妻不妒忌，亦許之。","sortOrder":22},
  {"id":"s_work_dnl_22_23","chapterId":"ch_work_dnl_22","text":"杜舍人牧，恃才名，頗縱聲色。嘗自言有鑒別之能。聞吳興郡有佳色，罢宛陵幕，往觀焉。使君聞其言，迎待頗厚。至郡旬日，繼以酣飲。睨官妓曰：\"未稱所傳也。\"將離郡去，使君敬請所欲，曰：\"願泛彩舟，許人縱视，得以寓目。\"使君甚悅。擇日大具戲舟，謳棹捷较之樂，以鮮華相尚。牧循泛肆目，意一無所得。及暮將散，忽於曲岸見里婦携幼女，年方十餘歲。牧悅之，召至與語。牧曰：\"今未帶去，第存晚期耳！\"遂赠羅缬一箧為质。婦辭曰：\"他日無状，或恐為所累。\"牧曰：\"不然。餘今西行，求典此郡。汝待我十年，不來而後嫁。\"遂書於紙而別。後十四年始出刺湖州。臨郡三日，即命訪之。女嫁已三載，有子二人矣。牧召母及女詰問，即出留書示之。乃曰：\"其辭也直。\"因赠詩曰：\"自是尋春去较遲，不須惆怅怨芳時。狂風落盡深紅色，绿葉成陰子滿枝。\"","sortOrder":23},
  {"id":"s_work_dnl_22_24","chapterId":"ch_work_dnl_22","text":"王起知舉，將入貢院，請德裕所欲。德裕曰：\"安問所欲？借如盧肇、丁稜、姚頡，不可在去流內也。\"起從之。","sortOrder":24},
  {"id":"s_work_dnl_22_25","chapterId":"ch_work_dnl_22","text":"進士放榜訖，則群謁宰相。其道啟詞者出状元，舉止尤宜精審。時盧肇、丁稜及第。肇有故。次乃至稜。口讷，貌寢陋。迨引見，連曰：\"稜等登……\"蓋言\"登科\"而卒莫能成語，左右莫不大笑。後為人所謔，雲：\"先辈善彈筝。\"讳曰：\"無有。\"曰：\"諸公謁宰相日，先辈獻藝，雲'稜等登，稜等登。'\"","sortOrder":25},
  {"id":"s_work_dnl_22_26","chapterId":"ch_work_dnl_22","text":"李、王铎，進士同年也。常恐铎先大用。及路巖出镇，益失势；铎柔弱易製，中官貪之，先用铎焉。知之，挈酒一壶，謂铎曰：\"公將登庸矣，吾恐不可及也。願先事少接左右。\"铎妻疑置鸩，使婢言之。驚曰：\"吾豈鸩者？\"即命大白滿引而去。","sortOrder":26},
  {"id":"s_work_dnl_22_27","chapterId":"ch_work_dnl_22","text":"御史府有大夫、中丞，雜事者，總台綱也。侍御史、殿中侍御史，有內外彈、四推、太仓、左藏库、左右巡，皆負重事也。不常備，有兼領者。監察使有祠祭使、馆驿使、與六察為八，分務東都，又常一二巡因，監决案覆，諸道不法事皆監察；亦不常備，亦有兼領事者。御史不聞攝他官，自武宗始。","sortOrder":27},
  {"id":"s_work_dnl_22_28","chapterId":"ch_work_dnl_22","text":"聖善寺銀佛，天寶亂，為賊將截一耳。後少傅白公奉佛，用銀三鋌添補，然不及舊者。會昌拆寺，命中貴人毀像，收銀送內库。中人以白公所添鑄，比舊耳少銀數十兩，遂詣白公索餘銀，恐涉隱没故也。","sortOrder":28},
  {"id":"s_work_dnl_22_29","chapterId":"ch_work_dnl_22","text":"京師貴牡丹，佛宇、道觀多遊覽者。慈恩浴室院有花兩丛，每开及五六百朵。僧恩振說：會昌中朝士數人，同遊僧舍。時東廊院有白花可愛，皆叹雲：\"世之所見者，但淺深紫而已，竟未見深紅者。\"老僧笑曰：\"安得無之？但諸賢未見爾！\"眾於是訪之，經宿不去。僧方言曰：\"諸君好尚如此，貧道安得藏之？但未知不漏於人否？\"眾皆許之。僧乃自开一房，其間施設幡像，有板壁遮以幕。後於幕下啟關，至一院，小堂甚華絜，柏木為軒庑欄槛。有殷紅牡丹一丛，婆娑數百朵。初日照辉，朝露半唏。眾共嗟賞，及暮而去。僧曰：\"予栽培二十年，偶出語示人，自今未知能存否？\"後有數少年詣僧，邀至曲江看花，藉草而坐。弟子奔走報：有數十人入院掘花，不可禁。坐中相视而笑。及歸至寺，見以大畚盛之而去。少年徐謂僧曰：\"知有名花，宅中鹹欲一看，不敢豫請，蓋恐難扌舍。已留金三十兩、蜀茶二斤，以為報矣！\"","sortOrder":29},
  {"id":"s_work_dnl_22_30","chapterId":"ch_work_dnl_22","text":"宣宗在藩邸，常為諸王所法。一日不豫，鄭太後奏上苦心疾。文宗召見，熟视上貌，以玉如意撫背曰：\"我家他日英主，豈疾乎？\"即賜御馬、金帶。","sortOrder":30},
  {"id":"s_work_dnl_22_31","chapterId":"ch_work_dnl_22","text":"宣宗在藩邸時，為武宗所薄，將中害者非一。一日，宣召打球，欲圖之。中官奏：瘡痍遍體，腥秽不可近。上命舁置殿下，果如所奏，遂釋之。武宗嘗夢為虎所逐，命京兆、同、華格虎以進。至宣宗即位，本命在寅，於屬為虎。","sortOrder":31},
  {"id":"s_work_dnl_22_32","chapterId":"ch_work_dnl_22","text":"宣宗即位。宮中每欲行幸，先以龍腦鬱金藉地，上併禁止。每上殿，與學士從容，未嘗不論儒學。頗留意於貢舉，於殿柱題乡貢進士。或宰臣出镇，賜詩遣之。凡欲對公卿，必整容貌，更衣盥手，然後方出。語及政事，終日忘倦。章表有不欲左右見者，率皆焚熟。倡優伎樂，終日嬉戲，上未嘗顧笑，賜赉甚薄。有時微行人間，采聽舆論，以觀選士之得失。","sortOrder":32},
  {"id":"s_work_dnl_22_33","chapterId":"ch_work_dnl_22","text":"宣宗時，越守進女樂，有絕色。上初悅之，數日，錫予盈積。忽晨興不樂，曰：\"明皇帝只一楊妃，天下至今未平。我豈敢忘？\"召詣前曰：\"應留汝不得。\"左右奏，可以放還。上曰：\"放還我必思之，可賜冗一杯。\"","sortOrder":33},
  {"id":"s_work_dnl_22_34","chapterId":"ch_work_dnl_22","text":"宣宗多追錄憲宗卿相子孫。裴谂，度之子，為學士，加承旨。上幸翰林，谂寓直，便中謝。上曰：\"加官之喜，不與妻子相面，得否？便放卿歸。\"谂降階蹈謝。却召，上以御盤內果實賜之，谂即以衫袖跪受。上顧一宮嫔，取領下小帛，裹以賜谂。","sortOrder":34},
  {"id":"s_work_dnl_22_35","chapterId":"ch_work_dnl_22","text":"宣宗讀《元和實錄》，見故江西觀察使韦丹政事卓異，問宰臣，\"孰為丹後\"，周墀曰：\"臣近任江西，見丹行事，遺愛餘風，至今在人。其子宙，見任河陽觀察判官。\"上曰：\"速與好官。\"御史府聞之，奏為御史。","sortOrder":35},
  {"id":"s_work_dnl_22_36","chapterId":"ch_work_dnl_22","text":"宣宗時加赠故楚州刺史、赠尚書工部侍郎李德修為禮部尚書。德修，吉甫長子。吉甫薨，太常謚曰\"簡\"。度支郎中張仲方，以憲宗好用兵，吉甫居辅弼之任，不得為\"簡\"。仲方貶开州司馬。寶歷中，方征諫議大夫。德修不欲同立朝，連牧舒、湖、楚三州。時吉甫少子德裕任荆南節度使、檢校司徒平章事。上即位，推恩德裕，當追赠祖、父；乞回赠其兄，故有是命。","sortOrder":36},
  {"id":"s_work_dnl_22_37","chapterId":"ch_work_dnl_22","text":"武宗任李德裕。德裕雖丞相子，文學過人，性孤峭，嫉朋党，挤牛僧儒、李宗闵、崔珙於嶺外；楊嗣复、貞穆李公珏，以會昌初册立事，亦七年嶺表。宣宗即位，嶺南五相，同日遷北。","sortOrder":37},
  {"id":"s_work_dnl_22_38","chapterId":"ch_work_dnl_22","text":"宣宗弧矢击鞠，皆盡其妙。所御馬，衔勒之外，不加雕飾。而馬尤矯捷；每持鞠杖，乘势奔躍，運鞠於空中，連击至數日，而馬馳不止，迅若流電。二軍老手，鹹服其能。","sortOrder":38},
  {"id":"s_work_dnl_22_39","chapterId":"ch_work_dnl_22","text":"《清夜遊西園圖》者，晉顧長康所畫。有梁朝諸王跋尾處，雲：\"圖上若幹人，併食天厨。\"唐貞觀中，褚河南裝背，題處具在。其圖本張維素家收得，傳至相國張公弘靖。元和中，准宣索併鐘元常寫《道德經》，同進入內（原註：時張镇併州，《進圖表》，李太尉衛公作）。後中貴人崔潭峻自禁中將出，复流傳人間。維素子周封，自涇州從事，秩滿在京。一日，有人將此圖求售，周封驚異之，遽以絹數匹贖得。經年，忽聞款關甚急，問之，見數人同稱仇中尉傳語評事：知《清夜圖》在宅，計閒居家貧，請以絹三百匹易之。周封憚其逼胁，遽以圖授使人。明日果赍絹至。後方知诈伪，乃是一豪士求江淮海鹽院，時王涯判鹽鐵，酷好書畫，謂此人曰：\"為餘訪得此圖，當遂公所請。\"因為計取之耳。及十家事起，後落在一粉鋪家。未幾，為郭侍郎家閽者以錢三百市之，以獻郭公。郭公卒，又流傳至令狐相家。宣宗一日嘗問相國有何名畫，相國具以圖對，复進入內。","sortOrder":39},
  {"id":"s_work_dnl_22_40","chapterId":"ch_work_dnl_22","text":"宣宗將命令狐為相，夜半幸含春亭召對，盡蠟燭一炬，方許歸院，仍賜金莲炬送之。院吏忽見金莲蠟燭，驚報院中曰：\"駕來矣！\"俄然至。院吏謂曰：\"金莲花引駕燭，學士用之，得安否？\"頃刻有丞相之命。","sortOrder":40},
  {"id":"s_work_dnl_22_41","chapterId":"ch_work_dnl_22","text":"宣宗以左拾遺鄭言為太常博士，鄭朗自御史大夫為相；朗先為浙西觀察使，左拾遺鄭言實居幕中。朗議：以諫官論時政得失，動關宰辅，請移言為博士。至大中二年，崔慎由自戶部侍郎秉政，复以左拾遺杜蔚為太常博士；蔚亦慎由舊寮，遂為故事。","sortOrder":41},
  {"id":"s_work_dnl_22_42","chapterId":"ch_work_dnl_22","text":"崔相慎由，廉察浙西，左目生赘肉，欲蔽瞳人。医久無验。聞扬州有穆生善医眼，托淮南判官楊收召之。收書報雲：\"穆生性粗疏，恐不可信。有谭簡者，用心精審，勝穆生遠甚。\"遂致以來。既見，白崔曰：\"此立可去。但能安神不撓，獨斷於中，則必效矣。\"崔曰：\"如約，雖妻子必不使知聞。\"又曰：\"須用天日晴明，亭午於靜室療之，始無忧矣。\"問崔飲多少？曰：\"飲雖不多，亦可引滿。\"谭生大喜。是日，崔引谭生於宅北樓，惟一小竖在，更無人知者。谭生請崔飲酒，以刀圭去赘，以絳帛拭血，傅以藥，遣報妻子知。後數日，征詔至金陵。及作相，谭生已卒。","sortOrder":42},
  {"id":"s_work_dnl_22_43","chapterId":"ch_work_dnl_22","text":"大中三年，李褒侍郎知舉，试《尧仁如天賦》。宿州李使君弟渎不識題，訊同鋪，或曰：\"止於'尧之如天'耳！\"渎不悟，乃為句曰，\"雲攒八彩之眉，電閃重瞳之目。\"賦成將寫，以字數不足，忧甚。同辈绐之曰：\"但一聯下添一'者也'，當足矣。\"褒覽之大笑。","sortOrder":43},
  {"id":"s_work_dnl_22_44","chapterId":"ch_work_dnl_22","text":"大中四年，進士冯涓登第，榜中文譽最高。是歲，新羅國起樓，厚赍金帛，奏請撰記，時人榮之。初官京兆參軍，恩地即杜相審權也。杜有江西之拜，製書未行，先召長樂公密話，垂延辟之命，欲以南昌箋奏任之，戒令勿泄。長樂公拜謝，辭出宅，速鞭而歸，於通衢遇友人鄭賓，見其喜形於色，駐馬恳詰，長樂遽以恩地之辭告之。滎陽尋捧刺京兆門謁贺，具言得於冯先辈也。京兆嗟憤，而鄙其淺露。洎製下开幕，冯不預焉。心緒忧疑，莫知所以。廉車發日，自灞桥乘肩舆，門生鹹在，長樂拜別，京兆公長揖冯曰：\"勉旃！\"由是嚣浮之譽，遍於紳，竟不通顯。中間又涉交通中貴，愈招清議。官工部郎中、眉州刺史，仕蜀，至御史大夫。","sortOrder":44},
  {"id":"s_work_dnl_22_45","chapterId":"ch_work_dnl_22","text":"崔郢中丞為京尹，三司使永達亭子宴丞郎，崔乘醉突飲。夏侯孜為戶部使，問曰：\"尹曾任給、舍否？\"崔曰：\"無。\"孜曰：\"若不歷給、舍，尹不合冲丞郎宴。\"命酒糾下筹進罰爵，取三大器滿飲之，良久方起。笞引馬前軍將至死。尋出為賓客分司。","sortOrder":45},
  {"id":"s_work_dnl_22_46","chapterId":"ch_work_dnl_22","text":"太常卿封敖於私第上事。御史彈奏，左遷國子祭酒。故事：太常卿上日，庭設九部樂，盡一時之盛。敖欲便於觀閱，遂就私第视事。","sortOrder":46},
  {"id":"s_work_dnl_22_47","chapterId":"ch_work_dnl_22","text":"大中十二年七月十四日退朝，宰相夏侯孜獨到衙門。以御史大夫李景讓為檢校吏部尚書，充劍南西川節度使。時中元休假，通事舍人無在馆者。麻案既出，孜受麻畢，乃召當直舍人冯圖宣之，捧麻皆兩省胥吏。自此始令通事舍人休亦在馆。","sortOrder":47},
  {"id":"s_work_dnl_22_48","chapterId":"ch_work_dnl_22","text":"李景讓為御史大夫。初，大夫不旬月，多拜丞相。台中故事：以百日內他人拜相為\"辱台\"。景讓未旬，除劍南節度使。未幾，請致仕。客有勸之曰：\"仆射廉絜，縱薄於富貴，豈不為諸郎謀耶？\"笑曰：\"李景讓兒詎饿死乎？\"退居洛中，門無雜賓。李琢罢浙西，謁景讓，且下馬，不肯見；方去，命人其馬台雲。","sortOrder":48},
  {"id":"s_work_dnl_22_49","chapterId":"ch_work_dnl_22","text":"李尚書景讓少孤，母夫人性嚴明。居東都。諸子尚幼，家貧無資。訓励諸子，言動以禮。時霖雨久，宅牆夜ㄨ，僮仆修筑，忽見一船槽，實之以錢。婢仆等來告，夫人謂僮仆曰：\"吾聞不勤而獲，猶謂之灾；士君子所慎者，非常之得也。若天實以先君餘慶，悯及未亡人，當令諸孤學問成立，他日為俸錢入吾門，此未敢取。\"乃令閉如故。其子景溫、景莊皆進士擢第，併有重名，位至方镇。景讓最刚正，奏彈無所避。初，夫人孀居，猶才未中年，貞幹嚴肅，姻族敬憚，訓厲諸子必以禮，雖貴達，稍怠於辭旨，猶杖之。景讓除浙西，問曰：\"何日進發？\"景讓忘於審思，對以近日。夫人曰：\"比行日，吾或有故，不行如何？\"景讓懼。夫人曰：\"汝今貴達，不須老母可矣！\"命僮仆斥去衣，於堂下，景讓時已班白矣。紳以為美談。在浙西，左押衙因應對有失，杖死；既而軍中汹汹，將為亂，太夫人乃候其受衙，出坐廳中，叱景讓立廳下，曰：\"天子以方镇命汝，安得輕用刑，如眾心不寧，非惟上負天子，而令垂白之母羞辱而死，使吾何面目見汝先人於地下？\"左右皆感咽。命杖其背。賓客大將，拜泣乞之，久乃許。軍中遂息。景莊累舉未登第，聞其被黜將笞，其兄中表皆勸景讓嘱於主司，景讓終不用，曰：\"朝廷取士，自有公論，豈敢效人求關節乎？主司知是景讓弟非冒取名者，自當放及第。\"是歲，景莊登科。","sortOrder":49},
  {"id":"s_work_dnl_22_50","chapterId":"ch_work_dnl_22","text":"溫庭筠字飛卿，彦博之裔孫。文章與李商隱齊名，時號\"溫、李\"。連舉進士，不中。宣宗時，謫為隨縣尉。製曰，\"放骚人於湘浦，移贾誼於長沙。\"舍人裴坦之詞，世以為笑。","sortOrder":50},
  {"id":"s_work_dnl_22_51","chapterId":"ch_work_dnl_22","text":"僧從誨住安國寺，道行高絜，兼工詩，以文章應製。宣宗每擇剧韻令賦，誨亦多稱旨。累年供奉，望方袍之賜，以耀法門。上兩召至殿上，謂之曰：\"朕不惜一副紫袈娑，但師頭耳稍薄，恐不勝耳！\"竟不賜，悒悒而卒。","sortOrder":51},
  {"id":"s_work_dnl_22_52","chapterId":"ch_work_dnl_22","text":"南卓郎中與李修古中外兄弟。修古性迂僻，卓常輕之。修古得許州從事，奏官敕下，許帥方大燕，遞到开角，有卓與修古書。修古執書，喜白帥曰：\"某與南二十三表兄弟平生相輕，今日某為尚書幕客，遂與某書。\"及开緘雲：\"即日卓老不死，生見李修古除目。\"帥视書大笑。","sortOrder":52},
  {"id":"s_work_dnl_22_53","chapterId":"ch_work_dnl_22","text":"諸葛武侯相蜀，製蠻侵漢界。自吐蕃西至東，接夷陵境，七百餘年不复侵軼。自大中蜀守任人不當，有喻士珍者，受朝廷高爵，而與蠻習之，頻為奸宄。使蠻用五千人，日开辟川路，由此致南詔，扰攘西蜀--蜀於是凶荒窮困，人民相食--由沐浴川通蠻陬也。","sortOrder":53},
  {"id":"s_work_dnl_22_54","chapterId":"ch_work_dnl_22","text":"大中初，吐蕃扰邊。宣宗欲讨伐，延英問宰臣，白敏中奏\"宜興師\"，請為都統。領兵數萬，陣於平川。以生騎數千，伏山穀為奇兵。有蕃將服緋茸裘、寶裝帶，乘白馬，出入驍銳。兵未交，至陣前者數四，頻來挑戰。敏中誡士無得應之。有潞州小將，善射，躍馬弯弧而前，連發兩，中其頸，搏而殺之，取其服帶，奪馬而還。蕃兵大呼，士眾鼓而前，追奔將及黑山，獲馬駝辎重不可勝計，降者數千人。自此复得河湟故地。宣宗見捷書雲：\"我知敏中必破賊。\"","sortOrder":54},
  {"id":"s_work_dnl_22_55","chapterId":"ch_work_dnl_22","text":"白敏中初入州幕府，罢遊同州，謁幕府李鳳侍御。久不出見，曰：\"誰謂雀無角，何以穿我屋？\"坐客皆非之。後為相，鳳除官過中書，曰：\"此官人頃相遇同州，今日猶作常調等色。\"","sortOrder":55},
  {"id":"s_work_dnl_22_56","chapterId":"ch_work_dnl_22","text":"白敏中守司空兼門下侍郎，充寧行營都統，讨南山、平夏党項。發日，以禁軍三百人從。敏中請依裴度讨淮西故事，开幕擇廷臣充大吏，上允之。乃以左諫議大夫孫景昌為左庶子行軍司馬，駕部郎中、知製誥蒋某為右庶子、節度副使，贺部員外郎李旬為節度判官，戶部員外郎李元為都統掌記，將軍冉戶、陳君從為左右虞候。","sortOrder":56},
  {"id":"s_work_dnl_22_57","chapterId":"ch_work_dnl_22","text":"白相敏中欲取進士侯溫為婿。其妻曰：\"公既姓白，又以侯氏子為婿，人必呼為'白侯'。\"敏中遂止。敏中始婚也，已朱衣矣；嘗戲其妻為接腳夫人，安用此？","sortOrder":57},
  {"id":"s_work_dnl_22_58","chapterId":"ch_work_dnl_22","text":"萬寿公主，宣宗之女。將嫁，命擇良婿。鄭顥，宰相子，状元及第，有聲名，待婚盧氏。宰臣白敏中奏選尚，顥深衔之。大中五年，敏中免相，為寧行營都統。將行，奏曰：\"頃者，公主下嫁，责臣選婿。時鄭顥赴婚楚州，行次鄭州，臣堂帖追回，上副聖念。顥不樂為國婚，衔臣入骨髓。臣在中書，顥無如臣何，自此必媒孽臣短，死無种矣！\"上曰：\"卿何言之晚耶？\"因命左右，殿中取一柽木小函，扃鑰甚固，謂敏中曰：\"此是顥說卿文字，便以賜卿。若聽其言，不任卿久矣！\"大中十二年，敏中任荆南節度使，暇日，與前進士在銷忧閣，追感上恩，泣話此事，盡以此函中文字示之。","sortOrder":58},
  {"id":"s_work_dnl_22_59","chapterId":"ch_work_dnl_22","text":"宣宗時，御史冯緘三院退入台，路逢集賢校理楊收，不為之却；緘為朝長（原註：台中故事，三院退朝入台，一人謂之朝長），取收仆笞之。集賢大學士馬植奏論\"开元中幸麗正殿賜酒，大學士張說、學士副知院事徐堅以下十八人，不知先舉酒者。說奏：'學士以德行相先，非其員吏。'遂十八爵一時舉酒。今冯緘笞收仆，是笞植仆隸一般，請黜之。\"御史中丞令狐，又引故事論救，上兩釋之。始著令：三馆學士不避行台。","sortOrder":59},
  {"id":"s_work_dnl_22_60","chapterId":"ch_work_dnl_22","text":"令狐以姓氏少，宗族有歸投者，多慰荐之。繇是遠近趨走，至有胡氏添\"令\"者。進士溫庭筠戲為詞曰：\"自從元老登庸後，天下諸'胡'悉帶'令'。\"","sortOrder":60},
  {"id":"s_work_dnl_22_61","chapterId":"ch_work_dnl_22","text":"令狐罢相。其子氵高進士，在父未罢相前拔解及第。諫議大夫崔上疏：\"氵高弄父權，势傾天下。舉人文卷須十月送納。豈可父為宰相，氵高私幹有司？請下御史推勘。\"疏留中不出。","sortOrder":61},
  {"id":"s_work_dnl_22_62","chapterId":"ch_work_dnl_22","text":"邕州蔡大夫京者，故令狐相公楚镇滑台之日，因道場中見於僧中，令京挈瓶鉢。彭陽公曰：\"此子眉目疏秀，進退不慑，惜其卑幼，可以勸學乎？\"師從之，乃得陪相國子弟。後以進士舉上第，尋又學究登科，而作尉畿服。既為御史，覆獄淮南，李相紳忧悸而已，頗得繡衣之稱。謫居澧州，為厲員外立所辱。稍遷撫州刺史，作詩责商山四老：\"秦末家家思逐鹿，商山四皓獨忘機。如何須發霜相似，更出深山定是非？\"及假節邕交，道經湖口，零陵鄭太守史與京同年，遠以酒樂相遲。坐有琼枝者，鄭君之所愛，蔡強奪之，鄭莫之競。邕交所為，多如此，為德義者見鄙。行泊《中興頌》所，黾勉不前，題篇久之，似有怅怅之思。才到邕南，製御失律，伏法湘川。論者以妄责四皓，而欲買山於浯溪之間，不徒言哉！詩曰：\"停桡積水中，舉目孤煙外；借問浯溪人，誰家有山賣？\"","sortOrder":62},
  {"id":"s_work_dnl_22_63","chapterId":"ch_work_dnl_22","text":"盧司空鈞為郎官，守衢州，有進士贽謁，公开卷閱其文十餘篇，皆公所製也。語曰：\"君何許得此文？\"對曰：\"某苦心夏課所為。\"公雲：\"此文乃某所為，尚能自誦。\"客乃伏，言：\"某得此文，不知姓名，不悟員外撰述者。\"","sortOrder":63},
  {"id":"s_work_dnl_22_64","chapterId":"ch_work_dnl_22","text":"盧彖安仁，李藩侍郎門生，性簡易。嘗與同年生在藩座。久之，彖起更衣，藩謂門生辈本風，言訖彖適至，聞藩言，即拱曰：\"是！不敢。\"藩與門生不覺失笑。宣宗嘗微行，遇彖妻肩舆，左右皆走避，上即撤舆觀之，大笑而去。時人盛傳彖妻丑。","sortOrder":64},
  {"id":"s_work_dnl_22_65","chapterId":"ch_work_dnl_22","text":"大中十二年，李藩侍郎下崔相沆、長安令盧彖同年。上巳日期集，盧稱疾不至。沆忽於曲道遇彖，侧席帽，映一氈車以避。沆時主罰，因舉詞曰：\"低垂席帽，遙映氈車。白日在天，不識同年之面；青雲得路，可知異日之心。\"時人比之崔嘏、施肩吾。","sortOrder":65},
  {"id":"s_work_dnl_22_66","chapterId":"ch_work_dnl_22","text":"相國韦公宙善治生。江陵府東有別業，良田美產，最號膏腴，而積稻如坻，皆為滯穗。大中初，除廣州節度。上以番禺珠翠之地，垂貪泉之戒。京兆從容奏對：\"江陵莊積稻尚有七十堆，宙無所貪。\"上曰：\"此可謂之'足翁'也。\"","sortOrder":66},
  {"id":"s_work_dnl_22_67","chapterId":"ch_work_dnl_22","text":"崔侍郎安潛崇奉釋氏，鮮茹葷血，唯於刑辟常自躬親，僧人犯罪，未嘗屈法。於廳前慮囚，必恤惻以盡其情；有大辟者，俾先示以判語，賜以酒食而付法。镇西川三年，唯多蔬食。宴諸司，以面及之類染作顏色，用象豚肩、羊脯脍炙之屬，皆逼真也。時人比於梁武。而頻於使宅堂前弄傀儡子，軍人百姓穿宅觀看，一無禁止。而中壶預政，以玷盛德。","sortOrder":67},
  {"id":"s_work_dnl_22_68","chapterId":"ch_work_dnl_22","text":"韦楚老，李宗闵之門生。自左拾遺辭官東歸，居於金陵。常乘驢經市中，貌陋而服衣布袍，群兒陋之。指畫自言曰：\"上不屬天，下不屬地，中不累人，可謂大韦楚老。\"群兒皆笑。與杜牧同年生，情好相得。初以諫官赴征，值牧分司東都，以詩送。及卒，又以詩哭之。","sortOrder":68},
  {"id":"s_work_dnl_22_69","chapterId":"ch_work_dnl_22","text":"李相回，舊名躔，累舉未第。嘗之洛桥，有二術士：一卜者，一筮者。乃先訪筮者曰：\"某欲改名赴舉，如何？\"筮者曰：\"改名甚善。不改，終不成事。\"乃訪卜者邹先生，曰：\"此行慎勿易，名將遠布矣。然成遂之後，二十年間，名字終當改矣。今則已應天象，異時方测餘言。\"將行，又戒之曰：\"郎中必享榮名，後當重任。引接後來，勿以白衣為隙，必為深累。\"長慶二年及第。至武宗登極，與上同名，始改為回。從辛丑至庚申，二十年矣，乃曰：\"筮短龟長，邹生之言中矣！\"李公既為丞郎，永興魏相為給事。因省會，魏公曰：\"昔求府解，侍郎為试官，送一百二人，獨小生不蒙一解。今日還忝金章，廁諸公之列。\"坐上皆驚。李曰：\"君今脱却紫衫，稱魏秀才，仆為试官，依前不送。何得以舊事相讓？\"李尋為獨坐，三台肅畏，而升相府。當時台官真拜者少。後數年間，魏亦自同州入相。宣宗時，李丞相有九江、臨川之行，跋涉江湖，喟然而叹曰：\"不遵洛桥先生之戒，吾自取尤焉。\"","sortOrder":69},
  {"id":"s_work_dnl_22_70","chapterId":"ch_work_dnl_22","text":"廣州監軍吳德離京師，病腳蹣跚，三載歸，足病复平。宣宗問之，遂為上說羅浮山人軒轅集之医。上聞之，驿召集赴京師。既至，馆於南山亭院，外庭不得見也。諫官屢以為言，上曰：\"軒轅道人口不幹世事，勿以為忧。\"留歲餘放歸。授朝散大夫、廣州司馬，集不受。","sortOrder":70},
  {"id":"s_work_dnl_22_71","chapterId":"ch_work_dnl_22","text":"羅浮生軒轅集，莫知何許人，有道術。宣宗召至京師。初若偶然，後皆可验。舍於禁中，往往以竹桐葉滿手，再三僜之，成銅錢。或散發箕踞，久之用氣上攻，其發條直如植。忽思歸海上，上置酒內殿，召坐。上曰：\"先生道高，不樂喧雜，今不可留矣！朕雖天下主，在位十餘年，競忄栗不暇。今海內小康矣，所不知者寿耳。\"集曰：\"陛下五十年天子。\"上喜。及帝崩，寿五十。","sortOrder":71},
  {"id":"s_work_dnl_22_72","chapterId":"ch_work_dnl_22","text":"舊製：三二歲，必於春時，內殿賜宴宰辅及百官，備太常諸樂，設魚龍曼衍之戲，連三日，抵暮方罢。宣宗妙於音律，每賜宴前，必製新曲，俾宮婢習之。至日，出數百人，衣以珠翠緹繡，分行列队，連袂而歌，其聲清怨，殆不類人間。其曲有曰《播皇猷》者，率高冠方履，褒衣博帶，趨赴俯仰，皆合規矩；有曰《葱嶺西》者，士女踏歌為队，其詞大率言葱嶺之士，樂河湟故地，歸國而复為唐民也；有《霓裳曲》者，率皆執幡節，被羽服，飄然有翔雲飛鶴之势。如是者數十曲。教坊曲工遂寫其曲，奏於外，往往傳於人間。","sortOrder":72},
  {"id":"s_work_dnl_22_73","chapterId":"ch_work_dnl_22","text":"相國李公福，庭有槐一本，抽三枝，直過堂舍屋脊，一枝不及。相國同堂崑季三人：曰石、曰程，皆登宰相；惟福一人，歷镇使相而已。","sortOrder":73},
  {"id":"s_work_dnl_22_74","chapterId":"ch_work_dnl_22","text":"大中十二年，宣州將康全泰噪逐觀察使鄭熏，乃以宋州刺史溫璋治其罪。時萧為浙西觀察使，與宣州接連，遂擢用武臣李琢代，建镇海軍節度使，以張掎角之势。兵罢後，或言琢虛立官健名目，廣占衣糧自入，宣宗命監察御史楊載往，按覆軍籍，無一人虛者。載還奏之，謗者始不勝。","sortOrder":74},
  {"id":"s_work_dnl_22_75","chapterId":"ch_work_dnl_22","text":"越人仇甫，聚眾攻陷剡縣、諸暨等縣。宣宗用王式為浙東觀察使，以武寧軍健卒二千人送之。王生擒仇甫以獻，斬於東市。","sortOrder":75},
  {"id":"s_work_dnl_22_76","chapterId":"ch_work_dnl_22","text":"宣宗時，吳居中恩泽甚厚。有謀於術者，欲败其事，術者令書上尊號於襪。有告者，上召至，视之信然，居中弃市。","sortOrder":76},
  {"id":"s_work_dnl_22_77","chapterId":"ch_work_dnl_22","text":"宣宗崩，內官定策立懿宗，入中書商議，命宰臣署状。宰相將有不同者，夏侯孜曰：\"三十年前，外大臣得與禁中事；三十年以來，外大臣固不得知。但是李氏子孫，內大臣立定，外大臣即北面事之，安有是非之說？\"遂率同列署状。","sortOrder":77},
  {"id":"s_work_dnl_22_78","chapterId":"ch_work_dnl_22","text":"大中末，京城小兒叠布蘸水，向日張之，謂之\"晕出入。\"（案：\"晕出入，蘇鹗《杜陽雜編》作\"捩晕。\"）懿宗自鄆王即位，晕之言應矣。","sortOrder":78},
  {"id":"s_work_dnl_22_79","chapterId":"ch_work_dnl_22","text":"宣宗製《泰邊陲》曲，其辭雲：\"海嶽晏鹹通。\"上即位，而年號\"鹹通\"。","sortOrder":79},
  {"id":"s_work_dnl_22_80","chapterId":"ch_work_dnl_22","text":"懿宗祠南郊。舊例：青城御幄前設彩樓，命仆寺辈作樂，上登樓以觀，眾呼萬歲。起居郎李璋上疏請罢，事不行。","sortOrder":80},
  {"id":"s_work_dnl_22_81","chapterId":"ch_work_dnl_22","text":"懿宗嘗幸左軍，見觀音像，禮之，而像陷地四尺。問左右，對曰：\"陛下，中國之天子；菩薩，地上之道人。\"上悅之。","sortOrder":81},
  {"id":"s_work_dnl_22_82","chapterId":"ch_work_dnl_22","text":"滑州城，北枕河堤，常有淪墊之患。貞元中，贾丞相耽凿八角井於城隅，以镇河水。鹹通初，刺史李ㄅ以其事上聞，立贾公祠，命從事韦岫紀其事。","sortOrder":82},
  {"id":"s_work_dnl_22_83","chapterId":"ch_work_dnl_22","text":"政平坊安國觀，明皇時玉真公主所建。門樓高九十尺，而柱端無斜。殿南有精思院，琢玉為天尊老君之像，葉法善、羅公遠、張果先生併圖形於壁。院南池引御渠水註之，叠石像蓬萊、方丈、瀛洲三山。女冠多上陽宮人。其東與國學相接。鹹通中，有書生雲：\"嘗聞山池內步虛笙磬之音。\"盧尚書有詩雲：\"夕照紗窗起暗尘，青松繞殿不知春。閒看白首誦經者，半是宮中歌舞人。\"","sortOrder":83},
  {"id":"s_work_dnl_22_84","chapterId":"ch_work_dnl_22","text":"薛能尚書镇鄆州，見舉進士者必加異禮。李勋尚書先德為衙前將校，八座方為客司小弟子，亦負文藻，潛慕進修，因扌舍歸田里。未逾歲，服麻衣，執所業於元戎，左右具白其行止，不請引見。元戎曰：\"此子慕善。才與不才，安可拒耶？\"命召之入。見其人质清秀；复覽其文卷，深器重之。乃出郵巡職牒一通與八座先德，俾罢職司閒居，恐妨令子進修爾。果策名第，扬歷清顯，出為鄆州節度也。","sortOrder":84},
  {"id":"s_work_dnl_22_85","chapterId":"ch_work_dnl_22","text":"沈宣詞嘗為麗水令。自言家大梁時，廄常列駿馬數十，而意常不足。鹹通六年，客有馬求售，絜白而毛鬣類朱，甚異之，酬以五十萬，客許而直未及給，遽為將校王公遂所買。他日，謁公遂，問向時馬，公遂曰：\"竟未嘗乘。\"因引出，至則奋眄，殆不可跨，公遂怒捶之，又仆，度終不可禁。翌日，令諸子乘之，亦如是；諸仆乘，亦如是。因求前所直售宣詞。宣詞得之，复如是。會魏帥李公蔚市貢馬，前後至者皆不可。公閱馬，一閱遂售之。後入飛龍，上最愛寵，為當時名馬。","sortOrder":85},
  {"id":"s_work_dnl_22_86","chapterId":"ch_work_dnl_22","text":"鹹通十年停貢舉。前一年，日者言：己丑年無文柄，值\"至仁\"必當重振，明年上加尊號，內有\"至仁\"兩字，韓褒為補闕，上疏請复之。夏侯孜謂楊元翼雲：\"李九丈行不得事，我行之。\"九丈即衛公也。","sortOrder":86},
  {"id":"s_work_dnl_22_87","chapterId":"ch_work_dnl_22","text":"皮日休，鄭尚書愚門生。春闈內宴於曲江，醉寢別榻，衣囊書笥，羅列旁侧，率皆新飾。同年崔昭符，鐐之子，素易日休。亦醉。更衣，見日休臥；疑他相知也，就视，乃日休，曰：\"勿呼之，渠方宗會矣！\"以囊笥皆皮也。時人以為口實。","sortOrder":87},
  {"id":"s_work_dnl_22_88","chapterId":"ch_work_dnl_22","text":"盧隱、李峭，皆王铎門生，時議皆以衽席不修，屢黜辱。隱從兄携，少相狎，志欲引用。及携為丞相，除右司員外郎。時崔沆方為吏部侍郎，謁携於私第，携欣然而出。沆曰：\"盧員外入省，時議未息；今复除糾司員外郎，省中所不敢從，他曹惟相公命。\"携大怒，馳去，曰：\"舍弟極屈，即當上陳矣！\"隱即放出。沆乃謁告，携即時替沆官。沆謂人曰：\"吾見丞郎出省郎，未見省郎出丞郎。\"隱初自太常博士除水部員外郎，為右丞李景溫抑焉，迨右司之命，景溫弟景莊复右轄，又抑之。是時諫官有陳疏者，携曰：\"諫官似狗，一狗吠，辄一時有聲。\"","sortOrder":88},
  {"id":"s_work_dnl_22_89","chapterId":"ch_work_dnl_22","text":"李譜者，珏之子。自淮南赴舉，路經蒲津，謁崔公铉。铉以子妻之，而性忌妒。譜，宰相子，懷不平，多爭競。铉忽召譜讓之，譜初猶端笏，既忿，即橫手板曰：\"譜及第不幹丈人，官職不幹丈人。\"語未卒，铉掩耳而去。其妻竟怨憤而卒。","sortOrder":89},
  {"id":"s_work_dnl_22_90","chapterId":"ch_work_dnl_22","text":"畢霞冶競ⅰＯ掏ǔ酰渚訟蛭匚椴深恥之，常使人諷令解役，為除官，反复數四，竟不從命。乃特除選人楊載為太湖令。涎又嗟冢鑫?除其猥籍，津送入京。楊令到任，具達絃狻Ｎ椴唬?\"某賤人也，豈有外甥為宰相耶？\"楊堅勉之，乃曰：\"某每歲秋夏征租，享六十千事例錢，苟無败闕，終身優足。不審相公欲致何官耶？\"楊乃具以聞稀Ｏ亦然其說，竟不奪其志也。又王蜀伪相庾傳素，與其從弟凝積，曾宰蜀州唐興縣。郎吏有楊會者，微有才用，庾氏崑弟深念之。洎迭秉蜀政，欲為楊會除長馬以現；嵩唬?\"某之吏役，遠近皆知，忝冒為官，寧掩人口？豈可將數千家供待，而博一虛名長馬乎？\"後雖假職名，止除檢校官，竟不扌舍縣役，亦畢舅之次也。（案：此條采自孫光憲《北夢琐言》，楊會非懿宗時人，原附畢現耸潞螅袢雲渚桑?","sortOrder":90},
  {"id":"s_work_dnl_22_91","chapterId":"ch_work_dnl_22","text":"鹹通初，洛中謠曰：\"勿雞言，送汝树上去；勿鸭言，送汝水中去。\"又曰：\"勿笑父母不以汝。\"及李納為河南尹，是年大水，納觀水於魏王堤上，波势浸盛，慮其覆溺，於是策馬而回。時人語曰：\"昔瓠子將坏，而王尊不去；洛水未至，而李納已回。\"是時男女多栖於木，鹹為所漂者，父母觀之不能救。","sortOrder":91},
  {"id":"s_work_dnl_22_92","chapterId":"ch_work_dnl_22","text":"鹹通中，有司天歷生胡某，以老還江南。後辟郡掾曹，辭不赴，歸居建業。盧符寶者，亦知名士也。嘗問：\"近年宰相不滿四人，豈非三台有異乎？\"曰：\"非三台也，乃紫微受灾耳！自今十餘年未可備。苟有之，即不免大禍。\"後路巖、於、王铎、韦保衡、楊收、劉鄴、盧携相次拜，後不免。","sortOrder":92},
  {"id":"s_work_dnl_22_93","chapterId":"ch_work_dnl_22","text":"池州李常侍宽，守江南數郡，皆請盧符寶為判官。及守陵陽，信子弟之谮，疏不召。盧忿謂人曰：\"李公面部所無者三：無子、無宅、無冢。\"時有龍公滿禪師。李氏所敬也，於坐難之曰：\"今李氏子弟皆長成，何言無子？\"盧曰：\"非承家令器。\"又曰：\"今土牆甲第，花竹猶不知其數，何言無宅？\"盧曰：\"是王行立宅，李氏安得歌笑於其間？\"時桂林大夫即常侍兄，同營別業於金陵，甲第之盛，冠於邑下，人皆號為\"土牆李家宅\"。江南宮城西街內，石井欄在通衢中者，即宅內廳前井也。自創宅，即令家人王行立看守，仅數十年矣，故盧君有此言。座客聞之，莫不笑。及池陽寇起，宽死，將歸葬新林，為賊所邀，舟人盡見殺，棺柩不知所在。諸子悉無成立。世亂，王行立獨守其宅，竟死其中。","sortOrder":93},
  {"id":"s_work_dnl_22_94","chapterId":"ch_work_dnl_22","text":"路巖镇劍南，出开遠門街，恣為瓦石所击，故京兆尹溫璋諸子之党也。初，李舉薛能，巖取於省部，權京兆尹事，至是謂能曰：\"臨行勞以瓦砾相餞。\"能徐舉笏曰：\"故事：宰相出镇，府司無發人防守者。\"巖甚慚。","sortOrder":94},
  {"id":"s_work_dnl_22_95","chapterId":"ch_work_dnl_22","text":"路相巖與崔雍同在崔相铉幕。雍恃己名聲，因醉，撫巖背曰：\"路子路子！爭得共崔雍同恩門？\"巖恨之。巖為丞相。會和州不守，有石琼者訟之，乃賜雍死。","sortOrder":95},
  {"id":"s_work_dnl_22_96","chapterId":"ch_work_dnl_22","text":"鹹通末，曹相確、楊相收、徐相商、路相巖同為宰相。楊、路以弄權賣官，曹、徐但備員而已。長安謠曰：\"'確''確'無論事，錢财總被'收'。'商'人都不管，货'賂'幾時休？\"","sortOrder":96},
  {"id":"s_work_dnl_22_97","chapterId":"ch_work_dnl_22","text":"僖宗好蹴球、斗鸭為樂，自以能於步打，謂俳優石野猪曰：\"朕若步打進士，當得状元。\"野猪對曰：\"或遇尧、舜、禹、湯作禮部侍郎，陛下不免且落第。\"帝大笑。","sortOrder":97},
  {"id":"s_work_dnl_22_98","chapterId":"ch_work_dnl_22","text":"黃寇入京，郭妃不食，奔赴行在，乞食於都城，時人嗟之。","sortOrder":98},
  {"id":"s_work_dnl_22_99","chapterId":"ch_work_dnl_22","text":"僖宗幸蜀，御座是明皇幸蜀故物；又舁御座人李再忠，經明皇時供奉，時以為異。（原註：案廣明元年，上距天寶將百年，此說甚妄）","sortOrder":99},
  {"id":"s_work_dnl_22_100","chapterId":"ch_work_dnl_22","text":"僖宗入蜀。太史歷本不及江東，而市有印货者，每差互朔晦，货者各征節候，因爭執。里人拘而送公，執政曰：\"爾非爭月之大小盡乎？同行經紀，一日半日，殊是小事。\"遂叱去。而不知陰陽之歷，吉凶是擇，所誤於眾多矣。","sortOrder":100},
  {"id":"s_work_dnl_22_101","chapterId":"ch_work_dnl_22","text":"僖宗幸蜀回，改元光啟。俗諺雲：\"軍中名'血'為'光'，又字體'戶口負戈'為'啟'，其未寧乎？\"俄而未久亂作，長安复陷。","sortOrder":101},
  {"id":"s_work_dnl_22_102","chapterId":"ch_work_dnl_22","text":"升州上元縣前有古浮圖，嘗有僧指雲：\"為此，無縣丞正位。\"詢之，自唐初併無縣丞，諸司註授，句留在京，縱有赴任者，不月餘必卒。唯廣明中，有丞張遜，到任才月餘，節度周寶追命上府筑夹城訖，歸縣未久，與令爭競，移為睦州遂安尉。","sortOrder":102},
  {"id":"s_work_dnl_22_103","chapterId":"ch_work_dnl_22","text":"劉瞻自丞相出镇荆南。鄭畋為翰林承旨，草製雲：\"居數畝之宮，仍非己有；却四方之賂，惟畏人知。\"路巖謂畋曰：\"侍郎乃表荐劉相也！\"出為同州刺史。","sortOrder":103},
  {"id":"s_work_dnl_22_104","chapterId":"ch_work_dnl_22","text":"鄭相畋與盧相携外兄弟，同在中書。後因議政喧競，扑碎砚，王侍中铎笑之曰：\"不意中書有瓦解之事！\"","sortOrder":104},
  {"id":"s_work_dnl_22_105","chapterId":"ch_work_dnl_22","text":"太尉韦昭度，舊族名人，位非忝竊，而沙門僧澈潛荐之中禁，一二時相皆因之大拜。悟達國師知元乃澈之師，世常鄙之。諸相在西川行在，每謁悟達，皆申跪禮，國師揖之，請於僧澈處吃茶。後韦掌武伐成都，田軍容致書曰：\"伏以太尉相公：頃因和尚，方始登庸。在中書則开鋪賣官，居翰林則倩人把筆。\"蓋謂此也。","sortOrder":105},
  {"id":"s_work_dnl_22_106","chapterId":"ch_work_dnl_22","text":"盧澄為李司空蔚淮南從事，因酒席請一舞妓解籍，公不許，澄怒，詞多不遜。公笑曰：\"昔之狂司馬，今也憨從事。\"澄索彩具，蔚與赌貴兆，曰：\"彩大者，秉大柄。\"澄掷之得十一，席上皆失聲。公徐掷之，得堂印。澄托醉而起。後數月，澄入南省；不數年，蔚入相。","sortOrder":106},
  {"id":"s_work_dnl_22_107","chapterId":"ch_work_dnl_22","text":"翰林學士孫《北里志》雲：\"鄭舉舉巧談諧，常有名賢醵宴。乾符中，状元孫頗惑之，與同年數人多至其舍，他人或不盡預。同年盧嗣業訴醵罰錢，致詩状元曰：'未識都知面，頻输复分錢。苦心親筆砚，得志助花钿。徒步求秋賦，持杯給暮饣。力微多謝病，非不奉同年。'嗣業，同年非舊知，又力窮不遵醵罰，故有此詩。曲內妓之頭角者為都知，舉舉、降真是也。曲中一席四，見燭即倍，新郎更倍，故曰'复分錢'。一日，同年宴，舉舉有疾，不來，令同年李深之為酒糾。状元吟曰：'南行忽見李深之，手舞如風令不疑，任你風流兼醞藉，天生不似鄭都知。'\"","sortOrder":107},
  {"id":"s_work_dnl_22_108","chapterId":"ch_work_dnl_22","text":"杜讓能，丞相審權之子；韦相保衡，審權之甥。保衡少不為讓能所禮。保衡為相，讓能久不中第。及登科，審權憤其沈厄，以一子出身奏監察御史。","sortOrder":108},
  {"id":"s_work_dnl_22_109","chapterId":"ch_work_dnl_22","text":"崔相沆知貢舉，得崔瀣。時榜中同姓，瀣最為沆知。谭者稱：\"座主門生，沆瀣一氣。\"","sortOrder":109},
  {"id":"s_work_dnl_22_110","chapterId":"ch_work_dnl_22","text":"許棠初试進士，與薛能、陆肱齊名。薛擢第，尉擢；肱下第，遊太原：棠併以詩送之。棠登第，薛已自京尹出镇徐州，陆亦出守南康，招棠為僿。初，高侍郎知舉，棠納卷，覽其詩雲：\"退已經三十載，登龍仅見一千人。\"乃曰：\"世复有屈於許棠者乎？\"永臨劉相，以其子希同年，留為淮南馆驿官，令和韻，棠嗜詩不通；南海仆射時為副使知府事，笑謂人曰：\"相公令許棠和韻，可謂虐人也！\"","sortOrder":110},
  {"id":"s_work_dnl_22_111","chapterId":"ch_work_dnl_22","text":"許棠常言於人曰：\"往者未成事，年漸衰暮，行倦達官門下，身疲且重，上馬極難。自喜得第來筋骨輕健，攬辔升降，猶愈於少年。則知一名，乃孤進之還丹。\"","sortOrder":111},
  {"id":"s_work_dnl_22_112","chapterId":"ch_work_dnl_22","text":"華鬱，三衢人，早遊田令孜門，擢進士第，歷正郎金紫。李瑞，曲江人，亦受知於令孜，擢進士第，又為令孜賓佐。俱為孔魯公所嫌。文德中，與鬱俱陷刑網。","sortOrder":112},
  {"id":"s_work_dnl_22_113","chapterId":"ch_work_dnl_22","text":"裴筠婚萧楚公女，言定未幾，便擢進士。羅隱以一絕刺之，略曰：\"細看月輪還有意，信知青桂近嫦娥。\"","sortOrder":113},
  {"id":"s_work_dnl_22_114","chapterId":"ch_work_dnl_22","text":"秦韜玉應進士舉，出於单素，屢為有司所斥。京兆尹楊損奏复等列。時在選中。明日將出榜，其夕忽叩试院門，大聲曰：\"大尹有帖！\"试官沈光發之，曰：\"聞解榜內有人，曾與路巖作文書者，仰落下。\"光以韜玉為問，損判曰：\"正是此。\"","sortOrder":114},
  {"id":"s_work_dnl_22_115","chapterId":"ch_work_dnl_22","text":"方幹貌陋唇缺，味嗜魚，性多譏戲。萧中丞典杭，軍僿吳杰患眸子赤；會宴於城樓飲，促召杰，杰至，目為風掠，不堪其苦。憲笑命近座女伶裂紅巾方寸帖脸，以障風。幹時在席，因為令戲杰曰：\"一盏酒，《一捻鹽》，止見門前懸箔，何處眼上垂帘？\"杰還之曰：\"一盏酒，一脔，止見半臂著钅，何處口唇开？\"一席絕倒。爾後人多目幹為\"方开\"。","sortOrder":115},
  {"id":"s_work_dnl_22_116","chapterId":"ch_work_dnl_22","text":"羅給事隱、顧博士雲，俱受知於相國令狐公。顧雖鹾商子，而風韻詳整。羅，錢塘人，乡音乖刺。相國子弟每有宴會，顧獨預之，丰韻談諧，不辨寒素之子也。顧賦為時所稱，而切於成名。嘗有啟事，陳於所知，只望丙科盡處，竟列名於尾科之前也。羅既頻不得意，未免怨望，意為貴子弟所排，契闊東歸。黃寇事平，朝賢意欲召之。韦貽范沮之曰：\"某與之同舟而載，雖未相識，舟人告雲：'此有朝官。'羅曰：'是何朝官！我腳夹筆，可以敵得數辈。'必若登科通籍，吾徒為秕糠也。'\"由是不果召。","sortOrder":116},
  {"id":"s_work_dnl_22_117","chapterId":"ch_work_dnl_22","text":"駙馬韦保衡為相，頗弄權势。及將败，長安小兒競彩戲，謂之\"打围\"。不旬日餘，韦禍及。","sortOrder":117},
  {"id":"s_work_dnl_22_118","chapterId":"ch_work_dnl_22","text":"大中十二年，李衛公謫崖州。歷宣、懿兩朝無宗相。至乾符二年，李蔚為相，俄罢去。歷乾符、廣明、中和、光啟、文德、龍紀、大順、景福、乾寧，悉無宗相，而宗室陵遲尤甚，居官者不過郡縣長，處乡里者或為里胥。","sortOrder":118},
  {"id":"s_work_dnl_22_119","chapterId":"ch_work_dnl_22","text":"唐末，飲席之間多以《上行杯》、《望遠行》拽盏為主，《下次據》副之。既而僖宗西行，後方镇多為下位者所據，此其验也。","sortOrder":119},
  {"id":"s_work_dnl_22_120","chapterId":"ch_work_dnl_22","text":"唐末士人之衣色尚黑，故有紫绿，有墨紫。迨兵起，士庶之衣俱皂，此其讖也。","sortOrder":120},
  {"id":"s_work_dnl_22_121","chapterId":"ch_work_dnl_22","text":"唐末婦人梳髻，謂\"拔丛\"；以亂發為胎，垂障於目。解者雲：\"群眾之計，目睹其亂發也。","sortOrder":121},
  {"id":"s_work_dnl_23_1","chapterId":"ch_work_dnl_23","text":"●卷八·補遺（無時代）","sortOrder":1},
  {"id":"s_work_dnl_23_2","chapterId":"ch_work_dnl_23","text":"宓犧氏以農官；神農以火；黃帝以雲；少昊以鳥；颛頊而名以民事，又以五行為官名；作司徒，敬敷五教；禹作司空，以平水土；周則以天、地、春、夏、秋、冬為官名。伏以古者命官，以天地、四氣、五行、雲龍為號者，皆上禀天時，下達人事，見聖人垂意，未有不及於惠民也。後代不究深旨，率爾命官，仆射、侍中，尤為不可。秦有侍中、仆射，其初且非官名，唯供奉左右，是其職業。侍中，當西漢掌乘舆服，下至亵器、虎子之類；虎子，溺器也。武帝以安國為侍中，以其儒者，特許掌御唾壶，朝廷榮之。班固雲：\"侍中，本丞相吏也。五人來往殿內奏事，故曰'侍中。'\"又仆射者，射音夜，尤寡其義。在秦有周青臣，孔衍註雲：\"仆射，小官扶左右者也。\"亦曰\"衛令仆射，守門之夫。\"在漢為武士門仆射，在宮則曰宮門仆射、永巷仆射：蓋言\"仆御\"執射之夫也，如今宦竖之首耳。皆因權幸，漸峻官名。开元元年，改左右仆射為左右丞相，是官號之不正也。又則天寵侍御者張昌宗，其官號曰\"控鶴監\"。向使五王未复唐德，則\"控鶴\"亦沾丞相之名也。","sortOrder":2},
  {"id":"s_work_dnl_23_3","chapterId":"ch_work_dnl_23","text":"兩省官上事日，宰相臨焉。上事者設床幾，面南而坐，判三道案。宰相別施一床，連上事官床，南坐於西隅，謂之\"壓角\"。自常侍而下，以南為上，差舛相承，實乖禮敬。曷不為丞相設位於眾官之南，常侍、諫議、給事、舍人循次而坐於丞相之下？尊卑有序，足以為儀。\"壓角\"之來，莫究其始。《开元禮》及累朝典故併無其文。習俗因循，莫近於理。今請去\"壓角\"，以釋眾疑。凡言九寺，皆曰\"棘卿\"。《周禮》\"三槐九棘\"：槐者，懷也；上佐天子，懷來四夷。棘者，言其赤心以奉其君，皆三公九卿之任也。唐世惟大理得言棘卿，他寺則否。九寺皆树棘木，大理則於棘下訊鞫其罪，所謂\"大司寇聽刑於棘木之下\"。","sortOrder":3},
  {"id":"s_work_dnl_23_4","chapterId":"ch_work_dnl_23","text":"朝廷百司諸廳皆有壁記，叙官秩創置及遷授始末。原其作意，蓋欲著前政履歷，而發將來健羨焉。故為記之體，貴其說事詳雅，不為苟飾，而近時作記，多措浮詞，褒美人才，抑扬功閥，殊失記事之本意。韦氏《兩京記》雲：\"郎官盛寫壁記，以紀當廳前後遷除出入，寢以成俗。\"然則壁記之起，當自國朝已來，始自台省，遂流郡邑耳。","sortOrder":4},
  {"id":"s_work_dnl_23_5","chapterId":"ch_work_dnl_23","text":"官衔之名，蓋興近代。當時選曹補授，須存資歷，聞奏之時，先具舊官名品於前，次書擬官於後，使新舊相衔不斷，故曰\"官衔\"，亦曰\"頭衔\"。所以名為\"衔\"者，言如人口衔物，取其連續之意。又如馬之有衔以製其首，前馬之進，後馬續來，相次不絕者，古人謂之\"衔尾相續\"，即其義也。","sortOrder":5},
  {"id":"s_work_dnl_23_6","chapterId":"ch_work_dnl_23","text":"近代通謂府庭為公衙，公衙即古之公朝也。字本作\"牙\"，《詩》曰：\"祈父，予王之爪牙。\"祈父，司馬，掌武備。象猛獸，以爪牙為衛，故軍前大旗謂\"牙旗\"，出師則有\"建牙\"、\"牙\"之事。是軍中聽號令，必至牙旗之下，稱與府朝無異。近俗尚武，是以通呼\"公府\"為\"公牙\"，\"府門\"為\"牙門\"，字稱訛变，轉而為\"衙\"。《漢書·地理志》冯翊有衙縣，春秋時彭衙之地，非公府之名。或雲：公門外刻木為牙，立於門侧，以象獸牙；軍將之行，置牙竿首，懸旗於上，其義一也。","sortOrder":6},
  {"id":"s_work_dnl_23_7","chapterId":"ch_work_dnl_23","text":"舆駕行幸，羽儀导從，謂之\"滷簿\"。自秦漢以來始有其名。蔡邕《獨斷》所載滷簿，有\"小駕\"、\"大駕\"、\"法駕\"之異，而不詳滷簿之義。按字書：\"滷，大也。\"字亦作\"橹\"，又作\"滷\"，音義皆同。以甲為之，所以敵。贾誼《過秦論》雲，\"伏尸百萬，流血漂滷\"是也。甲有先後部伍之次，皆著之簿籍。天子出，則案次道從，故謂之\"滷簿\"耳。儀衛具五兵，今不言他兵，獨以甲為名者，行道之時，甲居外，餘兵在內，但言\"滷簿\"，是舉凡也。南朝御史中丞、建康令俱有滷簿，人臣儀衛，亦得同於君上，則滷簿之名不容別於他義也。又百官從駕，謂之\"扈從\"。蓋臣下侍從至尊，各供所職，猶仆御扈養以從上，故謂之\"扈從\"耳。《上林賦》雲：\"扈從橫行\"，顏監釋雲：\"謂跋扈縱恣而行也。\"據顏此解，乃讀\"從\"為\"放縱\"之縱，不取\"行從\"之義，所未詳也。","sortOrder":7},
  {"id":"s_work_dnl_23_8","chapterId":"ch_work_dnl_23","text":"御史台三院：一曰台院，其僚曰侍御史，眾呼為\"端公\"。見宰相及台長，則曰\"某姓侍御\"。知雜事謂之\"雜端\"。見台長，則曰\"知雜侍御\"。雖他官高秩兼之，其侍御號不改。見宰相，則曰\"知雜某姓某官\"。台院非知雜者，俗號\"散端\"。二曰殿院，其僚曰殿中侍御史，眾呼為\"侍御\"。見宰相及台長雜端，則曰\"某姓殿中\"。最新入，知右巡；已次，知左巡：號\"兩巡使\"。所主繁剧。及遷向上，則又入推，益為煩勞。惟其中間，則入清閒。故台中諺曰：\"免巡未推，只得自如。\"言其閒適也。廳有壁畫，小山水甚工，雲是吳道子真跡。三曰察院，其僚曰監察御史，眾呼亦曰\"侍御史\"。見宰相及台長雜端，則曰\"某姓監察\"。若三院同見台長，則通曰\"三院侍御\"。而主簿紀其所行之事。每公堂食會，雜事不至，則無所檢轄，唯相揖而已。雜事至，則盡用憲府之禮。雜端在南榻，主簿在北榻，兩院則分坐。雖舉匕箸，皆絕谭笑。食畢，則主簿持黃卷揖曰：\"請舉事。\"於是台院長白雜端曰：\"舉事\"。（原註：欲上堂，三院長各於食堂之南廊下，先白雜端雲：\"合舉事。\"）則舉曰：\"某姓侍御史（原註：有同姓者，則以第行別之）有某過，請准條。\"主簿書之。其兩院皆仿此。若舉時差错，則最小殿中舉院長，則最小侍御史舉殿院長；又错，則向上人遞舉。雜端失笑，則三院皆笑，謂之\"烘堂\"，悉免罰矣。凡見黃卷罰直，遇赦悉免。台長到諸院，凡官吏有所罰，亦悉免。御史歷三院雖至美，而月滿殿中推鞫之勞，憚於轉兩院，以向下侍御史便領推也，多不願為，以此台中以\"殿中轉西院\"為戲詛之詞。每出入行步，侍御史在柱里，殿、察兩院在柱外；有時殿中入柱里，則共ㄉ之曰：\"著（原註：直略反）去也。\"三院御史主簿有事白端公，就其廳，若有中路白事，謂之\"端\"，有罰。殿中有免巡，遇正知巡者假故，則向上人又權知，謂之\"蘸巡\"。台官有親愛除拜及喜慶之事，則謁院長、雜端、台長，謂之\"取贺\"。凡此皆因胥徒走卒之言，遂成故事。察院每上堂了各報，諸御史皆入立於南廊，便服僸鞋，以俟院長。立定，院長方出，相揖而序行。至殿院門，揖殿中，又序行；至食堂前，揖侍御史。凡入門至食，凡數揖。祗揖者，古之肅拜也。台中無不揖，其酒無起謝之禮，但雲\"揖酒\"而已。酒取合敬，故恐煩却揖。往往自台拜他官，執事亦誤作\"台揖\"，人皆笑之。每赴朝序行，至待漏院偃息，則有\"臥揖\"；馬上則有\"馬揖\"。凡院長在廳院內，御史欲往他院，必先白，决罰又先白。察院有都廳，院長在本廳，諸人皆會話於都廳。（原註：御史初上後，遇雜端上堂，則舉三愆九失儀，緣是新人，欲併罰也。未遇雜端上堂，其犯舊條併不罰）察院南院，會昌初監察御史鄭路所葺。禮察廳謂之\"松廳\"，南有古松也。刑察廳，謂之\"魇廳\"，寢於此多魇。兵察常主院中，茶必市蜀之佳者，貯於陶器，以防暑濕。御史躬親緘啟，故謂之\"茶瓶廳\"。吏察主院中入朝人次第名籍，謂之\"朝簿廳\"。吏察之上，則馆驿使。馆驿使之上，則監察使。同僚之冠也，謂之院長。台中敬長，三院皆有長。察院風彩尤峻。凡三院御史初拜，未朝謝，先謁院長；辭疾不見，則不得謝及上矣。（原註：諸家《御史台記》，多載當時御史事跡戲笑之言，故事甚略。台中有儀註，後漸遺闕。雖有板榜，亦但錄一時要節，自此轉磨滅矣）","sortOrder":8},
  {"id":"s_work_dnl_23_9","chapterId":"ch_work_dnl_23","text":"御史主彈奏不法，肅清內外。唐興，宰辅多自憲司登鈞軸，故謂御史為宰相。杜鸿漸拜授之日，朝野傾羨。監察御史振舉百司綱紀，名曰\"入品宰相\"，高宗朝，王本立、餘偅始為御史里行，則天更置內供奉及員外试御史，有台使、里使，皆未正名也。其里行員外试者，俗名為\"合口椒\"，言最有毒；監察為\"开口椒\"，言稍毒散；殿中為\"萝卜\"，亦謂\"生薑\"，言雖辛辣而不能為患；侍御史謂之\"掐毒\"，言如蜂蠆去其芒刺也。御史多以清苦介直獲進，居常敝服羸馬，至於殿庭。开元末，宰相以御史權重，遂製彈奏者先谘中丞、大夫，皆通許，又於中書、門下通状先白，然後得奏。自是御史不得特奏，威權大减。天寶中，宰相任人不专清白，朝為清介，暮易其守，順情希旨，綱維稍紊。御史羅希猜毒，吉溫頗苛細，時稱\"羅鉗吉網，望風氣慑。\"开元已前，諸節製併無憲官，自張守為幽州節度，加御史大夫，幕府始帶憲官，由是方面威權益重。遊宦之士，至以朝廷為閒地，謂幕府為要津。遷騰倏忽，坐致郎省，彈劾之職，遂不复舉。","sortOrder":9},
  {"id":"s_work_dnl_23_10","chapterId":"ch_work_dnl_23","text":"御史舊例：初入台，陪直二十五日，節假五日，謂之\"伏豹\"，亦曰\"豹直\"。百司州縣初授官陪直者，皆有此名。杜易簡解\"伏豹\"之義雲：\"宿直者，離家獨宿，人情所貴。其人初蒙策拜，故以此相處。伏豹者，言眾官皆出，此人獨留，如伏藏之豹，伺候待搏，故雲'伏豹'耳。\"韓琬則解為\"爆直\"，言如燒竹，遇節則爆。餘以為南山赤豹，愛其毛體，每雪霜雨霧，諸禽獸皆出取食。唯赤豹深藏不出，古人以喻賢者隱居避世。鮑明遠《賦》雲：\"豈若南山赤豹，避雨霧而深藏。\"此言\"伏豹\"、\"豹直\"者，蓋取不出之意。初官陪直，已有\"伏豹\"之名，何必以遇節而比燒竹之\"爆\"也？杜說雖不甚明，粗得其意；韓則疏矣。","sortOrder":10},
  {"id":"s_work_dnl_23_11","chapterId":"ch_work_dnl_23","text":"新官併宿本署，曰\"爆直\"，佥作\"爆\"進之字。惠郎中實雲：\"合作虎'豹'字。\"言豹性絜，善服氣，雖雪雨霜霧，伏而不出，慮污其身。","sortOrder":11},
  {"id":"s_work_dnl_23_12","chapterId":"ch_work_dnl_23","text":"唐製十八道節度，其後號九節度。其後河朔三镇，及四凶、二竖之亂，可考大略。明皇天寶元年，置十節度經略使以備邊：曰安西、曰北庭、曰河西，以備西邊；曰朔方、曰河東、曰范陽，以備北邊；曰平盧，以備東邊；曰隴右、曰劍南，以備西邊；曰嶺南五府經略，以備南邊。節度之立，其初固止於沿邊十道耳。自安祿山之亂，則內地始置九節度以讨之，曰：朔方郭子儀，淮西魯炅，興平李，滑濮許叔冀，镇西李嗣業，鄭蔡李廣琛，河東李光弼，泽潞王思禮，河南崔光遠。內地之置節度，其初猶止於九道耳。自朱氏之倡亂中原也，則自國門之外，皆方镇矣。蓋其先也，欲以方镇御四夷，而其後也，則以方镇御方镇。十道既已兆亂，則內地必置九道，以除其亂；九道又兆亂，則關外近郡又不得不置矣。至代宗廣德元年，以田承嗣為魏博節度，李懷仙為盧龍節度，李寶臣為成德節度，是謂河北三镇，各有其地。其風俗獷戾，過於蠻貊，吾知其河北之地，非复朝廷有矣。至於大歷九年，相推戴而謂之四王：朱滔稱冀王，田悅稱魏王，王武俊稱趙王，李納稱齊王。李希烈又以淮西稱帝，朱糜忠怨刂諧頻邸Ａ淹良僂跽?\"四凶\"，滔天僭帝者\"二竖\"；紛紛籍籍，不知其幾也。蓋唐之亂，非藩镇無以平之，而亦藩镇有以亂之。其初跋扈陆梁者，必得藩镇而後可以戡定其禍亂，而其後戡定禍亂者，亦足以稱禍而致亂。故其所以去唐之亂者，藩镇也；而所以致唐之亂者，亦藩镇也。试以其一二論之。安氏之亂，懷恩平之也；而留三镇以遺患者，亦一懷恩也。將兵至京師，冒雨寒而來，姚令言之功也，而所以迎朱枚÷京師者，亦一令言也。擒子期破田悅者，李寶臣之功，而釋承嗣以為己資者，亦寶臣也。卒至於終唐之世，莫敢誰何者，由三镇始也。","sortOrder":12},
  {"id":"s_work_dnl_23_13","chapterId":"ch_work_dnl_23","text":"露布，捷書之別名也。諸軍破賊，則以帛書建諸竽上，兵部謂之\"露布\"。蓋自漢以來有其名。所以露布者，謂不封檢，露而宣布，欲四方之速聞也。亦謂之\"露板\"。魏晉奏事，雲\"有警急，辄露板插羽\"是也。宋時沈璞為盱眙太守，與臧质固拒魏軍，軍退，质謂璞城主，使自上露板。後魏韓顯宗大破齊軍，不作露布，高祖怪而問之，對曰：\"頃間諸將，獲賊二三，驢馬，皆為露布，臣每哂之。近雖仰凭威靈，得摧丑竖，斬擒不多，脱复高曳長缣，虛張功捷，尤而效之，其罪弥甚。所以斂毫卷帛，解上而已。\"然則露布、露板，古今通名也。隋文帝詔太常卿奇章公撰宣露布儀。开皇九年平陳，元帥晉王以ㄞ上露布，兵部請依新禮：\"集百官及四方客使於朝堂，內史令稱有詔，在位者皆拜；宣露布訖，蹈舞者三，又拜。郡縣皆同。\"唐因其體。然露布於大抵皆張皇國威，廣談帝德，動逾數千字，其能體要不煩者，鮮矣。","sortOrder":13},
  {"id":"s_work_dnl_23_14","chapterId":"ch_work_dnl_23","text":"古者閹尹擅權专製者多矣，其間不無忠孝，亦存編簡。唐自安史以來，兵難氵存臻，天子插越，親衡戎柄，皆付大閹，魚朝恩、窦文場乃其魁也。爾後置左右軍、十二衛，觀軍容、處置、枢密、宣徽四院使，擬於四相也。十六宮使，皆宦者為之，分卿寺之職，朝廷班行備員而已。供奉官紫衣入侍，後軍容使楊复恭俾具钅笏宣导，自复恭改作也。嚴遵美，內謁之最良也。嘗典戎，唐末致仕於蜀郡，鄙叟庸夫，時得親狎。其子仕蜀，至僩門使。曾為一僧致紫袈裟，僧來感謝之，書記所謝之語於掌中，方屬炎天，手汗模糊，文字莫辨。折腰而趨，流汗喘之，只雲：\"伏以軍容……\"寂無所道，抵视掌心良久，雲：\"貌寢人微，凡事無能。\"嚴曰：\"不敢，不敢。\"退而大哈。嚴公物故，蜀朝册命赠，給事中窦雍堅不承命。雖偏霸之世，亦不苟且，士人多之。","sortOrder":14},
  {"id":"s_work_dnl_23_15","chapterId":"ch_work_dnl_23","text":"邹山，古之嶧山，始皇刻碑處，文字分明。始皇乘羊車以上，其路猶存。案：此地，春秋時邾文公卜遷於繹者也。始皇刻石紀功，其文李斯小篆。後魏太武帝登山，使人排倒之。然歷代摹拓以為楷則，邑人疲於供命，聚薪其下，因野火焚之，由是殘缺，不堪摹寫，然由上官求請，行李登陟，人吏轉益勞弊。有縣宰取舊文勒於石碑之上，凡成數片，置之縣廨，須則拓取。自是山下之人，邑中之吏，得以息。今人間有《嶧山碑》，皆新刻之碑也。其文雲\"刻此樂石\"，學者不晓\"樂石\"之意，顏師古謂取泗濱磬石作此碑。始皇於琅琊、會稽諸山刻石，皆無此意，唯《嶧山碑》有之，故知然也。","sortOrder":15},
  {"id":"s_work_dnl_23_16","chapterId":"ch_work_dnl_23","text":"墓前碑碣，未詳所起。案《儀禮》：廟中有碑，所以系牲，併视日景。《禮記》雲：\"公室视丰碑，三家视桓楹。\"丰碑、桓楹、天子、諸侯葬時下棺之柱，其上有孔，以穿纟卒索，懸棺而下，取其安審，事畢即閉圹中。臣子或書君父勋閥於碑上，後又立之於隧口，故謂之\"神道碑\"，言神靈之道也。古碑上往往有孔，是貫纟卒之遺象。前漢碑甚少，後漢蔡邕、崔瑗之徒，多為人立碑；魏晉之後，其流浸盛。碣亦碑之類也。《周禮》：\"凡金玉錫石，曷而玺之。\"註雲：\"曷，如今題署物。\"《漢書》雲：\"瘞寺前，揭著其姓名。\"註雲：\"曷，弋也，弋於瘞處而書死者之姓名。曷音揭。\"然則物有標榜，皆謂之\"曷\"。郭景純《江賦》雲：\"峨眉為泉扬之曷。\"又变為\"碣\"，《說文》雲：\"碣，特立石也。\"據此則從木、從石兩體皆通。隋之製：五品以上立碑，螭首龟趺，上不得過四尺，載在《丧葬令》。近代碑碣稍眾，有力之家多輦金帛以祈作者。雖人子罔極之心，順情虛飾，遂成風俗。蔡邕雲：\"吾為人作碑多矣，唯郭有道無愧詞。\"隋文帝子齊王攸薨，僚佐請立碑，帝曰：\"欲求名，一卷史書足矣；若不能，徒為後人作镇石耳。\"誠哉是言！","sortOrder":16},
  {"id":"s_work_dnl_23_17","chapterId":"ch_work_dnl_23","text":"石碑皆有圓空。蓋碑者，悲也，本墟墓間物。每一墓有四焉。初葬，穿繩於孔以下棺，乃古懸窆之禮。《禮》曰：\"公室视丰碑，三家视桓楹。\"人因就紀其德，由是遂有碑表。數十年前，時有树德政碑，亦製圓空，不知根本甚矣。後有悟之者，遂改焉。","sortOrder":17},
  {"id":"s_work_dnl_23_18","chapterId":"ch_work_dnl_23","text":"人道尚右，以右為尊。禮先賓客，故西讓客，主人在東，蓋自卑也。後人或以東讓客，非禮也。蓋緣見所在地，所主在東，俗有東行南頭之戲，此乃貴為一方一境之主也。《記》曰：\"天子無客禮，莫敢為主焉。故君適其臣，升自阼階，不敢有其室也。\"註：\"明饗君，非也。\"唐之方镇及刺史，入本部，於令長已下，禮絕賓主，猶近君臣。至於藩镇經管內支郡，則俱是古南面諸侯，但以使職監臨，如台省之官至外地耳。即通宴饗，則異君臣，而用古天子升階之儀，非禮也。","sortOrder":18},
  {"id":"s_work_dnl_23_19","chapterId":"ch_work_dnl_23","text":"近代風俗，人子在膝下，每生日有酒食之事；孤露之後，不宜复以為歡會。梁孝元帝少時，每以載誕之辰，辄設斋講經，洎阮修容殁後，此事亦絕少。太宗曾以降誕日感泣。中宗常以降誕日宴侍臣內庭，與學士聯句《柏梁體詩》。然則唐以來，此日皆有宴會。开元十七年，丞相張說奏：以八月端午降誕日為千秋節，又改為天長節。肅宗因之，誕日為地平天成節。代宗雖不為節，猶受四方進獻。德宗即位，詔公卿議，吏部尚書顏真卿奏：\"准《禮經》及歷代帝王無降誕日，唯开元中始為之。复推本意：以為節者，喜聖寿無疆之慶，天下鹹贺，故號節；若千秋萬歲之後，尚存此日以為節假，恐乖本意。\"於是敕停之。","sortOrder":19},
  {"id":"s_work_dnl_23_20","chapterId":"ch_work_dnl_23","text":"明皇朝，海內殷贍。送葬者或當冲設祭，張施帏幕，有假花、假果、粉人、粉帳之屬。然大不過方丈，室高不逾數尺，識者猶或非之。丧亂以來，此風大扇，祭盤帳幕，高至九十尺，用床三、四百張，雕镌飾畫，窮極技巧，饌具牲牢，复居其外。大歷中，太原節度辛雲京葬日，諸道節度使使人修祭。范陽祭盤最為高大，刻木為尉遲鄂公與突厥斗將之戲，機關動作，不異於生。祭訖，靈車欲過，使者請曰：\"對數未盡。\"又停車，設項羽與漢祖會鸿門之象，良久乃畢。者皆手擘布幕，輟哭觀戲。事畢，孝子傳語與使人：\"祭盤大好，賞馬兩匹。\"滑州節度令狐母亡，鄰境致祭，昭義節度初於淇門載船桅以充幕柱，至時嫌短，特於衛州大河船上取長桅代之。及昭義節度薛公薨，歸葬絳州，諸方併管內縣涂陽城南設祭，每半里一祭，至漳河二十餘里，連延相次。大者費千餘貫，小者三、四百貫，互相窥觇，競為新奇。柩車暫過，皆為弃物矣。蓋自开辟至今，奠祭鬼神，未有如斯之盛者。","sortOrder":20},
  {"id":"s_work_dnl_23_21","chapterId":"ch_work_dnl_23","text":"俗間凶疏，本叙時序朔望，以表遠感之懷，此合於情理。至有叙經斋七日，此出釋教，不當形於書疏。","sortOrder":21},
  {"id":"s_work_dnl_23_22","chapterId":"ch_work_dnl_23","text":"准禮：父在，為所生母；父為嫡子；夫為妻；皆杖周。自周禮已降，至於《开元禮》，及唐史二百六十年，併無有易斯議，未聞為兄弟杖者。自離亂之後，武臣為弟始行周杖之禮，是賓佐不能以禮正之，致其谬誤也。乾寧三年九月，行弔於名士之家，睹其弟為兄杖，門人知舊來，無有言其乖禮者，實慮日久浸以為是。自今後，士子好禮者，於服式之中，慎而行之。","sortOrder":22},
  {"id":"s_work_dnl_23_23","chapterId":"ch_work_dnl_23","text":"今俗釋服多用昏時，非禮也。按《戴禮》：\"魯人有朝祥而暮歌者，子路笑之。\"夫子雖抑子路雲：\"三年之丧，亦已久矣。\"而复曰：\"逾月則其善。\"明知月晦之朝，去縞從吉也，明日則逾月矣，故夫子怪其不待明日而歌。今之免服准式給晦日假者，蓋以朝既從吉，使竟是日吉服，盡與親賓相見，遍示禮終，至明日复參公務，無樂不為之義。又禮書皆雲：前一夕除某物，废某物。又曰：\"夙興\"雲雲，知前夕除废，為明晨之漸。凡曰釋服，悉宜從朝矣（原註：今在脱服假內，反不見賓友也）。《禮》雲\"大丧不避涕泣而見人\"者，言既不行求見人，人來求之，不避涕泣，以表至哀無飾。今世卒哭之後，朔望時節，辭不見賓客，非也。若尊高居丧，弔者以是日客多，不敢求見，遽自退去，宜矣，非所以辭也。","sortOrder":23},
  {"id":"s_work_dnl_23_24","chapterId":"ch_work_dnl_23","text":"三日成服，聖人之製，世有至五日者，非也。","sortOrder":24},
  {"id":"s_work_dnl_23_25","chapterId":"ch_work_dnl_23","text":"忌日請假，非古也。《世說》雲：\"忌日惟不飲酒作樂。會稽王世子將以忌日送客至新亭，主人欲作樂，王便起去，持彈往衛洗馬墓彈鳥。\"《晉書》又載：桓玄\"忌日與賓客遊宴，惟至時一哭而已。\"此前代忌日無假之證也。沈約《答庾光祿書》雲：\"忌日製忌，應是晉、宋之間，其事未久。未至假前，止是不為宴樂，本自不封閉，如今世自處者。居丧再周之內，每至忌日，哭臨受弔，無不見人之義。而除服之後，乃不見人。實由世人以忌日不樂，而不能竟日興感，以對賓客，或弛懈，故過自屏晦，不與外接。設假之由，實在於此。\"顏延之：\"忌日感慕，故不接外賓，不理庶務，不能悲怆自居，何限於深藏也。世人或端坐奧室，不妨言笑，迫有急卒，寧無盡見之理？其不知禮意乎！\"","sortOrder":25},
  {"id":"s_work_dnl_23_26","chapterId":"ch_work_dnl_23","text":"李匡雲：\"《晉書》稱阮鹹善琵琶，是即是矣。\"按《周書》雲：\"武帝彈琵琶，後梁宣帝起舞，謂武帝曰：'陛下既彈五絃琴，臣何敢不同百獸舞？'\"則周武帝所彈，乃是今之五絃。可知前代凡此類，總號琵琶爾。又按《風俗通》雲：\"以手批把，謂之琵琶。自拨彈已後，惟今四絃始专琵琶之名。\"因依而言，則劉饣束所雲：\"貞觀中，悲洛兒始弃拨，用手以撫琵琶。\"是又不知故事者之言也。又因此而征之，五絃之號，即出於後梁宣帝之語也。而今阮氏琵琶，正以手撫，反不能占琵琶之名，失本義矣。","sortOrder":26},
  {"id":"s_work_dnl_23_27","chapterId":"ch_work_dnl_23","text":"今有奕局，共取一道，人行五棋，謂之\"蹙融\"。\"融\"宜作\"戎\"，此戲生於黃帝蹙鞠，意在軍戎也，殊非\"圓融\"之義。庾元規著《座右方》，所言\"蹙戎\"，是也。","sortOrder":27},
  {"id":"s_work_dnl_23_28","chapterId":"ch_work_dnl_23","text":"今之博戲，長行最盛。其具有局有子，黑、黃各十有五，掷采之頭有二。其法生於握槊，变於双陆。天後夢双陆不勝，狄公言\"宮中無子\"，是也。後人新意，長行出焉。又有小双陆、围透、大點、小點、遊談、鳳翼之名，然無如長行。鑒险易者，喻時事焉；適变通者，方《易》象焉。王公大臣，頗或耽玩，至於废慶弔，忘寢食。闾里用之，於是強名爭勝，謂之\"撩零\"；假借分畫，謂之\"囊家\"。囊家什一而取，謂之\"子頭\"。有通宵而戰者，有破產而输者。中世工者，有浑鎬、崔師本。围棋次於長行，其中世工者，韦延扈、楊。彈棋鮮有為之，中世工者，有吉達、高越首出焉。","sortOrder":28},
  {"id":"s_work_dnl_23_29","chapterId":"ch_work_dnl_23","text":"貞元中，董叔儒進博局，併《經》一卷，頗有新意，不行於世。","sortOrder":29},
  {"id":"s_work_dnl_23_30","chapterId":"ch_work_dnl_23","text":"隋置明經、進士科，唐承隋，置秀才、明法、明字、明算，併前六科。主司則以考功郎中，後以考功員外郎。士人所趨，明經、進士二科而已。及大足元年，置拔萃，始於崔翘。开元十九年，置宏詞，始於鄭昕。开元二十四年，置平判入等，始於顏真卿。是年，考功員外郎李昂摘進士李權章句疵之，榜於通衢；權摘昂詩句之失，由是世難其事，乃命禮部侍郎主之。後有左補闕薛邕，中書舍人達奚、李韦、李麟、姚子彦、張蒙、高郢、權德舆、衛次公、張宏靖、於允躬、韦貫之、李逢吉、李程、庾承宣、贾饣束、沈、杜審權、李、裴恒、王铎、李蔚、趙骘、鄭愚，太常少卿李建，尚書萧昕，仆射王起，常侍萧仿，黃門侍郎許孟容、鄭顯，刑部侍郎崔枢，戶部侍郎韦昭度雜主之，而宏靖不以進士顯。","sortOrder":30},
  {"id":"s_work_dnl_23_31","chapterId":"ch_work_dnl_23","text":"唐朝初，明經取通兩經，先帖文，乃案章疏试墨策十道；秀才试方略策三道；進士時務策五道。考功員外郎職當考试。其後舉人憚於方略之科，為秀才者殆絕，而多趨明經、進士。高宗時，進士特難其選。龍朔中，敕左史董思恭與考功員外郎權原崇同试貢舉。思恭吳士輕脱，泄進士問目，三司推，贓狼籍，命西朝堂斬决。告变，免死除名，流梧州。开耀元年，員外郎劉思立以進士惟试時務策，恐复傷膚淺，請加试雜文兩道，併帖小經。明皇時，士子殷盛，每歲進士到省者，常不减千餘人，在馆諸生更相造詣，互結朋党，以相傾奪，號之為\"棚\"，推聲望者為\"棚頭\"。權門貴盛，無不走也，以此熒惑主司视聽。其不第者率多喧訟。考功不能御。开元二十四年冬，遂移貢舉屬於禮部，侍郎姚奕頗振綱紀焉。後明經停墨策，试口義，併時務策三道。進士改貼大經，加《論語》。自是舉司帖經，多有聱牙、孤絕、例拔、筑註之目。文士多於經不精，至有白首舉場者，故進士以帖經為大厄。天寶初，達奚、李巖相次知貢舉。進士聲名高而帖落者，時或试詩放過，謂之\"贖帖\"。十一年，楊國忠初知選事，進士孫季卿會謁國忠，言禮部帖經之弊：\"舉人有實材者，帖經既落，不得试文；若先试雜文，然後帖經，則無遺才矣。\"國忠然之。無何，有敕進士先试帖，然仍前後开一行，是歲收人有倍常歲。又舊例：试雜文者，一時一賦，或兼试頌論，而題目多為隱僻。策問五道，舊例：三道為時務策，一道為方略，一道為征事；近者方略之中，或有異同，大抵非精究博贍之才，難以應乎茲選矣。故當代以進士登科為\"登龍門\"，解褐多拜清紧，十數年間擬跡廟堂。輕薄為之語曰：\"及第進士，俯视中、黃郎；落第進士，揖蒲、華長馬。\"又雲：\"進士初擢第，頭上七尺焰光。\"好事者紀其姓名，自神龍以來迄於茲，名曰《進士登科記》，亦所以示前良，發起後進也。寶應二年，楊綰為禮部侍郎，奏：舉人不先德行，率多浮薄，請依乡舉里選。於是詔天下舉秀才孝廉，而考试章條，漸加繁密，至於升進德行，未之能也。其後應此科者益少，遂罢之，复為明經、進士。","sortOrder":31},
  {"id":"s_work_dnl_23_32","chapterId":"ch_work_dnl_23","text":"唐製：常舉人之外，又有製科，搜扬拔擢，名目甚眾。則天廣收才彦，起家或拜中書舍人、員外郎，次拾遺、補闕。明皇尤加精選，下無滯才。然製舉出身，名望雖美，猶居進士之下。仕宦自進士而歷清貫，有八俊者：一曰進士出身，製策不入；二曰校書、正字不入；三曰畿尉不入；四曰監察御史、殿中丞不入；五曰拾遺、補闕不入；六曰員外郎、郎中不入；七曰中書舍人、給事中不入；八曰中書侍郎、中書令不入。言此八者，尤加俊捷，直登宰相，不要歷綰餘官也。朋僚遷拜，或以此更相譏弄。舉人應及第者，關檢無籍者，不得與第。陳章甫製策登科，吏部放榜，章甫上書：\"昨見榜雲：'戶部報無籍者。'昔傅說無姓，商後置於鹽梅之地；屠羊隱名，楚王延以三旌之位，未聞征籍也。范雎改姓易名為張祿先生，秦用之霸；張良為韓報仇，变姓名而遊下邳，漢高用之為相。則知籍者，所以計賦耳，本防群小，不約賢路。若人有大才，不可以籍弃之；苟無良德，雖籍何為？\"所司不能奪，特谘執政收之。常舉外，复有通五經、明一史，以獻文章併著述之辈，或府中書考试，亦同製舉。","sortOrder":32},
  {"id":"s_work_dnl_23_33","chapterId":"ch_work_dnl_23","text":"春官氏每歲選升進士三十人，以備將相之任。是日，自状元已下，同詣座主宅，座主立於庭。一一而進曰：\"某外氏某家。\"或曰\"甥\"，或曰\"弟\"。又曰：\"某大外氏某家。\"又曰：\"外大外氏某家。\"或曰\"重表弟\"，或曰\"表甥孫\"。又有同宗座主宜為侄，而反為叔。言叙既畢，拜禮得申。予辄議曰：\"春官氏選士得其人，止供職業耳，而俊造之士，以經術待聘，獲采拔於有司，則朝廷與春官氏皆何恩於舉子？今使謝之，則與選士之旨，豈不異乎？至有海東之子，嶺峤之人，皆與華族叙中表，從使拜首而已。論諸事體，又何有哉？\"","sortOrder":33},
  {"id":"s_work_dnl_23_34","chapterId":"ch_work_dnl_23","text":"神龍元年已來，累為主司者：房光庭再，太極元年、开元元年。裴耀卿再，开元五年、六年。李納四，开元七年、八年、九年、十年。嚴挺之三，开元十四年、十五年、十六年。裴敦复再，开元十九年、二十年。孫逖再，开元二十二年、二十三年。已前，併考功員外郎。姚奕再，开元二十四年、二十五年，始命春官小宗伯主之。崔翘三，开元二十七年、二十八年、二十九年。達奚四，天寶二年、三年、四年、五年。李巖三，天寶六年、七載、八載。李麟再，天寶十載、十一載。陽涣再，天寶十二載、十五載。裴士淹再，至德二年、三年。姚子彦再，乾元三年、上元二年。萧昕再，寶應二年、貞元三年。薛邕四，大歷二年、三年、四年、五年。張渭三，大歷六年、七年、八年。蒋涣再，大歷九年、十年。常兖三，大歷十年、十一年、十二年。潘炎再，大歷十三年、十四年。鮑防三，興元二年、貞元元年、二年。劉太真再，貞元四年、五年。顧少連再，貞元十年、十四年。呂渭三，貞元十一年、十二年、十三年。權德舆三，貞元十八年、十九年、二十年停舉，永貞元年。崔再，元和元年、二年。韦貫之再，元和八年、九年。庾承宣再，元和十年、十一年。王起四，長慶二年、三年、會昌三年、四年。楊嗣复再，寶歷元年、二年。崔郾再，太和元年、二年。鄭浣再，太和三年、四年。贾饣束再，太和五年、六年。高锴再，开成元年、二年。柳景再，开成五年、會昌元年。陳商再，會昌五年、六年。鄭顥再，大中十年、十三年。","sortOrder":34},
  {"id":"s_work_dnl_23_35","chapterId":"ch_work_dnl_23","text":"董生言：日常右轉，星常左轉。大凡不滿三萬，日行周二十八舍，三百六十五度。然必有差，約八十年差一度。自漢文三年甲子冬至，日在斗二十二度，至唐興元元年甲子冬至，日在斗九度，九百六十一年，差十三度矣。","sortOrder":35},
  {"id":"s_work_dnl_23_36","chapterId":"ch_work_dnl_23","text":"含元殿，凿龍首岡以為址，彤墀钅口砌，高五十餘尺。左右立栖鳳、翔鸞二闕，龍尾道出於闕前，倚欄下视，南山如在掌中。殿去五門二里，每元朔朝會，禁軍御杖宿於殿庭。金甲葆戈，雜以綺繡；文武纓佩，蕃夷酋長皆序立。仰觀玉座，若在霄漢。","sortOrder":36},
  {"id":"s_work_dnl_23_37","chapterId":"ch_work_dnl_23","text":"太湖中有禹廟。山僧雲：\"禹导吳江以泄具區，會諸侯於此。\"","sortOrder":37},
  {"id":"s_work_dnl_23_38","chapterId":"ch_work_dnl_23","text":"西明寺、慈恩寺多古畫。慈恩塔前壁有\"濕耳獅子趺心花\"，為時所重。聖善、敬愛兩寺，亦有古畫。聖善寺木塔院，多鄭廣文畫併書，敬愛寺山亭院有畫雉尾若丹砂子，上有進士房增題名處。後有人題曰：\"姚家新婿是房郎，未解芳顏意欲狂。見說正調穿淚箭，莫教射破寺家牆。\"西北角有病龍院，併吳生畫。","sortOrder":38},
  {"id":"s_work_dnl_23_39","chapterId":"ch_work_dnl_23","text":"盧言舊宅在東都歸德坊南街。廳屋是杏木梁，西壁有韦冕郎中畫馬六匹。","sortOrder":39},
  {"id":"s_work_dnl_23_40","chapterId":"ch_work_dnl_23","text":"兖州邹縣嶧山，南面半腹，東西長數十步。其處生桐，相傳以為《禹貢》\"嶧陽孤桐\"者也。土人雲：此桐所以異於常桐者，諸山皆發地土多，惟此山大石攒倚，石間周回，皆通人行，山中空虛，故桐木响絕，以是珍而入貢也。按《漢書·地理志》：下邳縣西，有葛嶧山，古之嶧陽下邳者是矣。","sortOrder":40},
  {"id":"s_work_dnl_23_41","chapterId":"ch_work_dnl_23","text":"關西西風則雨，東風則晴，皆以為常候。夫九州之地，洛陽為土中，風雨之所交也。今關西西風則雨，關東東風則雨，是風氣各自其方而來，交於土中，陰陽和則雨成。","sortOrder":41},
  {"id":"s_work_dnl_23_42","chapterId":"ch_work_dnl_23","text":"相里湯陰縣北有里城，周回可三百餘步，其中平實，高於城外地丈餘，北开一門，相傳文王演《易》之所。曹子建《詰紂文》雲：\"崇侯何功，乃用為辅？西伯何辜，囚之囹圄？囹圄既成，負土既盈，興立炮烙，賊害忠貞。\"觀此意，見文王所囚之地，紂使負土實此城也。未詳子建所據。今按：此東頓邱、臨黃諸縣多有古小城，周一里或一、二百步，其中皆實。郭緣生《述征記》雲：\"彭城東有宅城，雲是崇侯冢，自淮迄於河上。城而實中謂之'宅'，邱垅可阻謂之'固'。\"然則城小而實，皆古人因依立冢以為保固，子建所雲\"負土既盈\"，或承流俗之傳耳。","sortOrder":42},
  {"id":"s_work_dnl_23_43","chapterId":"ch_work_dnl_23","text":"晉文王欲修九龍堰，阮步兵舉鋤掘地，得古承水銅龍六枚，堰遂成。水歷曷東註，謂之千金渠。晉世又廣功焉。石人東肋下文雲：\"泰始七年六月二十三日大水，荡坏三曷，今改為曷。更於西开泄，名曰伐（原註：一作代）龍渠。增高千金之舊一丈四尺，若五龍。歲久复坏，可轉於西更开三曷。二渠合用二十三萬五千六百九十八功。以其年十月二十二日起作，功重人少，到八年四月二十日畢。\"伐龍渠，即九龍渠也。元魏修复故曷，朝廷太和中造石渠於水上。按桥西門之南頰文，稱晉元康二年十一月二日畢。漢司空王梁為河南，將引水以溉京都，渠成而水下流。後張純堰洛而通漕，是渠今引洛水，蓋純之創也。","sortOrder":43},
  {"id":"s_work_dnl_23_44","chapterId":"ch_work_dnl_23","text":"凡造物由水，水由土。故江東宜綾紗，宜紙，鏡水之故也。蜀人織錦初成，必濯於江，然後文采煥發。鄭人以滎水酿酒，近邑與遠郊美數倍。齊人以阿井煎膠，其井比旁井重數倍。","sortOrder":44},
  {"id":"s_work_dnl_23_45","chapterId":"ch_work_dnl_23","text":"蜀土舊無兔鴿。隋开皇中，荀秀镇益州，命左右賣兔、鴿而往。今蜀中鴿尚稀而兔已眾。戴祚《西征記》雲：\"开封縣東二佛寺，餘至此始見鴿，大小如鳩，戲時兩兩相對。\"祚，江東人，晉末從劉裕西征姚泓，至开封縣始識鴿。江東舊亦無鴿。梁武時，侯景围台城，軍士熏鼠捕鴿而食。數月之後，殿屋鼠鴿皆盡。然則江東有鴿，亦當自北贲往耳。","sortOrder":45},
  {"id":"s_work_dnl_23_46","chapterId":"ch_work_dnl_23","text":"凡東南郡邑無不通水，故天下货利，舟楫居多。轉運使歲運米二百萬石以输關中，皆自通濟渠入河也。淮南篙工不能入黃河。蜀之三峡，陝之三門，閩越之惡溪，南康贛石，皆絕险之處，自有本土人為工。大抵峡路峻急，故曰\"朝離白帝，暮宿江陵\"。四月、五月尤险，故曰：\"滟大如馬，瞿唐不可下；滟大如牛，瞿唐不可留；滟大如袱，瞿唐不可觸。\"扬子、錢塘二江，則乘兩潮發棹。舟船之盛，盡於江西，編蒲為帆，大者八十餘幅。自白沙溯流而上，常待東北風，謂之\"信風\"。七月、八月有上信，三月有鳥信，五月麥信。暴風之候，有抛車雲，舟人必祭婆官而事僧伽。江湖語曰：\"水不載萬。\"言大船不過八九千石。大歷、貞元間，有俞大娘航船最大，居者養生送死婚嫁悉在其間。开巷為圃，操駕之工數百。南至江西，北至淮南，歲一往來，其利甚大，此則不啻載萬也。洪、鄂水居頗多，與一屋殆相半。凡大船必為富商所有，奏聲樂，役奴婢，以據舵樓之下。","sortOrder":46},
  {"id":"s_work_dnl_23_47","chapterId":"ch_work_dnl_23","text":"海舶，外國船也，每歲至廣州、安邑。師子國船最大，梯上下數吏，皆積百货。至則本道輻輳，都邑為喧闐。有番長為主人，市舶使籍其名物，納船腳，禁珍異，商有以欺诈入牢獄者。船發海路，必養白鴿為信，船没則鴿歸。","sortOrder":47},
  {"id":"s_work_dnl_23_48","chapterId":"ch_work_dnl_23","text":"龍門人皆言善於懸水接水，上下如神，然寒食拜扫必於河濱，終於水死也。","sortOrder":48},
  {"id":"s_work_dnl_23_49","chapterId":"ch_work_dnl_23","text":"海上居人，時見飛樓如結構之状，甚壮麗者；太原以北晨行，則煙霭之中睹城闕状，如女牆雉堞者：皆《天官書》所謂蜃也。","sortOrder":49},
  {"id":"s_work_dnl_23_50","chapterId":"ch_work_dnl_23","text":"建安郡建安縣有大勤墟，中有石，無小大悉如砚形。舊說此墟人有好學，而於義理不能疾晓，常自咎顽愚，每盛夏烈暑，乃肉袒以自負。後因雷雨，空中有人謂曰：\"念爾恳誠，吾令爾墟內石，大小俱成砚，苟用者，義理速解，以旌爾志。\"雨止视之，果然。今俗謂之\"孔砚\"。","sortOrder":50},
  {"id":"s_work_dnl_23_51","chapterId":"ch_work_dnl_23","text":"輕紗，夏中用者名為\"冷子\"，取其似蕉葉之輕健而名之。","sortOrder":51},
  {"id":"s_work_dnl_23_52","chapterId":"ch_work_dnl_23","text":"林邑獻火珠，雲得於羅刹國。","sortOrder":52},
  {"id":"s_work_dnl_23_53","chapterId":"ch_work_dnl_23","text":"風爐子以周繞通風也，一說形象烽火，名\"烽爐子\"。","sortOrder":53},
  {"id":"s_work_dnl_23_54","chapterId":"ch_work_dnl_23","text":"茶拓子，始建中蜀相崔寧之女，以茶杯無衬，病其熨手，取碟子承之。既啜，杯傾，乃以蠟環碟中央，其杯遂定。即命工以漆環代蠟。寧善之，為製名，遂行於世。其後傳者，更環其底，以為百状焉（原註：貞元初，青鄆猶繪為碟形，以衬茶碗，別為一家之樣。後人多雲拓子，非也。蜀相即升平崔家）。","sortOrder":54},
  {"id":"s_work_dnl_23_55","chapterId":"ch_work_dnl_23","text":"元和中，酌酒猶用樽杓，所以丞相高公有\"斟酌\"之譽。數千人一樽一杓，挹酒而散，了無所遺。其後稍用註子，形若，而蓋、嘴、柄皆具。太和九年後，中貴人惡其名犯鄭註，乃去柄安系，若茗瓶而小異，名曰\"偏提\"，時亦以為便，且言柄有礙而屢傾侧。","sortOrder":55},
  {"id":"s_work_dnl_23_56","chapterId":"ch_work_dnl_23","text":"被袋非古製，不知何時起也，比者遠遊行則用。太和九年，以十家之累，士人被竄謫，人皆不自保，常虞仓卒之遣，每出私第，鹹備四時服用。舊以紐革為腰囊，置於殿乘，至是服用既繁，乃以被袋易之。大中以來，吳人亦結絲為之，或有餉遺，豪徒玩而不用。","sortOrder":56},
  {"id":"s_work_dnl_23_57","chapterId":"ch_work_dnl_23","text":"都堂南門道中有古槐，垂陰至廣。相傳夜深聞絲竹之音，省中即有入相者，俗謂之\"音聲树\"。丛有似薔薇而異，其花葉稍大者，時人謂之\"枚槐\"，實語訛強名也，當呼為\"梅槐\"。按《江陵記》雲：\"洪亭村下有梅槐村。當因梅與槐合生，遂以名之。今似薔薇者，得非分枝條而滋演哉？至今葉形尚處梅、槐之間，可取此為證，\"且未見'枚槐'之義也。正使便為'玫瑰'字，豈百花中獨珍是，取象於玫瑰耶？\"（原註：玫瑰之瑰，音回，不音傀。其音傀者，是琼瑰。字書有證）","sortOrder":57},
  {"id":"s_work_dnl_23_58","chapterId":"ch_work_dnl_23","text":"豆有紅而圓長，其首乌者，舉世呼為\"相思子\"，非也，\"甘草子\"也。相思子即紅豆之異名也。其木斜斫之則有文，可為彈博局及琵琶槽。其树也，大株而白枝，葉似槐。其花與皂荚花無殊。其子若扁豆，處於甲中，通身皆紅。李善雲\"其實赤如珊瑚\"是也。又言，甘草非國老之藥者，乃南方藤名也。其丛似薔薇而無刺，葉似夜合而黃細，其花淺紫而蕊黃，其實亦居甲中，以條葉俱甘，故謂之\"甘草藤\"，土人但呼為\"甘草\"而已。出在潮陽，而南漳亦有。","sortOrder":58},
  {"id":"s_work_dnl_23_59","chapterId":"ch_work_dnl_23","text":"雄麻有花，而雌者結實，欲識麻之雌雄，以此辨之。","sortOrder":59},
  {"id":"s_work_dnl_23_60","chapterId":"ch_work_dnl_23","text":"江東有吐蚊鳥，夏則夜鳴，吐蚊於芦狄中，湖水尤甚。","sortOrder":60},
  {"id":"s_work_dnl_23_61","chapterId":"ch_work_dnl_23","text":"《月令》：出土牛，以示農耕之早晚，謂為國之大計，不失農時。故聖人急於養民，務成東作。今天下州郡，立春製一大牛，飾以文彩，即以彩杖鞭之，既而破之，各持其土以祈丰稔，不亦乖乎？","sortOrder":61},
  {"id":"s_work_dnl_23_62","chapterId":"ch_work_dnl_23","text":"七夕者，七月七日夜。《荆楚歲時記》：\"七夕，婦人穿七孔針，設瓜果於庭以乞巧。\"今人乃以七月六日夜為之，至明晓望於彩縷，以冀織女遺絲，乃是七\"晓\"，非\"夕\"也。又取六夜穿七竅針，益谬矣。今貴家或連二宵陳乞巧之具，此不過苟悅童稚而已。","sortOrder":62},
  {"id":"s_work_dnl_23_63","chapterId":"ch_work_dnl_23","text":"唐世謁見尊者，皆曰：\"謹祗候起居。\"起居者，動止也，理固不乖。近者复雲\"謹起居某官\"，則\"動止某官\"，其義何在？相承斯誤，曾不經心。","sortOrder":63},
  {"id":"s_work_dnl_23_64","chapterId":"ch_work_dnl_23","text":"終軍請長纓，世多雲將系单於。按本傳雲：\"南越與漢和親，乃遣軍使越說其王，欲令入朝比內諸侯。自請願受長纓，必羁南越王而致之闕下。\"若系单於，乃贾誼之事。按班固雲：\"誼欲试屬國，施五餌三表以系单於。\"乃贾誼之事也。又陳思王《表》雲：\"贾誼弱冠求试屬國，請系单於之頸，而製其命。\"","sortOrder":64},
  {"id":"s_work_dnl_23_65","chapterId":"ch_work_dnl_23","text":"有人檢陆法言《切韻》，見其音字，遂雲：\"此吳兒直是翻字太辟。\"不知法言是河南陆，非吳郡也。","sortOrder":65},
  {"id":"s_work_dnl_23_66","chapterId":"ch_work_dnl_23","text":"又有書生讀經書甚精熟，不知近代事，因說骆賓王，遂雲：\"某識其孫李少府者，兄弟太多。\"意謂\"骆賓\"是諸王封號也。","sortOrder":66},
  {"id":"s_work_dnl_23_67","chapterId":"ch_work_dnl_23","text":"畢羅者，蕃中畢氏、羅氏好食此味，今字從\"食\"，非也。餛饨，以其象混沌之形，不可直書\"混沌\"，從\"食\"可矣。至如不托，言舊未有刀扣之時，皆掌拓烹之，刀扣既具，乃雲\"不托\"，今俗字作\"搏托\"，非也（原註：元和中，有奸僧鑒虛者，以羊之六腑特造一味，傳之於今。時人不得其名，遂以其號目之，曰\"鑒虛\"。後俗字多作\"鑒虛\"，率多此類）。","sortOrder":67},
  {"id":"s_work_dnl_23_68","chapterId":"ch_work_dnl_23","text":"肆有以筐以，或倚或垂，以鬻鮮物者，曰\"星货鋪\"，言其列货丛雜如星之繁。今俗呼\"星火鋪\"，誤也。","sortOrder":68},
  {"id":"s_work_dnl_23_69","chapterId":"ch_work_dnl_23","text":"襄州漢高祖廟，本為交甫解佩於漢皋之義，今為高祖，誤。","sortOrder":69},
  {"id":"s_work_dnl_23_70","chapterId":"ch_work_dnl_23","text":"每歲有司行祀典者，不可勝紀。一乡一里，必有祀廟。南中有泉，流出山洞，常帶树葉，好事者目為\"流桂泉\"，後人乃立為漢高祖之神，尸而祝之。又號為伍員廟者，必五分其髯，謂\"五髭須\"。","sortOrder":70},
  {"id":"s_work_dnl_23_71","chapterId":"ch_work_dnl_23","text":"江南有驿官，以幹事自任，白刺史曰：\"驿中已理，請一閱之。\"初至為酒库，諸醞畢熟，其外畫神，問：\"何也？\"曰：\"杜康。\"刺史曰：\"公有餘也。\"一室曰茶库也，諸茗畢貯，复有神，問：\"何也？\"曰：\"陆鸿漸。\"刺史益喜。又一室俎库，諸俎畢備，复有神，問：\"何也？\"曰：\"蔡伯喈。\"刺史笑曰：\"不須置此。\"","sortOrder":71},
  {"id":"s_work_dnl_23_72","chapterId":"ch_work_dnl_23","text":"吳主孫皓每宴群臣，皆令盡醉。韦昭飲酒不多，皓密賜茶茗以代飲酒。晉時謝安詣陆納，無所供辦，設茶果而已（案：此古人亦飲茶耳，但不如今之溺之甚。窮日盡夜，殆成風俗）。","sortOrder":72},
  {"id":"s_work_dnl_23_73","chapterId":"ch_work_dnl_23","text":"軍中有透劍門伎。大宴日，庭中設幄數十步，若廊宇者，而編劍刃為榱棟之状。其人乘小馬至門，審度端直，鞭馬而過，然聞劍動之聲，既過而人馬無傷。宣武軍有小將善此伎，每饗軍則為之，所獲賞止於三四匹帛而已。一日，主者誤漏其名，此人忿恨，訴於所管大將，得复召入。呈伎之际，極為調審。入數步，忽風起馬驚，觸劍而死。","sortOrder":73},
  {"id":"s_work_dnl_23_74","chapterId":"ch_work_dnl_23","text":"壁州刺史邓宏慶，飲酒至\"平\"、\"索\"、\"看\"、\"精\"四字。酒令之設，本骰子\"卷白波\"律令。自後聞以\"鞍馬\"\"香球\"，或調笑抛打時上酒，\"招\"\"搖\"之號。其後平、索、看、精四字與律令全废，多以\"瞻相\"\"下次據\"上酒，絕人罕通者；\"下次掘\"一曲子打三曲，此出於軍中善師酒令，聞於世。","sortOrder":74},
  {"id":"s_work_dnl_23_75","chapterId":"ch_work_dnl_23","text":"飲坐作令，有不誤而飲罰爵者，皆曰\"虫傷旱潦\"。推其由，蓋以為不偶之義。\"虫傷\"宜為\"虫霜\"，蓋言農田水旱之害。呼曲子名，則\"下兵\"為\"下平\"，\"閣羅鳳\"為\"閣羅鳳\"。著詞則\"河內王\"為\"河奈王\"，\"樯竿上\"為\"長竿上\"。如斯之語甚多。","sortOrder":75},
  {"id":"s_work_dnl_23_76","chapterId":"ch_work_dnl_23","text":"唐人酒令：白樂天詩：\"鞍馬呼教住，骰喝遣输，長驅波卷白，連掷采盛盧。\"（原註：\"骰盤\"、\"卷白波莫走鞍馬\"，皆當時酒令）予按皇甫松所著《醉乡日月》三卷，載骰子令雲；聚十双骰子齊掷，自出手六人，依采飲焉。堂印本采人勸合席；碧油，勸掷外三人。骰子聚於一處，謂之\"酒星\"。依采聚散，骰子令中，改易不過三章，次改鞍馬令，不過一章。又有旗幡令、閃ㄓ令、抛打令。今人不复晓其法矣。唯優伶家猶用手打令以為戲雲。","sortOrder":76},
  {"id":"s_work_dnl_23_77","chapterId":"ch_work_dnl_23","text":"有齒鞋匠與樂工居隔壁。齒鞋者母卒未殓，樂工理聲不輟。匠者怒，因相詬成訟。樂工曰：\"此某業也。苟不為，衣與食且废。\"執政判曰：\"此本業，安可丧輟？他日樂工有丧事，亦任爾齒鞋不輟。\"","sortOrder":77},
  {"id":"s_work_dnl_23_78","chapterId":"ch_work_dnl_23","text":"初，詼諧自贺知章，輕薄自祖詠，〈軍頁〉語自贺蘭廣、鄭涉。其後詠字有萧昕，寓言有李纾，隱語有張著，機警有李舟、張，歇後有姚峴、孫叔羽，訛語、影帶有李直方、獨孤申叔，題目人有曹著。","sortOrder":78},
  {"id":"s_work_dnl_23_79","chapterId":"ch_work_dnl_23","text":"有王某雲：往歲任同州，見御史出案回，止州驿，經宿不發。忽追雜案，又取印歷，鎖驿甚急，一州大扰。有老吏竊笑，乃因庖人以通憲胥，許百缣為赠。翌日未明，御史啟驿門，盡還案牍，乘馬而去。","sortOrder":79},
  {"id":"s_work_dnl_23_80","chapterId":"ch_work_dnl_23","text":"起居舍人韦綬以心疾废，校書郎李播亦以心疾废。播常疑遇毒，鎖井而飲。散騎常侍李益少有疑病，亦心疾也。夫心者，靈府也，為物所中，終身不痊。多思慮，多疑惑，乃疾之本也。","sortOrder":80},
  {"id":"s_work_dnl_24_1","chapterId":"ch_work_dnl_24","text":"●辑佚","sortOrder":1},
  {"id":"s_work_dnl_24_2","chapterId":"ch_work_dnl_24","text":"唐建中初，士人韦生移家汝州，中路逢一僧，因與連鑣，言論頗洽。日將夕，僧指路歧曰：\"此數里是貧道蘭若，郎君能垂顧乎？\"士人許之，因令家口先行，僧即處分從者供帳具食。行十餘里，不至，韦生問之，即指一處林煙曰：\"此是矣。\"及至，又前進。日已昏夜，韦生疑之。素善彈，乃密於靴中取張卸彈，懷銅丸十餘，方责僧曰：\"弟子有程期，適偶貪上人清論，勉副相邀。今已行二十里，不至，何也？\"僧但言且行是。僧前行百餘步，韦生知其盜也，乃彈之僧，正中其腦。僧初若不覺，凡五發中之，僧始扪中處，徐曰：\"郎君莫惡作剧。\"韦生知無可奈何，亦不复彈。良久，至一莊墅。數十人列火炬出迎。僧延韦生坐一廳中，笑雲：\"郎君勿忧。\"因問左右：\"夫人下處如法無？\"复曰：\"郎君且自慰安之，即就此也。\"韦生見妻女別在一處，供帳甚盛。相顧涕泣。即就僧，僧前執韦生手曰：\"貧道，盜也。本無好意。不知郎君藝若此，非貧道亦不支也。今日固無他，幸不疑耳。適來貧道所中郎君彈悉在。\"乃舉手搦腦後，五丸墜焉。有頃布筵，具蒸犢，犢上刀子十餘，以齏餅環之。揖韦生就座，复曰：\"貧道有義弟數人，欲令謁見。\"言已，朱衣巨帶者五六辈列於階下。僧呼曰：\"拜郎君，汝等向遇郎君，即成齏粉矣！\"食畢，僧曰：\"貧道久為此業，今向遲暮，欲改前非，不幸有一子，技過老僧，欲請郎君為老僧斷之。\"乃呼飛飛出參郎君。飛飛年才十六七，碧衣長袖，皮肉如腊。僧曰：\"向後堂侍郎君。\"僧乃授韦一劍及五丸，且曰：\"乞郎君盡藝殺之，無為老僧累也。\"引韦入一堂中，乃反鎖之。堂中四隅，明燈而已。飛飛當堂執一短鞭。韦引彈，意必中，丸已敲落。不覺躍在梁上，循壁虛躡，捷若猱ㄑ。彈丸盡，不复中，韦乃運劍逐之，飛飛倏忽逗閃，去韦身不尺，韦斷其鞭數節，竟不能傷。僧久乃开門，問韦：\"與老僧除得害乎？\"韦具言之，僧怅然，顧飛飛曰：\"郎君證成汝為賊也，知复如何？\"僧終夕與韦論劍及弧矢之事。天將晓，僧送韦路口，赠絹百疋，垂泣而別。（《太平廣記》卷一九四題作《僧俠》，雲出《唐語林》，汪紹楹校曰：\"明鈔本作出《酉陽雜俎》）\"","sortOrder":2},
  {"id":"s_work_dnl_24_3","chapterId":"ch_work_dnl_24","text":"信州一{宀娄}士。有人乞州圖，因浣染為裙，墨跡不落。會鄰邀之，出數妓，設酒。良久，一婢驚報雲：\"君子誤燒裙。\"其人遽問所損處，婢曰：\"正燒著大雲寺門樓。\"（《類說》卷三二《語林》題作《州圖為裙》）","sortOrder":3},
  {"id":"s_work_dnl_24_4","chapterId":"ch_work_dnl_24","text":"李福妻裴忌妒。福镇滑台，有以女奴獻者。福曰：\"吾官至節度使，指使者不過奴隸，夫人得無甚乎？\"裴曰：\"未知公所欲者。\"福指所獻奴，裴許诺。福賂左右：\"夫人沐發，必來告。\"既告，福乃佯為腹痛，促召女奴；既往，左右亦以白裴。裴遽出發盆中，跣問所苦。福業以病為言，即若不可忍状，裴乃以藥小便中進之。明日，監軍、從事來問候，福具告之，大笑。（《類說》卷三二《語林》題作《腹痛召女奴》）","sortOrder":4},
  {"id":"s_work_dnl_24_5","chapterId":"ch_work_dnl_24","text":"御史大夫李季卿宣慰江南，至臨淮。或言常伯熊善茶者，李公請之。伯熊著黃衫、乌紗帽，手執茶器，口誦茶名，區別指點，左右刮目。茶熟，李公為啜兩杯。至江外，又召陆鸿漸。漸身衣野服，隨茶具而入，既坐，敷攤如伯熊故事。公心鄙之。茶畢，令奴子取錢三十文酬前茶博士。鸿漸久遊江介，通狎勝流，至此羞愧，复著《毀茶論》。（《類說》卷三二《語林》題作《煎茶博士》）","sortOrder":5},
  {"id":"s_work_dnl_24_6","chapterId":"ch_work_dnl_24","text":"令狐相，每朝廷大事，一取决於子氵高，如元載之伯和，李吉甫之德裕。（《類說》卷三二《語林》題作《政事取决於子》）","sortOrder":6},
  {"id":"s_work_dnl_24_7","chapterId":"ch_work_dnl_24","text":"士人初登榮進遷除，尉贺歡宴，謂之\"燒尾宴\"。嘗有虎，变為人，惟尾不化，須焚除乃得成人。以蒙初授，如虎得為人，本尾猶在。一雲：新羊入群，諸羊所觸，不相親附，火燒其尾則定。（《類說》卷三二《語林》題作《燒尾士人》）","sortOrder":7},
  {"id":"s_work_dnl_24_8","chapterId":"ch_work_dnl_24","text":"人家有小虫，至微而响甚，細尋之，卒不可見，謂之\"竊虫\"雲。有此者不祥。此虫大如胡麻，如鼠負，有兩頭，白色，振其頭則有聲。窗壁暗黑處多有之。拾遺孟昌朝貶贺州，作《竊虫賦》，比之鬼，似不識此意。（《類說》卷三二《語林》題作《竊虫》）","sortOrder":8},
  {"id":"s_work_dnl_24_9","chapterId":"ch_work_dnl_24","text":"有人患應病，問医官蘇澄，澄雲：\"古無此方。吾選《本草》，盡天下藥物，试將讀之。\"每發一聲，腹中辄應；惟至一藥，再三無聲。澄因處方，以此藥為主，其疾自除。（《類說》卷三二《語林》題作《應病》）","sortOrder":9},
  {"id":"s_work_dnl_24_10","chapterId":"ch_work_dnl_24","text":"杜河南兼聚書萬卷，每卷後題雲：\"請俸寫來手自校，汝曹讀之知聖道，墜之鬻之為不孝。\"（《類說》卷三二《語林》題作《請俸寫書》）","sortOrder":10},
  {"id":"s_work_dnl_24_11","chapterId":"ch_work_dnl_24","text":"李遠為杭州刺史，嗜啖绿頭鸭。貴客經過，無他饋餉，相厚者乃绿頭鸭一對而已。（《類說》卷三二《語林》題作《嗜绿頭鸭》）","sortOrder":11},
  {"id":"s_work_dnl_24_12","chapterId":"ch_work_dnl_24","text":"文宗以前無門状。自李衛公貴盛，百官無以希取其意，以舊刺（原註：即今之名紙）留其御候起居，號為門状。（《類說》卷三二《語林》題作《門状》）","sortOrder":12},
  {"id":"s_work_dnl_24_13","chapterId":"ch_work_dnl_24","text":"王彦伯医既著，列三四竈，煮藥於庭。老幼塞門來請。彦伯指曰：\"熱者飲此，寒者飲此，風者、氣者飲此。\"皆飲而去。（《白孔六帖》卷十一《竈》引《唐語林》）","sortOrder":13},
  {"id":"s_work_dnl_24_14","chapterId":"ch_work_dnl_24","text":"韓會與名辈號\"四夔\"，會首而善歌妙絕。（《白孔六帖》卷六一《歌》引《唐語林》）","sortOrder":14},
  {"id":"s_work_dnl_24_15","chapterId":"ch_work_dnl_24","text":"周鄭客唐衢，有文學，老而無成。善哭，發聲哀切，聞者泣下。常遊太原，遇享軍，酒酣乃哭，滿座不樂，主人為罢。（《白孔六帖》卷六四《哭》引《唐語林》）","sortOrder":15},
  {"id":"s_work_dnl_24_16","chapterId":"ch_work_dnl_24","text":"陳諫強記。染人歲籍所染綾帛，尋丈尺寸，為簿合围，諫泛覽，悉記之。（《白孔六帖》卷八四《染》引《唐語林》）","sortOrder":16},
  {"id":"s_work_dnl_24_17","chapterId":"ch_work_dnl_24","text":"盧昂主福建鹽鐵，有瑟瑟枕，大如斗。憲宗召市人估其直，或雲\"至寶無价\"，或雲\"美石，非真瑟瑟。（程大昌《演繁露》卷十五《瑟瑟》引《唐語林》）","sortOrder":17},
  {"id":"s_work_dnl_24_18","chapterId":"ch_work_dnl_24","text":"崔殷夢知舉，吏部尚書歸仁晦托弟仁泽，殷夢唯唯而已。無何，仁晦复詣托之，至於三四。殷夢斂色端笏，曰：\"某見進表讓此官矣。\"仁晦始悟己姓，殷夢讳也。（《容斋續筆》卷十一《唐人避讳》條引《語林》）","sortOrder":18},
  {"id":"s_work_dnl_24_19","chapterId":"ch_work_dnl_24","text":"高宗朝改門下省為東台，中書為西台，尚書省為文昌台，故御史台呼南台。南朝同。武後朝，御史有左、右肅政之號，當時亦謂之左台、右台，則憲府未曾有東台、西台之稱，惟俗間呼在京為西台，東都為東台。李栖筠為御史大夫，後人不名者，呼為\"西台\"，不知出何故事？豈以其名上有\"栖\"字故邪？趙歷祠部郎，同舍多以祠曹為目，因质之曰：\"祠部，改後唯有職祠、司二號，無祠曹之名。\"為以後漢疏寵辟司徒府，轉為辭曹，掌天下獄訟，其平决無不厭伏；又晉朝荆州人為羊讳嫌名，改戶曹為祠曹，故誤呼耳。（《永樂大典》卷之二千六百六《台·西台》引《唐語林》）","sortOrder":19},
  {"id":"s_work_dnl_24_20","chapterId":"ch_work_dnl_24","text":"武宗王才人有寵。帝身長大，才人亦類。帝每從禽作樂，才人必從。常令才人與帝同裝束。苑中射獵，帝與才人南北走馬，左右有奏事者，往往誤奏於才人前，帝以為樂。帝好道術，召天下方士殆盡。五年秋，王才人謂宣徽使曰：\"聖人日日對藥爐，服神丹，言我取不死。今身上变差事，道士稱換骨皆如此，某獨為忧也。\"宣徽使固求变見状，才人忍淚不敢語。外人雖未知帝得疾，但訝稀畋獵也。明年正月，不御紫宸殿、不开延英門向百日，中外始公言帝病。頃刻無才人見，臥起益酸痛，飲食益辛苦。一日，帝熟顧才人曰：\"吾氣息奄微，情慮杳杳，將不久矣！顧以別汝。\"對曰：\"陛下春秋鼎盛，又嘗服不死藥，聖寿必無疆，何忽出不祥語？\"帝曰：\"吾於汝且同外庭臣耶？惡用作形跡意！脱不如汝所對，而千秋萬歲，何以報我？\"才人欲恸，恐驚帝，乃曰：\"帝若忽厭四海，妾當同日死。\"帝哽咽閉目不喘息者少頃，忽曰：\"誠如汝言，當何為？\"曰：\"妾止於縊。\"帝引手取巾授才人曰：\"以此！以此！\"帝遂向壁不語。後數日，帝疾亟。才人久侍帝，歸寢，浓妆絜服如常日。乃盡取服玩與內家，持帝所授巾至前，見帝已崩，自縊而絕。宣宗即位，赠貴妃，命與端陵同日時掩。其圹在端陵柏城內西南。又有名才人隨靈駕行慢城內，每夕望端陵焚錢帛衣物，風吹火燔所止。（《永樂大典》卷之二千九百七十二《人·才人》引《唐語林》）","sortOrder":20},
  {"id":"s_work_dnl_24_21","chapterId":"ch_work_dnl_24","text":"武寧節度使康季榮不恤軍士，部曲噪而逐之，投於嶺外。上以直金吾大將軍田牟曾為徐州，有政聲，开延英召對，再命往镇。（《永樂大典》卷之一萬八千二百九《將·軍士逐將》引《唐語林》）","sortOrder":21},
];

